#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_q8_0_block_two_linear_rows_with_cpu<F>(
    input_scales: &[f32],
    input_quants: &[i8],
    first_weight_blocks: &[u8],
    second_weight_blocks: &[u8],
    rows: usize,
    blocks_per_row: usize,
    first_output: &mut [f32],
    second_output: &mut [f32],
    cpu_work: F,
) -> bool
where
    F: FnOnce(),
{
    const Q8_0_BLOCK_VALUES: usize = 32;
    const Q8_0_BLOCK_BYTES: usize = 36;
    if rows == 0 || blocks_per_row == 0 || first_output.len() != rows || second_output.len() != rows
    {
        return false;
    }
    let expected_weight_bytes = rows
        .saturating_mul(blocks_per_row)
        .saturating_mul(Q8_0_BLOCK_BYTES);
    if input_scales.len() != blocks_per_row
        || input_quants.len() != blocks_per_row.saturating_mul(Q8_0_BLOCK_VALUES)
        || first_weight_blocks.len() != expected_weight_bytes
        || second_weight_blocks.len() != expected_weight_bytes
    {
        return false;
    }
    let Some(kernel) = metal_linear_kernel() else {
        return false;
    };
    let mut cache = metal_linear_cache()
        .lock()
        .expect("metal linear cache poisoned");
    let input_scales_buffer = cache.q8_input_scales_buffer(
        &kernel.device,
        std::mem::size_of_val(input_scales),
        input_scales.as_ptr(),
    );
    let input_quants_buffer = cache.q8_input_quants_buffer(
        &kernel.device,
        std::mem::size_of_val(input_quants),
        input_quants.as_ptr(),
    );
    let first_weight_blocks_buffer =
        cache.q8_block_weight_buffer(&kernel.device, first_weight_blocks);
    let second_weight_blocks_buffer =
        cache.q8_block_weight_buffer(&kernel.device, second_weight_blocks);
    let first_output_buffer = cache.output_buffer(
        &kernel.device,
        std::mem::size_of_val(first_output),
        first_output.as_mut_ptr(),
    );
    let second_output_buffer = cache.aux_output_buffer(
        &kernel.device,
        std::mem::size_of_val(second_output),
        second_output.as_mut_ptr(),
    );
    let scalar_buffer = cache.scalar_buffer(&kernel.device, 2 * std::mem::size_of::<u32>());
    write_buffer_f32(&input_scales_buffer, input_scales);
    write_buffer_i8(&input_quants_buffer, input_quants);
    unsafe {
        let scalars = scalar_buffer.contents() as *mut u32;
        *scalars = blocks_per_row as u32;
        *scalars.add(1) = rows as u32;
    }

    let width = kernel.q8_0_block_pipeline.thread_execution_width().max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: (rows as u64).div_ceil(width),
        height: 1,
        depth: 1,
    };

    let (command_buffer, is_session) = get_active_or_new_command_buffer(kernel);
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.q8_0_block_pipeline);
    encoder.set_buffer(0, Some(&input_scales_buffer), 0);
    encoder.set_buffer(1, Some(&input_quants_buffer), 0);
    encoder.set_buffer(4, Some(&scalar_buffer), 0);
    encoder.set_buffer(5, Some(&scalar_buffer), std::mem::size_of::<u32>() as u64);

    encoder.set_buffer(2, Some(&first_weight_blocks_buffer), 0);
    encoder.set_buffer(3, Some(&first_output_buffer), 0);
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);

    encoder.set_buffer(2, Some(&second_weight_blocks_buffer), 0);
    encoder.set_buffer(3, Some(&second_output_buffer), 0);
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);

    encoder.end_encoding();

    if is_session {
        cpu_work();
        cache.deferred_reads.push(DeferredRead {
            buffer: first_output_buffer.clone(),
            dest_ptr: first_output.as_mut_ptr() as usize,
            dest_len: first_output.len(),
        });
        cache.deferred_reads.push(DeferredRead {
            buffer: second_output_buffer.clone(),
            dest_ptr: second_output.as_mut_ptr() as usize,
            dest_len: second_output.len(),
        });
        drop(cache);
    } else {
        command_buffer.commit();
        cpu_work();
        command_buffer.wait_until_completed();
        drop(cache);
        read_buffer_f32(&first_output_buffer, first_output);
        read_buffer_f32(&second_output_buffer, second_output);
    }
    true
}

/// GPU RMSNorm of a single row: output = input / sqrt(mean(input^2) + eps) * weight.
/// Returns None if Metal is unavailable (caller falls back to CPU). Building block for
/// the GPU-resident forward pass; parity-checked against the CPU rms_norm.
#[cfg(target_os = "macos")]
pub fn try_rms_norm_f32(input: &[f32], weight: &[f32], eps: f32) -> Option<Vec<f32>> {
    if input.is_empty() || input.len() != weight.len() {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let width = input.len();
    let byte_len = std::mem::size_of_val(input) as u64;
    let in_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let weight_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let out_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let scalar_buf = kernel
        .device
        .new_buffer(8, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&in_buf, input);
    write_buffer_f32(&weight_buf, weight);
    unsafe {
        let p = scalar_buf.contents() as *mut u8;
        *(p as *mut u32) = width as u32;
        *(p.add(4) as *mut f32) = eps;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.rms_norm_pipeline);
    encoder.set_buffer(0, Some(&in_buf), 0);
    encoder.set_buffer(1, Some(&weight_buf), 0);
    encoder.set_buffer(2, Some(&out_buf), 0);
    encoder.set_buffer(3, Some(&scalar_buf), 0);
    encoder.set_buffer(4, Some(&scalar_buf), 4);
    let threads = metal::MTLSize {
        width: 256,
        height: 1,
        depth: 1,
    };
    let one_group = metal::MTLSize {
        width: 1,
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(one_group, threads);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; width];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// GPU per-head RMSNorm for Gemma QK-norm / weightless V-norm. `input` is
/// `head_count * head_dim`; each head's chunk is normalized independently with the
/// same reduction as `try_rms_norm_f32`. `weight` is `head_dim` (shared across
/// heads, e.g. q_norm/k_norm) or None for the weightless V-norm. None if Metal
/// unavailable or shapes mismatch.
#[cfg(target_os = "macos")]
pub fn try_rms_norm_per_head_f32(
    input: &[f32],
    weight: Option<&[f32]>,
    head_count: usize,
    head_dim: usize,
    eps: f32,
) -> Option<Vec<f32>> {
    if head_dim == 0 || head_count == 0 || input.len() != head_count * head_dim {
        return None;
    }
    if let Some(w) = weight {
        if w.len() != head_dim {
            return None;
        }
    }
    let kernel = metal_linear_kernel()?;
    let byte_len = std::mem::size_of_val(input) as u64;
    let in_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let out_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    // Weight buffer is always bound; a dummy when weightless (kernel won't read it).
    let weight_buf = kernel
        .device
        .new_buffer((head_dim * 4) as u64, MTLResourceOptions::StorageModeShared);
    if let Some(w) = weight {
        write_buffer_f32(&weight_buf, w);
    }
    let scalar_buf = kernel
        .device
        .new_buffer(12, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&in_buf, input);
    unsafe {
        let p = scalar_buf.contents() as *mut u8;
        *(p as *mut u32) = head_dim as u32;
        *(p.add(4) as *mut f32) = eps;
        *(p.add(8) as *mut u32) = u32::from(weight.is_some());
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.rms_norm_per_head_pipeline);
    encoder.set_buffer(0, Some(&in_buf), 0);
    encoder.set_buffer(1, Some(&weight_buf), 0);
    encoder.set_buffer(2, Some(&out_buf), 0);
    encoder.set_buffer(3, Some(&scalar_buf), 0);
    encoder.set_buffer(4, Some(&scalar_buf), 4);
    encoder.set_buffer(5, Some(&scalar_buf), 8);
    let threads = metal::MTLSize {
        width: 256,
        height: 1,
        depth: 1,
    };
    let groups = metal::MTLSize {
        width: head_count as u64,
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(groups, threads);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; input.len()];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// Standalone gemma4 f32-activation × wire-Q8 GEMV (builds buffers, one dispatch,
/// reads back). `weight_wire` is row-major 34-byte Q8_0 wire blocks
/// (`rows * blocks_per_row` of them); `y` is the f32 activation
/// (`blocks_per_row * 32`). This is the workhorse the gemma resident decode graph
/// runs 8× per layer, validated here against a CPU f32×dequant reference. None if
/// Metal is unavailable or shapes are invalid.
#[cfg(target_os = "macos")]
pub fn try_gemma4_q8_matmul_f32y(
    y: &[f32],
    weight_wire: &[u8],
    rows: usize,
    blocks_per_row: usize,
) -> Option<Vec<f32>> {
    const WIRE: usize = 34;
    if rows == 0
        || blocks_per_row == 0
        || y.len() != blocks_per_row * 32
        || weight_wire.len() != rows * blocks_per_row * WIRE
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let y_buf = k.device.new_buffer(
        std::mem::size_of_val(y) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let w_buf = k.device.new_buffer(
        weight_wire.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let out_buf = k
        .device
        .new_buffer((rows * 4) as u64, MTLResourceOptions::StorageModeShared);
    let scalar_buf = k
        .device
        .new_buffer(8, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&y_buf, y);
    write_buffer_u8(&w_buf, weight_wire);
    unsafe {
        let p = scalar_buf.contents() as *mut u32;
        *p = blocks_per_row as u32;
        *p.add(1) = rows as u32;
    }
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_q8_matmul(e, k, &y_buf, &w_buf, &out_buf, &scalar_buf, rows);
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; rows];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// Q4_0 wire GEMV on the GPU — the QAT-row counterpart of
/// [`try_gemma4_q8_matmul_f32y`]. `weight_wire` is `rows * blocks_per_row`
/// 18-byte Q4_0 blocks; `y` is `blocks_per_row * 32` f32 activations. Returns
/// `rows` f32 outputs (f32 activation x inline-dequantized Q4_0 weight). For
/// validating the Q4_0 GPU kernel against the CPU dequant reference.
#[cfg(target_os = "macos")]
pub fn try_gemma4_q4_0_matmul_f32y(
    y: &[f32],
    weight_wire: &[u8],
    rows: usize,
    blocks_per_row: usize,
) -> Option<Vec<f32>> {
    const WIRE: usize = 18;
    if rows == 0
        || blocks_per_row == 0
        || y.len() != blocks_per_row * 32
        || weight_wire.len() != rows * blocks_per_row * WIRE
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let y_buf = k.device.new_buffer(
        std::mem::size_of_val(y) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let w_buf = k.device.new_buffer(
        weight_wire.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let out_buf = k
        .device
        .new_buffer((rows * 4) as u64, MTLResourceOptions::StorageModeShared);
    let scalar_buf = k
        .device
        .new_buffer(8, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&y_buf, y);
    write_buffer_u8(&w_buf, weight_wire);
    unsafe {
        let p = scalar_buf.contents() as *mut u32;
        *p = blocks_per_row as u32;
        *p.add(1) = rows as u32;
    }
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_q4_0_matmul(e, k, &y_buf, &w_buf, &out_buf, &scalar_buf, rows);
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; rows];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// Batched Q4_0 expert projection against CPU-quantized Q8_0 activations.
///
/// This is the disk-paged Ghost-MoE bridge: one selected expert's wire matrix
/// is uploaded once, every prompt row that selected it is dispatched together,
/// and only the f32 outputs come back. The shader keeps the CPU comparator's
/// exact per-block integer dot and increasing-block accumulation order; it does
/// not use the resident lane's higher-throughput f32-activation reduction.
#[cfg(target_os = "macos")]
pub(crate) fn try_gemma4_q4_0_matmul_q8_batch(
    inputs: &[&[crate::tensor::Q8_0Block]],
    weight_wire: &[u8],
    rows: usize,
) -> Option<Vec<Vec<f32>>> {
    try_gemma4_q4_0_matmul_q8_batch_impl(inputs, weight_wire, rows, false)
}

#[cfg(target_os = "macos")]
fn try_gemma4_q4_0_matmul_q8_batch_impl(
    inputs: &[&[crate::tensor::Q8_0Block]],
    weight_wire: &[u8],
    rows: usize,
    prefer_simd: bool,
) -> Option<Vec<Vec<f32>>> {
    const WIRE: usize = 18;
    let blocks_per_row = inputs.first()?.len();
    let tokens = inputs.len();
    if rows == 0
        || blocks_per_row == 0
        || inputs.iter().any(|input| input.len() != blocks_per_row)
        || weight_wire.len() != rows.checked_mul(blocks_per_row)?.checked_mul(WIRE)?
        || rows.checked_mul(tokens)? > u32::MAX as usize
        || rows > u32::MAX as usize
        || blocks_per_row > u32::MAX as usize
        || tokens > u32::MAX as usize
    {
        return None;
    }

    let mut scales = Vec::with_capacity(tokens * blocks_per_row);
    let mut quants = Vec::with_capacity(tokens * blocks_per_row * 32);
    for input in inputs {
        for block in *input {
            scales.push(block.scale);
            quants.extend(block.quants.iter().map(|&q| q as u8));
        }
    }

    let k = metal_linear_kernel()?;
    let scales_buf = k.device.new_buffer(
        std::mem::size_of_val(scales.as_slice()) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let quants_buf = k
        .device
        .new_buffer(quants.len() as u64, MTLResourceOptions::StorageModeShared);
    let weight_buf = k.device.new_buffer(
        weight_wire.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let output_buf = k.device.new_buffer(
        (rows * tokens * std::mem::size_of::<f32>()) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let scalar_buf = k
        .device
        .new_buffer(12, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&scales_buf, &scales);
    write_buffer_u8(&quants_buf, &quants);
    write_buffer_u8(&weight_buf, weight_wire);
    unsafe {
        let p = scalar_buf.contents() as *mut u32;
        *p = blocks_per_row as u32;
        *p.add(1) = rows as u32;
        *p.add(2) = tokens as u32;
    }

    let simd_scratch_bytes = blocks_per_row.checked_mul(std::mem::size_of::<f32>())?;
    let simd_pipeline = (prefer_simd && threadgroup_alloc_fits(&k.device, simd_scratch_bytes))
        .then(|| admitted_32_lane_pipeline(k.q4_0_q8_ordered_simd_pipeline.as_ref()))
        .flatten();
    if prefer_simd && simd_pipeline.is_none() {
        return None;
    }
    let pipeline = simd_pipeline.unwrap_or(&k.q4_0_q8_ordered_pipeline);
    let command_buffer = k.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(pipeline);
    encoder.set_buffer(0, Some(&scales_buf), 0);
    encoder.set_buffer(1, Some(&quants_buf), 0);
    encoder.set_buffer(2, Some(&weight_buf), 0);
    encoder.set_buffer(3, Some(&output_buf), 0);
    encoder.set_buffer(4, Some(&scalar_buf), 0);
    encoder.set_buffer(5, Some(&scalar_buf), 4);
    encoder.set_buffer(6, Some(&scalar_buf), 8);
    if simd_pipeline.is_some() {
        encoder.set_threadgroup_memory_length(0, simd_scratch_bytes as u64);
        dispatch_one_simdgroup_per_row(encoder, rows * tokens);
    } else {
        dispatch_1d(encoder, pipeline, rows * tokens);
    }
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();

    let mut flat = vec![0.0f32; rows * tokens];
    read_buffer_f32(&output_buf, &mut flat);
    Some(flat.chunks_exact(rows).map(<[f32]>::to_vec).collect())
}

/// Gemma 4 26B routed-expert geometry. One `.cghost` record is the fused
/// gate/up Q4_0 matrix followed immediately by the down Q4_0 matrix.
#[cfg(target_os = "macos")]
pub(crate) const GEMMA4_Q4_EXPERT_RECORD_BYTES: usize = 3_345_408;
#[cfg(target_os = "macos")]
const GEMMA4_Q4_EXPERT_SLOT_ALIGNMENT: usize = 16 * 1024;
#[cfg(target_os = "macos")]
const GEMMA4_Q4_EXPERT_SLOT_STRIDE: usize = 3_358_720;
#[cfg(target_os = "macos")]
const GEMMA4_Q4_EXPERT_HIDDEN: usize = 2_816;
#[cfg(target_os = "macos")]
const GEMMA4_Q4_EXPERT_FF: usize = 704;
#[cfg(target_os = "macos")]
const GEMMA4_Q4_EXPERT_ROUTES: usize = 8;
#[cfg(target_os = "macos")]
const GEMMA4_Q4_EXPERT_INPUT_BLOCKS: usize = GEMMA4_Q4_EXPERT_HIDDEN / 32;
#[cfg(target_os = "macos")]
const GEMMA4_Q4_EXPERT_ACT_BLOCKS: usize = GEMMA4_Q4_EXPERT_FF / 32;

/// Caller-owned persistent Metal-visible routed-expert slots.
///
/// The storage is one `StorageModeShared` slab rather than many independent
/// buffers, allowing a single fixed-geometry kernel to select all top-8 experts
/// by slot ID. Every slot begins at a 16 KiB boundary. The first
/// [`GEMMA4_Q4_EXPERT_RECORD_BYTES`] bytes are writable expert payload; the tail
/// is padding. A cache miss can therefore issue a positioned read directly into
/// [`Self::slot_bytes_mut`] (or parallel disjoint reads through
/// [`Self::slab_bytes_mut`]) with no staging allocation and no GPU upload.
#[cfg(target_os = "macos")]
pub(crate) struct Gemma4Q4ExpertSlots {
    slab: Buffer,
    slot_count: usize,
    slab_bytes: usize,
}

#[cfg(target_os = "macos")]
impl Gemma4Q4ExpertSlots {
    pub(crate) fn new(slot_count: usize) -> Option<Self> {
        if slot_count == 0 || slot_count > u32::MAX as usize {
            return None;
        }
        let slab_bytes = slot_count.checked_mul(GEMMA4_Q4_EXPERT_SLOT_STRIDE)?;
        let kernel = metal_linear_kernel()?;
        if slab_bytes > kernel.device.max_buffer_length() as usize {
            return None;
        }
        let slab = kernel
            .device
            .new_buffer(slab_bytes as u64, MTLResourceOptions::StorageModeShared);
        // Direct-I/O-friendly slot offsets only help when the slab base itself
        // is aligned. Apple shared buffers are page-aligned; fail closed if a
        // future backend/device stops honoring that property.
        if !(slab.contents() as usize).is_multiple_of(GEMMA4_Q4_EXPERT_SLOT_ALIGNMENT) {
            return None;
        }
        Some(Self {
            slab,
            slot_count,
            slab_bytes,
        })
    }

    pub(crate) const fn slot_count(&self) -> usize {
        self.slot_count
    }

    pub(crate) const fn slot_record_bytes(&self) -> usize {
        GEMMA4_Q4_EXPERT_RECORD_BYTES
    }

    pub(crate) const fn slot_stride_bytes(&self) -> usize {
        GEMMA4_Q4_EXPERT_SLOT_STRIDE
    }

    /// Entire aligned slab for safe disjoint parallel fills. Callers split with
    /// `par_chunks_mut(slot_stride_bytes())` and pass only each chunk's leading
    /// `slot_record_bytes()` bytes to `GhostFile::read_moe_expert_into`.
    pub(crate) fn slab_bytes_mut(&mut self) -> &mut [u8] {
        // SAFETY: the shared buffer owns `slab_bytes` writable bytes for at
        // least this borrow, and `&mut self` prevents concurrent safe GPU use.
        unsafe {
            std::slice::from_raw_parts_mut(self.slab.contents().cast::<u8>(), self.slab_bytes)
        }
    }

    pub(crate) fn slot_bytes_mut(&mut self, slot: usize) -> Option<&mut [u8]> {
        if slot >= self.slot_count {
            return None;
        }
        let start = slot * GEMMA4_Q4_EXPERT_SLOT_STRIDE;
        // SAFETY: `start + record` lies inside the checked slab allocation;
        // `&mut self` makes the returned expert record uniquely borrowed.
        Some(unsafe {
            std::slice::from_raw_parts_mut(
                self.slab.contents().cast::<u8>().add(start),
                GEMMA4_Q4_EXPERT_RECORD_BYTES,
            )
        })
    }
}

/// One selected expert in router-rank order. `scale` is already the CPU
/// runtime's `down_exps_scale[e] * (prob[e] / selected_probability_sum)`.
#[cfg(target_os = "macos")]
#[derive(Debug, Clone, Copy)]
pub(crate) struct Gemma4Q4ExpertRoute {
    pub(crate) slot: usize,
    pub(crate) scale: f32,
}

/// Per-call evidence that the persistent expert lane remained a compact GPU
/// graph. `streamed_weight_bytes` is the useful Q4_0 traffic (top-8 complete
/// records), excluding tiny activation/route buffers.
#[cfg(target_os = "macos")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct Gemma4Q4ExpertDiagnostics {
    pub(crate) wall_us: u128,
    pub(crate) gpu_us: u128,
    pub(crate) kernel_us: u128,
    pub(crate) command_buffers: u32,
    pub(crate) dispatches: u32,
    pub(crate) streamed_weight_bytes: u64,
    pub(crate) cpu_geglu_boundary: bool,
}

#[cfg(target_os = "macos")]
impl Gemma4Q4ExpertDiagnostics {
    pub(crate) fn effective_gib_per_s(self) -> f64 {
        if self.gpu_us == 0 {
            return 0.0;
        }
        self.streamed_weight_bytes as f64
            / (1024.0 * 1024.0 * 1024.0)
            / (self.gpu_us as f64 / 1_000_000.0)
    }
}

/// One committed fused expert+MoE-tail graph. The command owns its Metal
/// command-buffer reference while the resident runtime owns every bound buffer.
/// The caller may enqueue the next layer's attention/router command behind it
/// on the singleton queue, then drain this handle after that later command has
/// completed. That turns this wait into bookkeeping instead of a second GPU
/// synchronization point per layer.
#[cfg(target_os = "macos")]
pub(crate) struct Gemma4Q4ExpertPending {
    command_buffer: metal::CommandBuffer,
    started: std::time::Instant,
    dispatches: u32,
    streamed_weight_bytes: u64,
}

#[cfg(target_os = "macos")]
impl Gemma4Q4ExpertPending {
    pub(crate) fn wait(self) -> Option<Gemma4Q4ExpertDiagnostics> {
        self.command_buffer.wait_until_completed();
        if self.command_buffer.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }
        let (gpu_us, kernel_us) = command_buffer_gpu_times_us(&self.command_buffer);
        let diagnostics = Gemma4Q4ExpertDiagnostics {
            wall_us: self.started.elapsed().as_micros(),
            gpu_us,
            kernel_us,
            command_buffers: 1,
            dispatches: self.dispatches,
            streamed_weight_bytes: self.streamed_weight_bytes,
            cpu_geglu_boundary: false,
        };
        Gemma4Q4ExpertMetal::maybe_report("common-fused-async", diagnostics);
        Some(diagnostics)
    }
}

/// Reusable scratch and execution state for the Gemma 4 26B Q4_0 top-8 routed
/// expert branch. This object is deliberately independent of a layer's slot
/// slab: one engine can serve all 30 layer-local caches serially while each
/// layer retains its own LFU/LRU contents.
///
/// Neither execution method allocates an `MTLBuffer` or copies expert weights.
/// [`Self::run_q8_into`] is the three-dispatch speed lane. Because Metal and
/// Rust tanh differ by a few ULP, [`Self::run_q8_into_parity`] exposes that one
/// boundary to the CPU oracle while keeping both dominant Q4_0 projections on
/// Metal. The runtime keeps both lanes opt-in until real-model greedy parity.
#[cfg(target_os = "macos")]
pub(crate) struct Gemma4Q4ExpertMetal {
    input_scales: Buffer,
    input_quants: Buffer,
    gate_up: Buffer,
    activated: Buffer,
    activation_scales: Buffer,
    activation_quants: Buffer,
    route_slots: Buffer,
    route_scales: Buffer,
    output: Buffer,
}

#[cfg(target_os = "macos")]
impl Gemma4Q4ExpertMetal {
    pub(crate) fn new() -> Option<Self> {
        let kernel = metal_linear_kernel()?;
        let shared = |bytes: usize| {
            kernel
                .device
                .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
        };
        Some(Self {
            input_scales: shared(GEMMA4_Q4_EXPERT_INPUT_BLOCKS * std::mem::size_of::<f32>()),
            input_quants: shared(GEMMA4_Q4_EXPERT_HIDDEN),
            gate_up: shared(
                GEMMA4_Q4_EXPERT_ROUTES * 2 * GEMMA4_Q4_EXPERT_FF * std::mem::size_of::<f32>(),
            ),
            activated: shared(
                GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF * std::mem::size_of::<f32>(),
            ),
            activation_scales: shared(
                GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_ACT_BLOCKS * std::mem::size_of::<f32>(),
            ),
            activation_quants: shared(GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF),
            route_slots: shared(GEMMA4_Q4_EXPERT_ROUTES * std::mem::size_of::<u32>()),
            route_scales: shared(GEMMA4_Q4_EXPERT_ROUTES * std::mem::size_of::<f32>()),
            output: shared(GEMMA4_Q4_EXPERT_HIDDEN * std::mem::size_of::<f32>()),
        })
    }

    fn prepare_routes(
        &mut self,
        slots: &Gemma4Q4ExpertSlots,
        routes: &[Gemma4Q4ExpertRoute; GEMMA4_Q4_EXPERT_ROUTES],
    ) -> Option<()> {
        if routes
            .iter()
            .any(|route| route.slot >= slots.slot_count || !route.scale.is_finite())
        {
            return None;
        }
        unsafe {
            let slot_out = self.route_slots.contents().cast::<u32>();
            let route_scale_out = self.route_scales.contents().cast::<f32>();
            for (route_idx, route) in routes.iter().enumerate() {
                *slot_out.add(route_idx) = route.slot as u32;
                *route_scale_out.add(route_idx) = route.scale;
            }
        }
        Some(())
    }

    fn prepare(
        &mut self,
        input: &[crate::tensor::Q8_0Block],
        slots: &Gemma4Q4ExpertSlots,
        routes: &[Gemma4Q4ExpertRoute; GEMMA4_Q4_EXPERT_ROUTES],
        output: &[f32],
    ) -> Option<()> {
        if input.len() != GEMMA4_Q4_EXPERT_INPUT_BLOCKS
            || output.len() != GEMMA4_Q4_EXPERT_HIDDEN
            || input.iter().any(|block| !block.scale.is_finite())
        {
            return None;
        }
        self.prepare_routes(slots, routes)?;
        unsafe {
            let scale_out = self.input_scales.contents().cast::<f32>();
            let quant_out = self.input_quants.contents().cast::<i8>();
            for (block_idx, block) in input.iter().enumerate() {
                *scale_out.add(block_idx) = block.scale;
                std::ptr::copy_nonoverlapping(
                    block.quants.as_ptr(),
                    quant_out.add(block_idx * 32),
                    32,
                );
            }
        }
        Some(())
    }

    fn encode_down_reduce_to(
        &self,
        encoder: &metal::ComputeCommandEncoderRef,
        kernel: &MetalLinearKernel,
        slots: &Gemma4Q4ExpertSlots,
        output: &Buffer,
        simd_fast: bool,
    ) {
        let turbo_pipeline = (simd_fast && gemma4_ghost_turbo_enabled())
            .then(|| {
                admitted_32_lane_pipeline(
                    kernel.gemma4_q4_expert_down_reduce_turbo_pipeline.as_ref(),
                )
            })
            .flatten();
        let simd_pipeline = (simd_fast && turbo_pipeline.is_none())
            .then(|| {
                admitted_32_lane_pipeline(
                    kernel.gemma4_q4_expert_down_reduce_simd_pipeline.as_ref(),
                )
            })
            .flatten();
        let pipeline = turbo_pipeline
            .or(simd_pipeline)
            .unwrap_or(&kernel.gemma4_q4_expert_down_reduce_pipeline);
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(&self.activation_scales), 0);
        encoder.set_buffer(1, Some(&self.activation_quants), 0);
        encoder.set_buffer(2, Some(&slots.slab), 0);
        encoder.set_buffer(3, Some(&self.route_slots), 0);
        encoder.set_buffer(4, Some(&self.route_scales), 0);
        encoder.set_buffer(5, Some(output), 0);
        if turbo_pipeline.is_some() {
            dispatch_four_simdgroup_rows(encoder, GEMMA4_Q4_EXPERT_HIDDEN);
        } else if simd_pipeline.is_some() {
            encoder.set_threadgroup_memory_length(
                0,
                (GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_ACT_BLOCKS * std::mem::size_of::<f32>())
                    as u64,
            );
            dispatch_one_simdgroup_per_row(encoder, GEMMA4_Q4_EXPERT_HIDDEN);
        } else {
            dispatch_1d(encoder, pipeline, GEMMA4_Q4_EXPERT_HIDDEN);
        }
    }

    fn encode_down_reduce(
        &self,
        encoder: &metal::ComputeCommandEncoderRef,
        kernel: &MetalLinearKernel,
        slots: &Gemma4Q4ExpertSlots,
        simd_fast: bool,
    ) {
        self.encode_down_reduce_to(encoder, kernel, slots, &self.output, simd_fast);
    }

    /// Full-speed lane: fused ordered gate/up+GeGLU, Q8_0 requantization, then
    /// ordered down+route-scale+top-8 reduction in one command buffer. There is
    /// no allocation, weight copy, or CPU readback between these three stages.
    pub(crate) fn run_q8_into(
        &mut self,
        input: &[crate::tensor::Q8_0Block],
        slots: &Gemma4Q4ExpertSlots,
        routes: &[Gemma4Q4ExpertRoute; GEMMA4_Q4_EXPERT_ROUTES],
        output: &mut [f32],
    ) -> Option<Gemma4Q4ExpertDiagnostics> {
        self.run_q8_into_fused(input, slots, routes, output, true)
    }

    fn run_q8_into_fused(
        &mut self,
        input: &[crate::tensor::Q8_0Block],
        slots: &Gemma4Q4ExpertSlots,
        routes: &[Gemma4Q4ExpertRoute; GEMMA4_Q4_EXPERT_ROUTES],
        output: &mut [f32],
        prefer_simd: bool,
    ) -> Option<Gemma4Q4ExpertDiagnostics> {
        self.prepare(input, slots, routes, output)?;
        let kernel = metal_linear_kernel()?;
        let simd_fast = prefer_simd && gemma4_q4_simd_fast_available(kernel);
        let started = std::time::Instant::now();
        let command_buffer = kernel.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        let turbo_gate = (simd_fast && gemma4_ghost_turbo_enabled())
            .then(|| {
                admitted_32_lane_pipeline(
                    kernel
                        .gemma4_q4_expert_gate_up_geglu_turbo_pipeline
                        .as_ref(),
                )
            })
            .flatten();
        let gate_pipeline = if let Some(turbo) = turbo_gate {
            turbo
        } else if simd_fast {
            kernel
                .gemma4_q4_expert_gate_up_geglu_simd_pipeline
                .as_ref()
                .expect("fused SIMD Q4 admission requires gate/up pipeline")
        } else {
            &kernel.gemma4_q4_expert_gate_up_geglu_pipeline
        };
        encoder.set_compute_pipeline_state(gate_pipeline);
        encoder.set_buffer(0, Some(&self.input_scales), 0);
        encoder.set_buffer(1, Some(&self.input_quants), 0);
        encoder.set_buffer(2, Some(&slots.slab), 0);
        encoder.set_buffer(3, Some(&self.route_slots), 0);
        encoder.set_buffer(4, Some(&self.activated), 0);
        if turbo_gate.is_some() {
            dispatch_four_simdgroup_rows(encoder, GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF);
        } else if simd_fast {
            encoder.set_threadgroup_memory_length(
                0,
                (2 * GEMMA4_Q4_EXPERT_INPUT_BLOCKS * std::mem::size_of::<f32>()) as u64,
            );
            dispatch_one_simdgroup_per_row(encoder, GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF);
        } else {
            dispatch_1d(
                encoder,
                gate_pipeline,
                GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF,
            );
        }

        encoder.set_compute_pipeline_state(&kernel.gemma4_q4_expert_quantize_pipeline);
        encoder.set_buffer(0, Some(&self.activated), 0);
        encoder.set_buffer(1, Some(&self.activation_scales), 0);
        encoder.set_buffer(2, Some(&self.activation_quants), 0);
        dispatch_1d(
            encoder,
            &kernel.gemma4_q4_expert_quantize_pipeline,
            GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_ACT_BLOCKS,
        );

        self.encode_down_reduce(encoder, kernel, slots, simd_fast);
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();
        if command_buffer.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }
        let (gpu_us, kernel_us) = command_buffer_gpu_times_us(&command_buffer.to_owned());
        read_buffer_f32(&self.output, output);
        let diagnostics = Gemma4Q4ExpertDiagnostics {
            wall_us: started.elapsed().as_micros(),
            gpu_us,
            kernel_us,
            command_buffers: 1,
            dispatches: 3,
            streamed_weight_bytes: (GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_RECORD_BYTES) as u64,
            cpu_geglu_boundary: false,
        };
        Self::maybe_report(
            if turbo_gate.is_some() {
                "fused-turbo"
            } else if simd_fast {
                "fused-simd"
            } else {
                "fused-scalar"
            },
            diagnostics,
        );
        Some(diagnostics)
    }

    /// Parity lane: ordered gate/up projections run on Metal, Rust owns GeGLU
    /// and Q8_0 activation quantization in persistent shared scratch, then the
    /// ordered down/reduce kernel runs on Metal. This isolates Metal-vs-Rust
    /// tanh drift while retaining the two bandwidth-dominant GPU sweeps.
    pub(crate) fn run_q8_into_parity(
        &mut self,
        input: &[crate::tensor::Q8_0Block],
        slots: &Gemma4Q4ExpertSlots,
        routes: &[Gemma4Q4ExpertRoute; GEMMA4_Q4_EXPERT_ROUTES],
        output: &mut [f32],
    ) -> Option<Gemma4Q4ExpertDiagnostics> {
        self.prepare(input, slots, routes, output)?;
        let kernel = metal_linear_kernel()?;
        let started = std::time::Instant::now();

        let gate_command = kernel.queue.new_command_buffer();
        let gate_encoder = gate_command.new_compute_command_encoder();
        gate_encoder.set_compute_pipeline_state(&kernel.gemma4_q4_expert_gate_up_split_pipeline);
        gate_encoder.set_buffer(0, Some(&self.input_scales), 0);
        gate_encoder.set_buffer(1, Some(&self.input_quants), 0);
        gate_encoder.set_buffer(2, Some(&slots.slab), 0);
        gate_encoder.set_buffer(3, Some(&self.route_slots), 0);
        gate_encoder.set_buffer(4, Some(&self.gate_up), 0);
        dispatch_1d(
            gate_encoder,
            &kernel.gemma4_q4_expert_gate_up_split_pipeline,
            GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF,
        );
        gate_encoder.end_encoding();
        gate_command.commit();
        gate_command.wait_until_completed();
        if gate_command.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }
        self.cpu_geglu_quantize()?;

        let down_command = kernel.queue.new_command_buffer();
        let down_encoder = down_command.new_compute_command_encoder();
        self.encode_down_reduce(down_encoder, kernel, slots, false);
        down_encoder.end_encoding();
        down_command.commit();
        down_command.wait_until_completed();
        if down_command.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }
        let (gate_gpu_us, gate_kernel_us) = command_buffer_gpu_times_us(&gate_command.to_owned());
        let (down_gpu_us, down_kernel_us) = command_buffer_gpu_times_us(&down_command.to_owned());
        read_buffer_f32(&self.output, output);
        let diagnostics = Gemma4Q4ExpertDiagnostics {
            wall_us: started.elapsed().as_micros(),
            gpu_us: gate_gpu_us + down_gpu_us,
            kernel_us: gate_kernel_us + down_kernel_us,
            command_buffers: 2,
            dispatches: 2,
            streamed_weight_bytes: (GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_RECORD_BYTES) as u64,
            cpu_geglu_boundary: true,
        };
        Self::maybe_report("parity", diagnostics);
        Some(diagnostics)
    }

    /// Device-chained expert branch for the persistent Ghost common core. The
    /// pre-normalized Q8 input is produced by `enqueue_router`; the expert reduce
    /// writes the common routed buffer and the exact MoE tail is appended before
    /// the command completes. No 2,816-value activation crosses to the host.
    pub(crate) fn run_common_with_tail(
        &mut self,
        common: &mut Gemma4GhostCommonMetal,
        layer_idx: usize,
        slots: &Gemma4Q4ExpertSlots,
        routes: &[Gemma4Q4ExpertRoute; GEMMA4_Q4_EXPERT_ROUTES],
        fused_fast: bool,
    ) -> Option<Gemma4Q4ExpertDiagnostics> {
        if fused_fast {
            return self
                .enqueue_common_with_tail(common, layer_idx, slots, routes)?
                .wait();
        }

        self.prepare_routes(slots, routes)?;
        let kernel = metal_linear_kernel()?;
        let started = std::time::Instant::now();

        // Parity mode keeps Rust's established GeGLU/Q8_0 boundary while the
        // hidden/routed/tail vectors remain device-resident.
        let gate_command = kernel.queue.new_command_buffer();
        let gate_encoder = gate_command.new_compute_command_encoder();
        let scratch = common.moe.as_ref()?;
        gate_encoder.set_compute_pipeline_state(&kernel.gemma4_q4_expert_gate_up_split_pipeline);
        gate_encoder.set_buffer(0, Some(&scratch.expert_input_scales), 0);
        gate_encoder.set_buffer(1, Some(&scratch.expert_input_quants), 0);
        gate_encoder.set_buffer(2, Some(&slots.slab), 0);
        gate_encoder.set_buffer(3, Some(&self.route_slots), 0);
        gate_encoder.set_buffer(4, Some(&self.gate_up), 0);
        dispatch_1d(
            gate_encoder,
            &kernel.gemma4_q4_expert_gate_up_split_pipeline,
            GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF,
        );
        gate_encoder.end_encoding();
        gate_command.commit();
        gate_command.wait_until_completed();
        if gate_command.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }
        self.cpu_geglu_quantize()?;

        let down_command = kernel.queue.new_command_buffer();
        let down_encoder = down_command.new_compute_command_encoder();
        self.encode_down_reduce_to(down_encoder, kernel, slots, &common.routed_output, false);
        let tail_dispatches = common.encode_moe_tail(down_encoder, kernel, layer_idx)?;
        down_encoder.end_encoding();
        down_command.commit();
        down_command.wait_until_completed();
        if down_command.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }
        let (gate_gpu_us, gate_kernel_us) = command_buffer_gpu_times_us(&gate_command.to_owned());
        let (down_gpu_us, down_kernel_us) = command_buffer_gpu_times_us(&down_command.to_owned());
        common.promote_tail_output();
        let diagnostics = Gemma4Q4ExpertDiagnostics {
            wall_us: started.elapsed().as_micros(),
            gpu_us: gate_gpu_us + down_gpu_us,
            kernel_us: gate_kernel_us + down_kernel_us,
            command_buffers: 2,
            dispatches: 2 + tail_dispatches,
            streamed_weight_bytes: (GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_RECORD_BYTES) as u64,
            cpu_geglu_boundary: true,
        };
        Self::maybe_report("common-parity", diagnostics);
        Some(diagnostics)
    }

    /// Commit the fused expert reduce and exact MoE tail without waiting. The
    /// tail output is promoted immediately after commit: Metal command encoders
    /// retain the old output buffer, while the next layer observes that buffer
    /// as its hidden input. FIFO queue ordering makes the dependency explicit
    /// without a host readback or event.
    pub(crate) fn enqueue_common_with_tail(
        &mut self,
        common: &mut Gemma4GhostCommonMetal,
        layer_idx: usize,
        slots: &Gemma4Q4ExpertSlots,
        routes: &[Gemma4Q4ExpertRoute; GEMMA4_Q4_EXPERT_ROUTES],
    ) -> Option<Gemma4Q4ExpertPending> {
        self.prepare_routes(slots, routes)?;
        let kernel = metal_linear_kernel()?;
        let started = std::time::Instant::now();
        let command_buffer = kernel.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        let scratch = common.moe.as_ref()?;
        let simd_fast = common.q4_simd_fast && gemma4_q4_simd_fast_available(kernel);
        let turbo_gate = (simd_fast && gemma4_ghost_turbo_enabled())
            .then(|| {
                admitted_32_lane_pipeline(
                    kernel
                        .gemma4_q4_expert_gate_up_geglu_turbo_pipeline
                        .as_ref(),
                )
            })
            .flatten();
        let gate_pipeline = if let Some(turbo) = turbo_gate {
            turbo
        } else if simd_fast {
            kernel
                .gemma4_q4_expert_gate_up_geglu_simd_pipeline
                .as_ref()
                .expect("fused SIMD Q4 admission requires gate/up pipeline")
        } else {
            &kernel.gemma4_q4_expert_gate_up_geglu_pipeline
        };
        encoder.set_compute_pipeline_state(gate_pipeline);
        encoder.set_buffer(0, Some(&scratch.expert_input_scales), 0);
        encoder.set_buffer(1, Some(&scratch.expert_input_quants), 0);
        encoder.set_buffer(2, Some(&slots.slab), 0);
        encoder.set_buffer(3, Some(&self.route_slots), 0);
        encoder.set_buffer(4, Some(&self.activated), 0);
        if turbo_gate.is_some() {
            dispatch_four_simdgroup_rows(encoder, GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF);
        } else if simd_fast {
            encoder.set_threadgroup_memory_length(
                0,
                (2 * GEMMA4_Q4_EXPERT_INPUT_BLOCKS * std::mem::size_of::<f32>()) as u64,
            );
            dispatch_one_simdgroup_per_row(encoder, GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF);
        } else {
            dispatch_1d(
                encoder,
                gate_pipeline,
                GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_FF,
            );
        }
        encoder.set_compute_pipeline_state(&kernel.gemma4_q4_expert_quantize_pipeline);
        encoder.set_buffer(0, Some(&self.activated), 0);
        encoder.set_buffer(1, Some(&self.activation_scales), 0);
        encoder.set_buffer(2, Some(&self.activation_quants), 0);
        dispatch_1d(
            encoder,
            &kernel.gemma4_q4_expert_quantize_pipeline,
            GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_ACT_BLOCKS,
        );
        self.encode_down_reduce_to(encoder, kernel, slots, &common.routed_output, simd_fast);
        let tail_dispatches = common.encode_moe_tail(encoder, kernel, layer_idx)?;
        encoder.end_encoding();
        command_buffer.commit();
        common.promote_tail_output();
        Some(Gemma4Q4ExpertPending {
            command_buffer: command_buffer.to_owned(),
            started,
            dispatches: 3 + tail_dispatches,
            streamed_weight_bytes: (GEMMA4_Q4_EXPERT_ROUTES * GEMMA4_Q4_EXPERT_RECORD_BYTES) as u64,
        })
    }

    fn cpu_geglu_quantize(&mut self) -> Option<()> {
        let gate_up = self.gate_up.contents().cast::<f32>();
        let activated = self.activated.contents().cast::<f32>();
        let scales = self.activation_scales.contents().cast::<f32>();
        let quants = self.activation_quants.contents().cast::<i8>();
        unsafe {
            for route in 0..GEMMA4_Q4_EXPERT_ROUTES {
                let gate_base = route * 2 * GEMMA4_Q4_EXPERT_FF;
                let up_base = gate_base + GEMMA4_Q4_EXPERT_FF;
                let activation_base = route * GEMMA4_Q4_EXPERT_FF;
                for i in 0..GEMMA4_Q4_EXPERT_FF {
                    let value = crate::inference::gemma4::gelu_tanh(*gate_up.add(gate_base + i))
                        * *gate_up.add(up_base + i);
                    if !value.is_finite() {
                        return None;
                    }
                    *activated.add(activation_base + i) = value;
                }
                for block in 0..GEMMA4_Q4_EXPERT_ACT_BLOCKS {
                    let base = activation_base + block * 32;
                    let mut max_abs = 0.0f32;
                    for i in 0..32 {
                        max_abs = max_abs.max((*activated.add(base + i)).abs());
                    }
                    let unrounded_scale = max_abs / 127.0;
                    let stored_scale = f16_bits_to_f32(f32_to_f16_bits(unrounded_scale));
                    let inverse = if unrounded_scale == 0.0 {
                        0.0
                    } else {
                        1.0 / unrounded_scale
                    };
                    *scales.add(route * GEMMA4_Q4_EXPERT_ACT_BLOCKS + block) = stored_scale;
                    for i in 0..32 {
                        *quants.add(base + i) = ((*activated.add(base + i) * inverse)
                            .round()
                            .clamp(-128.0, 127.0))
                            as i8;
                    }
                }
            }
        }
        Some(())
    }

    fn maybe_report(mode: &str, diagnostics: Gemma4Q4ExpertDiagnostics) {
        if std::env::var("CAMELID_GEMMA4_GHOST_METAL_TIMING")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
        {
            eprintln!(
                "[gemma4-ghost-metal] mode={mode} cb={} dispatches={} wall={}us gpu={}us kernel={}us weights={:.2}MiB effective={:.2}GiB/s",
                diagnostics.command_buffers,
                diagnostics.dispatches,
                diagnostics.wall_us,
                diagnostics.gpu_us,
                diagnostics.kernel_us,
                diagnostics.streamed_weight_bytes as f64 / (1024.0 * 1024.0),
                diagnostics.effective_gib_per_s(),
            );
        }
    }
}

/// Encode the strict single-token Q6_K x Q8_K GEMV used by Gemma 4's tied
/// head. `scalar` carries `n_superblocks` at byte 0 and `rows` at byte 4.
/// `weight_offset` permits a file-backed, page-aligned Metal buffer window to
/// expose a tensor that starts after the beginning of that window.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_q6k_ordered_single(
    encoder: &metal::ComputeCommandEncoderRef,
    kernel: &MetalLinearKernel,
    input_scales: &Buffer,
    input_quants: &Buffer,
    weight: &Buffer,
    weight_offset: u64,
    output: &Buffer,
    scalar: &Buffer,
    n_superblocks: usize,
    rows: usize,
) {
    let turbo_pipeline = gemma4_ghost_turbo_enabled()
        .then(|| admitted_32_lane_pipeline(kernel.q6k_linear_turbo_pipeline.as_ref()))
        .flatten();
    encoder
        .set_compute_pipeline_state(turbo_pipeline.unwrap_or(&kernel.q6k_linear_ordered_pipeline));
    encoder.set_buffer(0, Some(input_scales), 0);
    encoder.set_buffer(1, Some(input_quants), 0);
    encoder.set_buffer(2, Some(weight), weight_offset);
    encoder.set_buffer(3, Some(output), 0);
    encoder.set_buffer(4, Some(scalar), 0);
    encoder.set_buffer(5, Some(scalar), 4);
    if turbo_pipeline.is_some() {
        dispatch_four_simdgroup_rows(encoder, rows);
        return;
    }
    let scratch_bytes = (n_superblocks * 8 * std::mem::size_of::<i32>()).next_multiple_of(16);
    assert_threadgroup_fits(
        &kernel.device,
        scratch_bytes,
        "ordered Gemma 4 Q6_K tied-head scratch",
    );
    encoder.set_threadgroup_memory_length(0, scratch_bytes as u64);
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: rows as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 32,
            height: 1,
            depth: 1,
        },
    );
}

/// NVFP4 wire GEMV on the GPU (GABBRO M3) — the NVFP4 counterpart of
/// [`try_gemma4_q4_0_matmul_f32y`]. `weight_wire` is `rows * blocks_per_row`
/// 36-byte NVFP4 superblocks; `y` is `blocks_per_row * 64` f32 activations (the
/// superblock is 64 values, unlike the 32-value Q8_0/Q4_0 blocks). Returns `rows`
/// f32 outputs (f32 activation × inline-decoded NVFP4 weight). For validating the
/// NVFP4 GPU kernel against the CPU `nvfp4_wire_block_dequant` reference.
#[cfg(target_os = "macos")]
pub fn try_gemma4_nvfp4_matmul_f32y(
    y: &[f32],
    weight_wire: &[u8],
    rows: usize,
    blocks_per_row: usize,
) -> Option<Vec<f32>> {
    const WIRE: usize = 36;
    // The NVFP4 superblock is 64 values (block_elements), not 32 — the single
    // point where an NVFP4 row's activation stride differs from Q8_0/Q4_0.
    if rows == 0
        || blocks_per_row == 0
        || y.len() != blocks_per_row * GemmaWireFmt::Nvfp4.block_elements()
        || weight_wire.len() != rows * blocks_per_row * WIRE
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let y_buf = k.device.new_buffer(
        std::mem::size_of_val(y) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let w_buf = k.device.new_buffer(
        weight_wire.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let out_buf = k
        .device
        .new_buffer((rows * 4) as u64, MTLResourceOptions::StorageModeShared);
    let scalar_buf = k
        .device
        .new_buffer(8, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&y_buf, y);
    write_buffer_u8(&w_buf, weight_wire);
    unsafe {
        let p = scalar_buf.contents() as *mut u32;
        *p = blocks_per_row as u32;
        *p.add(1) = rows as u32;
    }
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_nvfp4_matmul(e, k, &y_buf, &w_buf, &out_buf, &scalar_buf, rows);
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; rows];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// Standalone gemma4 FFN sub-block: builds buffers, runs the whole
/// [`encode_gemma4_ffn`] chain in one command buffer, reads back the hidden output.
/// `gate`/`up` are `ffn_dim` rows over `hidden` in; `down` is `hidden` rows over
/// `ffn_dim` in; weights are row-major 34-byte Q8 wire blocks. For validating the
/// FFN sub-graph against CPU. None if Metal unavailable or shapes are invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_ffn(
    fmt: GemmaWireFmt,
    h_in: &[f32],
    ffn_norm: &[f32],
    post_ffw_norm: &[f32],
    eps: f32,
    gate_wire: &[u8],
    up_wire: &[u8],
    down_wire: &[u8],
    ffn_dim: usize,
) -> Option<Vec<f32>> {
    let wire: usize = fmt.wire_bytes();
    let hidden = h_in.len();
    if hidden == 0
        || ffn_dim == 0
        || !hidden.is_multiple_of(32)
        || !ffn_dim.is_multiple_of(32)
        || ffn_norm.len() != hidden
        || post_ffw_norm.len() != hidden
    {
        return None;
    }
    let bpr_hidden = hidden / 32;
    let bpr_ffn = ffn_dim / 32;
    if gate_wire.len() != ffn_dim * bpr_hidden * wire
        || up_wire.len() != ffn_dim * bpr_hidden * wire
        || down_wire.len() != hidden * bpr_ffn * wire
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = mkbuf(hidden * 4);
    let out_buf = mkbuf(hidden * 4);
    let gate_buf = mkbuf(gate_wire.len());
    let up_buf = mkbuf(up_wire.len());
    let down_buf = mkbuf(down_wire.len());
    write_buffer_f32(&in_buf, h_in);
    write_buffer_u8(&gate_buf, gate_wire);
    write_buffer_u8(&up_buf, up_wire);
    write_buffer_u8(&down_buf, down_wire);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_ffn(
        fmt,
        e,
        k,
        &mut keep,
        &in_buf,
        &out_buf,
        ffn_norm,
        post_ffw_norm,
        eps,
        &gate_buf,
        &up_buf,
        &down_buf,
        ffn_dim,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone gemma4 attention sub-block: builds buffers (incl. a caller-prefilled
/// KV cache laid out `[kv_head][max_positions][head_dim]`), runs the whole
/// [`encode_gemma4_attention`] chain in one command buffer, reads back the hidden
/// output. For validating the attention sub-graph against CPU. The current token's
/// K/V are scattered into the cache at `write_position`; attention covers the window
/// `[window_start .. filled)`. None if Metal unavailable or shapes invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_attention(
    fmt: GemmaWireFmt,
    h_in: &[f32],
    attn_norm: &[f32],
    q_norm: &[f32],
    k_norm: &[f32],
    post_attn_norm: &[f32],
    eps: f32,
    q_wire: &[u8],
    k_wire: &[u8],
    v_wire: Option<&[u8]>,
    o_wire: &[u8],
    cos_t: &[f32],
    sin_t: &[f32],
    cache_k_init: &[f32],
    cache_v_init: &[f32],
    max_positions: usize,
    write_position: usize,
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    filled: usize,
    window_start: usize,
    scale: f32,
    owns_kv: bool,
) -> Option<Vec<f32>> {
    let wire = fmt.wire_bytes();
    let hidden = h_in.len();
    let q_dim = n_heads * head_dim;
    let kv_dim = n_kv_heads * head_dim;
    let cache_len = n_kv_heads * max_positions * head_dim;
    if hidden == 0
        || !hidden.is_multiple_of(32)
        || !head_dim.is_multiple_of(2)
        || n_kv_heads == 0
        || !n_heads.is_multiple_of(n_kv_heads)
        || attn_norm.len() != hidden
        || post_attn_norm.len() != hidden
        || q_norm.len() != head_dim
        || k_norm.len() != head_dim
        || cos_t.len() != head_dim / 2
        || sin_t.len() != head_dim / 2
        || write_position >= filled
        || filled > max_positions
        || window_start >= filled
        || cache_k_init.len() != cache_len
        || cache_v_init.len() != cache_len
    {
        return None;
    }
    let bpr_hidden = hidden / 32;
    let bpr_q = q_dim / 32;
    if q_wire.len() != q_dim * bpr_hidden * wire
        || k_wire.len() != kv_dim * bpr_hidden * wire
        || v_wire.is_some_and(|w| w.len() != kv_dim * bpr_hidden * wire)
        || o_wire.len() != hidden * bpr_q * wire
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = mkbuf(hidden * 4);
    let out_buf = mkbuf(hidden * 4);
    let q_buf = mkbuf(q_wire.len());
    let kw_buf = mkbuf(k_wire.len());
    let vw_buf = v_wire.map(|w| mkbuf(w.len()));
    let o_buf = mkbuf(o_wire.len());
    let cache_k = mkbuf(cache_len * 4);
    let cache_v = mkbuf(cache_len * 4);
    write_buffer_f32(&in_buf, h_in);
    write_buffer_u8(&q_buf, q_wire);
    write_buffer_u8(&kw_buf, k_wire);
    if let (Some(buf), Some(wire)) = (&vw_buf, v_wire) {
        write_buffer_u8(buf, wire);
    }
    write_buffer_u8(&o_buf, o_wire);
    write_buffer_f32(&cache_k, cache_k_init);
    write_buffer_f32(&cache_v, cache_v_init);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_attention(
        fmt,
        e,
        k,
        &mut keep,
        &in_buf,
        &out_buf,
        attn_norm,
        q_norm,
        k_norm,
        post_attn_norm,
        eps,
        &q_buf,
        &kw_buf,
        vw_buf.as_ref(),
        &o_buf,
        cos_t,
        sin_t,
        &cache_k,
        &cache_v,
        max_positions,
        write_position,
        n_heads,
        n_kv_heads,
        head_dim,
        filled,
        window_start,
        scale,
        owns_kv,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone gemma4 PLE per-layer injection: builds buffers, runs
/// [`encode_gemma4_ple`] in one command buffer, reads back the updated hidden.
/// `pli_l` is this layer's per-token Per-Layer-Embedding input (CPU-computed);
/// `ple_inp_gate` (output-major `[ple_dim][hidden]`) and `ple_proj`
/// (`[hidden][ple_dim]`) are the f32 PLE matrices. None if Metal unavailable or
/// shapes invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_ple(
    h_in: &[f32],
    pli_l: &[f32],
    ple_inp_gate: &[f32],
    ple_proj: &[f32],
    post_norm: &[f32],
    output_scale: f32,
    eps: f32,
    ple_dim: usize,
) -> Option<Vec<f32>> {
    let hidden = h_in.len();
    if hidden == 0
        || ple_dim == 0
        || pli_l.len() != ple_dim
        || ple_inp_gate.len() != ple_dim * hidden
        || ple_proj.len() != hidden * ple_dim
        || post_norm.len() != hidden
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkf = |v: &[f32]| {
        let b = k
            .device
            .new_buffer((v.len() * 4) as u64, MTLResourceOptions::StorageModeShared);
        write_buffer_f32(&b, v);
        b
    };
    let h_buf = mkf(h_in);
    let pli_buf = mkf(pli_l);
    let ig = mkf(ple_inp_gate);
    let pj = mkf(ple_proj);
    let pn = mkf(post_norm);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_ple(
        e,
        k,
        &mut keep,
        &h_buf,
        &pli_buf,
        0,
        &ig,
        &pj,
        &pn,
        output_scale,
        eps,
        hidden,
        ple_dim,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&h_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone gemma4 per-token `pli` on the GPU (the folded
/// [`encode_gemma4_pli`] path). Takes the RAW gemma tensors and folds the constants
/// internally. `proj` is `[ple_total][hidden]` (per_layer_model_proj), `proj_norm`
/// is `[ple_dim]`, `ti` is the `[ple_total]` per_layer_token_embd row for the token.
/// Returns `pli` `[ple_total]`. For validating the GPU pli vs the CPU prep.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_pli(
    h0: &[f32],
    proj: &[f32],
    proj_norm: &[f32],
    ti: &[f32],
    hidden: usize,
    ple_dim: usize,
    n_layers: usize,
    eps: f32,
) -> Option<Vec<f32>> {
    let ple_total = n_layers * ple_dim;
    if h0.len() != hidden
        || proj.len() != ple_total * hidden
        || proj_norm.len() != ple_dim
        || ti.len() != ple_total
    {
        return None;
    }
    let frac = std::f32::consts::FRAC_1_SQRT_2;
    let proj_scale = (hidden as f32).powf(-0.5);
    let embed_scale = (ple_dim as f32).sqrt();
    // Fold the constants into the resident inputs.
    let proj_folded: Vec<f32> = proj.iter().map(|v| v * proj_scale).collect();
    let projnorm_folded: Vec<f32> = proj_norm.iter().map(|v| v * frac).collect();
    let ti_folded: Vec<f32> = ti.iter().map(|v| v * embed_scale * frac).collect();
    let k = metal_linear_kernel()?;
    let mkf = |v: &[f32]| {
        let b = k
            .device
            .new_buffer((v.len() * 4) as u64, MTLResourceOptions::StorageModeShared);
        write_buffer_f32(&b, v);
        b
    };
    let h0_buf = mkf(h0);
    let proj_buf = mkf(&proj_folded);
    let projnorm_buf = mkf(&projnorm_folded);
    let ti_buf = mkf(&ti_folded);
    let z = vec![0.0f32; ple_total];
    let ctx_buf = mkf(&z);
    let ctx_n_buf = mkf(&z);
    let pli_buf = mkf(&z);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_pli(
        e,
        k,
        &mut keep,
        &h0_buf,
        &proj_buf,
        &projnorm_buf,
        &ti_buf,
        &ctx_buf,
        &ctx_n_buf,
        &pli_buf,
        hidden,
        ple_total,
        ple_dim,
        n_layers,
        eps,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; ple_total];
    read_buffer_f32(&pli_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone gemma4 logits head: builds buffers, runs [`encode_gemma4_head`] in one
/// command buffer, reads back the `vocab` soft-capped logits. `token_embd_wire` is
/// the vocab-major Q8 embedding table in 34-byte wire blocks (`vocab * hidden/32`
/// blocks). None if Metal unavailable or shapes invalid.
#[cfg(target_os = "macos")]
pub fn try_gemma4_head(
    h_in: &[f32],
    output_norm: &[f32],
    token_embd_wire: &[u8],
    vocab: usize,
    softcap: f32,
    eps: f32,
) -> Option<Vec<f32>> {
    const WIRE: usize = 34;
    let hidden = h_in.len();
    if hidden == 0 || !hidden.is_multiple_of(32) || vocab == 0 || output_norm.len() != hidden {
        return None;
    }
    let bpr_hidden = hidden / 32;
    if token_embd_wire.len() != vocab * bpr_hidden * WIRE {
        return None;
    }
    let k = metal_linear_kernel()?;
    let h_buf = k
        .device
        .new_buffer((hidden * 4) as u64, MTLResourceOptions::StorageModeShared);
    let logits_buf = k
        .device
        .new_buffer((vocab * 4) as u64, MTLResourceOptions::StorageModeShared);
    let embd_buf = k.device.new_buffer(
        token_embd_wire.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    write_buffer_f32(&h_buf, h_in);
    write_buffer_u8(&embd_buf, token_embd_wire);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_head(
        e,
        k,
        &mut keep,
        &h_buf,
        &logits_buf,
        output_norm,
        &embd_buf,
        vocab,
        softcap,
        eps,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; vocab];
    read_buffer_f32(&logits_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Persistent no-copy Metal tied head for Gemma 4 QAT models whose embedding /
/// output table is Q6_K. The 26B Ghost-MoE artifact carries a 605 MB Q6_K tied
/// table; evaluating it on the CPU streams those bytes once per generated token.
/// This wrapper maps the GGUF tensor's file-backed pages directly into a Metal
/// buffer and keeps its activation/logit scratch resident. The parity-sensitive,
/// tiny stages stay on the CPU (2.8K-element RMSNorm + Q8_K quantization before
/// dispatch, scalar soft-cap after readback); the 605 MB ordered Q6_K GEMV runs
/// on Metal in one command buffer and is bit-exact with the CPU row-dot oracle.
///
/// The mapping is retained for the lifetime of the Metal buffer. There is no
/// anonymous 605 MB weight copy: under memory pressure these pages remain clean,
/// file-backed, and evictable. Calls are serialized because the scratch buffers
/// are reused in place; the serving runtime is single-request today, but keeping
/// that invariant here prevents accidental cross-request races later.
#[cfg(target_os = "macos")]
pub(crate) struct Gemma4Q6KHead {
    inner: Mutex<Gemma4Q6KHeadInner>,
    _mmap: std::sync::Arc<crate::wire_mmap::GgufWireMmap>,
}

#[cfg(target_os = "macos")]
struct Gemma4Q6KHeadInner {
    weight: Buffer,
    weight_offset: usize,
    q8k_scales: Buffer,
    q8k_quants: Buffer,
    logits: Buffer,
    matmul_scalar: Buffer,
    output_norm: Vec<f32>,
    eps: f32,
    hidden: usize,
    vocab: usize,
    softcap: f32,
}

#[cfg(target_os = "macos")]
impl Gemma4Q6KHead {
    /// Wrap one vocab-major Q6_K tensor in the existing GGUF mmap. `absolute_offset`
    /// and `byte_len` come from its descriptor. Returns `None` on unavailable Metal,
    /// an invalid tensor shape/range, or a device buffer-size limit smaller than the
    /// tensor. The caller then keeps the established CPU head as a safe fallback.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new(
        mmap: std::sync::Arc<crate::wire_mmap::GgufWireMmap>,
        absolute_offset: u64,
        byte_len: usize,
        output_norm: &[f32],
        vocab: usize,
        softcap: f32,
        eps: f32,
    ) -> Option<Self> {
        const Q6K_VALUES: usize = 256;
        const Q6K_WIRE: usize = 210;
        let hidden = output_norm.len();
        if hidden == 0
            || vocab == 0
            || !hidden.is_multiple_of(Q6K_VALUES)
            || byte_len
                != vocab
                    .checked_mul(hidden / Q6K_VALUES)?
                    .checked_mul(Q6K_WIRE)?
        {
            return None;
        }

        let kernel = metal_linear_kernel()?;
        let tensor = crate::wire_mmap::wire_mmap_tensors(
            &mmap,
            &[(absolute_offset, byte_len)],
            kernel.device.max_buffer_length() as usize,
        )
        .ok()?
        .pop()?;
        // SAFETY: `wire_mmap_tensors` returns a page-aligned window entirely
        // inside `mmap`, which this struct retains for the buffer's lifetime.
        let weight_ptr = unsafe { mmap.base_ptr().add(tensor.window.aligned_offset as usize) };
        // Default: file-backed no-copy — zero load cost, but the pages are
        // clean/evictable, so heavy expert paging can silently turn the head
        // sweep into per-token SSD refaults. The opt-in resident copy pins the
        // table in an owned allocation at the cost of one ~600 MB load copy.
        let resident_head = std::env::var("CAMELID_GEMMA4_GHOST_METAL_HEAD_RESIDENT")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"));
        let weight = if resident_head {
            let owned = kernel.device.new_buffer(
                tensor.window.len as u64,
                MTLResourceOptions::StorageModeShared,
            );
            // SAFETY: source window is `len` readable bytes inside the mmap;
            // destination is a fresh shared buffer of exactly `len` bytes.
            unsafe {
                std::ptr::copy_nonoverlapping(
                    weight_ptr,
                    owned.contents().cast::<u8>(),
                    tensor.window.len as usize,
                );
            }
            owned
        } else {
            kernel.device.new_buffer_with_bytes_no_copy(
                weight_ptr.cast(),
                tensor.window.len as u64,
                MTLResourceOptions::StorageModeShared,
                None,
            )
        };
        let shared = |bytes: usize| {
            kernel
                .device
                .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
        };
        let n_superblocks = hidden / Q6K_VALUES;
        let q8k_scales = shared(n_superblocks * std::mem::size_of::<f32>());
        let q8k_quants = shared(hidden);
        let logits = shared(vocab * std::mem::size_of::<f32>());
        let matmul_scalar = shared(12);
        unsafe {
            let m = matmul_scalar.contents() as *mut u32;
            *m = n_superblocks as u32;
            *m.add(1) = vocab as u32;
            *m.add(2) = 1;
        }
        Some(Self {
            inner: Mutex::new(Gemma4Q6KHeadInner {
                weight,
                weight_offset: tensor.window_offset,
                q8k_scales,
                q8k_quants,
                logits,
                matmul_scalar,
                output_norm: output_norm.to_vec(),
                eps,
                hidden,
                vocab,
                softcap,
            }),
            _mmap: mmap,
        })
    }

    /// Evaluate the final hidden state through the tied head. `None` is a soft
    /// failure: callers preserve the CPU implementation as the correctness path.
    pub(crate) fn forward(&self, hidden: &[f32]) -> Option<Vec<f32>> {
        let state = self.inner.lock().ok()?;
        if hidden.len() != state.hidden {
            return None;
        }
        let kernel = metal_linear_kernel()?;
        // Keep the 2.8K-element norm on the CPU: its established scalar
        // left-fold is the Gemma 4 parity oracle, whereas a tree-reduced GPU
        // norm can move Q8_K scales by one ULP and flip a near-tied argmax.
        // The 605 MB Q6_K projection remains entirely on Metal.
        let normalized =
            crate::gemma4_runtime::rms_norm(hidden, Some(&state.output_norm), state.eps);
        // The strict Metal quantizer reproduces every Q8_K integer code, but its
        // reciprocal can still differ by one ULP from Rust on Apple GPUs. Upload
        // the CPU-oracle activation instead (11 scales + 2816 bytes on the 26B
        // row) so exact ties retain the CPU greedy choice. The 605 MB projection
        // itself remains entirely on Metal.
        let q8 = crate::inference::quantize_q8_k_blocks(&normalized);
        let scales: Vec<f32> = q8.iter().map(|block| block.d).collect();
        let mut quants = Vec::with_capacity(state.hidden);
        for block in &q8 {
            quants.extend_from_slice(&block.qs);
        }
        write_buffer_f32(&state.q8k_scales, &scales);
        unsafe {
            std::ptr::copy_nonoverlapping(
                quants.as_ptr(),
                state.q8k_quants.contents().cast::<i8>(),
                quants.len(),
            );
        }
        let started = std::time::Instant::now();
        let cb = kernel.queue.new_command_buffer();
        let encoder = cb.new_compute_command_encoder();
        let n_superblocks = state.hidden / 256;
        encode_q6k_ordered_single(
            encoder,
            kernel,
            &state.q8k_scales,
            &state.q8k_quants,
            &state.weight,
            state.weight_offset as u64,
            &state.logits,
            &state.matmul_scalar,
            n_superblocks,
            state.vocab,
        );
        encoder.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        if cb.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }

        if std::env::var("CAMELID_GEMMA4_METAL_HEAD_TIMING")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
        {
            let (gpu_us, kernel_us) = command_buffer_gpu_times_us(&cb.to_owned());
            eprintln!(
                "[gemma4-metal-head] Q6_K vocab={} wall={}us gpu={}us kernel={}us",
                state.vocab,
                started.elapsed().as_micros(),
                gpu_us,
                kernel_us,
            );
        }
        let mut output = vec![0.0f32; state.vocab];
        read_buffer_f32(&state.logits, &mut output);
        // Rust's scalar tanh is the established Gemma 4 oracle. Metal's tanh
        // differs by a few ULP and can alter the lowest-index tie-break after
        // saturation, even when the pre-cap Q6_K projection agrees. This 1 MB
        // elementwise tail is tiny beside the 605 MB matrix sweep.
        if state.softcap.is_finite() && state.softcap > 0.0 {
            crate::inference::gemma4::soft_cap_in_place(&mut output, state.softcap);
        }
        Some(output)
    }
}

/// A resident gemma4 model ready to decode: all weights (layers + tied `token_embd`)
/// stay GPU-resident, the per-owning-layer KV caches PERSIST across tokens (allocated
/// once, scattered one slot per token), and the hidden/logits buffers are reused. Each
/// [`Gemma4ResidentModel::forward_token`] runs the whole token graph in ONE command
/// buffer with no per-token weight copy — unlike [`try_gemma4_forward`] (a stateless
/// test helper that rebuilds the cache and re-copies the 0.7GB embedding every call).
/// Resident state for computing the per-token PLE input `pli` ON the GPU (replacing
/// the ~12ms/token CPU prep — a 110MB f32 matvec). `proj`/`projnorm` have the gemma
/// constants folded in (proj * hidden^-0.5, proj_norm * FRAC_1_SQRT_2); `ti` is
/// written per token (the per_layer_token_embd row * ple_dim^0.5 * FRAC_1_SQRT_2).
#[cfg(target_os = "macos")]
struct Gemma4PliResident {
    proj: Buffer,
    projnorm: Buffer,
    ti: Buffer,
    ctx: Buffer,
    ctx_n: Buffer,
    pli: Buffer,
    ple_total: usize,
    ple_dim: usize,
}

#[cfg(target_os = "macos")]
pub struct Gemma4ResidentModel {
    layers: Vec<Gemma4ResidentLayer>,
    ple: Vec<Option<Gemma4ResidentPle>>,
    /// Per-layer `layer_output_scale` (1.0 when the tensor is absent). E-series
    /// layers apply it inside the PLE encode (`Gemma4ResidentPle.output_scale`,
    /// same tensor); dense rows (12B-class, no PLE) apply it standalone at the
    /// end of the layer — the reference multiplies it UNCONDITIONALLY.
    layer_scales: Vec<f32>,
    /// Per-layer resident PLE matrix buffers (inp_gate, proj, post_norm), uploaded
    /// once so forward_token doesn't re-copy ~220MB of f32 matrices every token.
    ple_bufs: Vec<Option<(Buffer, Buffer, Buffer)>>,
    /// Resident PLE `pli` computation (set via `set_pli`); when present, forward_token
    /// computes `pli` on the GPU from the input embedding instead of on the CPU.
    pli_res: Option<Gemma4PliResident>,
    owns_kv: Vec<bool>,
    kv_source: Vec<usize>,
    caches: Vec<Option<(Buffer, Buffer)>>,
    token_embd: Buffer,
    output_norm: Vec<f32>,
    buf_a: Buffer,
    buf_b: Buffer,
    mid: Buffer,
    logits: Buffer,
    hidden: usize,
    vocab: usize,
    softcap: f32,
    eps: f32,
    max_positions: usize,
    scale: f32,
}

#[cfg(target_os = "macos")]
impl Gemma4ResidentModel {
    /// Build the resident model. `token_embd_wire` is the vocab-major Q8 table in
    /// 34-byte wire blocks for the GPU logits head (copied once into a resident buffer;
    /// in the production runtime pass a nocopy WirePages buffer instead). Pass an EMPTY
    /// slice on the QAT hybrid lane (Q6_K head runs on the CPU) — no head buffer is
    /// allocated and only `forward_token_hidden` is valid. KV caches are allocated for
    /// owning layers (`owns_kv[l]`) sized to that layer's head_dim. None on bad shapes.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        layers: Vec<Gemma4ResidentLayer>,
        ple: Vec<Option<Gemma4ResidentPle>>,
        layer_scales: Vec<f32>,
        owns_kv: Vec<bool>,
        kv_source: Vec<usize>,
        token_embd_wire: &[u8],
        output_norm: Vec<f32>,
        hidden: usize,
        vocab: usize,
        softcap: f32,
        eps: f32,
        max_positions: usize,
        scale: f32,
    ) -> Option<Self> {
        let n = layers.len();
        if n == 0
            || ple.len() != n
            || layer_scales.len() != n
            || owns_kv.len() != n
            || kv_source.len() != n
            || output_norm.len() != hidden
            || vocab == 0
            || max_positions == 0
        {
            return None;
        }
        let k = metal_linear_kernel()?;
        let mkbuf = |bytes: usize| {
            k.device
                .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
        };
        let mut caches = Vec::with_capacity(n);
        for (l, layer) in layers.iter().enumerate() {
            if owns_kv[l] {
                let len = layer.n_kv_heads * max_positions * layer.head_dim;
                caches.push(Some((mkbuf(len * 4), mkbuf(len * 4))));
            } else {
                caches.push(None);
            }
        }
        // Empty wire = QAT hybrid lane: the Q6_K head runs on the CPU, so don't upload
        // the (large) tied table to the GPU. A 1-byte placeholder keeps the field valid;
        // forward_inner only reads it on the want_head path, which the hybrid never takes.
        let token_embd = mkbuf(token_embd_wire.len().max(1));
        if !token_embd_wire.is_empty() {
            write_buffer_u8(&token_embd, token_embd_wire);
        }
        // Upload each layer's PLE matrices once into resident buffers.
        let upload = |v: &[f32]| {
            let b = mkbuf(v.len() * 4);
            write_buffer_f32(&b, v);
            b
        };
        let ple_bufs: Vec<Option<(Buffer, Buffer, Buffer)>> = ple
            .iter()
            .map(|p| {
                p.as_ref()
                    .map(|p| (upload(&p.inp_gate), upload(&p.proj), upload(&p.post_norm)))
            })
            .collect();
        Some(Self {
            layers,
            ple,
            layer_scales,
            ple_bufs,
            pli_res: None,
            owns_kv,
            kv_source,
            caches,
            token_embd,
            output_norm,
            buf_a: mkbuf(hidden * 4),
            buf_b: mkbuf(hidden * 4),
            mid: mkbuf(hidden * 4),
            logits: mkbuf(vocab * 4),
            hidden,
            vocab,
            softcap,
            eps,
            max_positions,
            scale,
        })
    }

    /// Enable on-GPU `pli` computation: uploads the (constant-folded) PLE projection
    /// matrices once. After this, `forward_token` computes `pli` from the input
    /// embedding on the GPU (passing `ti` per token) instead of relying on CPU prep.
    /// `proj` = per_layer_model_proj `[ple_total][hidden]`, `proj_norm` = `[ple_dim]`.
    pub fn set_pli(&mut self, proj: &[f32], proj_norm: &[f32], ple_dim: usize) -> bool {
        let n_layers = self.layers.len();
        let ple_total = n_layers * ple_dim;
        if proj.len() != ple_total * self.hidden || proj_norm.len() != ple_dim {
            return false;
        }
        let Some(k) = metal_linear_kernel() else {
            return false;
        };
        let frac = std::f32::consts::FRAC_1_SQRT_2;
        let proj_scale = (self.hidden as f32).powf(-0.5);
        let proj_folded: Vec<f32> = proj.iter().map(|v| v * proj_scale).collect();
        let projnorm_folded: Vec<f32> = proj_norm.iter().map(|v| v * frac).collect();
        let up = |v: &[f32]| {
            let b = k
                .device
                .new_buffer((v.len() * 4) as u64, MTLResourceOptions::StorageModeShared);
            write_buffer_f32(&b, v);
            b
        };
        let alloc = |n: usize| {
            k.device
                .new_buffer((n * 4) as u64, MTLResourceOptions::StorageModeShared)
        };
        self.pli_res = Some(Gemma4PliResident {
            proj: up(&proj_folded),
            projnorm: up(&projnorm_folded),
            ti: alloc(ple_total),
            ctx: alloc(ple_total),
            ctx_n: alloc(ple_total),
            pli: alloc(ple_total),
            ple_total,
            ple_dim,
        });
        true
    }

    /// Decode one token at absolute `position`: writes `h0` (the position's scaled
    /// input embedding) into the resident hidden buffer, runs all layers (each scatters
    /// its K/V into the PERSISTENT cache at `position`) + PLE + head in ONE command
    /// buffer, and returns the `vocab` soft-capped logits. `inputs[l]` carries this
    /// layer's RoPE tables, `pli`, and window start (CPU-computed for `position`).
    pub fn forward_token(
        &self,
        h0: &[f32],
        inputs: &[Gemma4TokenLayerInput],
        ti: &[f32],
        position: usize,
    ) -> Option<Vec<f32>> {
        self.forward_inner(h0, inputs, ti, position, true)
    }

    /// Like [`Self::forward_token`] but stops BEFORE the GPU logits head and returns the
    /// final decoder hidden state (the head's input). The QAT hybrid lane uses this: the
    /// tied head is Q6_K, which has no GPU kernel, so the head runs on the CPU instead.
    pub fn forward_token_hidden(
        &self,
        h0: &[f32],
        inputs: &[Gemma4TokenLayerInput],
        ti: &[f32],
        position: usize,
    ) -> Option<Vec<f32>> {
        self.forward_inner(h0, inputs, ti, position, false)
    }

    #[allow(clippy::needless_range_loop)] // layer index `l` indexes several parallel arrays
    fn forward_inner(
        &self,
        h0: &[f32],
        inputs: &[Gemma4TokenLayerInput],
        ti: &[f32],
        position: usize,
        want_head: bool,
    ) -> Option<Vec<f32>> {
        let n = self.layers.len();
        if h0.len() != self.hidden || inputs.len() != n || position >= self.max_positions {
            return None;
        }
        let k = metal_linear_kernel()?;
        let filled = position + 1;
        write_buffer_f32(&self.buf_a, h0);
        let mut keep = Vec::new();
        let cb = k.queue.new_command_buffer();
        let e = cb.new_compute_command_encoder();
        // Compute this token's pli on the GPU (folded constants) before the layers.
        if let Some(p) = &self.pli_res {
            if ti.len() != p.ple_total {
                return None;
            }
            write_buffer_f32(&p.ti, ti);
            encode_gemma4_pli(
                e,
                k,
                &mut keep,
                &self.buf_a,
                &p.proj,
                &p.projnorm,
                &p.ti,
                &p.ctx,
                &p.ctx_n,
                &p.pli,
                self.hidden,
                p.ple_total,
                p.ple_dim,
                n,
                self.eps,
            );
        }
        let mut from_a = true;
        for l in 0..n {
            let (in_buf, out_buf) = if from_a {
                (&self.buf_a, &self.buf_b)
            } else {
                (&self.buf_b, &self.buf_a)
            };
            let src = if self.owns_kv[l] {
                l
            } else {
                self.kv_source[l]
            };
            let (ck, cv) = self.caches[src].as_ref()?;
            let inp = &inputs[l];
            encode_gemma4_layer(
                e,
                k,
                &mut keep,
                &self.layers[l],
                in_buf,
                &self.mid,
                out_buf,
                &inp.cos_t,
                &inp.sin_t,
                ck,
                cv,
                self.max_positions,
                position,
                filled,
                inp.window_start,
                self.scale,
                self.owns_kv[l],
            );
            if let (Some(p), Some((ig, pj, pn)), Some(pr)) =
                (&self.ple[l], &self.ple_bufs[l], &self.pli_res)
            {
                encode_gemma4_ple(
                    e,
                    k,
                    &mut keep,
                    out_buf,
                    &pr.pli,
                    l * pr.ple_dim,
                    ig,
                    pj,
                    pn,
                    p.output_scale,
                    self.eps,
                    self.hidden,
                    pr.ple_dim,
                );
            } else if self.layer_scales[l] != 1.0 {
                // Dense rows (no PLE) still carry layer_output_scale — the
                // reference multiplies the layer output unconditionally.
                let sc = pool_get(k, 8);
                unsafe {
                    let p = sc.contents() as *mut u8;
                    *(p as *mut u32) = self.hidden as u32;
                    *(p.add(4) as *mut f32) = self.layer_scales[l];
                }
                encode_scale_f32(e, k, out_buf, out_buf, &sc, self.hidden);
                keep.push(sc);
            }
            from_a = !from_a;
        }
        let final_buf = if from_a { &self.buf_a } else { &self.buf_b };
        // QAT hybrid (`want_head == false`): skip the GPU head and read the final hidden
        // back so the CPU can run the Q6_K tied head. Otherwise encode the Q8 head and
        // read the soft-capped logits.
        if want_head {
            encode_gemma4_head(
                e,
                k,
                &mut keep,
                final_buf,
                &self.logits,
                &self.output_norm,
                &self.token_embd,
                self.vocab,
                self.softcap,
                self.eps,
            );
        }
        e.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        let out = if want_head {
            let mut out = vec![0.0f32; self.vocab];
            read_buffer_f32(&self.logits, &mut out);
            out
        } else {
            let mut h = vec![0.0f32; self.hidden];
            read_buffer_f32(final_buf, &mut h);
            h
        };
        // Return the per-token scratch to the pool so the next token reuses it instead
        // of allocating ~hundreds of fresh Metal buffers (safe: the command buffer has
        // completed). Persistent weights/caches/token_embd are NOT in `keep`.
        pool_recycle(k, keep);
        Some(out)
    }
}

/// One layer's f32 PLE matrices (E-series only; `None` per layer for dense models).
/// Output-major like the CPU `f32_matvec`: `inp_gate` is `[ple_dim][hidden]`, `proj`
/// is `[hidden][ple_dim]`, `post_norm` is `[hidden]`.
pub struct Gemma4ResidentPle {
    pub inp_gate: Vec<f32>,
    pub proj: Vec<f32>,
    pub post_norm: Vec<f32>,
    pub output_scale: f32,
}

/// Per-token CPU-computed inputs the GPU forward needs for one layer: the dual-θ
/// RoPE tables for this position, the PLE per-layer input `pli`, and the resolved
/// attention window start (`max(0, filled-window)` for sliding, 0 for global).
pub struct Gemma4TokenLayerInput {
    pub cos_t: Vec<f32>,
    pub sin_t: Vec<f32>,
    pub pli: Vec<f32>,
    pub window_start: usize,
}

/// Drive a full gemma4 token forward on the GPU in ONE command buffer:
/// `h0` (the position's scaled input embedding) → N decoder layers (each
/// [`encode_gemma4_layer`] + optional [`encode_gemma4_ple`]) → [`encode_gemma4_head`]
/// → soft-capped logits. Cross-layer KV sharing: owning layers (`owns_kv[l]`) hold
/// their own cache (built from `cache_k_init[l]`/`cache_v_init[l]`); shared layers
/// read `kv_source[l]`'s cache. The caller computes per-token data (embedding,
/// RoPE tables, `pli`, window starts) on the CPU — see [`Gemma4TokenLayerInput`].
/// Returns the `vocab` logits. None if Metal unavailable or shapes invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_forward(
    layers: &[Gemma4ResidentLayer],
    ple: &[Option<Gemma4ResidentPle>],
    owns_kv: &[bool],
    kv_source: &[usize],
    inputs: &[Gemma4TokenLayerInput],
    cache_k_init: &[Option<Vec<f32>>],
    cache_v_init: &[Option<Vec<f32>>],
    h0: &[f32],
    output_norm: &[f32],
    token_embd_wire: &[u8],
    vocab: usize,
    softcap: f32,
    eps: f32,
    max_positions: usize,
    write_position: usize,
    filled: usize,
    scale: f32,
) -> Option<Vec<f32>> {
    let n = layers.len();
    let hidden = h0.len();
    if n == 0
        || hidden == 0
        || ple.len() != n
        || owns_kv.len() != n
        || kv_source.len() != n
        || inputs.len() != n
        || cache_k_init.len() != n
        || cache_v_init.len() != n
        || output_norm.len() != hidden
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
    };
    // Build a cache buffer pair for each owning layer; shared layers reuse a source's.
    let mut caches: Vec<Option<(Buffer, Buffer)>> = Vec::with_capacity(n);
    for l in 0..n {
        if owns_kv[l] {
            let ck = cache_k_init[l].as_ref()?;
            let cv = cache_v_init[l].as_ref()?;
            let len = layers[l].n_kv_heads * max_positions * layers[l].head_dim;
            if ck.len() != len || cv.len() != len {
                return None;
            }
            let ckb = mkbuf(len * 4);
            let cvb = mkbuf(len * 4);
            write_buffer_f32(&ckb, ck);
            write_buffer_f32(&cvb, cv);
            caches.push(Some((ckb, cvb)));
        } else {
            caches.push(None);
        }
    }
    let buf_a = mkbuf(hidden * 4);
    let buf_b = mkbuf(hidden * 4);
    let mid = mkbuf(hidden * 4);
    let logits_buf = mkbuf(vocab * 4);
    let embd_buf = mkbuf(token_embd_wire.len());
    write_buffer_f32(&buf_a, h0);
    write_buffer_u8(&embd_buf, token_embd_wire);

    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    let mut from_a = true;
    for l in 0..n {
        let (in_buf, out_buf) = if from_a {
            (&buf_a, &buf_b)
        } else {
            (&buf_b, &buf_a)
        };
        let src = if owns_kv[l] { l } else { kv_source[l] };
        let (ck, cv) = caches[src].as_ref()?;
        let inp = &inputs[l];
        encode_gemma4_layer(
            e,
            k,
            &mut keep,
            &layers[l],
            in_buf,
            &mid,
            out_buf,
            &inp.cos_t,
            &inp.sin_t,
            ck,
            cv,
            max_positions,
            write_position,
            filled,
            inp.window_start,
            scale,
            owns_kv[l],
        );
        if let Some(p) = &ple[l] {
            let mkf = |v: &[f32]| {
                let b = k
                    .device
                    .new_buffer((v.len() * 4) as u64, MTLResourceOptions::StorageModeShared);
                write_buffer_f32(&b, v);
                b
            };
            let (ig, pj, pn) = (mkf(&p.inp_gate), mkf(&p.proj), mkf(&p.post_norm));
            let pli_buf = mkf(&inp.pli);
            encode_gemma4_ple(
                e,
                k,
                &mut keep,
                out_buf,
                &pli_buf,
                0,
                &ig,
                &pj,
                &pn,
                p.output_scale,
                eps,
                hidden,
                inp.pli.len(),
            );
            keep.push(pli_buf);
            keep.extend([ig, pj, pn]);
        }
        from_a = !from_a;
    }
    // After n layers the final hidden is the last out_buf (buf_b iff n is odd).
    let final_buf = if from_a { &buf_a } else { &buf_b };
    encode_gemma4_head(
        e,
        k,
        &mut keep,
        final_buf,
        &logits_buf,
        output_norm,
        &embd_buf,
        vocab,
        softcap,
        eps,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; vocab];
    read_buffer_f32(&logits_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone full gemma4 layer: builds buffers (incl. a prefilled cache), runs
/// [`encode_gemma4_layer`] (attention → FFN) in one command buffer, reads back the
/// hidden output. For validating the full-layer chain against CPU. None if Metal
/// unavailable or shapes invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_layer(
    layer: &Gemma4ResidentLayer,
    h_in: &[f32],
    cos_t: &[f32],
    sin_t: &[f32],
    cache_k_init: &[f32],
    cache_v_init: &[f32],
    max_positions: usize,
    write_position: usize,
    filled: usize,
    window_start: usize,
    scale: f32,
    owns_kv: bool,
) -> Option<Vec<f32>> {
    let hidden = h_in.len();
    let cache_len = layer.n_kv_heads * max_positions * layer.head_dim;
    if hidden == 0 || cache_k_init.len() != cache_len || cache_v_init.len() != cache_len {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = mkbuf(hidden * 4);
    let mid_buf = mkbuf(hidden * 4);
    let out_buf = mkbuf(hidden * 4);
    let cache_k = mkbuf(cache_len * 4);
    let cache_v = mkbuf(cache_len * 4);
    write_buffer_f32(&in_buf, h_in);
    write_buffer_f32(&cache_k, cache_k_init);
    write_buffer_f32(&cache_v, cache_v_init);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_layer(
        e,
        k,
        &mut keep,
        layer,
        &in_buf,
        &mid_buf,
        &out_buf,
        cos_t,
        sin_t,
        &cache_k,
        &cache_v,
        max_positions,
        write_position,
        filled,
        window_start,
        scale,
        owns_kv,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    drop(keep);
    Some(out)
}

/// GPU elementwise binary op helper for residual add / silu-mul (same buffer shape).
#[cfg(target_os = "macos")]
fn try_binary_elementwise_f32(
    pipeline: &ComputePipelineState,
    lhs: &[f32],
    rhs: &[f32],
) -> Option<Vec<f32>> {
    if lhs.is_empty() || lhs.len() != rhs.len() {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let n = lhs.len();
    let byte_len = std::mem::size_of_val(lhs) as u64;
    let lhs_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let rhs_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let out_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let n_buf = kernel
        .device
        .new_buffer(4, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&lhs_buf, lhs);
    write_buffer_f32(&rhs_buf, rhs);
    unsafe {
        *(n_buf.contents() as *mut u32) = n as u32;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(pipeline);
    encoder.set_buffer(0, Some(&lhs_buf), 0);
    encoder.set_buffer(1, Some(&rhs_buf), 0);
    encoder.set_buffer(2, Some(&out_buf), 0);
    encoder.set_buffer(3, Some(&n_buf), 0);
    let width = pipeline.thread_execution_width().max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: (n as u64).div_ceil(width),
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; n];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// GPU residual add: output = a + b. None if Metal unavailable.
#[cfg(target_os = "macos")]
pub fn try_residual_add_f32(a: &[f32], b: &[f32]) -> Option<Vec<f32>> {
    let kernel = metal_linear_kernel()?;
    try_binary_elementwise_f32(&kernel.residual_add_pipeline, a, b)
}

/// GPU gated activation: output = (gate / (1 + e^-gate)) * up. None if Metal unavailable.
#[cfg(target_os = "macos")]
pub fn try_silu_mul_f32(gate: &[f32], up: &[f32]) -> Option<Vec<f32>> {
    let kernel = metal_linear_kernel()?;
    try_binary_elementwise_f32(&kernel.silu_mul_pipeline, gate, up)
}

/// GPU GeGLU activation (Gemma MLP): output = gelu_pytorch_tanh(gate) * up. Same
/// buffer shape as silu-mul. None if Metal unavailable.
#[cfg(target_os = "macos")]
pub fn try_gelu_mul_f32(gate: &[f32], up: &[f32]) -> Option<Vec<f32>> {
    let kernel = metal_linear_kernel()?;
    try_binary_elementwise_f32(&kernel.gelu_mul_pipeline, gate, up)
}

/// GPU final-logit soft-cap: output = cap * tanh(input / cap). A non-finite or
/// non-positive cap returns the input unchanged (matches the CPU reference). None
/// if Metal unavailable.
#[cfg(target_os = "macos")]
pub fn try_soft_cap_f32(input: &[f32], cap: f32) -> Option<Vec<f32>> {
    if input.is_empty() {
        return None;
    }
    if !cap.is_finite() || cap <= 0.0 {
        return Some(input.to_vec());
    }
    let kernel = metal_linear_kernel()?;
    let n = input.len();
    let byte_len = std::mem::size_of_val(input) as u64;
    let in_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let out_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let n_buf = kernel
        .device
        .new_buffer(4, MTLResourceOptions::StorageModeShared);
    let cap_buf = kernel
        .device
        .new_buffer(4, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&in_buf, input);
    unsafe {
        *(n_buf.contents() as *mut u32) = n as u32;
        *(cap_buf.contents() as *mut f32) = cap;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.soft_cap_pipeline);
    encoder.set_buffer(0, Some(&in_buf), 0);
    encoder.set_buffer(1, Some(&out_buf), 0);
    encoder.set_buffer(2, Some(&n_buf), 0);
    encoder.set_buffer(3, Some(&cap_buf), 0);
    let width = kernel.soft_cap_pipeline.thread_execution_width().max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: (n as u64).div_ceil(width),
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; n];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// GPU forward RoPE rotation across all heads, applied to a copy of `data`. The
/// cos/sin tables (one entry per rotated pair) come from the CPU's frequency/scaling
/// math; this only performs the rotation. `split_half_pairing` selects split-half vs
/// adjacent even/odd. None if Metal is unavailable.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_rope_rotate_f32(
    data: &[f32],
    cos_table: &[f32],
    sin_table: &[f32],
    head_count: usize,
    head_dim: usize,
    half_rope: usize,
    split_half_pairing: bool,
) -> Option<Vec<f32>> {
    if head_count == 0
        || half_rope == 0
        || data.len() != head_count * head_dim
        || cos_table.len() != half_rope
        || sin_table.len() != half_rope
        || half_rope * 2 > head_dim
    {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let data_bytes = std::mem::size_of_val(data) as u64;
    let table_bytes = std::mem::size_of_val(cos_table) as u64;
    let data_buf = kernel
        .device
        .new_buffer(data_bytes, MTLResourceOptions::StorageModeShared);
    let cos_buf = kernel
        .device
        .new_buffer(table_bytes, MTLResourceOptions::StorageModeShared);
    let sin_buf = kernel
        .device
        .new_buffer(table_bytes, MTLResourceOptions::StorageModeShared);
    let scalar_buf = kernel
        .device
        .new_buffer(16, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&data_buf, data);
    write_buffer_f32(&cos_buf, cos_table);
    write_buffer_f32(&sin_buf, sin_table);
    unsafe {
        let p = scalar_buf.contents() as *mut u32;
        *p = head_count as u32;
        *p.add(1) = head_dim as u32;
        *p.add(2) = half_rope as u32;
        *p.add(3) = u32::from(split_half_pairing);
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.rope_rotate_pipeline);
    encoder.set_buffer(0, Some(&data_buf), 0);
    encoder.set_buffer(1, Some(&cos_buf), 0);
    encoder.set_buffer(2, Some(&sin_buf), 0);
    encoder.set_buffer(3, Some(&scalar_buf), 0);
    encoder.set_buffer(4, Some(&scalar_buf), 4);
    encoder.set_buffer(5, Some(&scalar_buf), 8);
    encoder.set_buffer(6, Some(&scalar_buf), 12);
    let total = (head_count * half_rope) as u64;
    let width = kernel.rope_rotate_pipeline.thread_execution_width().max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: total.div_ceil(width),
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; data.len()];
    read_buffer_f32(&data_buf, &mut out);
    Some(out)
}

/// GPU single-query (decode) causal attention over a contiguous KV cache laid out
/// [kv_head][position][head_dim]. GQA via `group = n_heads / n_kv_heads`. Returns the
/// per-head context [n_heads*head_dim], or None if Metal is unavailable. Mirrors
/// attention_context_for_head_into. Thin wrapper over `try_attention_decode_strided_f32`.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_attention_decode_f32(
    query: &[f32],
    keys: &[f32],
    values: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
) -> Option<Vec<f32>> {
    if head_dim == 0
        || position_count == 0
        || keys.len() != n_kv_heads * position_count * head_dim
        || values.len() != keys.len()
    {
        return None;
    }
    try_attention_decode_strided_f32(
        query,
        keys,
        values,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        scale,
        head_dim,
        position_count * head_dim,
        0,
    )
}

/// GPU single-query (decode) causal attention reading the KV cache with explicit strides:
/// the K/V element at (kv_head, position, d) is at `kv_base_offset + kv_head*kv_head_stride
/// + position*position_stride + d` (strides in floats) in `keys`/`values`. This lets the
/// kernel read a per-layer slice of an interleaved `[position][layer][kv_head][head_dim]`
/// cache directly, with no CPU repack. GQA via `group = n_heads / n_kv_heads`. Returns the
/// per-head context `[n_heads*head_dim]`, or None if Metal is unavailable / inputs invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_attention_decode_strided_f32(
    query: &[f32],
    keys: &[f32],
    values: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
    position_stride: usize,
    kv_head_stride: usize,
    kv_base_offset: usize,
) -> Option<Vec<f32>> {
    attention_decode_strided_f32_variant(
        query,
        keys,
        values,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        scale,
        position_stride,
        kv_head_stride,
        kv_base_offset,
        false,
    )
}

/// Same computation as [`try_attention_decode_strided_f32`], forced through the
/// three-dispatch `encode_attention_split3` encode. Test-only: production picks the
/// encode via `attn_split3_enabled()`, and the two must agree bit-for-bit.
#[cfg(all(target_os = "macos", test))]
#[allow(clippy::too_many_arguments)]
fn try_attention_decode_strided_split3_f32(
    query: &[f32],
    keys: &[f32],
    values: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
    position_stride: usize,
    kv_head_stride: usize,
    kv_base_offset: usize,
) -> Option<Vec<f32>> {
    attention_decode_strided_f32_variant(
        query,
        keys,
        values,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        scale,
        position_stride,
        kv_head_stride,
        kv_base_offset,
        true,
    )
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn attention_decode_strided_f32_variant(
    query: &[f32],
    keys: &[f32],
    values: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
    position_stride: usize,
    kv_head_stride: usize,
    kv_base_offset: usize,
    split3: bool,
) -> Option<Vec<f32>> {
    // Largest float index the kernel will touch in keys/values (last head, last position).
    // saturating_sub keeps this panic-free for zero inputs, which the checks below reject.
    let max_index = kv_base_offset
        + n_kv_heads.saturating_sub(1) * kv_head_stride
        + position_count.saturating_sub(1) * position_stride
        + head_dim.saturating_sub(1);
    if n_heads == 0
        || n_kv_heads == 0
        || head_dim == 0
        || position_count == 0
        || !n_heads.is_multiple_of(n_kv_heads)
        || query.len() != n_heads * head_dim
        || values.len() != keys.len()
        || keys.len() <= max_index
    {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let group = (n_heads / n_kv_heads) as u32;
    let new = |bytes: u64| {
        kernel
            .device
            .new_buffer(bytes, MTLResourceOptions::StorageModeShared)
    };
    let query_buf = new(std::mem::size_of_val(query) as u64);
    let keys_buf = new(std::mem::size_of_val(keys) as u64);
    let values_buf = new(std::mem::size_of_val(values) as u64);
    let scores_buf = new((n_heads * position_count * 4) as u64);
    let output_buf = new((n_heads * head_dim * 4) as u64);
    let scalar_buf = new(32);
    write_buffer_f32(&query_buf, query);
    write_buffer_f32(&keys_buf, keys);
    write_buffer_f32(&values_buf, values);
    unsafe {
        let p = scalar_buf.contents() as *mut u8;
        *(p as *mut u32) = n_heads as u32;
        *(p.add(4) as *mut u32) = head_dim as u32;
        *(p.add(8) as *mut u32) = position_count as u32;
        *(p.add(12) as *mut u32) = group;
        *(p.add(16) as *mut f32) = scale;
        *(p.add(20) as *mut u32) = position_stride as u32;
        *(p.add(24) as *mut u32) = kv_head_stride as u32;
        *(p.add(28) as *mut u32) = kv_base_offset as u32;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    if split3 {
        let denom_buf = new((n_heads * 4).max(4) as u64);
        let blocks_buf = new(8);
        encode_attention_split3(
            encoder,
            kernel,
            &query_buf,
            &keys_buf,
            &values_buf,
            &scores_buf,
            &denom_buf,
            &output_buf,
            &scalar_buf,
            &blocks_buf,
            n_heads,
            head_dim,
            position_count,
            0,
            0,
        );
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();
        let mut out = vec![0.0f32; n_heads * head_dim];
        read_buffer_f32(&output_buf, &mut out);
        return Some(out);
    }
    encoder.set_compute_pipeline_state(&kernel.attention_decode_pipeline);
    encoder.set_buffer(0, Some(&query_buf), 0);
    encoder.set_buffer(1, Some(&keys_buf), 0);
    encoder.set_buffer(2, Some(&values_buf), 0);
    encoder.set_buffer(3, Some(&scores_buf), 0);
    encoder.set_buffer(4, Some(&output_buf), 0);
    encoder.set_buffer(5, Some(&scalar_buf), 0);
    encoder.set_buffer(6, Some(&scalar_buf), 4);
    encoder.set_buffer(7, Some(&scalar_buf), 8);
    encoder.set_buffer(8, Some(&scalar_buf), 12);
    encoder.set_buffer(9, Some(&scalar_buf), 16);
    encoder.set_buffer(10, Some(&scalar_buf), 20);
    encoder.set_buffer(11, Some(&scalar_buf), 24);
    encoder.set_buffer(12, Some(&scalar_buf), 28);
    // One threadgroup per head, a single 32-lane SIMD group cooperating within it.
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: n_heads as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 32,
            height: 1,
            depth: 1,
        },
    );
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; n_heads * head_dim];
    read_buffer_f32(&output_buf, &mut out);
    Some(out)
}

/// GPU Q8_0 quantization of an f32 row (length a multiple of 32). Returns the per-block
/// scales (f32) and quants (i8) in the layout the Q8 block matmul consumes — the
/// on-GPU equivalent of the CPU activation quantizer, so activations produced on-GPU
/// can feed the matmul without a CPU round-trip. None if Metal is unavailable.
#[cfg(target_os = "macos")]
pub fn try_quantize_q8_0_f32(input: &[f32]) -> Option<(Vec<f32>, Vec<i8>)> {
    if input.is_empty() || !input.len().is_multiple_of(32) {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let n_blocks = input.len() / 32;
    let in_buf = kernel.device.new_buffer(
        std::mem::size_of_val(input) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let scales_buf = kernel
        .device
        .new_buffer((n_blocks * 4) as u64, MTLResourceOptions::StorageModeShared);
    let quants_buf = kernel
        .device
        .new_buffer(input.len() as u64, MTLResourceOptions::StorageModeShared);
    let n_buf = kernel
        .device
        .new_buffer(4, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&in_buf, input);
    unsafe {
        *(n_buf.contents() as *mut u32) = n_blocks as u32;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.quantize_q8_0_pipeline);
    encoder.set_buffer(0, Some(&in_buf), 0);
    encoder.set_buffer(1, Some(&scales_buf), 0);
    encoder.set_buffer(2, Some(&quants_buf), 0);
    encoder.set_buffer(3, Some(&n_buf), 0);
    let width = kernel
        .quantize_q8_0_pipeline
        .thread_execution_width()
        .max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: (n_blocks as u64).div_ceil(width),
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut scales = vec![0.0f32; n_blocks];
    read_buffer_f32(&scales_buf, &mut scales);
    let mut quants = vec![0i8; input.len()];
    read_buffer_i8(&quants_buf, &mut quants);
    Some((scales, quants))
}

/// GPU-resident `quantize -> Q8 matmul` chain in a single command buffer: quantize the
/// f32 input activation and matmul it against a Q8_0 weight (36-byte blocks), passing
/// the quantized scales/quants between the two kernels via GPU buffers with no CPU
/// readback. This is the core decode primitive and the proof that resident buffer
/// chaining works; it is bit-identical to running the two standalone kernels. None if
/// Metal is unavailable. `weight_blocks` is [output_width * blocks_per_row * 36] bytes.
#[cfg(target_os = "macos")]
pub fn try_quantized_matmul_resident(
    input: &[f32],
    weight_blocks: &[u8],
    output_width: usize,
) -> Option<Vec<f32>> {
    if input.is_empty() || !input.len().is_multiple_of(32) || output_width == 0 {
        return None;
    }
    let blocks_per_row = input.len() / 32;
    if weight_blocks.len() != output_width * blocks_per_row * 36 {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let new = |bytes: u64| {
        kernel
            .device
            .new_buffer(bytes, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = new(std::mem::size_of_val(input) as u64);
    let scales_buf = new((blocks_per_row * 4) as u64);
    let quants_buf = new(input.len() as u64);
    let weight_buf = new(weight_blocks.len() as u64);
    let out_buf = new((output_width * 4) as u64);
    let n_blocks_buf = new(4);
    let mm_scalar_buf = new(8);
    write_buffer_f32(&in_buf, input);
    write_buffer_u8(&weight_buf, weight_blocks);
    unsafe {
        *(n_blocks_buf.contents() as *mut u32) = blocks_per_row as u32;
        let p = mm_scalar_buf.contents() as *mut u32;
        *p = blocks_per_row as u32;
        *p.add(1) = output_width as u32;
    }
    let command_buffer = kernel.queue.new_command_buffer();

    // Stage 1: quantize the activation into scales_buf / quants_buf.
    let q_enc = command_buffer.new_compute_command_encoder();
    q_enc.set_compute_pipeline_state(&kernel.quantize_q8_0_pipeline);
    q_enc.set_buffer(0, Some(&in_buf), 0);
    q_enc.set_buffer(1, Some(&scales_buf), 0);
    q_enc.set_buffer(2, Some(&quants_buf), 0);
    q_enc.set_buffer(3, Some(&n_blocks_buf), 0);
    let qw = kernel
        .quantize_q8_0_pipeline
        .thread_execution_width()
        .max(1);
    q_enc.dispatch_thread_groups(
        metal::MTLSize {
            width: (blocks_per_row as u64).div_ceil(qw),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: qw,
            height: 1,
            depth: 1,
        },
    );
    q_enc.end_encoding();

    // Stage 2: matmul reads the quantized buffers stage 1 just wrote (same command
    // buffer; ordered, hazard-tracked for shared buffers).
    let m_enc = command_buffer.new_compute_command_encoder();
    m_enc.set_compute_pipeline_state(&kernel.q8_0_block_pipeline);
    m_enc.set_buffer(0, Some(&scales_buf), 0);
    m_enc.set_buffer(1, Some(&quants_buf), 0);
    m_enc.set_buffer(2, Some(&weight_buf), 0);
    m_enc.set_buffer(3, Some(&out_buf), 0);
    m_enc.set_buffer(4, Some(&mm_scalar_buf), 0);
    m_enc.set_buffer(5, Some(&mm_scalar_buf), 4);
    let mw = kernel.q8_0_block_pipeline.thread_execution_width().max(1);
    m_enc.dispatch_thread_groups(
        metal::MTLSize {
            width: (output_width as u64).div_ceil(mw),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: mw,
            height: 1,
            depth: 1,
        },
    );
    m_enc.end_encoding();

    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; output_width];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

// --- Resident-buffer encode helpers: encode one kernel into a shared command buffer,
// operating on GPU buffers with no readback. Reusable building blocks for the
// GPU-resident forward pass (KV cache + per-token chaining build on these). ---

#[cfg(target_os = "macos")]
fn dispatch_1d(
    encoder: &metal::ComputeCommandEncoderRef,
    pipeline: &ComputePipelineState,
    n: usize,
) {
    let w = pipeline.thread_execution_width().max(1);
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: (n as u64).div_ceil(w),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: w,
            height: 1,
            depth: 1,
        },
    );
}

#[cfg(target_os = "macos")]
fn admitted_32_lane_pipeline(
    pipeline: Option<&ComputePipelineState>,
) -> Option<&ComputePipelineState> {
    pipeline.filter(|pipeline| {
        pipeline.thread_execution_width() == 32
            && pipeline.max_total_threads_per_threadgroup() >= 32
    })
}

/// Opt-in reassociated-summation kernels for the experimental Ghost-MoE lane.
/// Cached once: the flag participates in per-layer per-token dispatch choices.
#[cfg(target_os = "macos")]
pub(crate) fn gemma4_ghost_turbo_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        std::env::var("CAMELID_GEMMA4_GHOST_METAL_TURBO")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
    })
}

/// One admission decision covers the generic common-core row dot and both
/// fixed-geometry expert row dots. Fused-fast falls back as a unit when any
/// optional SIMD pipeline is unavailable or the device does not expose the
/// 32-lane execution width compiled into their indexing contract.
#[cfg(target_os = "macos")]
fn gemma4_q4_simd_fast_available(kernel: &MetalLinearKernel) -> bool {
    const MAX_COMMON_BLOCKS: usize = GEMMA4_GHOST_26B_HEADS * GEMMA4_GHOST_26B_GLOBAL_HEAD_DIM / 32;
    threadgroup_alloc_fits(
        &kernel.device,
        MAX_COMMON_BLOCKS * std::mem::size_of::<f32>(),
    ) && admitted_32_lane_pipeline(kernel.q4_0_q8_ordered_simd_pipeline.as_ref()).is_some()
        && admitted_32_lane_pipeline(kernel.gemma4_q4_expert_gate_up_geglu_simd_pipeline.as_ref())
            .is_some()
        && admitted_32_lane_pipeline(kernel.gemma4_q4_expert_down_reduce_simd_pipeline.as_ref())
            .is_some()
}

#[cfg(target_os = "macos")]
fn dispatch_one_simdgroup_per_row(encoder: &metal::ComputeCommandEncoderRef, rows: usize) {
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: rows as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 32,
            height: 1,
            depth: 1,
        },
    );
}

/// Turbo-kernel geometry: four SIMD groups per 128-wide threadgroup, four
/// output rows per SIMD group (sixteen rows per threadgroup). The row batching
/// amortizes shared-activation reads across weight rows; the width keeps
/// enough traffic in flight to hide device-memory latency.
#[cfg(target_os = "macos")]
fn dispatch_four_simdgroup_rows(encoder: &metal::ComputeCommandEncoderRef, rows: usize) {
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: rows.div_ceil(16) as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 128,
            height: 1,
            depth: 1,
        },
    );
}

/// Fused rms_norm + Q8_0 quantize: reads `input`, emits the quantized normed row directly
/// into `scales`/`quants` (one dispatch, no intermediate normed buffer). `scalar` holds
/// width (u32) then eps (f32), like `encode_rms_norm`.
#[cfg(target_os = "macos")]
fn encode_rms_norm_quantize(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    input: &Buffer,
    weight: &Buffer,
    scales: &Buffer,
    quants: &Buffer,
    scalar: &Buffer,
) {
    e.set_compute_pipeline_state(&k.rms_norm_quantize_pipeline);
    e.set_buffer(0, Some(input), 0);
    e.set_buffer(1, Some(weight), 0);
    e.set_buffer(2, Some(scales), 0);
    e.set_buffer(3, Some(quants), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 256,
            height: 1,
            depth: 1,
        },
    );
}

/// Fused SiLU-mul + Q8_0 quantize: reads `gate`/`up`, emits the quantized activation row
/// directly into `scales`/`quants` (one dispatch, no intermediate activation buffer).
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_silu_mul_quantize(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    gate: &Buffer,
    up: &Buffer,
    scales: &Buffer,
    quants: &Buffer,
    nblocks_buf: &Buffer,
    n_blocks: usize,
) {
    e.set_compute_pipeline_state(&k.silu_mul_quantize_pipeline);
    e.set_buffer(0, Some(gate), 0);
    e.set_buffer(1, Some(up), 0);
    e.set_buffer(2, Some(scales), 0);
    e.set_buffer(3, Some(quants), 0);
    e.set_buffer(4, Some(nblocks_buf), 0);
    dispatch_1d(e, &k.silu_mul_quantize_pipeline, n_blocks);
}

#[cfg(target_os = "macos")]
fn encode_quantize(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    input: &Buffer,
    scales: &Buffer,
    quants: &Buffer,
    nblocks_buf: &Buffer,
    n_blocks: usize,
) {
    e.set_compute_pipeline_state(&k.quantize_q8_0_pipeline);
    e.set_buffer(0, Some(input), 0);
    e.set_buffer(1, Some(scales), 0);
    e.set_buffer(2, Some(quants), 0);
    e.set_buffer(3, Some(nblocks_buf), 0);
    dispatch_1d(e, &k.quantize_q8_0_pipeline, n_blocks);
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_q8_matmul(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    scales: &Buffer,
    quants: &Buffer,
    weight: &Buffer,
    out: &Buffer,
    scalar: &Buffer,
    rows: usize,
) {
    // Three GEMV layouts, selected per dispatch:
    // - ksplit (opt-in via CAMELID_METAL_KSPLIT): two rows per threadgroup, four simdgroups
    //   partitioning the contraction with a threadgroup-memory reduction — maximizes
    //   concurrent weight streams per output row.
    // - qmv4 (rows % 4 == 0): two simdgroups per TG, four rows per simdgroup, input cached
    //   in registers, four independent accumulator chains.
    // - one-row-per-simdgroup fallback for other row counts.
    const SIMD_GROUPS_PER_TG: u64 = 2;
    let ksplit = ksplit_gemv_enabled();
    let qmv4 = rows.is_multiple_of(4);
    let (pipeline, rows_per_tg, threads_per_tg) = if ksplit {
        (&k.q8_0_block_ksplit_pipeline, 2, 128)
    } else if qmv4 {
        (
            &k.q8_0_block_simd_qmv4_pipeline,
            SIMD_GROUPS_PER_TG * 4,
            SIMD_GROUPS_PER_TG * 32,
        )
    } else {
        (
            &k.q8_0_block_simd_mr_pipeline,
            SIMD_GROUPS_PER_TG,
            SIMD_GROUPS_PER_TG * 32,
        )
    };
    e.set_compute_pipeline_state(pipeline);
    e.set_buffer(0, Some(scales), 0);
    e.set_buffer(1, Some(quants), 0);
    e.set_buffer(2, Some(weight), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    if ksplit {
        // Two rows x 32 lanes of f32 partials for the cross-simdgroup reduction.
        e.set_threadgroup_memory_length(0, 2 * 32 * 4);
    }
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (rows as u64).div_ceil(rows_per_tg),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: threads_per_tg,
            height: 1,
            depth: 1,
        },
    );
}

/// Opt-in experiment flag for the K-split cooperative GEMV layout in the resident decode.
#[cfg(target_os = "macos")]
