/// GPU-side sampling operation attached to a resident token graph.
#[derive(Clone, Copy)]
pub enum SampleMode {
    Greedy,
    Temperature {
        inv_temperature: f32,
        base_seed: u64,
    },
}

#[cfg(target_os = "macos")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SampleSignature {
    Greedy,
    Temperature {
        inv_temperature_bits: u32,
        token_seed: u64,
    },
}

impl SampleMode {
    #[cfg(target_os = "macos")]
    fn signature(self, position: usize) -> SampleSignature {
        match self {
            Self::Greedy => SampleSignature::Greedy,
            Self::Temperature {
                inv_temperature,
                base_seed,
            } => SampleSignature::Temperature {
                inv_temperature_bits: inv_temperature.to_bits(),
                token_seed: base_seed ^ 0x9E37_79B9_7F4A_7C15u64.wrapping_mul(position as u64 + 1),
            },
        }
    }
}

/// GPU-side sampling stage for the resident decode fast path: the token graph's
/// tail samples the logits and gathers the selected token's embedding row into
/// the next graph's input buffer, so the CPU never sits between two tokens.
pub struct SampleStage<'a> {
    /// Token-embedding Q8_0 bytes (36-byte CPU blocks wire-converted in the buffer
    /// cache, or page-aligned wire pages wrapped in place).
    pub embedding_blocks: ResidentWeightBytes<'a>,
    pub mode: SampleMode,
    /// Post-dequant multiplier applied by the GPU gather: 1.0 for Llama-family
    /// rows (exact no-op), `Gemma3Metadata::embed_scale` (sqrt(d_model)) for
    /// gemma3 — the gathered row feeds the NEXT token graph's layer 0, which
    /// expects the scaled embedding just like the CPU-written one.
    pub embed_scale: f32,
}

/// Whether the device-side sampling tail can honour `SampleStage::embed_scale`
/// on an embedding table of this format. Only `embed_row_gather_q8_wire`
/// declares the scale at buffer(4); `embed_row_gather_q4k`/`_q6k` declare
/// buffers 0..3 and apply no factor, so binding buffer(4) on them is legal and
/// INERT — a non-unit scale would be silently dropped on the fast lane's
/// self-fed next token while the CPU-written path applies it. When this returns
/// false the tail is not encoded at all and the caller samples on the CPU from
/// the returned logits, which is slower but correct.
#[cfg(target_os = "macos")]
fn gpu_sampling_tail_is_scale_safe(format: ResidentWeightFormat, embed_scale: f32) -> bool {
    embed_scale == 1.0
        || matches!(
            format,
            ResidentWeightFormat::Q8_0
                | ResidentWeightFormat::Q1_0
                | ResidentWeightFormat::Q2_0G64
                | ResidentWeightFormat::Q2_0G128
        )
}

/// What a resident forward_token call produced: the raw logits/hidden vector (CPU
/// sampling path), or the GPU-sampled next token id (greedy fast path).
pub enum ResidentTokenOut {
    Data(Vec<f32>),
    Sampled(u32),
}

/// Per-layer RoPE-theta selection for dual-theta architectures (gemma3): layer
/// `i` ropes with the token's ALT (local-theta) cos/sin tables when
/// `use_alt_rope[i]`, else the primary tables. Built host-side from
/// `Gemma3Metadata::layer_is_sliding` (locals use the local base, globals the
/// GGUF `rope.freq_base`). `None` schedule on the session = the existing
/// single-table behavior, byte-identical. The batched prefill and
/// speculative-verify paths cannot express a per-layer table and fail closed
/// when a schedule is present.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ResidentLayerSchedule {
    pub use_alt_rope: Vec<bool>,
    /// Per-layer sliding window in positions, INCLUDING the current one: a
    /// local layer at position `pos` attends `[pos + 1 - w ..= pos]` (same
    /// convention as `Gemma3Metadata::layer_window` / `Gemma4LayerPlan::window`
    /// — the pinned reference is [`crate::window_ref::window_bounds`], whose unit
    /// tests assert it against the encode expression below). `None` = full causal
    /// attention (global layers, and every non-gemma3 arch).
    pub window: Vec<Option<usize>>,
}

impl ResidentLayerSchedule {
    /// True when any layer needs the ALT tables (callers must then pass
    /// `alt_rope` to `forward_token`).
    pub fn needs_alt_rope(&self) -> bool {
        self.use_alt_rope.iter().any(|&b| b)
    }
}

/// `(window_start, position_count)` for one layer's attention read range — the
/// NORMATIVE expression, written once and shared by the token-by-token decode
/// encode (`prepare_token`) and the batched windowed prefill
/// (`prefill_tokens_windowed`). Two callers computing the same arithmetic
/// separately is exactly how a batched path drifts from the lane it must be
/// bit-identical to.
///
/// `filled` is `position + 1` (the window INCLUDES the current position). The
/// expression is `filled.saturating_sub(w)` VERBATIM rather than a call to
/// [`crate::window_ref::window_bounds`], because the two disagree on the
/// degenerate `Some(0)`: `window_bounds` treats it as full causal, this treats it
/// as an empty read range. Bit-identity with the shipped decode lane is the gate,
/// so the shipped expression wins; `schedule_window_bounds_matches_window_ref`
/// pins the agreement for every `w > 0`, which is the only case any real schedule
/// produces.
#[cfg(target_os = "macos")]
fn schedule_window_bounds(window: Option<usize>, filled: usize) -> (usize, usize) {
    let window_start = window.map_or(0, |w| filled.saturating_sub(w));
    (window_start, filled - window_start)
}

/// Gate for the gemma3 batched windowed prefill (long-prompt TTFT campaign,
/// Tier A). **Default ON since Phase 4**, with `=0` as the operator opt-out —
/// the convention the serve lanes already use.
///
/// This path is bit-identical to the token-by-token lane on its own; what rides
/// inside it is not (see [`gemma3_prefill_mm_enabled`] and
/// [`gemma3_prefill_attn_mm_enabled`]), and the three flip together because
/// arming this one alone buys 1.25x while the stack buys ~9x on TTFT. Setting
/// this to 0 restores the pre-campaign token-by-token prefill exactly, whatever
/// the other two say.
///
/// It does NOT require `CAMELID_METAL_RESIDENT_PREFILL`, which arms the *other*
/// (non-windowed) batched prefill that gemma3 fails closed on. It is ANDed with
/// the arch at its only production caller, so in ANY state it is a no-op for
/// every non-gemma3 row.
pub fn gemma3_batch_prefill_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| {
        !std::env::var("CAMELID_GEMMA3_BATCH_PREFILL")
            .is_ok_and(|v| v == "0" || v.eq_ignore_ascii_case("false"))
    })
}

/// Rows per batched-prefill command buffer. Overridable with
/// `CAMELID_GEMMA3_BATCH_PREFILL_ROWS` for measurement; clamped to `[1, 1024]`.
/// The chunk width sets how many activation columns one weight streaming pass
/// serves — the whole point of Tier A — against the transient activation
/// scratch, which is linear in it (~32 MB at 256 rows on the 1B row).
pub fn gemma3_batch_prefill_rows() -> usize {
    static ROWS: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *ROWS.get_or_init(|| {
        std::env::var("CAMELID_GEMMA3_BATCH_PREFILL_ROWS")
            .ok()
            .and_then(|v| v.trim().parse::<usize>().ok())
            .map(|v| v.clamp(1, 1024))
            .unwrap_or(256)
    })
}

/// Which GEMM the batched windowed prefill streams its weights through.
///
/// The production wrappers pass [`PrefillGemm::EnvDefault`]; the test-only wrappers
/// pin a side explicitly, so ONE process can compare both without fighting the
/// process-latched env `OnceLock`.
#[cfg(target_os = "macos")]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
// `ForceScalar` / `ForceMm` exist so the gates can pin a side; production only ever
// constructs `EnvDefault`.
#[cfg_attr(not(test), allow(dead_code))]
pub(crate) enum PrefillGemm {
    /// `CAMELID_GEMMA3_PREFILL_MM` decides.
    EnvDefault,
    /// The Phase 2 batched-column GEMV — bit-identical to the token-by-token lane.
    ForceScalar,
    /// The tiled simdgroup-matrix kernel, where the shape admits it.
    ForceMm,
}

/// Gate for the Phase 3 tiled simdgroup-matmul prefill GEMM (long-prompt TTFT
/// campaign). **Default ON since Phase 4**, `=0` to opt out.
///
/// This path is **not** bit-identical to the token-by-token lane — the dequantized
/// Q8_0 weight and the activation panel are staged in half and accumulated in
/// tile-MMA order — so its gate is the published KV-equivalence envelope
/// (`GEMMA3_METAL_CONDUCTOR.md` §18a/§18b), not raw bit equality. Shipping it on
/// by default is a deliberate choice of prefill speed over prefill bit-identity,
/// recorded in §19c. Decode is not on this path and stays bit-exact.
///
/// Setting this to 0 without also setting `CAMELID_GEMMA3_BATCH_PREFILL=0` leaves
/// Tier A's bit-identical batched GEMV in place, which is the conservative middle
/// posture. Setting it in either direction does nothing for a non-gemma3 row: the
/// only production caller of `prefill_tokens_windowed` is the gemma3 seam.
pub fn gemma3_prefill_mm_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| {
        !std::env::var("CAMELID_GEMMA3_PREFILL_MM")
            .is_ok_and(|v| v == "0" || v.eq_ignore_ascii_case("false"))
    })
}

/// Which attention the batched windowed prefill runs (long-prompt TTFT campaign,
/// Tier B). Same shape and the same reason as [`PrefillGemm`]: the env gate is a
/// process-latched `OnceLock`, so a test process could otherwise never compare the
/// per-row attention against the batched one.
#[cfg(target_os = "macos")]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[cfg_attr(not(test), allow(dead_code))]
pub(crate) enum PrefillAttn {
    /// `CAMELID_GEMMA3_PREFILL_ATTN_MM` decides.
    EnvDefault,
    /// Per row, through the unchanged `encode_attention` — Phase 2/3's attention.
    ForceRow,
    /// Batched windowed attention-as-matmul, where the shape admits it.
    ForceMm,
}

/// Gate for the Phase 4 batched windowed attention-as-matmul (long-prompt TTFT
/// campaign, Tier B). **Default ON**, `=0` to opt out.
///
/// Like [`gemma3_prefill_mm_enabled`] this path is **not** bit-identical to the
/// token-by-token lane — Q/K/V and the score and probability panels stage in half
/// and the MMA accumulates in tile order — so its gate is the published
/// KV-equivalence envelope plus the exact-count mask gate
/// (`windowed_attn_mm_mask_matches_the_pinned_window_convention`), not raw bit
/// equality.
///
/// Rides on `CAMELID_GEMMA3_PREFILL_MM` (the context panel stays half all the way
/// into the O projection) inside `CAMELID_GEMMA3_BATCH_PREFILL`; turning either of
/// those off turns this off too, whatever it says.
pub fn gemma3_prefill_attn_mm_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| {
        !std::env::var("CAMELID_GEMMA3_PREFILL_ATTN_MM")
            .is_ok_and(|v| v == "0" || v.eq_ignore_ascii_case("false"))
    })
}

/// Threadgroup memory `half_mm_batched_f16o` needs: two 64x32 half staging tiles.
/// FIXED — `sa = shmem`, `sb = shmem + 2048` — and independent of head_dim, which is
/// what makes attention-as-matmul admissible at head_dim 256 while the `MAX_DPL` /
/// `MAX_DOCT` kernels keep their <=128 memory-safety gates untouched.
#[cfg(target_os = "macos")]
const ATTN_MM_THREADGROUP_BYTES: usize = 8192;

/// `half_mm_batched_f16o`'s square output tile (`NR0` = A rows, `NR1` = B rows). Both
/// the S and PV passes tile on it, and `softmax_causal_rows` writes P up to the same
/// 64-aligned causal boundary the PV pass reads.
#[cfg(target_os = "macos")]
const ATTN_MM_TILE: usize = 64;

/// Threadgroup memory `q8_0_block_wire_mm` needs: A 128x32 half (8192 B) + B 64x32
/// half (4096 B). FIXED — independent of head_dim, rows and chunk width — which is
/// why this path is admissible at head_dim 256 while the `MAX_DPL` / `MAX_DOCT`
/// kernels keep their <=128 memory-safety gates.
#[cfg(target_os = "macos")]
const PREFILL_MM_THREADGROUP_BYTES: usize = 12288;

/// Output rows per `q8_0_block_wire_mm` threadgroup tile.
#[cfg(target_os = "macos")]
const PREFILL_MM_ROW_TILE: usize = 64;

/// Prompt columns per `q8_0_block_wire_mm` threadgroup tile — the batching factor
/// this phase is buying (the GEMV's is `MAX_T = 8`, §17e).
#[cfg(target_os = "macos")]
const PREFILL_MM_TOKEN_TILE: usize = 128;

/// True when `bytes` fits this device's per-threadgroup limit.
///
/// The tree queried `maxThreadgroupMemoryLength` nowhere before this: every
/// size-dependent `set_threadgroup_memory_length` was computed and handed straight
/// to Metal. Call sites that can decline (an admission predicate) use this; call
/// sites that cannot use [`assert_threadgroup_fits`].
#[cfg(target_os = "macos")]
fn threadgroup_alloc_fits(device: &metal::DeviceRef, bytes: usize) -> bool {
    bytes as u64 <= device.max_threadgroup_memory_length()
}

/// Panic with the two numbers rather than handing an over-large threadgroup
/// allocation to Metal. Used at the size-dependent allocation sites that have no
/// fallback; a failure here is a programming error, and today it surfaces as an
/// opaque GPU fault instead.
#[cfg(target_os = "macos")]
fn assert_threadgroup_fits(device: &metal::DeviceRef, bytes: usize, label: &str) {
    assert!(
        threadgroup_alloc_fits(device, bytes),
        "{label}: threadgroup allocation of {bytes} B exceeds this device's \
         maxThreadgroupMemoryLength of {} B",
        device.max_threadgroup_memory_length()
    );
}

/// A resident decode session that owns the on-GPU KV cache (per layer, sized to
/// `max_positions`) and the reused hidden ping-pong buffers. A multi-token greedy decode runs
/// each token in ONE command buffer with the KV cache persisting on the GPU across tokens --
/// only the new token's K/V is blitted in each step, never re-uploaded -- and Q8 weights stay
/// resident via the global `MetalLinearCache`. For its sequence the session is the
/// authoritative KV store (the kernel computes and appends each token's K/V at `position`).
#[cfg(target_os = "macos")]
pub struct ResidentDecodeState {
    n_layers: usize,
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    hidden: usize,
    ffn_dim: usize,
    /// Positions the KV cache is currently allocated for; grown on demand toward `cap`.
    max_positions: usize,
    /// Hard ceiling on `max_positions` (the model context length): growth never exceeds it.
    cap: usize,
    eps: f32,
    split_half_pairing: bool,
    /// Per-layer dual-theta RoPE schedule (gemma3). `None` for every other
    /// arch — zero behavior change.
    schedule: Option<ResidentLayerSchedule>,
    cache_k: Vec<Buffer>,
    cache_v: Vec<Buffer>,
    /// Half-precision mirrors of cache_k/cache_v (empty in kv16-primary mode, where the
    /// primary caches are already half). Dual-written by the prefill and per-token
    /// scatters; read by the split-K kv16 decode attention, which halves the dominant
    /// KV traffic at depth. Zero-filled at allocation/growth so padded positions read 0.
    cache_k16: Vec<Buffer>,
    cache_v16: Vec<Buffer>,
    buf_a: Buffer,
    buf_b: Buffer,
    mid: Buffer,
    /// Number of KV positions currently materialized in the cache (seeded history + appended
    /// tokens). The caller uses this to detect a new sequence and reseed.
    filled: usize,
    /// Encode-ahead pipeline: the NEXT token's fully-encoded AND committed command buffer,
    /// built on the CPU while the previous token executed on the GPU. Execution is gated on
    /// `gate_event`, signaled only after the token's input embedding is written — so by
    /// signal time, scheduling cost is already paid. Invalidated whenever the KV cache
    /// reallocates (the encoded graph references the old buffers); a committed-but-ungated
    /// stale graph MUST be released via `release_stale` or it deadlocks the serial queue.
    pending: Option<PreparedToken>,
    /// True when `pending` was already event-signaled (GPU-sampling fast path): its input
    /// embedding comes from the previous graph's gather, so it may already be executing.
    pending_signaled: bool,
    /// Token id the previous graph's tail sampled (greedy fast path); the next call skips
    /// the CPU embedding write only when its input token matches.
    last_sampled: Option<u32>,
    /// Signaled BY the GPU as each token graph's last command; the fast lane polls this
    /// (a shared-memory read) instead of wait_until_completed, skipping the
    /// completion-handler wake-up latency on the per-token critical path.
    done_event: metal::SharedEvent,
    /// The previously returned fast-lane graph, kept alive until the next call calls
    /// wait_until_completed on it (its GPU work was already observed done via done_event;
    /// the deferred wait only settles command-buffer bookkeeping off the critical path).
    retiring: Option<PreparedToken>,
    /// Gates pre-committed token graphs; monotonically increasing values.
    gate_event: metal::SharedEvent,
    event_counter: u64,
    /// KV cache element width: f16 when CAMELID_METAL_KV16 is set, else f32.
    kv16: bool,
    /// Q8_0-primary cache, selected by CAMELID_METAL_KV_DTYPE=q8.
    kvq8: bool,
}

/// A fully-encoded, uncommitted per-token command buffer. The input embedding is written
/// into the session's input buffer just before commit (the graph reads it first), so the
/// expensive encode happens off the critical path.
#[cfg(target_os = "macos")]
struct PreparedToken {
    position: usize,
    has_logits: bool,
    has_sample: bool,
    sample_signature: Option<SampleSignature>,
    event_value: u64,
    cb: metal::CommandBuffer,
    logits_buf: Option<Buffer>,
    /// GPU-sampled token id (uint), present when the graph tail runs the greedy sampler.
    sampled_buf: Option<Buffer>,
    final_from_a: bool,
    /// Scratch buffers the encoded graph references; kept alive until completion.
    _keep: Vec<Buffer>,
    encode_us: u128,
}

/// WIN2METAL Phase 4 — tree-attention descriptor handed to the (otherwise shared)
/// `verify_batch_inner`. `None` ⇒ today's contiguous linear verify (byte-unchanged).
/// `Some` ⇒ each node attends `prefix [0, base)` ∪ its ancestor draft slots.
#[cfg(target_os = "macos")]
struct TreeAttn {
    /// Contiguous committed-history prefix length (`base_position`). Slots `[0, base)`
    /// are all-ancestor, so the kernels read them directly (no indirection).
    base: usize,
    /// Per-node ancestor draft cache slots (absolute, increasing, INCLUDING self), built
    /// from the ancestor bitset. `tail_slots[i].len()` is the node's `tail_count`; its
    /// attention `position_count` is `base + tail_count`.
    tail_slots: Vec<Vec<u32>>,
}

#[cfg(target_os = "macos")]
impl ResidentDecodeState {
    /// Allocate the session. `max_positions` is the initial KV-cache capacity (grown on demand
    /// up to `cap`, the model context length). Returns None if Metal is unavailable or the
    /// dimensions are invalid.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        n_layers: usize,
        n_heads: usize,
        n_kv_heads: usize,
        head_dim: usize,
        hidden: usize,
        ffn_dim: usize,
        max_positions: usize,
        cap: usize,
        eps: f32,
        split_half_pairing: bool,
        schedule: Option<ResidentLayerSchedule>,
    ) -> Option<Self> {
        let q_dim = n_heads * head_dim;
        // Fail closed on a mis-sized schedule: the per-layer decode loop indexes
        // `use_alt_rope[i]`/`window[i]` unchecked, so a short table must be a
        // clean `None` here rather than an out-of-bounds panic on token 1.
        if schedule
            .as_ref()
            .is_some_and(|s| s.use_alt_rope.len() != n_layers || s.window.len() != n_layers)
        {
            return None;
        }
        let kv_format = resident_kv_format();
        let kv16 = kv_format == ResidentKvFormat::F16;
        let kvq8 = kv_format == ResidentKvFormat::Q8;
        if n_layers == 0
            || hidden == 0
            || !hidden.is_multiple_of(32)
            || !q_dim.is_multiple_of(32)
            || head_dim == 0
            || !head_dim.is_multiple_of(2)
            || n_heads == 0
            || n_kv_heads == 0
            || !n_heads.is_multiple_of(n_kv_heads)
            || ffn_dim == 0
            || !ffn_dim.is_multiple_of(32)
            || max_positions == 0
            || cap < max_positions
            || (kvq8 && (!head_dim.is_multiple_of(32) || head_dim > 128))
        {
            return None;
        }
        let k = metal_linear_kernel()?;
        let nb = |n: usize| {
            k.device
                .new_buffer((n * 4) as u64, MTLResourceOptions::StorageModeShared)
        };
        let kv_slots = n_kv_heads * max_positions * head_dim;
        let kv_row_bytes = (head_dim / 32) * 34;
        let kvb = |slots: usize| {
            let bytes = if kvq8 {
                n_kv_heads * max_positions * kv_row_bytes
            } else {
                slots * if kv16 { 2 } else { 4 }
            };
            k.device
                .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
        };
        let cache_k = (0..n_layers).map(|_| kvb(kv_slots)).collect();
        let cache_v = (0..n_layers).map(|_| kvb(kv_slots)).collect();
        // Half mirrors for the split-K kv16 decode attention (skip in kv16-primary
        // mode, where the primary caches are already half). Zero-filled so padded
        // positions read 0 in the attention kernels.
        let kvb16 = |slots: usize| {
            let b = k
                .device
                .new_buffer((slots * 2) as u64, MTLResourceOptions::StorageModeShared);
            unsafe { std::ptr::write_bytes(b.contents() as *mut u8, 0, slots * 2) };
            b
        };
        let (cache_k16, cache_v16) = if kv16 || kvq8 {
            (Vec::new(), Vec::new())
        } else {
            (
                (0..n_layers).map(|_| kvb16(kv_slots)).collect(),
                (0..n_layers).map(|_| kvb16(kv_slots)).collect(),
            )
        };
        Some(Self {
            n_layers,
            n_heads,
            n_kv_heads,
            head_dim,
            hidden,
            ffn_dim,
            max_positions,
            cap,
            eps,
            split_half_pairing,
            schedule,
            cache_k,
            cache_v,
            cache_k16,
            cache_v16,
            buf_a: nb(hidden),
            buf_b: nb(hidden),
            mid: nb(hidden),
            filled: 0,
            pending: None,
            pending_signaled: false,
            last_sampled: None,
            done_event: k.device.new_shared_event(),
            retiring: None,
            gate_event: k.device.new_shared_event(),
            event_counter: 0,
            kv16,
            kvq8,
        })
    }

    /// Grow the KV cache to at least `needed` positions (capped at `self.cap`) by allocating
    /// larger per-layer buffers and blitting the `filled` materialized slots across (the
    /// per-head position stride changes with `max_positions`). GPU-to-GPU, no CPU readback.
    /// Returns false if `needed` exceeds the cap or Metal is unavailable.
    fn ensure_capacity(&mut self, needed: usize) -> bool {
        if needed <= self.max_positions {
            return true;
        }
        if needed > self.cap {
            return false;
        }
        let new_max = (self.max_positions * 2).max(needed).min(self.cap);
        let k = match metal_linear_kernel() {
            Some(k) => k,
            None => return false,
        };
        let kv_elem = if self.kv16 { 2 } else { 4 };
        let kv_row_bytes = (self.head_dim / 32) * 34;
        let kv_slots = self.n_kv_heads * new_max * self.head_dim;
        let new_k: Vec<Buffer> = (0..self.n_layers)
            .map(|_| {
                let bytes = if self.kvq8 {
                    self.n_kv_heads * new_max * kv_row_bytes
                } else {
                    kv_slots * kv_elem
                };
                k.device
                    .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
            })
            .collect();
        let new_v: Vec<Buffer> = (0..self.n_layers)
            .map(|_| {
                let bytes = if self.kvq8 {
                    self.n_kv_heads * new_max * kv_row_bytes
                } else {
                    kv_slots * kv_elem
                };
                k.device
                    .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
            })
            .collect();
        let mirror = |_| {
            let b = k
                .device
                .new_buffer((kv_slots * 2) as u64, MTLResourceOptions::StorageModeShared);
            unsafe { std::ptr::write_bytes(b.contents() as *mut u8, 0, kv_slots * 2) };
            b
        };
        let new_k16: Vec<Buffer> = if self.kv16 || self.kvq8 {
            Vec::new()
        } else {
            (0..self.n_layers).map(mirror).collect()
        };
        let new_v16: Vec<Buffer> = if self.kv16 || self.kvq8 {
            Vec::new()
        } else {
            (0..self.n_layers).map(mirror).collect()
        };
        if self.filled > 0 {
            let cb = k.queue.new_command_buffer();
            let blit = cb.new_blit_command_encoder();
            for layer in 0..self.n_layers {
                for h in 0..self.n_kv_heads {
                    let row_bytes = if self.kvq8 {
                        kv_row_bytes
                    } else {
                        self.head_dim * kv_elem
                    };
                    let run = (self.filled * row_bytes) as u64;
                    let src = (h * self.max_positions * row_bytes) as u64;
                    let dst = (h * new_max * row_bytes) as u64;
                    blit.copy_from_buffer(&self.cache_k[layer], src, &new_k[layer], dst, run);
                    blit.copy_from_buffer(&self.cache_v[layer], src, &new_v[layer], dst, run);
                    if !self.kv16 && !self.kvq8 {
                        let run16 = (self.filled * self.head_dim * 2) as u64;
                        let src16 = (h * self.max_positions * self.head_dim * 2) as u64;
                        let dst16 = (h * new_max * self.head_dim * 2) as u64;
                        blit.copy_from_buffer(
                            &self.cache_k16[layer],
                            src16,
                            &new_k16[layer],
                            dst16,
                            run16,
                        );
                        blit.copy_from_buffer(
                            &self.cache_v16[layer],
                            src16,
                            &new_v16[layer],
                            dst16,
                            run16,
                        );
                    }
                }
            }
            blit.end_encoding();
            cb.commit();
            cb.wait_until_completed();
        }
        self.cache_k = new_k;
        self.cache_v = new_v;
        self.cache_k16 = new_k16;
        self.cache_v16 = new_v16;
        self.max_positions = new_max;
        true
    }

    /// Positions currently materialized in the KV cache (seeded + appended).
    pub fn filled(&self) -> usize {
        self.filled
    }

    /// Whether THIS engine's KV survives a GPU -> CPU -> GPU round trip unchanged.
    ///
    /// The CPU KV history always stores f16-ROUNDED values — `store_kv_head_row`
    /// rounds through f16 even in `KvDtype::F32` mode, and every writer including
    /// the GPU mirror-back routes through it. So an F16 primary round-trips
    /// exactly (f16 -> f32 is exact; f32 -> f16 of a value that came from f16 is
    /// the identity), while an F32 primary would be silently rounded on the way
    /// out and a resumed sequence would attend over different K/V than its
    /// prefill produced. Q8 is lossy by construction.
    ///
    /// Deliberately reads the format THIS engine was built with rather than the
    /// process-global `resident_kv_format()`: a model switch re-decides the
    /// global (`set_resident_kquant_lane`) while an older session still holds an
    /// engine built under the previous format, so the global is a time-of-check
    /// answer to a time-of-use question.
    pub fn kv_roundtrips_through_cpu_exactly(&self) -> bool {
        self.kv16
    }

    /// Mark `n` positions as materialized (called after seeding history from a CPU cache).
    pub fn set_filled(&mut self, n: usize) {
        self.filled = n;
    }

    /// Discard the KV positions at and after `position` (speculative rollback of rejected
    /// draft tokens). The cache is position-indexed and the next append overwrites the
    /// dropped slots, so nothing but the materialized count moves — no buffer work, and the
    /// still-valid history `[0, position)` stays on the GPU instead of being reseeded from
    /// the CPU. A no-op when the cache holds no more than `position` positions. The
    /// encode-ahead graph was built for the abandoned position, so it is released here
    /// rather than left for `forward_token` to discover (releasing is mandatory: it sits
    /// committed and gated on the serial queue).
    pub fn rollback_to_position(&mut self, position: usize) {
        if position >= self.filled {
            return;
        }
        if let Some(stale) = self.pending.take() {
            self.release_stale(stale);
        }
        self.pending_signaled = false;
        self.last_sampled = None;
        self.filled = position;
    }

    /// Decode one token at sequence position `position` (0-based): append this token's K/V to
    /// the persistent GPU cache and attend over positions `0..=position`, all layers in one
    /// command buffer. `cos_t`/`sin_t` are the RoPE tables for `position`; `scale` is the
    /// attention scale. Returns the post-final-layer hidden state `[hidden]` (the caller
    /// applies the final norm + output projection), or None on dimension mismatch.
    #[allow(clippy::too_many_arguments)]
    #[allow(clippy::too_many_arguments)]
    pub fn forward_token(
        &mut self,
        embedding: &[f32],
        layers: &[ResidentLayerWeights],
        cos_t: &[f32],
        sin_t: &[f32],
        alt_rope: Option<(&[f32], &[f32])>,
        position: usize,
        scale: f32,
        logits_stage: Option<LogitsStage>,
        sample_stage: Option<SampleStage>,
        input_token_id: u32,
        next_rope: Option<(&[f32], &[f32])>,
        next_alt_rope: Option<(&[f32], &[f32])>,
    ) -> Option<ResidentTokenOut> {
        let fn_started = std::time::Instant::now();
        let half_rope = cos_t.len();
        // Dual-theta schedule (gemma3): when any layer selects the ALT table,
        // the caller must supply it for this token — fail closed, never rope
        // with the wrong theta. The tables share the primary's pair count.
        let needs_alt = self.schedule.as_ref().is_some_and(|s| s.needs_alt_rope());
        if needs_alt {
            match alt_rope {
                Some((ac, as_)) if ac.len() == half_rope && as_.len() == half_rope => {}
                _ => return None,
            }
        }
        // Grow the on-GPU KV cache if this token's position is past the current capacity.
        // Growth reallocates the cache buffers, so any pre-encoded pending graph (which
        // references the old buffers) must be dropped.
        let before_growth = self.max_positions;
        if !self.ensure_capacity(position + 1) {
            return None;
        }
        if self.max_positions != before_growth {
            if let Some(stale) = self.pending.take() {
                self.release_stale(stale);
            }
            self.pending_signaled = false;
        }
        if embedding.len() != self.hidden
            || layers.len() != self.n_layers
            || sin_t.len() != half_rope
            || half_rope * 2 > self.head_dim
        {
            return None;
        }
        let q_dim = self.n_heads * self.head_dim;
        let kv_dim = self.n_kv_heads * self.head_dim;
        for l in layers {
            if l.attn_norm.len() != self.hidden
                || l.ffn_norm.len() != self.hidden
                || !l.q_weight_blocks.matches_shape(self.hidden, q_dim)
                || !l.k_weight_blocks.matches_shape(self.hidden, kv_dim)
                || !l.v_weight_blocks.matches_shape(self.hidden, kv_dim)
                || !l.o_weight_blocks.matches_shape(q_dim, self.hidden)
                || !l
                    .gate_weight_blocks
                    .matches_shape(self.hidden, self.ffn_dim)
                || !l.up_weight_blocks.matches_shape(self.hidden, self.ffn_dim)
                || !l
                    .down_weight_blocks
                    .matches_shape(self.ffn_dim, self.hidden)
            {
                return None;
            }
            if let Some(m) = &l.moe {
                let ne = m.n_expert;
                if m.n_expert_used == 0
                    || m.n_expert_used > ne
                    || ne > 256
                    || m.expert_ff == 0
                    || !m.expert_ff.is_multiple_of(32)
                    || m.router.len() != ne * self.hidden
                    || m.expert_bias.is_some_and(|b| b.len() != ne)
                    || !m.gate_exps.matches_shape(self.hidden, m.expert_ff * ne)
                    || !m.up_exps.matches_shape(self.hidden, m.expert_ff * ne)
                    || !m.down_exps.matches_shape(m.expert_ff, self.hidden * ne)
                {
                    return None;
                }
            }
        }
        if let Some(s) = &logits_stage {
            if s.vocab_size == 0
                || s.final_norm.len() != self.hidden
                || !s
                    .output_weight_blocks
                    .matches_shape(self.hidden, s.vocab_size)
            {
                return None;
            }
        }
        let k = metal_linear_kernel()?;
        let trace = std::env::var_os("CAMELID_RESIDENT_TRACE").is_some();
        // Take the pre-encoded, pre-committed graph for this position (built and committed
        // while the PREVIOUS token was executing on the GPU, scheduling already paid), or
        // encode inline on the first token / after invalidation. A stale pending graph is
        // committed on the serial queue gated behind its event and MUST be released.
        // The sampling tail's embedding gather reads wire-format rows; outside wire mode
        // prepare_token would encode no tail, so drop the stage up front to keep the
        // pending-graph reuse check consistent with what actually gets encoded.
        let sample_stage = if f32y_gemv_enabled() && wire_weights_enabled() {
            sample_stage
        } else {
            None
        };
        let want_sample = sample_stage.is_some() && logits_stage.is_some();
        let requested_sample_signature = sample_stage
            .as_ref()
            .map(|stage| stage.mode.signature(position));
        let pending = self.pending.take();
        let pending_signaled = std::mem::take(&mut self.pending_signaled);
        let usable = matches!(
            &pending,
            Some(p) if p.position == position
                && p.has_logits == logits_stage.is_some()
                && p.has_sample == want_sample
                && p.sample_signature == requested_sample_signature
        );
        // Fast path: the pending graph was already signaled last call (its input embedding
        // comes from the previous graph's GPU-side gather). It only matches the caller's
        // intent when the input token IS the token that gather selected; a forced different
        // continuation re-runs the position with the CPU-written embedding (the KV scatter
        // overwrites the same slot, so the re-run is exact).
        let already_running =
            usable && pending_signaled && self.last_sampled == Some(input_token_id);
        let prepared = if usable && (already_running || !pending_signaled) {
            pending.unwrap()
        } else {
            if let Some(stale) = pending {
                self.release_stale(stale);
            }
            self.prepare_token(
                k,
                layers,
                cos_t,
                sin_t,
                alt_rope,
                position,
                scale,
                logits_stage.as_ref(),
                sample_stage.as_ref(),
            )?
        };
        let gpu_started = std::time::Instant::now();
        if !already_running {
            // The graph's first op reads the embedding from buf_a; it is gated on the shared
            // event, so writing the embedding and then signaling releases it instantly.
            write_buffer_f32(&self.buf_a, embedding);
            self.gate_event.set_signaled_value(prepared.event_value);
        }
        // Encode-ahead: build the NEXT token's command buffer on the CPU while this one
        // executes on the GPU (greedy decode advances one position at a time). Skipped at
        // the KV-capacity edge — growth would invalidate the encoded graph, so the next
        // call grows first and encodes inline once.
        let mut next_encode_us = 0u128;
        if let Some((cos_n, sin_n)) = next_rope {
            // Encode-ahead needs the NEXT token's ALT tables too when the
            // schedule selects them; without them, skip the pipeline (correct,
            // just not overlapped) rather than encode a wrong-theta graph.
            let next_alt_ok = !needs_alt
                || next_alt_rope
                    .is_some_and(|(ac, as_)| ac.len() == half_rope && as_.len() == half_rope);
            if position + 2 <= self.max_positions && next_alt_ok {
                if let Some(next) = self.prepare_token(
                    k,
                    layers,
                    cos_n,
                    sin_n,
                    next_alt_rope,
                    position + 1,
                    scale,
                    logits_stage.as_ref(),
                    sample_stage.as_ref(),
                ) {
                    next_encode_us = next.encode_us;
                    // Greedy fast path: the next graph's input is produced by THIS graph's
                    // sampling tail on the GPU timeline (serial queue order), so it can be
                    // released now — the GPU runs token-to-token with no CPU on the path.
                    if want_sample && next.has_sample {
                        self.gate_event.set_signaled_value(next.event_value);
                        self.pending_signaled = true;
                    }
                    self.pending = Some(next);
                }
            }
        }
        if want_sample && prepared.sampled_buf.is_some() && !trace {
            // Settle the PREVIOUS fast-lane graph's bookkeeping (its GPU work finished at
            // least one token ago) while this token still executes. Its scratch goes back
            // to the pool instead of dropping: several hundred MTLBuffer creates/releases
            // per token otherwise cross into IOGPU on the decode loop's thread.
            if let Some(r) = self.retiring.take() {
                r.cb.wait_until_completed();
                pool_recycle(
                    k,
                    r._keep.into_iter().chain(r.sampled_buf).chain(r.logits_buf),
                );
            }
            // Observe THIS graph's completion via the GPU-stamped event: a shared-memory
            // poll, no kernel wake-up on the critical path.
            while self.done_event.signaled_value() < prepared.event_value {
                std::hint::spin_loop();
            }
        } else {
            if let Some(r) = self.retiring.take() {
                r.cb.wait_until_completed();
                pool_recycle(
                    k,
                    r._keep.into_iter().chain(r.sampled_buf).chain(r.logits_buf),
                );
            }
            prepared.cb.wait_until_completed();
        }
        if trace {
            let gpu_us = gpu_started.elapsed().as_micros();
            // True GPU-busy window from the command buffer's hardware timestamps: splits
            // "kernel executing" from submission/scheduling gaps inside commit_wait.
            let (gpu_busy_us, kernel_total_us) = command_buffer_gpu_times_us(&prepared.cb);
            let pre_us = fn_started.elapsed().as_micros() - gpu_us;
            eprintln!(
                "[resident] pos={position} layers={} pre={pre_us}us encode={}us next_encode={next_encode_us}us commit_wait={gpu_us}us gpu_busy={gpu_busy_us}us kernel_window={kernel_total_us}us",
                self.n_layers, prepared.encode_us,
            );
        }
        self.filled = position + 1;
        if let Some(sampled_buf) = &prepared.sampled_buf {
            let id = unsafe { *(sampled_buf.contents() as *const u32) };
            self.last_sampled = Some(id);
            // Keep the graph (and its scratch buffers) alive until the next call settles
            // it; its GPU work was observed complete above.
            self.retiring = Some(prepared);
            return Some(ResidentTokenOut::Sampled(id));
        }
        self.last_sampled = None;
        if let Some(logits_buf) = prepared.logits_buf {
            let vocab = logits_stage.as_ref().map(|s| s.vocab_size).unwrap_or(0);
            let mut out = vec![0.0f32; vocab];
            read_buffer_f32(&logits_buf, &mut out);
            return Some(ResidentTokenOut::Data(out));
        }
        let final_buf = if prepared.final_from_a {
            &self.buf_a
        } else {
            &self.buf_b
        };
        let mut out = vec![0.0f32; self.hidden];
        read_buffer_f32(final_buf, &mut out);
        Some(ResidentTokenOut::Data(out))
    }

    /// Encode one token's full graph into an uncommitted command buffer. Everything here is
    /// CPU work (buffer allocs + encoder calls) — callable while the GPU executes the
    /// previous token. The graph reads its input embedding from `buf_a` at execution time.
    #[allow(clippy::too_many_arguments)]
    fn prepare_token(
        &mut self,
        k: &'static MetalLinearKernel,
        layers: &[ResidentLayerWeights],
        cos_t: &[f32],
        sin_t: &[f32],
        alt_rope: Option<(&[f32], &[f32])>,
        position: usize,
        scale: f32,
        logits_stage: Option<&LogitsStage>,
        sample_stage: Option<&SampleStage>,
    ) -> Option<PreparedToken> {
        // The MoE lane encodes only the f32-activation wire-format chain.
        if layers.iter().any(|l| l.moe.is_some())
            && !(f32y_gemv_enabled() && wire_weights_enabled())
        {
            return None;
        }
        // Resolve all resident weight buffers (layer weights + optional output stage) under one
        // cache lock. They are keyed by (pointer, len), so they upload once and persist.
        let resident: Vec<[ResidentLinearWeight; 7]>;
        let resident_moe: Vec<Option<ResidentMoeResolved>>;
        let stage_bufs: Option<(ResidentLinearWeight, Buffer)>;
        let emb_buf: Option<ResidentLinearWeight>;
        {
            let mut cache = metal_linear_cache().lock().ok()?;
            let wire = f32y_gemv_enabled() && wire_weights_enabled();
            let mut wb =
                |w: &ResidentWeightBytes| resolve_resident_weight(&mut cache, &k.device, w, wire);
            resident = layers
                .iter()
                .map(|l| {
                    Some([
                        wb(&l.q_weight_blocks)?,
                        wb(&l.k_weight_blocks)?,
                        wb(&l.v_weight_blocks)?,
                        wb(&l.o_weight_blocks)?,
                        wb(&l.gate_weight_blocks)?,
                        wb(&l.up_weight_blocks)?,
                        wb(&l.down_weight_blocks)?,
                    ])
                })
                .collect::<Option<Vec<_>>>()?;
            stage_bufs = match logits_stage {
                Some(s) => {
                    let ow = wb(&s.output_weight_blocks)?;
                    Some((ow, cache.weight_buffer(&k.device, s.final_norm)))
                }
                None => None,
            };
            // The sampling tail needs the wire-format weight layout for the embedding
            // gather; outside wire mode the fast path is disabled by the caller.
            emb_buf = match sample_stage {
                Some(s) if wire => {
                    resolve_resident_weight(&mut cache, &k.device, &s.embedding_blocks, wire)
                }
                _ => None,
            };
            resident_moe = layers
                .iter()
                .map(|l| {
                    // dense layer -> Some(None); MoE layer -> Some(Some(resolved)),
                    // or None (abort the whole graph) if any expert buffer fails to resolve.
                    l.moe.as_ref().map_or(Some(None), |m| {
                        Some(Some(ResidentMoeResolved {
                            router: ResidentLinearWeight {
                                format: ResidentWeightFormat::DenseF32,
                                buffer: cache.weight_buffer(&k.device, m.router),
                                q8_wire: false,
                            },
                            expert_bias: m.expert_bias.map(|b| cache.weight_buffer(&k.device, b)),
                            gate_exps: resolve_resident_weight(
                                &mut cache,
                                &k.device,
                                &m.gate_exps,
                                wire,
                            )?,
                            up_exps: resolve_resident_weight(
                                &mut cache, &k.device, &m.up_exps, wire,
                            )?,
                            down_exps: resolve_resident_weight(
                                &mut cache,
                                &k.device,
                                &m.down_exps,
                                wire,
                            )?,
                            n_expert: m.n_expert,
                            n_expert_used: m.n_expert_used,
                            expert_ff: m.expert_ff,
                            weights_scale: m.weights_scale,
                            weights_norm: m.weights_norm,
                        }))
                    })
                })
                .collect::<Option<Vec<_>>>()?;
        }
        let filled = position + 1;
        let mut keep = Vec::new();
        let encode_started = std::time::Instant::now();
        self.event_counter += 1;
        let event_value = self.event_counter;
        let cb = k.queue.new_command_buffer();
        cb.encode_wait_for_event(&self.gate_event, event_value);
        let e = cb.new_compute_command_encoder();
        let mut from_a = true;
        for (i, layer) in layers.iter().enumerate() {
            let (in_buf, out_buf) = if from_a {
                (&self.buf_a, &self.buf_b)
            } else {
                (&self.buf_b, &self.buf_a)
            };
            let w = &resident[i];
            // Dual-theta schedule (gemma3): sliding layers rope with the ALT
            // (local-theta) tables, globals with the primary. The caller
            // validated availability (forward_token fails closed without them).
            let (l_cos, l_sin) = match (&self.schedule, alt_rope) {
                (Some(sched), Some((ac, as_))) if sched.use_alt_rope[i] => (ac, as_),
                _ => (cos_t, sin_t),
            };
            // Sliding-window layers read only the trailing `window` positions
            // (window INCLUDES the current position — gemma4 math verbatim:
            // window_start = filled.saturating_sub(window), position_count =
            // filled - window_start). Full-causal layers keep window_start = 0.
            let (window_start, position_count) =
                schedule_window_bounds(self.schedule.as_ref().and_then(|s| s.window[i]), filled);
            encode_attention_block(
                e,
                k,
                &mut keep,
                in_buf,
                &self.mid,
                layer.attn_norm,
                self.eps,
                layer.q_norm,
                layer.k_norm,
                layer.post_attn_norm,
                &w[0],
                &w[1],
                &w[2],
                &w[3],
                l_cos,
                l_sin,
                &self.cache_k[i],
                &self.cache_v[i],
                if self.kv16 || self.kvq8 {
                    None
                } else {
                    Some((&self.cache_k16[i], &self.cache_v16[i]))
                },
                self.kv16,
                self.kvq8,
                self.max_positions,
                position,
                self.n_heads,
                self.n_kv_heads,
                self.head_dim,
                position_count,
                window_start,
                scale,
                self.split_half_pairing,
                layer.qk_l2_norm_after_rope,
            );
            match resident_moe[i].as_ref() {
                Some(moe) => encode_moe_ffn_block(
                    e,
                    k,
                    &mut keep,
                    &self.mid,
                    out_buf,
                    layer.ffn_norm,
                    self.eps,
                    &w[4],
                    &w[5],
                    &w[6],
                    self.ffn_dim,
                    moe,
                ),
                None => encode_ffn_block(
                    e,
                    k,
                    &mut keep,
                    &self.mid,
                    out_buf,
                    layer.ffn_norm,
                    self.eps,
                    layer.post_ffw_norm,
                    layer.ffn_geglu,
                    &w[4],
                    &w[5],
                    &w[6],
                    self.ffn_dim,
                ),
            }
            from_a = !from_a;
        }
        let final_buf = if from_a { &self.buf_a } else { &self.buf_b };
        // Optional final stage: RMSNorm + output (vocab) projection in the SAME command buffer,
        // so the large logits matmul runs on the GPU instead of falling to the slow CPU path.
        let logits_buf = if let (Some(s), Some((ow_buf, fnorm_buf))) = (logits_stage, &stage_bufs) {
            let nb = |bytes: u64| pool_get(k, bytes);
            let rms_scalar = nb(8);
            let bpr_hidden = self.hidden / 32;
            let lscales = nb((bpr_hidden * 4) as u64);
            let lquants = nb(self.hidden as u64);

            let lmm_scalar = nb(12);
            let logits_buf = nb((s.vocab_size * 4) as u64);
            unsafe {
                let p = rms_scalar.contents() as *mut u8;
                *(p as *mut u32) = self.hidden as u32;
                *(p.add(4) as *mut f32) = self.eps;
            }
            if f32y_gemv_enabled() {
                let normf = nb((self.hidden * 4) as u64);
                encode_rms_norm_f32(e, k, final_buf, fnorm_buf, &normf, &rms_scalar);
                encode_resident_matmul_f32(
                    e,
                    k,
                    &mut keep,
                    &normf,
                    ow_buf,
                    &logits_buf,
                    &lmm_scalar,
                    self.hidden,
                    s.vocab_size,
                    1,
                );
                keep.push(normf);
            } else {
                if ow_buf.format != ResidentWeightFormat::Q8_0 {
                    return None;
                }
                unsafe {
                    let m = lmm_scalar.contents() as *mut u32;
                    *m = (self.hidden / 32) as u32;
                    *m.add(1) = s.vocab_size as u32;
                }
                encode_rms_norm_quantize(
                    e,
                    k,
                    final_buf,
                    fnorm_buf,
                    &lscales,
                    &lquants,
                    &rms_scalar,
                );
                encode_q8_matmul(
                    e,
                    k,
                    &lscales,
                    &lquants,
                    &ow_buf.buffer,
                    &logits_buf,
                    &lmm_scalar,
                    s.vocab_size,
                );
            }
            keep.extend([rms_scalar, lscales, lquants, lmm_scalar]);
            Some(logits_buf)
        } else {
            None
        };
        // Sampling tail: select an id from the logits, then gather that token's
        // embedding row into buf_a — the input the NEXT pre-encoded graph reads.
        // Both operations are hazard-ordered after the logits matmul by Metal.
        let sampled_buf = match (&logits_buf, &emb_buf, logits_stage, sample_stage) {
            // Fail closed rather than gather an unscaled embedding row: the
            // K-quant gathers ignore buffer(4). Unreachable from the production
            // caller (it requires a Q8_0 embedding table before it builds the
            // stage at all), so this costs the fast lane nothing today.
            (Some(_), Some(eb), Some(_), Some(sample))
                if !gpu_sampling_tail_is_scale_safe(eb.format, sample.embed_scale) =>
            {
                None
            }
            (Some(lb), Some(eb), Some(s), Some(sample)) => {
                let nb = |bytes: u64| pool_get(k, bytes);
                let id_buf = nb(4);
                let am_scalar = nb(4);
                // Gather scalar: bpr (u32) | embed_scale (f32).
                let eg_scalar = nb(8);
                unsafe {
                    *(am_scalar.contents() as *mut u32) = s.vocab_size as u32;
                    // Both fields must be written: `pool_get` classes by
                    // `bytes.max(32).next_power_of_two()` and never zeroes, so an
                    // unwritten embed_scale is a recycled stale float from another
                    // scalar in this same 32-byte class.
                    let p = eg_scalar.contents() as *mut u8;
                    *(p as *mut u32) = match eb.format {
                        ResidentWeightFormat::Q8_0 => self.hidden / 32,
                        ResidentWeightFormat::Q4K
                        | ResidentWeightFormat::Q5K
                        | ResidentWeightFormat::Q6K => self.hidden / 256,
                        ResidentWeightFormat::Q1_0 | ResidentWeightFormat::Q2_0G128 => {
                            self.hidden / 128
                        }
                        ResidentWeightFormat::Q2_0G64 => self.hidden / 64,
                        ResidentWeightFormat::DenseF32
                        | ResidentWeightFormat::DenseF16
                        | ResidentWeightFormat::DenseBF16 => {
                            unreachable!("dense weights are not token embeddings")
                        }
                    } as u32;
                    *(p.add(4) as *mut f32) = sample.embed_scale;
                }
                match sample.mode {
                    SampleMode::Greedy => {
                        e.set_compute_pipeline_state(&k.argmax_f32_greedy_pipeline);
                        e.set_buffer(0, Some(lb), 0);
                        e.set_buffer(1, Some(&id_buf), 0);
                        e.set_buffer(2, Some(&am_scalar), 0);
                    }
                    SampleMode::Temperature {
                        inv_temperature,
                        base_seed,
                    } => {
                        let temperature_scalar = nb(4);
                        let seed_scalar = nb(8);
                        let token_seed =
                            base_seed ^ 0x9E37_79B9_7F4A_7C15u64.wrapping_mul(position as u64 + 1);
                        unsafe {
                            *(temperature_scalar.contents() as *mut f32) = inv_temperature;
                            *(seed_scalar.contents() as *mut u64) = token_seed;
                        }
                        e.set_compute_pipeline_state(&k.sample_gumbel_f32_pipeline);
                        e.set_buffer(0, Some(lb), 0);
                        e.set_buffer(1, Some(&id_buf), 0);
                        e.set_buffer(2, Some(&am_scalar), 0);
                        e.set_buffer(3, Some(&temperature_scalar), 0);
                        e.set_buffer(4, Some(&seed_scalar), 0);
                        keep.extend([temperature_scalar, seed_scalar]);
                    }
                }
                e.dispatch_thread_groups(
                    metal::MTLSize {
                        width: 1,
                        height: 1,
                        depth: 1,
                    },
                    metal::MTLSize {
                        width: 1024,
                        height: 1,
                        depth: 1,
                    },
                );
                let gather_pipeline = match eb.format {
                    ResidentWeightFormat::Q8_0 => &k.embed_row_gather_q8_wire_pipeline,
                    ResidentWeightFormat::Q4K => &k.embed_row_gather_q4k_pipeline,
                    ResidentWeightFormat::Q5K => &k.embed_row_gather_q5k_pipeline,
                    ResidentWeightFormat::Q6K => &k.embed_row_gather_q6k_pipeline,
                    ResidentWeightFormat::Q1_0 => &k.embed_row_gather_q1_0_pipeline,
                    ResidentWeightFormat::Q2_0G64 => &k.embed_row_gather_q2_0_g64_pipeline,
                    ResidentWeightFormat::Q2_0G128 => &k.embed_row_gather_q2_0_g128_pipeline,
                    ResidentWeightFormat::DenseF32
                    | ResidentWeightFormat::DenseF16
                    | ResidentWeightFormat::DenseBF16 => {
                        unreachable!("dense weights are not token embeddings")
                    }
                };
                e.set_compute_pipeline_state(gather_pipeline);
                e.set_buffer(0, Some(&eb.buffer), 0);
                e.set_buffer(1, Some(&id_buf), 0);
                e.set_buffer(2, Some(&self.buf_a), 0);
                e.set_buffer(3, Some(&eg_scalar), 0);
                // Only `embed_row_gather_q8_wire` declares buffer(4) (embed_scale);
                // binding it on the K-quant gathers is legal and inert, so a non-unit
                // embed_scale must be refused before this point on those formats.
                e.set_buffer(4, Some(&eg_scalar), 4);
                dispatch_1d(e, gather_pipeline, self.hidden);
                keep.extend([am_scalar, eg_scalar]);
                Some(id_buf)
            }
            _ => None,
        };
        e.end_encoding();
        // The GPU stamps the done event as the graph's last command; the fast lane polls
        // it to observe completion without the completion-handler wake-up.
        cb.encode_signal_event(&self.done_event, event_value);
        // Commit NOW (still gated on the event): commandBuffer scheduling happens while the
        // previous token executes, so signaling the event later starts the GPU immediately.
        cb.commit();
        let encode_us = encode_started.elapsed().as_micros();
        Some(PreparedToken {
            position,
            has_logits: logits_stage.is_some(),
            has_sample: sampled_buf.is_some(),
            sample_signature: sample_stage.map(|stage| stage.mode.signature(position)),
            event_value,
            cb: cb.to_owned(),
            logits_buf,
            sampled_buf,
            final_from_a: from_a,
            _keep: keep,
            encode_us,
        })
    }

    /// One-command-buffer GPU prefill over `n` prompt tokens: rms_norm/RoPE/scatter/tiled
    /// attention run per token, but every matmul is the wire GEMM, so weights stream ONCE per
    /// prefill, not once per token. KV lands directly in the resident caches (positions
    /// 0..n); generation then continues with the resident decode, no CPU seeding. Returns
    /// the logits of the LAST prefilled token. Requirements mirror forward_token plus:
    /// f32 or Q8 KV cache, wire weights, head_dim % 32 == 0.
    #[allow(clippy::too_many_arguments)]
    pub fn prefill_tokens(
        &mut self,
        embeddings: &[f32],
        n_tokens: usize,
        layers: &[ResidentLayerWeights],
        cos_all: &[f32],
        sin_all: &[f32],
        scale: f32,
    ) -> Option<()> {
        if std::env::var_os("CAMELID_RESIDENT_TRACE").is_some() {
            eprintln!(
                "[resident-prefill] prefill_tokens ENTER n_tokens={n_tokens} moe={}",
                layers.iter().any(|l| l.moe.is_some())
            );
        }
        // MoE layers ride the f32 activation path with the routed experts added after the
        // (shared-expert) dense FFN. Opt out with CAMELID_METAL_MOE_PREFILL=0 -> CPU prefill.
        let has_moe = layers.iter().any(|l| l.moe.is_some());
        if has_moe && !moe_prefill_enabled() {
            {
                prefill_decline("prefill_tokens", 1);
                return None;
            }
        }
        if n_tokens == 0
            || !wire_weights_enabled()
            || !self.head_dim.is_multiple_of(32)
            || self.head_dim > 128
            || embeddings.len() != n_tokens * self.hidden
            || self.filled != 0
            || !self.ensure_capacity(n_tokens)
        {
            {
                prefill_decline("prefill_tokens", 2);
                return None;
            }
        }
        // gemma3 sandwich norms are wired into the decode encodes only
        // (encode_attention_block / encode_ffn_block); this batched prefill does
        // not apply them, so it must fail closed rather than run an incomplete
        // forward. Likewise the per-layer dual-theta schedule: this prefill
        // ropes every layer from ONE table set. (gemma3 additionally never
        // reaches here: head_dim 256 > 128.)
        if self.schedule.is_some()
            || layers
                .iter()
                .any(|l| l.post_attn_norm.is_some() || l.post_ffw_norm.is_some() || l.ffn_geglu)
        {
            {
                prefill_decline("prefill_tokens", 3);
                return None;
            }
        }
        let half_rope = cos_all.len() / n_tokens;
        if sin_all.len() != cos_all.len() || half_rope * 2 > self.head_dim {
            {
                prefill_decline("prefill_tokens", 4);
                return None;
            }
        }
        let k = metal_linear_kernel()?;
        // Qwen3 per-head QK-norm: when the layers carry q_norm/k_norm we apply an
        // in-place per-head RMSNorm to Q and K (after the QKV GEMM, before RoPE).
        // The per-head norm kernel is f32, so we keep the tiled-MM GEMM (fast) but
        // force off use_attn_mm/use_h16: that makes the MM GEMM emit f32 Q/K
        // [token][head][head_dim] and routes attention through the validated
        // non-attn-mm path, so the per-head norm runs in the cpu_reference order.
        let has_qk_norm = layers.first().is_some_and(|l| l.q_norm.is_some());
        let q_dim = self.n_heads * self.head_dim;
        let kv_dim = self.n_kv_heads * self.head_dim;
        let bpr_hidden = self.hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = self.ffn_dim / 32;

        let resident: Vec<[ResidentLinearWeight; 7]>;
        {
            let mut cache = metal_linear_cache().lock().ok()?;
            let mut wb =
                |w: &ResidentWeightBytes| resolve_resident_weight(&mut cache, &k.device, w, true);
            resident = layers
                .iter()
                .map(|l| {
                    Some([
                        wb(&l.q_weight_blocks)?,
                        wb(&l.k_weight_blocks)?,
                        wb(&l.v_weight_blocks)?,
                        wb(&l.o_weight_blocks)?,
                        wb(&l.gate_weight_blocks)?,
                        wb(&l.up_weight_blocks)?,
                        wb(&l.down_weight_blocks)?,
                    ])
                })
                .collect::<Option<Vec<_>>>()?;
        }
        let all_q8 = resident
            .iter()
            .flatten()
            .all(|w| w.format == ResidentWeightFormat::Q8_0);
        let resident_moe: Vec<Option<ResidentMoeResolved>> = if has_moe {
            let mut cache = metal_linear_cache().lock().ok()?;
            layers
                .iter()
                .map(|l| {
                    l.moe.as_ref().map_or(Some(None), |m| {
                        Some(Some(ResidentMoeResolved {
                            router: ResidentLinearWeight {
                                format: ResidentWeightFormat::DenseF32,
                                buffer: cache.weight_buffer(&k.device, m.router),
                                q8_wire: false,
                            },
                            expert_bias: m.expert_bias.map(|b| cache.weight_buffer(&k.device, b)),
                            gate_exps: resolve_resident_weight(
                                &mut cache,
                                &k.device,
                                &m.gate_exps,
                                true,
                            )?,
                            up_exps: resolve_resident_weight(
                                &mut cache, &k.device, &m.up_exps, true,
                            )?,
                            down_exps: resolve_resident_weight(
                                &mut cache,
                                &k.device,
                                &m.down_exps,
                                true,
                            )?,
                            n_expert: m.n_expert,
                            n_expert_used: m.n_expert_used,
                            expert_ff: m.expert_ff,
                            weights_scale: m.weights_scale,
                            weights_norm: m.weights_norm,
                        }))
                    })
                })
                .collect::<Option<Vec<_>>>()?
        } else {
            vec![None; layers.len()]
                .into_iter()
                .map(|_: Option<()>| None)
                .collect()
        };

        let nb = |bytes: usize| {
            k.device
                .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
        };
        // The attention-as-matmul gate and the all-half activation-stream gate are
        // decided before buffer allocation: when active, the layer chain's working
        // buffers are half-precision end to end (GEMM outputs, residual stream,
        // norms, silu), halving activation traffic.
        let n_pad = n_tokens.next_multiple_of(128);
        let gqa_group = self.n_heads / self.n_kv_heads;
        // A Q8 primary is admitted here by staging its blocks into a transient half K/V
        // buffer below (`kv_dequant_q8_to_h`); kv16-primary is still excluded because its
        // primary IS half and wants a direct binding rather than a staging pass.
        let stage_q8_kv = self.kvq8 && q8_attn_mm_enabled();
        let q8_stage_bytes = stage_q8_kv.then_some(()).and_then(|()| {
            attention_matmul_prefill_q8_stage_bytes(
                self.n_kv_heads,
                self.max_positions,
                self.head_dim,
                k.device.max_buffer_length() as usize,
            )
        });
        // MoE layers ride the f16 stream only when the routed path is the id-GEMM + panel
        // add (those have half variants); the grouped-GEMV fallback reads/writes f32.
        let use_attn_mm = (!has_moe || (moe_prefill_mm_enabled() && moe_prefill_grouped_enabled()))
            && !self.kv16
            && (!self.kvq8 || stage_q8_kv)
            && (!stage_q8_kv || q8_stage_bytes.is_some())
            && all_q8
            && mm_prefill_enabled()
            && !has_qk_norm
            && attention_matmul_prefill_rows_fit(n_tokens, self.max_positions)
            && q_dim.is_multiple_of(128)
            && kv_dim.is_multiple_of(128)
            && self.hidden.is_multiple_of(128)
            && self.ffn_dim.is_multiple_of(128)
            && attention_matmul_prefill_head_dim_supported(self.head_dim)
            && self.n_heads * n_pad * 256 * 4 <= attn_mm_scratch_cap_bytes();
        // Query-block width for the S/P panels: the panels are [head][qb][n_pad], so
        // memory is linear in the block width and the budget sets how many query
        // columns are materialized at once. Prompts that fit in one block reproduce
        // the untiled math bit-for-bit (q_offset = 0).
        let attn_qb = if use_attn_mm {
            let per_col = self.n_heads * n_pad * 4; // S + P bytes per query column
                                                    // max-then-min, NOT clamp: short prompts have n_pad < 256 and clamp(256,
                                                    // n_pad) panics on min > max; a single block covering n_pad is correct there.
            ((attn_mm_scratch_cap_bytes() / per_col) & !63)
                .max(256)
                .min(n_pad)
        } else {
            0
        };
        // Element size of the whole activation stream. This once had to track
        // `use_fused_rope` rather than `use_attn_mm`, because with the fused RoPE off the
        // attn-mm block rebuilt `q_h` via a convert hardwired to f32->f16 -- so a half
        // `q_buf` was reinterpreted as f32 and the sampler saw non-finite logits.
        //
        // The Q8 lane no longer needs that restriction: `rope_rotate_batch_h` rotates Q
        // straight into the half panel (and K in place), and `kv_scatter_batch_kvq8_h`
        // quantizes from half operands, so the es=2 stream is closed end to end without a
        // fused rope+scatter kernel -- which would have been the wrong shape anyway, since
        // Q8 needs a per-32-element-block amax and the fused kernel runs one thread per
        // RoPE pair. The convert is now guarded on `!use_h16` to match.
        let use_h16 = use_attn_mm && half_rope * 2 == self.head_dim;
        let es = if use_h16 { 2 } else { 4 }; // element size of the activation stream
        let seq = nb(n_tokens * self.hidden * es);
        let seq_out = nb(n_tokens * self.hidden * es);
        let normf = nb(n_tokens * self.hidden * 4);
        let q_buf = nb(n_tokens * q_dim * es);
        let k_buf = nb(n_tokens * kv_dim * es);
        let v_buf = nb(n_tokens * kv_dim * es);
        let ctx_buf = nb(n_tokens * q_dim * 4);
        let o_buf = nb(n_tokens * self.hidden * es);
        let gate_buf = nb(n_tokens * self.ffn_dim * es);
        let up_buf = nb(n_tokens * self.ffn_dim * es);
        let silu_buf = nb(n_tokens * self.ffn_dim * 4);
        let down_buf = nb(n_tokens * self.hidden * es);
        let cos_buf = nb(cos_all.len() * 4);
        let sin_buf = nb(sin_all.len() * 4);
        // h16: memcpy raw f32 to a staging buffer; the command buffer's first dispatch
        // converts it to the half panel on the GPU (the per-element CPU conversion cost
        // ~3ms of wall time on a 601-token prompt).
        let seq_f32 = if use_h16 {
            let b = nb(n_tokens * self.hidden * 4);
            write_buffer_f32(&b, embeddings);
            Some(b)
        } else {
            write_buffer_f32(&seq, embeddings);
            None
        };
        write_buffer_f32(&cos_buf, cos_all);
        write_buffer_f32(&sin_buf, sin_all);

        // Constant scalars shared by every layer.
        let rms_scalar = nb(8);
        let qkv_scalar = nb(16);
        let ffn_scalar = nb(20);
        let o_scalar = nb(12);
        let n_elems = nb(12);
        unsafe {
            let p = rms_scalar.contents() as *mut u8;
            *(p as *mut u32) = self.hidden as u32;
            *(p.add(4) as *mut f32) = self.eps;
            let q = qkv_scalar.contents() as *mut u32;
            *q = bpr_hidden as u32; // blocks per row over hidden
            *q.add(1) = q_dim as u32;
            *q.add(2) = kv_dim as u32;
            *q.add(3) = n_tokens as u32;
            let f = ffn_scalar.contents() as *mut u32;
            *f = bpr_hidden as u32; // gate/up: blocks per row over hidden
            *f.add(1) = self.ffn_dim as u32; // gate/up rows
            *f.add(2) = bpr_ffn as u32; // down: blocks per row over ffn
            *f.add(3) = self.hidden as u32; // down rows
            *f.add(4) = n_tokens as u32;
            let o = o_scalar.contents() as *mut u32;
            *o = bpr_q as u32;
            *o.add(1) = self.hidden as u32;
            *o.add(2) = n_tokens as u32;
            let n = n_elems.contents() as *mut u32;
            *n = (n_tokens * self.hidden) as u32;
            *n.add(1) = (n_tokens * self.ffn_dim) as u32;
            *n.add(2) = (n_tokens * q_dim) as u32;
        }
        // Batched RoPE / scatter / attention scalars — one set shared by every token row
        // (the per-token position is recovered from the grid's y coordinate in-kernel).
        let rope_q_scalar = nb(16);
        let rope_k_scalar = nb(16);
        let scatter_scalar = nb(16);
        let attn_scalar = nb(32);
        unsafe {
            let r = rope_q_scalar.contents() as *mut u32;
            *r = self.n_heads as u32;
            *r.add(1) = self.head_dim as u32;
            *r.add(2) = half_rope as u32;
            *r.add(3) = u32::from(self.split_half_pairing);
            let r = rope_k_scalar.contents() as *mut u32;
            *r = self.n_kv_heads as u32;
            *r.add(1) = self.head_dim as u32;
            *r.add(2) = half_rope as u32;
            *r.add(3) = u32::from(self.split_half_pairing);
            let sc = scatter_scalar.contents() as *mut u32;
            *sc = self.head_dim as u32;
            *sc.add(1) = self.max_positions as u32;
            *sc.add(2) = 0u32; // base position: prefill always starts an empty cache
            *sc.add(3) = if self.kvq8 {
                (self.n_kv_heads * (self.head_dim / 32)) as u32
            } else {
                kv_dim as u32
            };
            let a = attn_scalar.contents() as *mut u8;
            *(a as *mut u32) = self.n_heads as u32;
            *(a.add(4) as *mut u32) = self.head_dim as u32;
            *(a.add(8) as *mut u32) = (self.n_heads / self.n_kv_heads) as u32;
            *(a.add(12) as *mut f32) = scale;
            let kv_position_stride = if self.kvq8 {
                (self.head_dim / 32) * 34
            } else {
                self.head_dim
            };
            *(a.add(16) as *mut u32) = kv_position_stride as u32;
            *(a.add(20) as *mut u32) = (self.max_positions * kv_position_stride) as u32;
            *(a.add(24) as *mut u32) = 0u32; // kv base offset
            *(a.add(28) as *mut u32) = n_tokens as u32;
        }
        // Per-head QK-norm scalar (Qwen3): head_dim(u32) | eps(f32) | use_weight(u32).
        // Shared by every layer; the per-layer q_norm/k_norm weights vary, the geometry
        // does not. Built only when QK-norm is in play.
        let perhead_qk_scalar = nb(12);
        if has_qk_norm {
            unsafe {
                let p = perhead_qk_scalar.contents() as *mut u8;
                *(p as *mut u32) = self.head_dim as u32;
                *(p.add(4) as *mut f32) = self.eps;
                *(p.add(8) as *mut u32) = 1u32; // use_weight
            }
        }

        // CAMELID_PREFILL_TRACE=1: split each stage into its own command buffer and
        // report accumulated hardware GPU-busy time per stage (per-stage waits inflate
        // wall time; the split is for attribution, not for production).
        let trace = std::env::var_os("CAMELID_PREFILL_TRACE").is_some();
        let mut stage_us: std::collections::BTreeMap<&'static str, u128> =
            std::collections::BTreeMap::new();
        let mut cb: metal::CommandBuffer = k.queue.new_command_buffer().to_owned();
        let mut e: metal::ComputeCommandEncoder = cb.new_compute_command_encoder().to_owned();
        macro_rules! stage {
            ($label:expr) => {
                if trace {
                    e.end_encoding();
                    cb.commit();
                    cb.wait_until_completed();
                    let (busy_us, _) = command_buffer_gpu_times_us(&cb);
                    *stage_us.entry($label).or_insert(0) += busy_us;
                    cb = k.queue.new_command_buffer().to_owned();
                    e = cb.new_compute_command_encoder().to_owned();
                }
            };
        }
        // The tiled-MM prefill GEMM needs 32-multiple row counts, paired Q8_0 blocks
        // (BK=64 = 2 blocks/step), and half activations — decided once for the whole
        // prefill since the activation buffers are emitted in the matching precision.
        // QK-norm (Qwen3) keeps the tiled-MM GEMM (the dominant prefill cost: weights
        // stream once per 64 tokens instead of once per 8) — only use_attn_mm/use_h16
        // are forced off so Q/K stay f32 [token][head][head_dim] for the per-head norm
        // and the validated non-attn-mm attention path. The MM GEMM here outputs f32
        // (use_h16 is false), so the per-head norm runs in f32 against the existing
        // rms_norm_per_head_f32 kernel.
        // MoE layers keep the GEMM path for attention + shared expert (their dense work is
        // ~85% of the prefill and the batched-column GEMV is issue-bound); only the
        // attention-as-matmul/f16-stream path is declined so the residual stream stays f32
        // for the routed-expert kernels.
        let use_mm = all_q8
            && mm_prefill_enabled()
            && q_dim.is_multiple_of(128)
            && kv_dim.is_multiple_of(128)
            && self.hidden.is_multiple_of(128)
            && self.ffn_dim.is_multiple_of(128);
        // Half-precision GEMM inputs, padded to a 64-token multiple so the MM kernel's
        // direct device B loads never run off the end (padding rows are garbage; they
        // only feed output columns past n_tokens, which are never stored).
        // Attention-as-matmul scratch (prompts short enough to materialize S):
        // half K/V copies, half Q, half S scores and P probabilities per head.
        // Half KV mirrors are persistent per-layer session buffers (zero-filled at
        // allocation/growth): the attention-as-matmul prefill consumes them, the fallback
        // path's scatter fills them, and the split-K kv16 decode attention reads them.
        // The half KV mirrors are always real session buffers on this path (resident
        // prefill requires !kv16-primary), so the scatter always fills them.
        let kv16_flag = nb(4);
        unsafe {
            *(kv16_flag.contents() as *mut u32) = 1u32;
        }

        let q_h = nb(if use_attn_mm { n_pad * q_dim * 2 } else { 2 });
        let s_big = nb(if use_attn_mm {
            self.n_heads * n_pad * attn_qb * 2
        } else {
            2
        });
        let p_big = nb(if use_attn_mm {
            self.n_heads * n_pad * attn_qb * 2
        } else {
            2
        });
        let vt_scratch = nb(if use_attn_mm {
            self.n_kv_heads * self.head_dim * n_pad * 2
        } else {
            2
        });
        // Transient half K/V staging for the Q8 lane, laid out exactly like the f32 lane's
        // persistent cache_k16/cache_v16 mirrors (max_positions stride) so every consumer
        // below binds it without a stride change. Reused across all layers: one layer is
        // live at a time, so this is ~16.8 MB at 8192 positions rather than the ~256 MB of
        // permanent mirrors the f32 lane carries.
        let q8_k_stage = nb(if use_attn_mm && stage_q8_kv {
            q8_stage_bytes.expect("Q8 staging admission checked above")
        } else {
            2
        });
        let q8_v_stage = nb(if use_attn_mm && stage_q8_kv {
            q8_stage_bytes.expect("Q8 staging admission checked above")
        } else {
            2
        });
        let q8_stage_scalar = nb(28);
        if use_attn_mm && stage_q8_kv {
            unsafe {
                let p = q8_stage_scalar.contents() as *mut u32;
                *p = self.head_dim as u32;
                *p.add(1) = n_pad as u32; // rows to fill
                *p.add(2) = n_tokens as u32; // rows actually materialized
                *p.add(3) = ((self.head_dim / 32) * 34) as u32; // src position stride (bytes)
                *p.add(4) = (self.max_positions * (self.head_dim / 32) * 34) as u32; // src kv-head stride (bytes)
                *p.add(5) = self.head_dim as u32; // dst position stride (elements)
                *p.add(6) = (self.max_positions * self.head_dim) as u32; // dst kv-head stride (elements)
            }
        }
        let fused_rope_scalar = nb(24);
        let vt_scalar = nb(16);
        unsafe {
            let p = fused_rope_scalar.contents() as *mut u32;
            *p = self.n_heads as u32;
            *p.add(1) = self.n_kv_heads as u32;
            *p.add(2) = self.head_dim as u32;
            *p.add(3) = half_rope as u32;
            *p.add(4) = u32::from(self.split_half_pairing);
            *p.add(5) = self.max_positions as u32;
        }
        unsafe {
            let p = vt_scalar.contents() as *mut u32;
            *p = self.head_dim as u32;
            *p.add(1) = self.max_positions as u32;
            *p.add(2) = n_pad as u32;
            *p.add(3) = n_tokens as u32;
        }
        let attn_mm_scalar = nb(48);
        unsafe {
            let p = attn_mm_scalar.contents() as *mut u32;
            // S pass: kdim=head_dim, rows=n_pad (positions), cols=n_tokens (queries)
            *p = self.head_dim as u32;
            *p.add(1) = n_pad as u32;
            *p.add(2) = n_tokens as u32;
            // PV pass: kdim=n_pad, rows=head_dim, cols=n_tokens
            *p.add(3) = n_pad as u32;
            *p.add(4) = self.head_dim as u32;
            *p.add(5) = n_tokens as u32;
            // shared strides and modes filled per-dispatch below
            *p.add(6) = (self.max_positions * self.head_dim) as u32; // kv batch stride
            *p.add(7) = (n_pad * attn_qb) as u32; // S/P batch stride (per query block)
            *p.add(8) = self.head_dim as u32; // q batch stride / kv row stride
            *p.add(9) = q_dim as u32; // q row stride (also ctx row stride)
            *p.add(10) = 1u32; // group=1 placeholder (real group below)
            *p.add(11) = gqa_group as u32;
        }
        let softmax_scalar = nb(20);
        unsafe {
            let p = softmax_scalar.contents() as *mut u32;
            *p = n_pad as u32;
            *p.add(1) = n_tokens as u32;
            *(p.add(2) as *mut f32) = scale;
            *p.add(3) = attn_qb as u32; // rows per query block
            *p.add(4) = 0; // window = 0: full causal, this path serves no windowed arch
        }
        let normf_h = nb(if use_mm { n_pad * self.hidden * 2 } else { 2 });
        let ctx_h = nb(if use_mm { n_pad * q_dim * 2 } else { 2 });
        let silu_h = nb(if use_mm { n_pad * self.ffn_dim * 2 } else { 2 });
        let convert = |e: &metal::ComputeCommandEncoderRef,
                       src: &Buffer,
                       dst: &Buffer,
                       count_buf: &Buffer,
                       count_off: u64,
                       count: usize| {
            e.set_compute_pipeline_state(&k.f32_to_f16_pipeline);
            e.set_buffer(0, Some(src), 0);
            e.set_buffer(1, Some(dst), 0);
            e.set_buffer(2, Some(count_buf), count_off);
            dispatch_1d(e, &k.f32_to_f16_pipeline, count);
        };
        let mut projection_keep = Vec::new();
        // One activation-quant scratch pair per contraction width, shared by
        // every K-quant projection of every layer. See
        // `encode_resident_kquant_matmul_f32`: allocating per dispatch instead
        // would hold n_layers x 7 live scratch buffers at once, which for an 8B
        // model on a multi-thousand-token prompt is gigabytes of unified memory
        // on top of the resident weights.
        let mut kquant_scratch: HashMap<usize, (Buffer, Buffer)> = HashMap::new();
        let mut gemm = |e: &metal::ComputeCommandEncoderRef,
                        y: &Buffer,
                        w: &ResidentLinearWeight,
                        out: &Buffer,
                        scalar: &Buffer,
                        bpr_off: u64,
                        rows_off: u64,
                        n_off: u64,
                        input_width: usize,
                        rows: usize| {
            if use_mm {
                // Simdgroup-matrix tiles: 64-row x 64-token output per threadgroup, so
                // weights stream once per 64 tokens instead of once per 8.
                e.set_compute_pipeline_state(if use_h16 {
                    &k.q8_0_block_wire_mm_f16o_pipeline
                } else {
                    &k.q8_0_block_wire_mm_pipeline
                });
                e.set_buffer(0, Some(y), 0);
                e.set_buffer(2, Some(&w.buffer), 0);
                e.set_buffer(3, Some(out), 0);
                e.set_buffer(4, Some(scalar), bpr_off);
                e.set_buffer(5, Some(scalar), rows_off);
                e.set_buffer(6, Some(scalar), n_off);
                // A 128x32 half | B 64x32 half (A region doubles as tail scratch).
                e.set_threadgroup_memory_length(0, 12288);
                e.dispatch_thread_groups(
                    metal::MTLSize {
                        width: (rows / 64) as u64,
                        height: (n_tokens as u64).div_ceil(128),
                        depth: 1,
                    },
                    metal::MTLSize {
                        width: 256,
                        height: 1,
                        depth: 1,
                    },
                );
                return;
            }
            let local_scalar = pool_get(k, 12);
            match w.format {
                ResidentWeightFormat::DenseF32
                | ResidentWeightFormat::DenseF16
                | ResidentWeightFormat::DenseBF16
                | ResidentWeightFormat::Q8_0
                | ResidentWeightFormat::Q1_0
                | ResidentWeightFormat::Q2_0G64
                | ResidentWeightFormat::Q2_0G128 => encode_resident_matmul_f32(
                    e,
                    k,
                    &mut projection_keep,
                    y,
                    w,
                    out,
                    &local_scalar,
                    input_width,
                    rows,
                    n_tokens,
                ),
                ResidentWeightFormat::Q4K
                | ResidentWeightFormat::Q5K
                | ResidentWeightFormat::Q6K => {
                    let (scales, quants) = kquant_scratch.entry(input_width).or_insert_with(|| {
                        let n_sb = input_width / 256;
                        (
                            pool_get(k, (n_tokens * n_sb * 4) as u64),
                            pool_get(k, (n_tokens * input_width) as u64),
                        )
                    });
                    encode_resident_kquant_matmul_f32(
                        e,
                        k,
                        y,
                        w,
                        out,
                        &local_scalar,
                        scales,
                        quants,
                        input_width,
                        rows,
                        n_tokens,
                    );
                }
            }
            projection_keep.push(local_scalar);
        };
        // One thread per (unit, token): elementwise grid with token rows on y.
        let dispatch_rows = |e: &metal::ComputeCommandEncoderRef,
                             pipeline: &ComputePipelineState,
                             n: usize,
                             rows: usize| {
            let w = pipeline.thread_execution_width().max(1);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (n as u64).div_ceil(w),
                    height: rows as u64,
                    depth: 1,
                },
                metal::MTLSize {
                    width: w,
                    height: 1,
                    depth: 1,
                },
            );
        };
        // rms_norm_batch over n_tokens contiguous rows: one 256-thread group per row
        // (same group size as the per-token kernel, so the reduction is byte-exact).
        let norm_rows = |e: &metal::ComputeCommandEncoderRef,
                         pipeline: &ComputePipelineState,
                         input: &Buffer,
                         weight: &Buffer,
                         output: &Buffer,
                         scalar: &Buffer,
                         rows: usize| {
            e.set_compute_pipeline_state(pipeline);
            e.set_buffer(0, Some(input), 0);
            e.set_buffer(1, Some(weight), 0);
            e.set_buffer(2, Some(output), 0);
            e.set_buffer(3, Some(scalar), 0);
            e.set_buffer(4, Some(scalar), 4);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: rows as u64,
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 256,
                    height: 1,
                    depth: 1,
                },
            );
        };
        if let Some(seq_f32) = &seq_f32 {
            convert(&e, seq_f32, &seq, &n_elems, 0, n_tokens * self.hidden);
        }
        let mut moe_keep: Vec<Buffer> = Vec::new();
        // Expert-indexed MMA prefill scratch, allocated ONCE (per-layer fresh allocation of
        // ~60 MB of panels inflated the driver scheduling window from 2 to 29 ms).
        let moe_mm = if has_moe && moe_prefill_mm_enabled() {
            resident_moe.iter().flatten().next().map(|m| {
                let kk = m.n_expert_used;
                let ff = m.expert_ff;
                let ne = m.n_expert;
                let slots = n_tokens * kk;
                let tile_tok = if moe_prefill_tile32_enabled() {
                    32
                } else {
                    128
                };
                let j_max = ne + slots.div_ceil(tile_tok);
                // rows: every expert padded to 32 + a 128-row slack the last tile may over-read
                let total_pad = slots + 32 * ne + 128;
                (
                    j_max,
                    total_pad,
                    nb(j_max * 3 * 4),               // tile_map
                    nb(ne * 4),                      // panel_off
                    nb(total_pad * 4),               // panel_slot
                    nb(total_pad * 4),               // row_map_tok (was panel_x)
                    nb(total_pad * ff * 4),          // pg
                    nb(total_pad * ff * 4),          // pu
                    nb(total_pad * ff * 2),          // pact_h (f16, silu fused)
                    nb(total_pad * self.hidden * 4), // pd
                    nb(80),                          // scalars (+ zero word at 76)
                    nb(slots * 4),                   // slot_panel (inverse map)
                )
            })
        } else {
            None
        };
        let (cur, nxt) = (&seq, &seq_out);
        for (i, layer) in layers.iter().enumerate() {
            // The resident prefill exists to fill the KV cache: the caller discards the
            // hidden stream and the last prompt token re-runs through the resident
            // single-token path. So the final layer only needs norm -> K/V GEMMs ->
            // rope/scatter; its Q projection, attention, O, and FFN outputs are dead.
            let last_layer = i + 1 == layers.len();
            let w = &resident[i];
            let attn_norm_buf;
            let ffn_norm_buf;
            {
                let mut cache = metal_linear_cache().lock().ok()?;
                attn_norm_buf = cache.weight_buffer(&k.device, layer.attn_norm);
                ffn_norm_buf = cache.weight_buffer(&k.device, layer.ffn_norm);
            }
            // Attention half: batched norm -> batched QKV GEMM -> batched rope/scatter ->
            // causal prefill attention (one dispatch, grid (n_heads, n_tokens)) -> O GEMM
            // -> residual.
            let qkv_y: &Buffer = if use_mm {
                norm_rows(
                    &e,
                    if use_h16 {
                        &k.rms_norm_batch_h_pipeline
                    } else {
                        &k.rms_norm_batch_f16o_pipeline
                    },
                    cur,
                    &attn_norm_buf,
                    &normf_h,
                    &rms_scalar,
                    n_tokens,
                );
                &normf_h
            } else {
                norm_rows(
                    &e,
                    &k.rms_norm_batch_pipeline,
                    cur,
                    &attn_norm_buf,
                    &normf,
                    &rms_scalar,
                    n_tokens,
                );
                &normf
            };
            stage!("1:norm+cvt");
            if !last_layer {
                gemm(
                    &e,
                    qkv_y,
                    &w[0],
                    &q_buf,
                    &qkv_scalar,
                    0,
                    4,
                    12,
                    self.hidden,
                    q_dim,
                );
            }
            gemm(
                &e,
                qkv_y,
                &w[1],
                &k_buf,
                &qkv_scalar,
                0,
                8,
                12,
                self.hidden,
                kv_dim,
            );
            gemm(
                &e,
                qkv_y,
                &w[2],
                &v_buf,
                &qkv_scalar,
                0,
                8,
                12,
                self.hidden,
                kv_dim,
            );
            stage!("2:gemm_qkv");
            // Qwen3 per-head QK-norm: in-place RMSNorm over each head's head_dim slice
            // of the f32 Q/K buffers (layout [token][head][head_dim] -> n_tokens*heads
            // contiguous groups), applied after the QKV GEMM and before RoPE. has_qk_norm
            // forces the f32 path, so q_buf/k_buf are f32 here.
            if let (Some(qn), Some(kn)) = (layer.q_norm, layer.k_norm) {
                let qnorm_buf = nb(self.head_dim * 4);
                let knorm_buf = nb(self.head_dim * 4);
                write_buffer_f32(&qnorm_buf, qn);
                write_buffer_f32(&knorm_buf, kn);
                if !last_layer {
                    encode_rms_norm_per_head(
                        &e,
                        k,
                        &q_buf,
                        &qnorm_buf,
                        &q_buf,
                        &perhead_qk_scalar,
                        n_tokens * self.n_heads,
                        0,
                    );
                }
                encode_rms_norm_per_head(
                    &e,
                    k,
                    &k_buf,
                    &knorm_buf,
                    &k_buf,
                    &perhead_qk_scalar,
                    n_tokens * self.n_kv_heads,
                    0,
                );
                stage!("2b:qk_norm");
            }
            // Deliberately excludes the Q8 lane: rope_scatter_qh_h writes rotated K straight
            // into cache_k/cache_k16, which a Q8 primary cannot accept without a quantizing
            // twin of that kernel. Decoupling it from use_attn_mm keeps this change to the
            // attention path; the unfused RoPE costs three dispatches instead of one per
            // layer, which is small next to the O(n^2) attention win being unblocked.
            let use_fused_rope = use_attn_mm && !stage_q8_kv && half_rope * 2 == self.head_dim;
            if use_fused_rope {
                // Fused rope(Q)->half panel + rope(K)->caches + V scatter, one dispatch.
                e.set_compute_pipeline_state(if use_h16 {
                    &k.rope_scatter_qh_h_pipeline
                } else {
                    &k.rope_scatter_qh_pipeline
                });
                e.set_buffer(0, Some(&q_buf), 0);
                e.set_buffer(1, Some(&k_buf), 0);
                e.set_buffer(2, Some(&v_buf), 0);
                e.set_buffer(3, Some(&q_h), 0);
                e.set_buffer(4, Some(&self.cache_k[i]), 0);
                e.set_buffer(5, Some(&self.cache_v[i]), 0);
                e.set_buffer(6, Some(&self.cache_k16[i]), 0);
                e.set_buffer(7, Some(&self.cache_v16[i]), 0);
                e.set_buffer(8, Some(&cos_buf), 0);
                e.set_buffer(9, Some(&sin_buf), 0);
                for j in 0..6u64 {
                    e.set_buffer(10 + j, Some(&fused_rope_scalar), j * 4);
                }
                dispatch_rows(
                    &e,
                    if use_h16 {
                        &k.rope_scatter_qh_h_pipeline
                    } else {
                        &k.rope_scatter_qh_pipeline
                    },
                    (self.n_heads + self.n_kv_heads) * half_rope + kv_dim,
                    n_tokens,
                );
                // MobileMoE: parameterless per-head L2 AFTER RoPE. The fused kernel already
                // wrote Q to the half panel and K into the caches, so norm them in place.
                if layer.qk_l2_norm_after_rope {
                    debug_assert!(use_h16, "fused-rope L2 expects the half query panel");
                    let l2s = nb(8);
                    unsafe {
                        let q = l2s.contents() as *mut u8;
                        *(q as *mut u32) = n_tokens as u32;
                        *(q.add(4) as *mut f32) = self.eps;
                    }
                    e.set_compute_pipeline_state(&k.moe_l2_post_rope_h_pipeline);
                    e.set_buffer(0, Some(&q_h), 0);
                    e.set_buffer(1, Some(&self.cache_k[i]), 0);
                    e.set_buffer(2, Some(&self.cache_k16[i]), 0);
                    e.set_buffer(3, Some(&fused_rope_scalar), 0); // n_heads
                    e.set_buffer(4, Some(&fused_rope_scalar), 4); // n_kv_heads
                    e.set_buffer(5, Some(&fused_rope_scalar), 8); // head_dim
                    e.set_buffer(6, Some(&fused_rope_scalar), 20); // max_positions
                    e.set_buffer(7, Some(&l2s), 0);
                    e.set_buffer(8, Some(&l2s), 4);
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: (n_tokens * (self.n_heads + self.n_kv_heads)) as u64,
                            height: 1,
                            depth: 1,
                        },
                        metal::MTLSize {
                            width: 32,
                            height: 1,
                            depth: 1,
                        },
                    );
                }
            } else if use_h16 && stage_q8_kv {
                // es=2 Q8 lane: q_buf/k_buf/v_buf are half here, so the f32 RoPE would
                // reinterpret them. Q rotates straight into the half query panel rather
                // than in place, because the `convert` that would otherwise build q_h is
                // hardwired f32->f16 and would misread a half q_buf. Safe only under full
                // rotary coverage (half_rope * 2 == head_dim), which use_h16 requires.
                let rope_h = |e: &metal::ComputeCommandEncoderRef,
                              src: &Buffer,
                              dst: &Buffer,
                              scalar: &Buffer,
                              heads: usize| {
                    e.set_compute_pipeline_state(&k.rope_rotate_batch_h_pipeline);
                    e.set_buffer(0, Some(src), 0);
                    e.set_buffer(1, Some(dst), 0);
                    e.set_buffer(2, Some(&cos_buf), 0);
                    e.set_buffer(3, Some(&sin_buf), 0);
                    for j in 0..4u64 {
                        e.set_buffer(4 + j, Some(scalar), j * 4);
                    }
                    dispatch_rows(
                        e,
                        &k.rope_rotate_batch_h_pipeline,
                        heads * half_rope,
                        n_tokens,
                    );
                };
                rope_h(&e, &q_buf, &q_h, &rope_q_scalar, self.n_heads);
                rope_h(&e, &k_buf, &k_buf, &rope_k_scalar, self.n_kv_heads);
                e.set_compute_pipeline_state(&k.kv_scatter_batch_kvq8_h_pipeline);
                e.set_buffer(0, Some(&k_buf), 0);
                e.set_buffer(1, Some(&v_buf), 0);
                e.set_buffer(2, Some(&self.cache_k[i]), 0);
                e.set_buffer(3, Some(&self.cache_v[i]), 0);
                for j in 0..4u64 {
                    e.set_buffer(4 + j, Some(&scatter_scalar), j * 4);
                }
                dispatch_rows(
                    &e,
                    &k.kv_scatter_batch_kvq8_h_pipeline,
                    self.n_kv_heads * (self.head_dim / 32),
                    n_tokens,
                );
            } else {
                e.set_compute_pipeline_state(&k.rope_rotate_batch_pipeline);
                e.set_buffer(0, Some(&q_buf), 0);
                e.set_buffer(1, Some(&cos_buf), 0);
                e.set_buffer(2, Some(&sin_buf), 0);
                for j in 0..4u64 {
                    e.set_buffer(3 + j, Some(&rope_q_scalar), j * 4);
                }
                dispatch_rows(
                    &e,
                    &k.rope_rotate_batch_pipeline,
                    self.n_heads * half_rope,
                    n_tokens,
                );
                e.set_compute_pipeline_state(&k.rope_rotate_batch_pipeline);
                e.set_buffer(0, Some(&k_buf), 0);
                e.set_buffer(1, Some(&cos_buf), 0);
                e.set_buffer(2, Some(&sin_buf), 0);
                for j in 0..4u64 {
                    e.set_buffer(3 + j, Some(&rope_k_scalar), j * 4);
                }
                dispatch_rows(
                    &e,
                    &k.rope_rotate_batch_pipeline,
                    self.n_kv_heads * half_rope,
                    n_tokens,
                );
                // MobileMoE: parameterless per-head L2 norm on Q and K AFTER RoPE — must match
                // the decode path or the prefilled K in the cache is un-normed.
                if layer.qk_l2_norm_after_rope {
                    let l2_scalar = nb(12);
                    unsafe {
                        let p = l2_scalar.contents() as *mut u8;
                        *(p as *mut u32) = self.head_dim as u32;
                        *(p.add(4) as *mut f32) = self.eps;
                        *(p.add(8) as *mut u32) = 0;
                    }
                    if !last_layer {
                        encode_rms_norm_per_head(
                            &e,
                            k,
                            &q_buf,
                            &cos_buf,
                            &q_buf,
                            &l2_scalar,
                            n_tokens * self.n_heads,
                            0,
                        );
                    }
                    encode_rms_norm_per_head(
                        &e,
                        k,
                        &k_buf,
                        &cos_buf,
                        &k_buf,
                        &l2_scalar,
                        n_tokens * self.n_kv_heads,
                        0,
                    );
                }
                let scatter_pipeline = if self.kvq8 {
                    &k.kv_scatter_batch_kvq8_pipeline
                } else if self.kv16 {
                    &k.kv_scatter_batch_kv16_pipeline
                } else {
                    &k.kv_scatter_batch_pipeline
                };
                e.set_compute_pipeline_state(scatter_pipeline);
                e.set_buffer(0, Some(&k_buf), 0);
                e.set_buffer(1, Some(&v_buf), 0);
                e.set_buffer(2, Some(&self.cache_k[i]), 0);
                e.set_buffer(3, Some(&self.cache_v[i]), 0);
                for j in 0..4u64 {
                    e.set_buffer(4 + j, Some(&scatter_scalar), j * 4);
                }
                if !self.kv16 && !self.kvq8 {
                    e.set_buffer(8, Some(&self.cache_k16[i]), 0);
                    e.set_buffer(9, Some(&self.cache_v16[i]), 0);
                    e.set_buffer(10, Some(&kv16_flag), 0);
                }
                let scatter_units = if self.kvq8 {
                    self.n_kv_heads * (self.head_dim / 32)
                } else {
                    kv_dim
                };
                dispatch_rows(&e, scatter_pipeline, scatter_units, n_tokens);
            }
            stage!("3:rope+scatter");
            if last_layer {
                // KV cache writes for this layer are complete; everything below only
                // feeds the discarded hidden stream.
                continue;
            }
            // The flash-tiled prefill attention stages K/V and the P weights as half;
            // past ~1.6k positions on low-entropy prompts that quantization measurably
            // degrades attention (anchored-recall probes fail while the v3 kernel and the
            // CPU path agree), so v3 is the default beyond the attention-as-matmul cap and
            // flash stays opt-in. Moving the per-tile rescale diagonal to f32 was not
            // sufficient (probes still fail at 2k/8k); the remaining sink is the half
            // K/Q score staging, and fixing it needs an f32 staging layout that exceeds
            // the current threadgroup-memory budget — a redesign, not a patch.
            let use_flash_attn = std::env::var_os("CAMELID_METAL_FLASH_PREFILL")
                .is_some_and(|v| v == "1" || v.eq_ignore_ascii_case("true"))
                && !self.kv16
                && !self.kvq8
                && use_mm
                && self.head_dim.is_multiple_of(8)
                && self.head_dim <= 128;
            if use_attn_mm {
                // Attention as two batched half GEMMs + a causal row softmax: the
                // matmuls ride the same staged simdgroup-tile structure as the
                // weight GEMMs, with upper-triangle S tiles culled and the PV k-range
                // clamped to the causal limit.
                // q -> half (already produced by the fused rope pass when eligible)
                // q -> half. Produced by the fused rope pass when eligible, and by
                // rope_rotate_batch_h on the es=2 Q8 lane. This convert is hardwired
                // f32->f16, so it is correct ONLY when q_buf is genuinely f32 (es=4).
                if !use_fused_rope && !use_h16 {
                    convert(&e, &q_buf, &q_h, &n_elems, 8, n_tokens * q_dim);
                }
                // S = Q K^T (per query head; K shared per KV head)
                #[allow(clippy::too_many_arguments)]
                let smm = |e: &metal::ComputeCommandEncoderRef,
                           a: &Buffer,
                           b_buf2: &Buffer,
                           b_off: u64,
                           c_buf2: &Buffer,
                           c_off: u64,
                           kdim_off: u64,
                           a_bs: u32,
                           b_bs: u32,
                           c_bs: u32,
                           a_rs: u32,
                           b_rs: u32,
                           c_rs: u32,
                           a_es: u32,
                           grp: u32,
                           mode: u32,
                           q_off: u32,
                           rows: usize,
                           cols: usize| {
                    e.set_compute_pipeline_state(&k.half_mm_batched_f16o_pipeline);
                    e.set_buffer(0, Some(a), 0);
                    e.set_buffer(1, Some(b_buf2), b_off);
                    e.set_buffer(2, Some(c_buf2), c_off);
                    e.set_buffer(3, Some(&attn_mm_scalar), kdim_off);
                    e.set_buffer(4, Some(&attn_mm_scalar), kdim_off + 4);
                    // dynamic scalars in a transient buffer (cols and the absolute
                    // query offset vary per query block)
                    let dyn_buf = nb(48);
                    unsafe {
                        let p = dyn_buf.contents() as *mut u32;
                        *p = a_bs;
                        *p.add(1) = b_bs;
                        *p.add(2) = c_bs;
                        *p.add(3) = a_rs;
                        *p.add(4) = b_rs;
                        *p.add(5) = c_rs;
                        *p.add(6) = a_es;
                        *p.add(7) = grp;
                        *p.add(8) = mode;
                        *p.add(9) = cols as u32;
                        *p.add(10) = q_off;
                        // window = 0: this path serves the non-windowed archs, and the
                        // kernel's window terms all collapse at 0. gemma3's windowed
                        // prefill is a different function entirely.
                        *p.add(11) = 0;
                    }
                    e.set_buffer(5, Some(&dyn_buf), 36);
                    for j in 0..9u64 {
                        e.set_buffer(6 + j, Some(&dyn_buf), j * 4);
                    }
                    e.set_buffer(15, Some(&dyn_buf), 40);
                    e.set_buffer(16, Some(&dyn_buf), 44);
                    e.set_threadgroup_memory_length(0, 8192);
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: (rows as u64).div_ceil(64),
                            height: (cols as u64).div_ceil(64),
                            depth: self.n_heads as u64,
                        },
                        metal::MTLSize {
                            width: 128,
                            height: 1,
                            depth: 1,
                        },
                    );
                };
                // Q8 primary: materialize this layer's K/V as half into the staging pair
                // before anything reads them. Must precede transpose_v16 (V) and the S=QK^T
                // panel (K), both of which expect the f32 lane's mirror layout.
                if stage_q8_kv {
                    for (src, dst) in [
                        (&self.cache_k[i], &q8_k_stage),
                        (&self.cache_v[i], &q8_v_stage),
                    ] {
                        e.set_compute_pipeline_state(&k.kv_dequant_q8_to_h_pipeline);
                        e.set_buffer(0, Some(src), 0);
                        e.set_buffer(1, Some(dst), 0);
                        for j in 0..7u64 {
                            e.set_buffer(2 + j, Some(&q8_stage_scalar), j * 4);
                        }
                        e.dispatch_threads(
                            metal::MTLSize {
                                width: self.head_dim as u64,
                                height: n_pad as u64,
                                depth: self.n_kv_heads as u64,
                            },
                            metal::MTLSize {
                                width: 32,
                                height: 4,
                                depth: 1,
                            },
                        );
                    }
                }
                let attn_k16: &Buffer = if stage_q8_kv {
                    &q8_k_stage
                } else {
                    &self.cache_k16[i]
                };
                let attn_v16: &Buffer = if stage_q8_kv {
                    &q8_v_stage
                } else {
                    &self.cache_v16[i]
                };
                // Transpose this layer's V slice ONCE so every query block's PV
                // A-staging reads contiguously.
                e.set_compute_pipeline_state(&k.transpose_v16_pipeline);
                e.set_buffer(0, Some(attn_v16), 0);
                e.set_buffer(1, Some(&vt_scratch), 0);
                for j in 0..4u64 {
                    e.set_buffer(2 + j, Some(&vt_scalar), j * 4);
                }
                e.dispatch_threads(
                    metal::MTLSize {
                        width: n_pad as u64,
                        height: self.head_dim as u64,
                        depth: self.n_kv_heads as u64,
                    },
                    metal::MTLSize {
                        width: 32,
                        height: 4,
                        depth: 1,
                    },
                );
                // Query-block loop: S and P panels hold attn_qb query columns at a time
                // (memory linear in the block width); q_offset keeps the causal mask and
                // PV clamp on absolute positions. One block reproduces the untiled math.
                let mut qb = 0usize;
                while qb < n_tokens {
                    let cols_b = (n_tokens - qb).min(attn_qb);
                    let qh_off = (qb * q_dim * 2) as u64;
                    // S = Q K^T (per query head; K shared per KV head)
                    smm(
                        &e,
                        attn_k16,
                        &q_h,
                        qh_off,
                        &s_big,
                        0,
                        0,
                        (self.max_positions * self.head_dim) as u32,
                        self.head_dim as u32,
                        (n_pad * attn_qb) as u32,
                        self.head_dim as u32,
                        q_dim as u32,
                        n_pad as u32,
                        1,
                        gqa_group as u32,
                        1,
                        qb as u32,
                        n_pad,
                        cols_b,
                    );
                    // causal softmax rows -> P
                    let qoff_buf = nb(4);
                    unsafe {
                        *(qoff_buf.contents() as *mut u32) = qb as u32;
                    }
                    e.set_compute_pipeline_state(&k.softmax_causal_rows_pipeline);
                    e.set_buffer(0, Some(&s_big), 0);
                    e.set_buffer(1, Some(&p_big), 0);
                    e.set_buffer(2, Some(&softmax_scalar), 0);
                    e.set_buffer(3, Some(&softmax_scalar), 4);
                    e.set_buffer(4, Some(&softmax_scalar), 8);
                    e.set_buffer(5, Some(&qoff_buf), 0);
                    e.set_buffer(6, Some(&softmax_scalar), 12);
                    e.set_buffer(7, Some(&softmax_scalar), 16); // window = 0
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: self.n_heads as u64,
                            height: (attn_qb as u64).div_ceil(8),
                            depth: 1,
                        },
                        metal::MTLSize {
                            width: 256,
                            height: 1,
                            depth: 1,
                        },
                    );
                    // O = P V into ctx_h [token][q_dim] half (head offset via c batch
                    // stride; this block's queries land at qh_off)
                    smm(
                        &e,
                        &vt_scratch,
                        &p_big,
                        0,
                        &ctx_h,
                        qh_off,
                        12,
                        (self.head_dim * n_pad) as u32,
                        (n_pad * attn_qb) as u32,
                        self.head_dim as u32,
                        n_pad as u32,
                        n_pad as u32,
                        q_dim as u32,
                        1,
                        gqa_group as u32,
                        2,
                        qb as u32,
                        self.head_dim,
                        cols_b,
                    );
                    qb += attn_qb;
                }
            } else if use_flash_attn {
                // Flash-tiled attention: K/V tiles stage once per 32-query tile and the
                // score/value matmuls ride the simdgroup matrix units.
                e.set_compute_pipeline_state(&k.attention_prefill_flash_pipeline);
            } else if self.kvq8 {
                e.set_compute_pipeline_state(&k.attention_prefill_v3_kvq8_pipeline);
            } else if self.kv16 {
                e.set_compute_pipeline_state(&k.attention_prefill_v3_kv16_pipeline);
            } else {
                e.set_compute_pipeline_state(&k.attention_prefill_v3_pipeline);
            }
            if !use_attn_mm {
                e.set_buffer(0, Some(&q_buf), 0);
                e.set_buffer(1, Some(&self.cache_k[i]), 0);
                e.set_buffer(2, Some(&self.cache_v[i]), 0);
                e.set_buffer(4, Some(&ctx_buf), 0);
                for j in 0..8u64 {
                    e.set_buffer(5 + j, Some(&attn_scalar), j * 4);
                }
                if use_flash_attn {
                    // Q + K/V half tiles (32 x head_dim each) | S 32x32 f32 | P 32x32 half
                    // | 4 x 8x8 half diag | 32 f32 inv-l.
                    // Linear in head_dim: 23 680 B at 128, 40 064 B at 256 — past the
                    // 32 KiB Apple limit. The <=128 host gate keeps it in range; this
                    // asserts the arithmetic instead of trusting it.
                    let flash_tg_bytes = 128 * self.head_dim + 7296;
                    assert_threadgroup_fits(
                        &k.device,
                        flash_tg_bytes,
                        "attention_prefill_flash_f32 tiles",
                    );
                    e.set_threadgroup_memory_length(0, flash_tg_bytes as u64);
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: self.n_heads as u64,
                            height: (n_tokens as u64).div_ceil(32),
                            depth: 1,
                        },
                        metal::MTLSize {
                            width: 128,
                            height: 1,
                            depth: 1,
                        },
                    );
                } else {
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: self.n_heads as u64,
                            height: (n_tokens as u64).div_ceil(4),
                            depth: 1,
                        },
                        metal::MTLSize {
                            width: 128,
                            height: 1,
                            depth: 1,
                        },
                    );
                }
            }
            let o_y: &Buffer = if use_mm {
                if !use_attn_mm {
                    // flash/v3 write f32 ctx; the MM path's PV pass wrote ctx_h directly
                    convert(&e, &ctx_buf, &ctx_h, &n_elems, 8, n_tokens * q_dim);
                }
                &ctx_h
            } else {
                &ctx_buf
            };
            stage!("4:attention");
            gemm(
                &e,
                o_y,
                &w[3],
                &o_buf,
                &o_scalar,
                0,
                4,
                8,
                q_dim,
                self.hidden,
            );
            stage!("5:gemm_o");
            encode_binary_off(
                &e,
                if use_h16 {
                    &k.residual_add_h_pipeline
                } else {
                    &k.residual_add_pipeline
                },
                cur,
                &o_buf,
                nxt,
                &n_elems,
                0,
                n_tokens * self.hidden,
            );
            // FFN half.
            let ffn_y: &Buffer = if use_mm {
                norm_rows(
                    &e,
                    if use_h16 {
                        &k.rms_norm_batch_h_pipeline
                    } else {
                        &k.rms_norm_batch_f16o_pipeline
                    },
                    nxt,
                    &ffn_norm_buf,
                    &normf_h,
                    &rms_scalar,
                    n_tokens,
                );
                &normf_h
            } else {
                norm_rows(
                    &e,
                    &k.rms_norm_batch_pipeline,
                    nxt,
                    &ffn_norm_buf,
                    &normf,
                    &rms_scalar,
                    n_tokens,
                );
                &normf
            };
            stage!("6:norm2+cvt");
            gemm(
                &e,
                ffn_y,
                &w[4],
                &gate_buf,
                &ffn_scalar,
                0,
                4,
                16,
                self.hidden,
                self.ffn_dim,
            );
            gemm(
                &e,
                ffn_y,
                &w[5],
                &up_buf,
                &ffn_scalar,
                0,
                4,
                16,
                self.hidden,
                self.ffn_dim,
            );
            stage!("7:gemm_gateup");
            if use_mm {
                encode_binary_off(
                    &e,
                    if use_h16 {
                        &k.silu_mul_h2_pipeline
                    } else {
                        &k.silu_mul_f16o_pipeline
                    },
                    &gate_buf,
                    &up_buf,
                    &silu_h,
                    &n_elems,
                    4,
                    n_tokens * self.ffn_dim,
                );
            } else {
                encode_binary_off(
                    &e,
                    &k.silu_mul_pipeline,
                    &gate_buf,
                    &up_buf,
                    &silu_buf,
                    &n_elems,
                    4,
                    n_tokens * self.ffn_dim,
                );
            }
            let down_y: &Buffer = if use_mm { &silu_h } else { &silu_buf };
            gemm(
                &e,
                down_y,
                &w[6],
                &down_buf,
                &ffn_scalar,
                8,
                12,
                16,
                self.ffn_dim,
                self.hidden,
            );
            stage!("8:gemm_down");
            encode_binary_off(
                &e,
                if use_h16 {
                    &k.residual_add_h_pipeline
                } else {
                    &k.residual_add_pipeline
                },
                nxt,
                &down_buf,
                cur,
                &n_elems,
                0,
                n_tokens * self.hidden,
            );
            stage!("9:resid+silu");
            if let Some(moe) = resident_moe[i].as_ref().filter(|_| !moe_ablate("routed")) {
                if use_mm && !use_h16 {
                    // the GEMM path normed into f16 `normf_h`; the f32 router reads f32 rows
                    norm_rows(
                        &e,
                        &k.rms_norm_batch_pipeline,
                        nxt,
                        &ffn_norm_buf,
                        &normf,
                        &rms_scalar,
                        n_tokens,
                    );
                }
                // cur = nxt + shared. Add the routed experts for all n_tokens: route each
                // token (one threadgroup each), gate/up/silu over n_tokens*k slots reading
                // y row = slot/k, down per slot, then cur[t] += sum_s w[t,s] * ed[t*k+s].
                let kk = moe.n_expert_used;
                let ff = moe.expert_ff;
                let ne = moe.n_expert;
                let slots = n_tokens * kk;
                let ids = nb(slots * 4);
                let wts = nb(slots * 4);
                let ea = nb(slots * ff * 4);
                let ed = nb(slots * self.hidden * 4);
                let mk = |routed: bool, bpr: usize, rows: usize, stride: usize, ydiv: usize| {
                    let b = nb(40);
                    unsafe {
                        let q = b.contents() as *mut u32;
                        *q = bpr as u32;
                        *q.add(1) = rows as u32;
                        *q.add(2) = stride as u32;
                        *q.add(3) = ydiv.max(1) as u32;
                        *q.add(4) = ne as u32;
                        *q.add(5) = kk as u32;
                        *q.add(6) = u32::from(moe.weights_norm);
                        *q.add(7) = u32::from(moe.expert_bias.is_some());
                        *q.add(8) = u32::from(routed);
                        *(q.add(9) as *mut f32) = moe.weights_scale;
                    }
                    b
                };
                let rt_p = mk(true, bpr_hidden, ne, 0, 1);
                let p1 = mk(true, bpr_hidden, ff, ff * bpr_hidden, kk);
                let p2 = mk(true, ff / 32, self.hidden, self.hidden * (ff / 32), 1);
                let bias_buf: &Buffer = moe.expert_bias.as_ref().unwrap_or(&wts);
                let tg256 = metal::MTLSize {
                    width: 256,
                    height: 1,
                    depth: 1,
                };
                if use_h16 {
                    e.set_compute_pipeline_state(&k.moe_router_topk_v2_h_pipeline);
                    e.set_buffer(0, Some(&normf_h), 0);
                } else {
                    e.set_compute_pipeline_state(&k.moe_router_topk_v2_pipeline);
                    e.set_buffer(0, Some(&normf), 0);
                }
                e.set_buffer(1, Some(&moe.router.buffer), 0);
                e.set_buffer(2, Some(bias_buf), 0);
                e.set_buffer(3, Some(&ids), 0);
                e.set_buffer(4, Some(&wts), 0);
                e.set_buffer(6, Some(&rt_p), 0);
                e.dispatch_thread_groups(
                    metal::MTLSize {
                        width: n_tokens as u64,
                        height: 1,
                        depth: 1,
                    },
                    tg256,
                );
                if moe_prefill_grouped_enabled() {
                    // group slots by expert: zero counts -> count -> prefix/cursors -> scatter
                    let counts = nb(ne * 4);
                    let starts = nb((ne + 1) * 4);
                    let cursors = nb(ne * 4);
                    let by_expert = nb(slots * 4);
                    let gs = nb(8);
                    unsafe {
                        let q = gs.contents() as *mut u32;
                        *q = ne as u32;
                        *q.add(1) = slots as u32;
                    }
                    e.set_compute_pipeline_state(&k.moe_zero_u32_pipeline);
                    e.set_buffer(0, Some(&counts), 0);
                    e.set_buffer(1, Some(&gs), 0);
                    dispatch_1d(&e, &k.moe_zero_u32_pipeline, ne);
                    e.set_compute_pipeline_state(&k.moe_slot_count_pipeline);
                    e.set_buffer(0, Some(&ids), 0);
                    e.set_buffer(1, Some(&counts), 0);
                    e.set_buffer(2, Some(&gs), 4);
                    dispatch_1d(&e, &k.moe_slot_count_pipeline, slots);
                    e.set_compute_pipeline_state(&k.moe_slot_prefix_pipeline);
                    e.set_buffer(0, Some(&counts), 0);
                    e.set_buffer(1, Some(&starts), 0);
                    e.set_buffer(2, Some(&cursors), 0);
                    e.set_buffer(3, Some(&gs), 0);
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: 1,
                            height: 1,
                            depth: 1,
                        },
                        metal::MTLSize {
                            width: 1,
                            height: 1,
                            depth: 1,
                        },
                    );
                    e.set_compute_pipeline_state(&k.moe_slot_scatter_pipeline);
                    e.set_buffer(0, Some(&ids), 0);
                    e.set_buffer(1, Some(&cursors), 0);
                    e.set_buffer(2, Some(&by_expert), 0);
                    e.set_buffer(3, Some(&gs), 4);
                    dispatch_1d(&e, &k.moe_slot_scatter_pipeline, slots);
                    if let Some((
                        j_max,
                        total_pad,
                        tile_map,
                        panel_off,
                        panel_slot,
                        row_map_tok,
                        pg,
                        pu,
                        pact_h,
                        pd,
                        sc,
                        slot_panel,
                    )) = moe_mm.as_ref()
                    {
                        // Expert-indexed MMA: tile map -> gather f16 panel -> gate/up GEMMs ->
                        // silu (f16 store) -> down GEMM -> scatter rows back to slot order.
                        let (j_max, total_pad) = (*j_max, *total_pad);
                        unsafe {
                            let q = sc.contents() as *mut u32;
                            *q = ne as u32;
                            *q.add(1) = j_max as u32;
                            *q.add(2) = total_pad as u32;
                            *q.add(3) = 0xFFFF_FFFF;
                            *q.add(4) = slots as u32;
                            *q.add(5) = self.hidden as u32;
                            *q.add(6) = kk as u32;
                            *q.add(7) = (total_pad * self.hidden) as u32;
                            *q.add(8) = (total_pad * ff) as u32;
                            *q.add(9) = 1u32; // indirect flag = 1 (offset 36); offset 0..3 reused below
                            *q.add(10) = (ff * bpr_hidden) as u32;
                            *q.add(11) = (self.hidden * (ff / 32)) as u32;
                            *q.add(12) = bpr_hidden as u32;
                            *q.add(13) = ff as u32;
                            *q.add(14) = (ff / 32) as u32;
                            *q.add(15) = self.hidden as u32;
                            *q.add(16) = if moe_prefill_tile32_enabled() {
                                32u32
                            } else {
                                128u32
                            }; // token tile (offset 64)
                            *q.add(19) = 0u32; // zero word at offset 76 (indirect = 0)
                        }
                        e.set_compute_pipeline_state(&k.moe_tile_map_pipeline);
                        e.set_buffer(0, Some(&counts), 0);
                        e.set_buffer(1, Some(tile_map), 0);
                        e.set_buffer(2, Some(panel_off), 0);
                        e.set_buffer(3, Some(sc), 0);
                        e.set_buffer(4, Some(sc), 4);
                        e.set_buffer(5, Some(sc), 64);
                        e.dispatch_thread_groups(
                            metal::MTLSize {
                                width: 1,
                                height: 1,
                                depth: 1,
                            },
                            metal::MTLSize {
                                width: 1,
                                height: 1,
                                depth: 1,
                            },
                        );
                        // padding rows -> NONE in both panel_slot and row_map_tok
                        e.set_compute_pipeline_state(&k.moe_fill_u32_pipeline);
                        e.set_buffer(0, Some(panel_slot), 0);
                        e.set_buffer(1, Some(sc), 8);
                        e.set_buffer(2, Some(sc), 12);
                        dispatch_1d(&e, &k.moe_fill_u32_pipeline, total_pad);
                        e.set_buffer(0, Some(row_map_tok), 0);
                        dispatch_1d(&e, &k.moe_fill_u32_pipeline, total_pad);
                        e.set_compute_pipeline_state(&k.moe_panel_fill_pipeline);
                        e.set_buffer(0, Some(&ids), 0);
                        e.set_buffer(1, Some(&by_expert), 0);
                        e.set_buffer(2, Some(&starts), 0);
                        e.set_buffer(3, Some(panel_off), 0);
                        e.set_buffer(4, Some(panel_slot), 0);
                        e.set_buffer(5, Some(sc), 16);
                        e.set_buffer(6, Some(row_map_tok), 0);
                        e.set_buffer(7, Some(slot_panel), 0);
                        e.set_buffer(8, Some(sc), 24);
                        dispatch_1d(&e, &k.moe_panel_fill_pipeline, slots);
                        let mm_id = |e: &metal::ComputeCommandEncoderRef,
                                     y: &Buffer,
                                     w: &ResidentLinearWeight,
                                     out: &Buffer,
                                     bpr_off: u64,
                                     rows_off: u64,
                                     stride_off: u64,
                                     rows: usize,
                                     indirect: bool| {
                            // 32-token tiles need rows % 128 == 0; otherwise the 128-token kernel
                            // consumes the same (32-token) tile map as a ragged tail.
                            let t32 = moe_prefill_tile32_enabled() && rows.is_multiple_of(128);
                            e.set_compute_pipeline_state(if t32 {
                                &k.moe_wire_mm_id32_pipeline
                            } else {
                                &k.moe_wire_mm_id_pipeline
                            });
                            e.set_buffer(0, Some(y), 0);
                            e.set_buffer(2, Some(&w.buffer), 0);
                            e.set_buffer(3, Some(out), 0);
                            e.set_buffer(4, Some(sc), bpr_off);
                            e.set_buffer(5, Some(sc), rows_off);
                            e.set_buffer(6, Some(tile_map), 0);
                            e.set_buffer(7, Some(sc), stride_off);
                            e.set_buffer(8, Some(row_map_tok), 0);
                            e.set_buffer(9, Some(sc), if indirect { 36 } else { 3 * 4 + 64 }); // 36 -> 1; 76 -> zero word (see zero_word below)
                            e.set_threadgroup_memory_length(0, if t32 { 10240 } else { 12288 });
                            e.dispatch_thread_groups(
                                metal::MTLSize {
                                    width: (rows / if t32 { 128 } else { 64 }) as u64,
                                    height: j_max as u64,
                                    depth: 1,
                                },
                                metal::MTLSize {
                                    width: 256,
                                    height: 1,
                                    depth: 1,
                                },
                            );
                        };
                        // gate/up read the f16 FFN-norm rows IN PLACE through row_map_tok (no gather)
                        mm_id(&e, &normf_h, &moe.gate_exps, pg, 48, 52, 40, ff, true);
                        mm_id(&e, &normf_h, &moe.up_exps, pu, 48, 52, 40, ff, true);
                        // silu(gate)*up with the f16 store fused (the down GEMM consumes f16, panel order)
                        encode_binary_off(
                            &e,
                            &k.silu_mul_f16o_pipeline,
                            pg,
                            pu,
                            pact_h,
                            sc,
                            32,
                            total_pad * ff,
                        );
                        // the "indirect" flag must be 0 here: scalar slot 60 holds `hidden` (nonzero) so
                        // use a dedicated zero at offset 56? no — 56 holds down bpr. Use slot 3's neighbour:
                        // we pass indirect=false via offset 60 being nonzero is WRONG; bind a zero word.
                        mm_id(
                            &e,
                            pact_h,
                            &moe.down_exps,
                            pd,
                            56,
                            60,
                            44,
                            self.hidden,
                            false,
                        );
                    } else {
                        // grouped expert GEMVs: grid (rows/16, n_expert)
                        e.set_compute_pipeline_state(&k.moe_grouped_gate_up_silu_pipeline);
                        e.set_buffer(0, Some(&normf), 0);
                        e.set_buffer(1, Some(&by_expert), 0);
                        e.set_buffer(2, Some(&moe.gate_exps.buffer), 0);
                        e.set_buffer(3, Some(&moe.up_exps.buffer), 0);
                        e.set_buffer(4, Some(&ea), 0);
                        e.set_buffer(5, Some(&starts), 0);
                        e.set_buffer(6, Some(&p1), 0);
                        e.dispatch_thread_groups(
                            metal::MTLSize {
                                width: (ff as u64).div_ceil(16),
                                height: ne as u64,
                                depth: 1,
                            },
                            tg256,
                        );
                        e.set_compute_pipeline_state(&k.moe_grouped_down_pipeline);
                        e.set_buffer(0, Some(&ea), 0);
                        e.set_buffer(1, Some(&by_expert), 0);
                        e.set_buffer(2, Some(&moe.down_exps.buffer), 0);
                        e.set_buffer(3, Some(&ed), 0);
                        e.set_buffer(5, Some(&starts), 0);
                        e.set_buffer(6, Some(&p2), 0);
                        e.dispatch_thread_groups(
                            metal::MTLSize {
                                width: (self.hidden as u64).div_ceil(16),
                                height: ne as u64,
                                depth: 1,
                            },
                            tg256,
                        );
                    }
                    moe_keep.extend([counts, starts, cursors, by_expert, gs]);
                } else {
                    e.set_compute_pipeline_state(&k.moe_gate_up_silu_turbo_pipeline);
                    e.set_buffer(0, Some(&normf), 0);
                    e.set_buffer(1, Some(&ids), 0);
                    e.set_buffer(2, Some(&moe.gate_exps.buffer), 0);
                    e.set_buffer(3, Some(&moe.up_exps.buffer), 0);
                    e.set_buffer(4, Some(&ea), 0);
                    e.set_buffer(6, Some(&p1), 0);
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: (ff as u64).div_ceil(16),
                            height: slots as u64,
                            depth: 1,
                        },
                        tg256,
                    );
                    e.set_compute_pipeline_state(&k.moe_down_turbo_pipeline);
                    e.set_buffer(0, Some(&ea), 0);
                    e.set_buffer(1, Some(&ids), 0);
                    e.set_buffer(2, Some(&moe.down_exps.buffer), 0);
                    e.set_buffer(3, Some(&ed), 0);
                    e.set_buffer(6, Some(&p2), 0);
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: (self.hidden as u64).div_ceil(16),
                            height: slots as u64,
                            depth: 1,
                        },
                        tg256,
                    );
                }
                let ar = nb(12);
                unsafe {
                    let q = ar.contents() as *mut u32;
                    *q = self.hidden as u32;
                    *q.add(1) = kk as u32;
                    *q.add(2) = (n_tokens * self.hidden) as u32;
                }
                if let Some((_, _, _, _, _, _, _, _, _, pd, _, slot_panel)) =
                    moe_mm.as_ref().filter(|_| moe_prefill_grouped_enabled())
                {
                    e.set_compute_pipeline_state(if use_h16 {
                        &k.moe_add_routed_panel_h_pipeline
                    } else {
                        &k.moe_add_routed_panel_pipeline
                    });
                    e.set_buffer(0, Some(cur), 0);
                    e.set_buffer(1, Some(pd), 0);
                    e.set_buffer(2, Some(&wts), 0);
                    e.set_buffer(3, Some(slot_panel), 0);
                    e.set_buffer(4, Some(&ar), 0);
                    e.set_buffer(5, Some(&ar), 4);
                    e.set_buffer(6, Some(&ar), 8);
                    dispatch_1d(&e, &k.moe_add_routed_panel_pipeline, n_tokens * self.hidden);
                } else {
                    e.set_compute_pipeline_state(&k.moe_add_routed_rows_pipeline);
                    e.set_buffer(0, Some(cur), 0);
                    e.set_buffer(1, Some(&ed), 0);
                    e.set_buffer(2, Some(&wts), 0);
                    e.set_buffer(3, Some(&ar), 0);
                    e.set_buffer(4, Some(&ar), 4);
                    e.set_buffer(5, Some(&ar), 8);
                    dispatch_1d(&e, &k.moe_add_routed_rows_pipeline, n_tokens * self.hidden);
                }
                moe_keep.extend([ids, wts, ea, ed, rt_p, p1, p2, ar]);
            }
            // Attention residual wrote cur -> nxt; FFN residual wrote nxt -> cur, so this
            // layer's output is back in `cur` for the next layer.

            // Commit the first layer as its own command buffer so the GPU starts (~35ms
            // of work) while the host encodes the remaining layers (~10ms): the encode
            // cost disappears behind GPU execution. The serial queue keeps ordering.
            if i == 0 && !trace {
                e.end_encoding();
                cb.commit();
                cb = k.queue.new_command_buffer().to_owned();
                e = cb.new_compute_command_encoder().to_owned();
            }
        }
        e.end_encoding();
        let time_edges = std::env::var_os("CAMELID_PREFILL_TIME").is_some();
        let commit_started = std::time::Instant::now();
        cb.commit();
        cb.wait_until_completed();
        if time_edges && !trace {
            let (busy_us, window_us) = command_buffer_gpu_times_us(&cb);
            eprintln!(
                "[prefill-time] commit->complete {:.1}ms | gpu busy {:.1}ms | gpu window {:.1}ms",
                commit_started.elapsed().as_micros() as f64 / 1000.0,
                busy_us as f64 / 1000.0,
                window_us as f64 / 1000.0,
            );
        }
        if trace {
            let total: u128 = stage_us.values().sum();
            eprintln!(
                "[prefill-trace] n_tokens={n_tokens} total_gpu_busy={}ms",
                total / 1000
            );
            for (label, us) in &stage_us {
                eprintln!("[prefill-trace]   {label}: {}ms", us / 1000);
            }
        }
        self.filled = n_tokens;
        Some(())
    }

    /// Long-prompt TTFT campaign, Tier A — **batched weight streaming, BIT-IDENTICAL
    /// to `n_tokens` sequential `forward_token` prefill decodes.**
    ///
    /// Shaped like `verify_batch_inner`, not like `prefill_tokens`: the prompt is walked
    /// in chunks of `chunk_rows`, and inside a chunk every stage whose output depends on a
    /// single row runs the EXACT single-token kernel at a row byte offset, while every
    /// stage that streams a weight matrix runs the proven byte-exact batched twin.
    ///
    /// - batched (one weight stream per chunk instead of one per token): `rms_norm_batch_f32`
    ///   for the input / FFN / both sandwich norms, and the C0 batched-column GEMV
    ///   `encode_q8_matmul_f32y_batched` for Q/K/V/O/gate/up/down (each output column is
    ///   bit-identical to the single-token dispatch — `metal_verify_gemv_batched_bit_identical`);
    /// - elementwise with a wider `n`: `residual_add_f32`, and `gelu_mul_f32` / `silu_mul_f32`
    ///   (`if (gid >= n) return;` guards, so a wider grid is the same arithmetic);
    /// - per row, at a byte offset: per-head QK-norm, RoPE, K/V scatter and attention —
    ///   so cos/sin pairing, the scatter slot, the attention routing and the window read
    ///   range are reproduced verbatim.
    ///
    /// The three gemma3 features `prefill_tokens` fails closed on
    /// (its gate at the top of that function) are all carried here:
    ///
    /// 1. **per-layer dual-theta RoPE** — `alt_rope` is selected per layer by
    ///    `schedule.use_alt_rope[l]`, mirroring `prepare_token`;
    /// 2. **sandwich norms** — `post_attn_norm` / `post_ffw_norm` as two extra
    ///    `rms_norm_batch_f32` dispatches per layer, applied BEFORE their residual adds,
    ///    exactly as `encode_attention_block` / `encode_ffn_block` do;
    /// 3. **GeGLU** — the same `gelu_mul_f32` kernel the decode encode uses, dispatched
    ///    with `n = rows * ffn_dim`.
    ///
    /// The sliding-window mask needs no new kernel: row `i`'s `(window_start,
    /// position_count)` come from the shared [`schedule_window_bounds`] at
    /// `filled = base + i + 1` and ride into the unchanged `encode_attention` through the
    /// attention scalar's `kv_base_offset` word — the same mechanism the token-by-token
    /// lane uses. At head_dim 256 that routes to `encode_attention_split3`, the exact
    /// kernel the shipped lane already runs.
    ///
    /// `head_dim > 128` is NOT gated here: this is a separate admission path, and the ≤128
    /// gates on `prefill_tokens`, `verify_batch` and the `MAX_DPL`/`MAX_DOCT` kernels are
    /// untouched.
    ///
    /// **Phases 3 and 4 amend the bit-identity claim above, in two named places and
    /// nowhere else.** Both are default-ON with `=0` opt-outs (§19c); both are gated by
    /// the published KV-equivalence envelope (`GEMMA3_METAL_CONDUCTOR.md` §18a/§18b)
    /// rather than by raw bit equality, because neither can be bit-identical:
    ///
    /// 1. **The weight GEMMs** (`CAMELID_GEMMA3_PREFILL_MM`). Q/K/V/O/gate/up/down run
    ///    through the tiled simdgroup-matrix kernel `q8_0_block_wire_mm` instead of the
    ///    batched-column GEMV: each weight block is read once per 128 prompt columns
    ///    rather than once per 8 (`MAX_T`), and both operands stage in threadgroup memory.
    /// 2. **Attention** (`CAMELID_GEMMA3_PREFILL_ATTN_MM`, and it needs (1) because the
    ///    context panel stays half all the way into the O projection). The per-row
    ///    `encode_attention` loop becomes three dispatches per layer-chunk —
    ///    `half_mm_batched_f16o` for S = K Qᵀ, `softmax_causal_rows`, and
    ///    `half_mm_batched_f16o` again for O = Vᵀ P — reading the half K/V mirrors the
    ///    scatter already dual-writes. The sliding window becomes a `window` uniform on
    ///    the first and third of those, culling score tiles that lie entirely below it;
    ///    `window = 0` is the disabled case the 4 global layers take.
    ///
    /// What did NOT move under either: the per-head QK-norm, RoPE and the K/V scatter
    /// still run the EXACT single-token kernels at a row byte offset, and the window
    /// bounds still come from the shared [`schedule_window_bounds`] — the batched mask is
    /// the same arithmetic in the kernel rather than a second convention. With (2) off,
    /// attention is the per-row path described above, unchanged.
    ///
    /// Sets `filled = n_tokens` on success (the caller's `filled() == position` invariant;
    /// getting it wrong re-seeds from a CPU KV cache this lane leaves hollow). Returns
    /// `None` — losslessly, having written nothing — on any unsupported config.
    #[allow(clippy::too_many_arguments)]
    pub fn prefill_tokens_windowed(
        &mut self,
        embeddings: &[f32],
        n_tokens: usize,
        layers: &[ResidentLayerWeights],
        cos_all: &[f32],
        sin_all: &[f32],
        alt_rope_all: Option<(&[f32], &[f32])>,
        scale: f32,
        chunk_rows: usize,
    ) -> Option<()> {
        // The batched paths encode the dense FFN only; a MoE layer must fail closed.
        if layers.iter().any(|l| l.moe.is_some()) {
            return None;
        }
        self.prefill_tokens_windowed_inner(
            embeddings,
            n_tokens,
            layers,
            cos_all,
            sin_all,
            alt_rope_all,
            scale,
            chunk_rows,
            false,
            PrefillGemm::EnvDefault,
            PrefillAttn::EnvDefault,
        )
        .map(|_| ())
    }

    /// `prefill_tokens_windowed` with the GEMM pinned rather than read from the env.
    /// Test-only: the env gate is a process-latched `OnceLock`, so a single test process
    /// could otherwise never compare the scalar and MM GEMMs against each other.
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    fn prefill_tokens_windowed_gemm(
        &mut self,
        embeddings: &[f32],
        n_tokens: usize,
        layers: &[ResidentLayerWeights],
        cos_all: &[f32],
        sin_all: &[f32],
        alt_rope_all: Option<(&[f32], &[f32])>,
        scale: f32,
        chunk_rows: usize,
        gemm: PrefillGemm,
        attn: PrefillAttn,
    ) -> Option<()> {
        self.prefill_tokens_windowed_inner(
            embeddings,
            n_tokens,
            layers,
            cos_all,
            sin_all,
            alt_rope_all,
            scale,
            chunk_rows,
            false,
            gemm,
            attn,
        )
        .map(|_| ())
    }

    /// `prefill_tokens_windowed` that also reads back every row's post-final-layer hidden
    /// state (`n_tokens * hidden`, row-major). Test-only: gates G1/G6 compare the final
    /// hidden alongside the KV caches, because a defect confined to the LAST layer's
    /// attention moves ZERO cache bits (conductor §16e) and is visible only there. The
    /// production lane never pays the readback.
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    fn prefill_tokens_windowed_hidden(
        &mut self,
        embeddings: &[f32],
        n_tokens: usize,
        layers: &[ResidentLayerWeights],
        cos_all: &[f32],
        sin_all: &[f32],
        alt_rope_all: Option<(&[f32], &[f32])>,
        scale: f32,
        chunk_rows: usize,
        gemm: PrefillGemm,
        attn: PrefillAttn,
    ) -> Option<Vec<f32>> {
        self.prefill_tokens_windowed_inner(
            embeddings,
            n_tokens,
            layers,
            cos_all,
            sin_all,
            alt_rope_all,
            scale,
            chunk_rows,
            true,
            gemm,
            attn,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn prefill_tokens_windowed_inner(
        &mut self,
        embeddings: &[f32],
        n_tokens: usize,
        layers: &[ResidentLayerWeights],
        cos_all: &[f32],
        sin_all: &[f32],
        alt_rope_all: Option<(&[f32], &[f32])>,
        scale: f32,
        chunk_rows: usize,
        read_hidden: bool,
        gemm: PrefillGemm,
        attn: PrefillAttn,
    ) -> Option<Vec<f32>> {
        // ---- Eligibility gate (return None -> caller falls back, lossless) --------------
        // Mirrors verify_batch_inner's gate, MINUS the head_dim <= 128 clause: nothing on
        // this path carries a per-lane fixed-size array, so head_dim 256 is admissible here
        // while `prefill_tokens` / `verify_batch` / the MAX_DPL kernels keep their ≤128
        // memory-safety gates exactly as they are.
        if n_tokens == 0 || chunk_rows == 0 {
            return None;
        }
        // The batched GEMV mirrors exactly the f32y + wire + NSG=8 production GEMV; any
        // other GEMV path would not match the token-by-token lane bit-for-bit.
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            return None;
        }
        if !self.head_dim.is_multiple_of(32) {
            return None;
        }
        if self.filled != 0 || embeddings.len() != n_tokens * self.hidden {
            return None;
        }
        if layers.len() != self.n_layers || n_tokens > self.cap {
            return None;
        }
        if cos_all.len() != sin_all.len()
            || cos_all.is_empty()
            || !cos_all.len().is_multiple_of(n_tokens)
        {
            return None;
        }
        let half_rope = cos_all.len() / n_tokens;
        if half_rope == 0 || half_rope * 2 > self.head_dim {
            return None;
        }
        // Dual-theta schedule: when any layer selects the ALT table the caller MUST supply
        // it for every position — fail closed, never rope with the wrong theta (the same
        // contract `forward_token` enforces).
        let needs_alt = self.schedule.as_ref().is_some_and(|s| s.needs_alt_rope());
        let alt_rope_all = match alt_rope_all {
            Some((ac, as_)) if ac.len() == cos_all.len() && as_.len() == sin_all.len() => {
                Some((ac, as_))
            }
            Some(_) => return None,
            None if needs_alt => return None,
            None => None,
        };
        if let Some(s) = &self.schedule {
            if s.use_alt_rope.len() != self.n_layers || s.window.len() != self.n_layers {
                return None;
            }
        }
        let q_dim = self.n_heads * self.head_dim;
        let kv_dim = self.n_kv_heads * self.head_dim;
        for l in layers {
            if l.attn_norm.len() != self.hidden
                || l.ffn_norm.len() != self.hidden
                || l.post_attn_norm.is_some_and(|n| n.len() != self.hidden)
                || l.post_ffw_norm.is_some_and(|n| n.len() != self.hidden)
                || l.q_norm.is_some() != l.k_norm.is_some()
                || l.q_norm.is_some_and(|n| n.len() != self.head_dim)
                || l.k_norm.is_some_and(|n| n.len() != self.head_dim)
                || !l.q_weight_blocks.matches_shape(self.hidden, q_dim)
                || !l.k_weight_blocks.matches_shape(self.hidden, kv_dim)
                || !l.v_weight_blocks.matches_shape(self.hidden, kv_dim)
                || !l.o_weight_blocks.matches_shape(q_dim, self.hidden)
                || !l
                    .gate_weight_blocks
                    .matches_shape(self.hidden, self.ffn_dim)
                || !l.up_weight_blocks.matches_shape(self.hidden, self.ffn_dim)
                || !l
                    .down_weight_blocks
                    .matches_shape(self.ffn_dim, self.hidden)
            {
                return None;
            }
        }

        // A pre-committed pending graph (from forward_token's encode-ahead) sits gated on
        // the serial queue; release it so these command buffers are not ordered behind a
        // graph that never gets signaled.
        if let Some(stale) = self.pending.take() {
            self.release_stale(stale);
        }
        self.pending_signaled = false;
        self.last_sampled = None;
        // Grow ONCE, for the whole prompt: growth reallocates the cache buffers, and every
        // chunk's encoded graph holds raw references to them.
        if !self.ensure_capacity(n_tokens) {
            return None;
        }

        let kern = metal_linear_kernel()?;
        // Shares CAMELID_RESIDENT_TRACE with the token-by-token lane, so one env var
        // gives a comparable per-command-buffer line from whichever path ran.
        let trace = std::env::var_os("CAMELID_RESIDENT_TRACE").is_some();
        let max_positions = self.max_positions;
        let n_heads = self.n_heads;
        let n_kv_heads = self.n_kv_heads;
        let head_dim = self.head_dim;
        let hidden = self.hidden;
        let ffn_dim = self.ffn_dim;
        let eps = self.eps;
        let pairing = u32::from(self.split_half_pairing);
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn_dim / 32;
        let chunk = chunk_rows.min(n_tokens);
        let kv_position_stride = if self.kvq8 {
            (head_dim / 32) * 34
        } else {
            head_dim
        };

        // ---- Resolve resident weights (wire format; gated on f32y+wire above) ------------
        let resident: Vec<[ResidentLinearWeight; 7]>;
        let attn_norm_bufs: Vec<Buffer>;
        let ffn_norm_bufs: Vec<Buffer>;
        let qk_norm_bufs: Vec<Option<(Buffer, Buffer)>>;
        let post_attn_norm_bufs: Vec<Option<Buffer>>;
        let post_ffw_norm_bufs: Vec<Option<Buffer>>;
        {
            let mut cache = metal_linear_cache().lock().ok()?;
            let mut wb = |w: &ResidentWeightBytes| {
                resolve_resident_weight(&mut cache, &kern.device, w, true)
            };
            resident = layers
                .iter()
                .map(|l| {
                    Some([
                        wb(&l.q_weight_blocks)?,
                        wb(&l.k_weight_blocks)?,
                        wb(&l.v_weight_blocks)?,
                        wb(&l.o_weight_blocks)?,
                        wb(&l.gate_weight_blocks)?,
                        wb(&l.up_weight_blocks)?,
                        wb(&l.down_weight_blocks)?,
                    ])
                })
                .collect::<Option<Vec<_>>>()?;
            attn_norm_bufs = layers
                .iter()
                .map(|l| cache.weight_buffer(&kern.device, l.attn_norm))
                .collect();
            ffn_norm_bufs = layers
                .iter()
                .map(|l| cache.weight_buffer(&kern.device, l.ffn_norm))
                .collect();
            qk_norm_bufs = layers
                .iter()
                .map(|l| match (l.q_norm, l.k_norm) {
                    (Some(qn), Some(kn)) => Some((
                        cache.weight_buffer(&kern.device, qn),
                        cache.weight_buffer(&kern.device, kn),
                    )),
                    _ => None,
                })
                .collect();
            post_attn_norm_bufs = layers
                .iter()
                .map(|l| {
                    l.post_attn_norm
                        .map(|n| cache.weight_buffer(&kern.device, n))
                })
                .collect();
            post_ffw_norm_bufs = layers
                .iter()
                .map(|l| {
                    l.post_ffw_norm
                        .map(|n| cache.weight_buffer(&kern.device, n))
                })
                .collect();
        }

        // ---- Phase 3: the prefill GEMM ---------------------------------------------------
        // The Phase 2 batched-column GEMV is bit-identical to the token-by-token lane and
        // pinned at ~0.12 TFLOPS: `q8_0_block_linear_ksplit_f32y_wire_nsg8_verify` carries
        // `MAX_T = 8`, so every weight block is re-read once per 8 columns and every
        // threadgroup re-walks the whole activation panel (conductor §17e). The tiled
        // simdgroup-matrix kernel `q8_0_block_wire_mm` — the SHIPPED default prefill GEMM
        // for every other Q8_0 row on this host (`CAMELID_METAL_MM`, on by default in the
        // CLI fast stack) — reads each weight block once per 128 columns and stages both
        // operands in threadgroup memory. It is NOT bit-identical (half operand staging +
        // tile-MMA accumulation order), which is why it sits behind its own flag and is
        // gated by the published KV envelope rather than by raw bit equality.
        //
        // Admission is a SEPARATE predicate — it relaxes nothing. `MAX_DPL` / `MAX_DOCT`
        // and the <=128 host gates they guard are untouched; this kernel has no per-lane
        // fixed-size array and a FIXED 12 288 B threadgroup allocation, so head_dim never
        // enters. What it does need is 128-multiple output row counts (its 64-row tile with
        // the same 128 gate the shipped `prefill_tokens` MM path uses) and 32-multiple
        // contraction widths (NK = 32 = one Q8_0 block per step).
        let all_q8 = resident
            .iter()
            .flatten()
            .all(|w| w.format == ResidentWeightFormat::Q8_0);
        let use_mm = match gemm {
            PrefillGemm::ForceScalar => false,
            PrefillGemm::EnvDefault => gemma3_prefill_mm_enabled(),
            PrefillGemm::ForceMm => true,
        } && all_q8
            && [q_dim, kv_dim, hidden, ffn_dim]
                .iter()
                .all(|r| r.is_multiple_of(2 * PREFILL_MM_ROW_TILE))
            && [hidden, q_dim, ffn_dim]
                .iter()
                .all(|w| w.is_multiple_of(32))
            && threadgroup_alloc_fits(&kern.device, PREFILL_MM_THREADGROUP_BYTES);
        // Half activation panels, padded up to a whole token tile so the kernel's direct
        // device B loads never run off the end. Padding rows only feed output columns past
        // `n_rows_in`, which are never stored; they are zeroed once anyway so a run is not
        // reading whatever the allocator handed back.
        let mm_pad = if use_mm {
            chunk.next_multiple_of(PREFILL_MM_TOKEN_TILE)
        } else {
            0
        };

        // ---- Chunk-sized activation scratch, allocated ONCE and reused ------------------
        // Row-major [row][dim] throughout, matching the batched GEMV's `[token][dim]`
        // contract. ~32 MB total at chunk = 256 on the 1B row.
        let nb = |bytes: usize| {
            kern.device
                .new_buffer(bytes.max(4) as u64, MTLResourceOptions::StorageModeShared)
        };
        let act_a = nb(chunk * hidden * 4);
        let act_b = nb(chunk * hidden * 4);
        let mid = nb(chunk * hidden * 4);
        let norm_buf = nb(chunk * hidden * 4);
        let q_buf = nb(chunk * q_dim * 4);
        let k_buf = nb(chunk * kv_dim * 4);
        let v_buf = nb(chunk * kv_dim * 4);
        let ctx_buf = nb(chunk * q_dim * 4);
        let o_buf = nb(chunk * hidden * 4);
        let post_buf = nb(chunk * hidden * 4);
        let gate_buf = nb(chunk * ffn_dim * 4);
        let up_buf = nb(chunk * ffn_dim * 4);
        let act_buf = nb(chunk * ffn_dim * 4);
        let down_buf = nb(chunk * hidden * 4);
        let cos_buf = nb(cos_all.len() * 4);
        let sin_buf = nb(sin_all.len() * 4);
        write_buffer_f32(&cos_buf, cos_all);
        write_buffer_f32(&sin_buf, sin_all);
        let alt_bufs = alt_rope_all.map(|(ac, as_)| {
            let cb = nb(ac.len() * 4);
            let sb = nb(as_.len() * 4);
            write_buffer_f32(&cb, ac);
            write_buffer_f32(&sb, as_);
            (cb, sb)
        });
        // One shared scores buffer, sized to the deepest read range any row can take
        // (a global layer at the last position). Sharing it serializes the per-row
        // attention dispatches — which is exactly what the token-by-token lane already
        // does, one command buffer per token, so it costs nothing relative to today.
        let scores_buf = nb(n_heads * n_tokens * 4);
        // Half GEMM-input panels, one per contraction width (hidden for Q/K/V and
        // gate/up, q_dim for O, ffn_dim for down). ~4.6 MB total at chunk = 256 on the
        // 1B row. Reused within a layer across the two hidden-width stages: dispatches on
        // an `MTLComputeCommandEncoder` are serial, so the QKV GEMMs have consumed the
        // panel before the FFN norm overwrites it.
        let mm_y_hidden = nb(mm_pad * hidden * 2);
        let mm_y_q = nb(mm_pad * q_dim * 2);
        let mm_y_ffn = nb(mm_pad * ffn_dim * 2);
        let mm_counts = nb(12);
        if use_mm {
            for (buf, bytes) in [
                (&mm_y_hidden, mm_pad * hidden * 2),
                (&mm_y_q, mm_pad * q_dim * 2),
                (&mm_y_ffn, mm_pad * ffn_dim * 2),
            ] {
                unsafe { std::ptr::write_bytes(buf.contents() as *mut u8, 0, bytes) };
            }
        }

        // ---- Scalars --------------------------------------------------------------------
        let rms_scalar = nb(8);
        let q_gemv = nb(12);
        let kv_gemv = nb(12);
        let o_gemv = nb(12);
        let gateup_gemv = nb(12);
        let down_gemv = nb(12);
        let rope_q_scalar = nb(16);
        let rope_k_scalar = nb(16);
        let act_n = nb(4);
        let resid_n = nb(4);
        let kv16_write = nb(4);
        let perhead_qk_scalar = nb(12);
        let scatter_scalars = nb(16 * chunk);
        unsafe {
            let p = rms_scalar.contents() as *mut u8;
            *(p as *mut u32) = hidden as u32;
            *(p.add(4) as *mut f32) = eps;
            let set_gemv = |buf: &Buffer, bpr: usize, rows: usize| {
                let q = buf.contents() as *mut u32;
                *q = bpr as u32;
                *q.add(1) = rows as u32;
            };
            set_gemv(&q_gemv, bpr_hidden, q_dim);
            set_gemv(&kv_gemv, bpr_hidden, kv_dim);
            set_gemv(&o_gemv, bpr_q, hidden);
            set_gemv(&gateup_gemv, bpr_hidden, ffn_dim);
            set_gemv(&down_gemv, bpr_ffn, hidden);
            let set_rope = |buf: &Buffer, hc: usize| {
                let r = buf.contents() as *mut u32;
                *r = hc as u32;
                *r.add(1) = head_dim as u32;
                *r.add(2) = half_rope as u32;
                *r.add(3) = pairing;
            };
            set_rope(&rope_q_scalar, n_heads);
            set_rope(&rope_k_scalar, n_kv_heads);
            *(kv16_write.contents() as *mut u32) = u32::from(!self.kv16 && !self.kvq8);
            let p = perhead_qk_scalar.contents() as *mut u8;
            *(p as *mut u32) = head_dim as u32;
            *(p.add(4) as *mut f32) = eps;
            *(p.add(8) as *mut u32) = 1; // use_weight
        }

        // Distinct window values across the schedule (2 for gemma3: the 512-position
        // sliding layers and the full-causal globals) — one 32-byte attention scalar per
        // (window class, row), rewritten per chunk. Every layer with the same window
        // shares its class, so the scalar count is `classes * chunk`, not `layers * chunk`.
        let layer_windows: Vec<Option<usize>> = (0..self.n_layers)
            .map(|l| self.schedule.as_ref().and_then(|s| s.window[l]))
            .collect();
        let mut classes: Vec<Option<usize>> = Vec::new();
        for w in &layer_windows {
            if !classes.contains(w) {
                classes.push(*w);
            }
        }
        let layer_class: Vec<usize> = layer_windows
            .iter()
            .map(|w| {
                classes
                    .iter()
                    .position(|c| c == w)
                    .expect("every layer window was collected into a class above")
            })
            .collect();
        let attn_scalars: Vec<Buffer> = (0..classes.len() * chunk).map(|_| nb(32)).collect();

        // ---- Phase 4: batched windowed attention (Tier B) --------------------------------
        // Phase 3 left prefill 79 % attention at 1 200 tokens and 84 % at 2 400 (§18e):
        // every row still ran its own `encode_attention`, re-reading the whole window per
        // query. This replaces the per-row loop with the attention-as-matmul chain the
        // tree already ships for non-windowed rows — S = K Qᵀ and O = Vᵀ P through
        // `half_mm_batched_f16o`, with `softmax_causal_rows` between them — and teaches
        // exactly those two kernels the per-query-row LOWER mask bound they never had.
        //
        // On the `!has_qk_norm` clause that keeps `prefill_tokens` off this chain
        // (`use_attn_mm`, src/metal.rs, rationale in that function's comment): it is about
        // the surrounding plumbing, NOT about `half_mm_batched_f16o`. There it forces the
        // WEIGHT GEMM to emit f32 Q/K so the f32 per-head norm can run in cpu_reference
        // order. On this path the weight GEMM already emits f32 (both the Phase 2 GEMV and
        // Phase 3's `q8_0_block_wire_mm` write f32), the per-head QK-norm and RoPE already
        // run the exact single-token f32 kernels per row, and Q is converted to half only
        // AFTER both. So the condition the clause exists to enforce is already met, and the
        // GEMM itself has no QK-norm dependence at all.
        //
        // Admission relaxes nothing: `MAX_DPL` / `MAX_DOCT` and their <=128 host gates are
        // untouched, and this chain has no per-lane fixed-size array and a FIXED 8 192 B
        // threadgroup allocation, so head_dim never enters it.
        let n_pad_max = n_tokens.next_multiple_of(ATTN_MM_TILE);
        // S and P, [head][chunk row][n_pad] half each. Linear in the CHUNK width, not in
        // n_tokens squared, because queries are already blocked by the chunk loop.
        let attn_panel_elems = n_heads * chunk * n_pad_max;
        let use_attn_mm = match attn {
            PrefillAttn::ForceRow => false,
            PrefillAttn::EnvDefault => gemma3_prefill_attn_mm_enabled(),
            PrefillAttn::ForceMm => true,
        } && use_mm
            // The PV pass writes the context panel in half straight into the O GEMM's
            // input; with the scalar GEMV there is no f32 consumer for it.
            && !self.kv16
            && !self.kvq8
            // The S and PV operands are the half K/V mirrors, which are dual-written by
            // the scatter in exactly this mode (and are dead weight in it today).
            && head_dim.is_multiple_of(ATTN_MM_TILE)
            && n_heads.is_multiple_of(n_kv_heads)
            // Chunk starts must be 64-aligned so a query tile's causal boundary is the
            // PV pass's `k_end` exactly; a single chunk covering the whole prompt starts
            // at 0 and is aligned whatever its width.
            && (chunk.is_multiple_of(ATTN_MM_TILE) || chunk == n_tokens)
            // `Some(0)` means an EMPTY read range to `schedule_window_bounds` and a
            // DISABLED window to the kernels. No real schedule produces it; fail closed
            // rather than let the two conventions disagree.
            && layer_windows.iter().all(|w| *w != Some(0))
            && attn_panel_elems * 2 * 2 <= attn_mm_scratch_cap_bytes()
            && threadgroup_alloc_fits(&kern.device, ATTN_MM_THREADGROUP_BYTES);
        let attn_q_h = nb(if use_attn_mm { mm_pad * q_dim * 2 } else { 4 });
        let attn_s = nb(if use_attn_mm { attn_panel_elems * 2 } else { 4 });
        let attn_p = nb(if use_attn_mm { attn_panel_elems * 2 } else { 4 });
        let attn_vt = nb(if use_attn_mm {
            n_kv_heads * head_dim * n_pad_max * 2
        } else {
            4
        });
        if use_attn_mm {
            // Zeroed once: the padded query rows of the Q panel are read by the S pass's
            // unguarded vector loads, and S/P columns past a row's causal boundary are
            // never read but should not be whatever the allocator handed back.
            for (buf, bytes) in [
                (&attn_q_h, mm_pad * q_dim * 2),
                (&attn_s, attn_panel_elems * 2),
                (&attn_p, attn_panel_elems * 2),
                (&attn_vt, n_kv_heads * head_dim * n_pad_max * 2),
            ] {
                unsafe { std::ptr::write_bytes(buf.contents() as *mut u8, 0, bytes) };
            }
        }
        // The window uniform, one word per window class, written ONCE: `window = 0` is the
        // disabled case, so the 4 global layers and the 22 sliding ones run the SAME
        // parameterised kernel rather than two variants.
        let attn_window_buf = nb(classes.len().max(1) * 4);
        unsafe {
            let p = attn_window_buf.contents() as *mut u32;
            for (c, w) in classes.iter().enumerate() {
                *p.add(c) = w.unwrap_or(0) as u32;
            }
        }
        let attn_s_scalar = nb(52);
        let attn_pv_scalar = nb(52);
        let attn_sm_scalar = nb(20);
        let attn_vt_scalar = nb(16);

        // f32 -> half staging for one GEMM input panel. `count_off` selects the element
        // count word in `mm_counts` (0 = k*hidden, 4 = k*q_dim, 8 = k*ffn_dim).
        let mm_stage = |e: &metal::ComputeCommandEncoderRef,
                        src: &Buffer,
                        dst: &Buffer,
                        count_off: u64,
                        n: usize| {
            e.set_compute_pipeline_state(&kern.f32_to_f16_pipeline);
            e.set_buffer(0, Some(src), 0);
            e.set_buffer(1, Some(dst), 0);
            e.set_buffer(2, Some(&mm_counts), count_off);
            dispatch_1d(e, &kern.f32_to_f16_pipeline, n);
        };
        // One `q8_0_block_wire_mm` dispatch: a 64-row x 128-column output tile per
        // threadgroup, 256 threads = 8 simdgroups. `scalar` is the shared 12-byte
        // [blocks_per_row, rows, n_rows_in] triple the GEMV path already carries, bound at
        // offsets 0/4/8 exactly as the shipped `prefill_tokens` MM path binds it.
        let mm_gemm = |e: &metal::ComputeCommandEncoderRef,
                       y: &Buffer,
                       w: &ResidentLinearWeight,
                       out: &Buffer,
                       scalar: &Buffer,
                       rows: usize,
                       n_rows_in: usize| {
            e.set_compute_pipeline_state(&kern.q8_0_block_wire_mm_pipeline);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(2, Some(&w.buffer), 0);
            e.set_buffer(3, Some(out), 0);
            e.set_buffer(4, Some(scalar), 0);
            e.set_buffer(5, Some(scalar), 4);
            e.set_buffer(6, Some(scalar), 8);
            e.set_threadgroup_memory_length(0, PREFILL_MM_THREADGROUP_BYTES as u64);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (rows / PREFILL_MM_ROW_TILE) as u64,
                    height: (n_rows_in as u64).div_ceil(PREFILL_MM_TOKEN_TILE as u64),
                    depth: 1,
                },
                metal::MTLSize {
                    width: 256,
                    height: 1,
                    depth: 1,
                },
            );
        };

        // One `half_mm_batched_f16o` dispatch: a 64x64 output tile per threadgroup, 128
        // threads = 4 simdgroups, a FIXED 8 192 B of threadgroup memory. Buffers 3..=15
        // are the thirteen uniform words of `scalar` in order; buffer 16 is the window,
        // which rides in the per-class buffer so one dispatch path serves both the
        // sliding and the global layers.
        #[allow(clippy::too_many_arguments)]
        let attn_mm_gemm = |e: &metal::ComputeCommandEncoderRef,
                            a: &Buffer,
                            b: &Buffer,
                            c: &Buffer,
                            scalar: &Buffer,
                            window_off: u64,
                            grid_rows: usize,
                            grid_cols: usize| {
            e.set_compute_pipeline_state(&kern.half_mm_batched_f16o_pipeline);
            e.set_buffer(0, Some(a), 0);
            e.set_buffer(1, Some(b), 0);
            e.set_buffer(2, Some(c), 0);
            for j in 0..13u64 {
                e.set_buffer(3 + j, Some(scalar), j * 4);
            }
            e.set_buffer(16, Some(&attn_window_buf), window_off);
            e.set_threadgroup_memory_length(0, ATTN_MM_THREADGROUP_BYTES as u64);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (grid_rows as u64).div_ceil(ATTN_MM_TILE as u64),
                    height: (grid_cols as u64).div_ceil(ATTN_MM_TILE as u64),
                    depth: n_heads as u64,
                },
                metal::MTLSize {
                    width: 128,
                    height: 1,
                    depth: 1,
                },
            );
        };

        let mut hidden_out: Vec<f32> = if read_hidden {
            Vec::with_capacity(n_tokens * hidden)
        } else {
            Vec::new()
        };

        // ---- One command buffer per chunk ------------------------------------------------
        let mut base = 0usize;
        while base < n_tokens {
            let k = chunk.min(n_tokens - base);
            // Per-chunk scalars: the last chunk is narrower, and every previous chunk's
            // command buffer has already completed (waited on below), so rewriting the
            // shared scalar buffers here is safe.
            unsafe {
                *(act_n.contents() as *mut u32) = (k * ffn_dim) as u32;
                *(resid_n.contents() as *mut u32) = (k * hidden) as u32;
                if use_mm {
                    // The MM path writes the GEMV scalars itself (the scalar path lets
                    // `encode_resident_matmul_f32` write them at encode time). The third
                    // word is `n_rows_in` — the kernel's ragged-tail guard.
                    let c = mm_counts.contents() as *mut u32;
                    *c = (k * hidden) as u32;
                    *c.add(1) = (k * q_dim) as u32;
                    *c.add(2) = (k * ffn_dim) as u32;
                    for (buf, bpr, rows) in [
                        (&q_gemv, bpr_hidden, q_dim),
                        (&kv_gemv, bpr_hidden, kv_dim),
                        (&o_gemv, bpr_q, hidden),
                        (&gateup_gemv, bpr_hidden, ffn_dim),
                        (&down_gemv, bpr_ffn, hidden),
                    ] {
                        let p = buf.contents() as *mut u32;
                        *p = bpr as u32;
                        *p.add(1) = rows as u32;
                        *p.add(2) = k as u32;
                    }
                }
                for i in 0..k {
                    let s = (scatter_scalars.contents() as *mut u8).add(i * 16) as *mut u32;
                    *s = head_dim as u32;
                    *s.add(1) = max_positions as u32;
                    *s.add(2) = (base + i) as u32;
                    *s.add(3) = if self.kvq8 {
                        (n_kv_heads * (head_dim / 32)) as u32
                    } else {
                        kv_dim as u32
                    };
                }
                for (c, window) in classes.iter().enumerate() {
                    for i in 0..k {
                        // `filled = base + i + 1` — the window INCLUDES the current
                        // position, and this is the SAME expression the decode encode runs.
                        let (window_start, position_count) =
                            schedule_window_bounds(*window, base + i + 1);
                        let p = attn_scalars[c * chunk + i].contents() as *mut u8;
                        *(p as *mut u32) = n_heads as u32;
                        *(p.add(4) as *mut u32) = head_dim as u32;
                        *(p.add(8) as *mut u32) = position_count as u32;
                        *(p.add(12) as *mut u32) = (n_heads / n_kv_heads) as u32;
                        *(p.add(16) as *mut f32) = scale;
                        *(p.add(20) as *mut u32) = kv_position_stride as u32;
                        *(p.add(24) as *mut u32) = (max_positions * kv_position_stride) as u32;
                        // Shares `position_stride`'s units (BYTES on a Q8 primary,
                        // elements on f32/f16) — scale with the stride, NOT with head_dim.
                        *(p.add(28) as *mut u32) = (window_start * kv_position_stride) as u32;
                    }
                }
            }
            // Phase 4 per-chunk geometry. Positions [0, n_pos) are live once this chunk's
            // K/V are scattered; `n_pad` rounds that to the kernels' 64 tile so a query
            // tile's causal boundary and `softmax_causal_rows`'s `write_end` coincide with
            // the PV pass's `k_end`. The S pass is handed `rows = n_pos`, NOT n_pad, so its
            // A-row guard never reads a cache slot past the live range.
            let n_pos = base + k;
            let n_pad = n_pos.next_multiple_of(ATTN_MM_TILE);
            if use_attn_mm {
                unsafe {
                    // S = K Qᵀ: A = the half K mirror [kv_head][max_positions][head_dim],
                    // B = the half Q panel [row][q_dim], C = S [head][row][n_pad].
                    let p = attn_s_scalar.contents() as *mut u32;
                    *p = head_dim as u32; // kdim (contract over head_dim)
                    *p.add(1) = n_pos as u32; // rows: live KV positions
                    *p.add(2) = k as u32; // cols: this chunk's queries
                    *p.add(3) = (max_positions * head_dim) as u32; // a batch stride
                    *p.add(4) = head_dim as u32; // b batch stride (head slice of a row)
                    *p.add(5) = (chunk * n_pad) as u32; // c batch stride
                    *p.add(6) = head_dim as u32; // a row stride
                    *p.add(7) = q_dim as u32; // b row stride
                    *p.add(8) = n_pad as u32; // c row stride
                    *p.add(9) = 1; // a elem stride
                    *p.add(10) = (n_heads / n_kv_heads) as u32; // GQA: share the KV head
                    *p.add(11) = 1; // causal_mode: upper cull + window cull
                    *p.add(12) = base as u32; // q_offset: chunk-local -> absolute

                    // O = Vᵀ P: A = Vᵀ [kv_head][head_dim][n_pad], B = P, C = the half
                    // context panel the O projection consumes.
                    let p = attn_pv_scalar.contents() as *mut u32;
                    *p = n_pad as u32; // kdim (contract over positions)
                    *p.add(1) = head_dim as u32; // rows
                    *p.add(2) = k as u32; // cols
                    *p.add(3) = (head_dim * n_pad) as u32; // a batch stride
                    *p.add(4) = (chunk * n_pad) as u32; // b batch stride
                    *p.add(5) = head_dim as u32; // c batch stride (head slice)
                    *p.add(6) = n_pad as u32; // a row stride
                    *p.add(7) = n_pad as u32; // b row stride
                    *p.add(8) = q_dim as u32; // c row stride
                    *p.add(9) = 1; // a elem stride
                    *p.add(10) = (n_heads / n_kv_heads) as u32;
                    *p.add(11) = 2; // causal_mode: k_end clamp + window k_start
                    *p.add(12) = base as u32;
                    let p = attn_sm_scalar.contents() as *mut u32;
                    *p = n_pad as u32; // score-row stride
                    *p.add(1) = n_pos as u32;
                    *(p.add(2) as *mut f32) = scale;
                    *p.add(3) = base as u32; // q_offset

                    // rows per block is the PANEL's row pitch, which is the chunk width
                    // and NOT this chunk's row count: `softmax_causal_rows` derives its
                    // per-head base as `head * rows_per_block * n_pad`, the same stride
                    // the two GEMMs are handed as `c_batch_stride` / `b_batch_stride`.
                    // A ragged last chunk (k < chunk) that passed `k` here sent every
                    // head above 0 to the wrong panel offset — caught by G6 at n = 257 /
                    // 513 / 2400 and by nothing else. The live-row count rides in the
                    // dispatch height instead.
                    *p.add(4) = chunk as u32;
                    let p = attn_vt_scalar.contents() as *mut u32;
                    *p = head_dim as u32;
                    *p.add(1) = max_positions as u32;
                    *p.add(2) = n_pad as u32;
                    *p.add(3) = n_pos as u32; // zero-fill past the live range
                }
            }
            write_buffer_f32(&act_a, &embeddings[base * hidden..(base + k) * hidden]);

            let encode_started = std::time::Instant::now();
            let mut keep: Vec<Buffer> = Vec::new();
            let cb = kern.queue.new_command_buffer();
            let e = cb.new_compute_command_encoder();
            let mut from_a = true;
            for l in 0..self.n_layers {
                let (cur, nxt) = if from_a {
                    (&act_a, &act_b)
                } else {
                    (&act_b, &act_a)
                };
                let w = &resident[l];
                // Dual-theta: sliding layers rope with the ALT (local-theta) tables,
                // globals with the primary — `prepare_token`'s selection verbatim.
                let (l_cos, l_sin) = match (&self.schedule, &alt_bufs) {
                    (Some(sched), Some((ac, as_))) if sched.use_alt_rope[l] => (ac, as_),
                    _ => (&cos_buf, &sin_buf),
                };
                // --- Attention block ---
                encode_rms_norm_batch(kern, e, cur, &attn_norm_bufs[l], &norm_buf, &rms_scalar, k);
                if use_mm {
                    mm_stage(e, &norm_buf, &mm_y_hidden, 0, k * hidden);
                    mm_gemm(e, &mm_y_hidden, &w[0], &q_buf, &q_gemv, q_dim, k);
                    mm_gemm(e, &mm_y_hidden, &w[1], &k_buf, &kv_gemv, kv_dim, k);
                    mm_gemm(e, &mm_y_hidden, &w[2], &v_buf, &kv_gemv, kv_dim, k);
                } else {
                    encode_resident_matmul_f32(
                        e, kern, &mut keep, &norm_buf, &w[0], &q_buf, &q_gemv, hidden, q_dim, k,
                    );
                    encode_resident_matmul_f32(
                        e, kern, &mut keep, &norm_buf, &w[1], &k_buf, &kv_gemv, hidden, kv_dim, k,
                    );
                    encode_resident_matmul_f32(
                        e, kern, &mut keep, &norm_buf, &w[2], &v_buf, &kv_gemv, hidden, kv_dim, k,
                    );
                }
                // Per-head QK-norm (Qwen3/gemma3), per row, in place, before RoPE.
                if let Some((qn_buf, kn_buf)) = &qk_norm_bufs[l] {
                    for i in 0..k {
                        encode_rms_norm_per_head(
                            e,
                            kern,
                            &q_buf,
                            qn_buf,
                            &q_buf,
                            &perhead_qk_scalar,
                            n_heads,
                            (i * q_dim * 4) as u64,
                        );
                        encode_rms_norm_per_head(
                            e,
                            kern,
                            &k_buf,
                            kn_buf,
                            &k_buf,
                            &perhead_qk_scalar,
                            n_kv_heads,
                            (i * kv_dim * 4) as u64,
                        );
                    }
                }
                // RoPE — per row at position base+i (cos/sin position-major, stride half_rope).
                for i in 0..k {
                    let table_off = ((base + i) * half_rope * 4) as u64;
                    encode_rope(
                        e,
                        kern,
                        &q_buf,
                        l_cos,
                        l_sin,
                        &rope_q_scalar,
                        n_heads,
                        half_rope,
                        (i * q_dim * 4) as u64,
                        table_off,
                    );
                    encode_rope(
                        e,
                        kern,
                        &k_buf,
                        l_cos,
                        l_sin,
                        &rope_k_scalar,
                        n_kv_heads,
                        half_rope,
                        (i * kv_dim * 4) as u64,
                        table_off,
                    );
                }
                // K/V scatter — every row into slot base+i BEFORE any attention reads, so
                // row i sees its own slot and every earlier row exactly as a standalone
                // decode at that position would.
                for i in 0..k {
                    let scatter_pipeline = if self.kvq8 {
                        &kern.kv_scatter_kvq8_pipeline
                    } else if self.kv16 {
                        &kern.kv_scatter_kv16_pipeline
                    } else {
                        &kern.kv_scatter_pipeline
                    };
                    e.set_compute_pipeline_state(scatter_pipeline);
                    e.set_buffer(0, Some(&k_buf), (i * kv_dim * 4) as u64);
                    e.set_buffer(1, Some(&v_buf), (i * kv_dim * 4) as u64);
                    e.set_buffer(2, Some(&self.cache_k[l]), 0);
                    e.set_buffer(3, Some(&self.cache_v[l]), 0);
                    e.set_buffer(4, Some(&scatter_scalars), (i * 16) as u64);
                    e.set_buffer(5, Some(&scatter_scalars), (i * 16 + 4) as u64);
                    e.set_buffer(6, Some(&scatter_scalars), (i * 16 + 8) as u64);
                    e.set_buffer(7, Some(&scatter_scalars), (i * 16 + 12) as u64);
                    if !self.kv16 && !self.kvq8 {
                        e.set_buffer(8, Some(&self.cache_k16[l]), 0);
                        e.set_buffer(9, Some(&self.cache_v16[l]), 0);
                        e.set_buffer(10, Some(&kv16_write), 0);
                    }
                    let scatter_units = if self.kvq8 {
                        n_kv_heads * (head_dim / 32)
                    } else {
                        kv_dim
                    };
                    dispatch_1d(e, scatter_pipeline, scatter_units);
                }
                // Attention — per row, through the UNCHANGED encode_attention, so the
                // v2 / split-K / split3 routing at that position_count is whatever the
                // token-by-token lane would pick.
                let class_base = layer_class[l] * chunk;
                if use_attn_mm {
                    // Phase 4: the whole chunk's attention as three dispatches instead of
                    // 3k. Q is converted to half only HERE — after the f32 per-head
                    // QK-norm and the f32 RoPE, both of which still run the exact
                    // single-token kernels at a row byte offset.
                    mm_stage(e, &q_buf, &attn_q_h, 4, k * q_dim);
                    // Vᵀ for this layer's live cache slice, so the PV pass's A staging
                    // reads contiguously; positions past `n_pos` are zero-filled.
                    e.set_compute_pipeline_state(&kern.transpose_v16_pipeline);
                    e.set_buffer(0, Some(&self.cache_v16[l]), 0);
                    e.set_buffer(1, Some(&attn_vt), 0);
                    for j in 0..4u64 {
                        e.set_buffer(2 + j, Some(&attn_vt_scalar), j * 4);
                    }
                    e.dispatch_threads(
                        metal::MTLSize {
                            width: n_pad as u64,
                            height: head_dim as u64,
                            depth: n_kv_heads as u64,
                        },
                        metal::MTLSize {
                            width: 32,
                            height: 4,
                            depth: 1,
                        },
                    );
                    let window_off = (layer_class[l] * 4) as u64;
                    attn_mm_gemm(
                        e,
                        &self.cache_k16[l],
                        &attn_q_h,
                        &attn_s,
                        &attn_s_scalar,
                        window_off,
                        n_pad,
                        k,
                    );
                    e.set_compute_pipeline_state(&kern.softmax_causal_rows_pipeline);
                    e.set_buffer(0, Some(&attn_s), 0);
                    e.set_buffer(1, Some(&attn_p), 0);
                    for j in 0..5u64 {
                        e.set_buffer(2 + j, Some(&attn_sm_scalar), j * 4);
                    }
                    e.set_buffer(7, Some(&attn_window_buf), window_off);
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: n_heads as u64,
                            height: (k as u64).div_ceil(8),
                            depth: 1,
                        },
                        metal::MTLSize {
                            width: 256,
                            height: 1,
                            depth: 1,
                        },
                    );
                    // Straight into the O projection's half input panel: no f32 context
                    // round trip, and the padded rows stay zero from the one-time memset.
                    attn_mm_gemm(
                        e,
                        &attn_vt,
                        &attn_p,
                        &mm_y_q,
                        &attn_pv_scalar,
                        window_off,
                        head_dim,
                        k,
                    );
                } else {
                    for i in 0..k {
                        let (_, position_count) =
                            schedule_window_bounds(layer_windows[l], base + i + 1);
                        encode_attention(
                            e,
                            kern,
                            &mut keep,
                            &q_buf,
                            &self.cache_k[l],
                            &self.cache_v[l],
                            if self.kv16 || self.kvq8 {
                                None
                            } else {
                                Some((&self.cache_k16[l], &self.cache_v16[l]))
                            },
                            &scores_buf,
                            &ctx_buf,
                            &attn_scalars[class_base + i],
                            n_heads,
                            n_kv_heads,
                            head_dim,
                            position_count,
                            (i * q_dim * 4) as u64,
                            (i * q_dim * 4) as u64,
                        );
                    }
                }
                if use_mm {
                    if !use_attn_mm {
                        mm_stage(e, &ctx_buf, &mm_y_q, 4, k * q_dim);
                    }
                    mm_gemm(e, &mm_y_q, &w[3], &o_buf, &o_gemv, hidden, k);
                } else {
                    encode_resident_matmul_f32(
                        e, kern, &mut keep, &ctx_buf, &w[3], &o_buf, &o_gemv, q_dim, hidden, k,
                    );
                }
                // gemma3 sandwich norm: RMSNorm on the attention output BEFORE the residual.
                let attn_resid_src = match &post_attn_norm_bufs[l] {
                    Some(pn) => {
                        encode_rms_norm_batch(kern, e, &o_buf, pn, &post_buf, &rms_scalar, k);
                        &post_buf
                    }
                    None => &o_buf,
                };
                encode_binary(
                    e,
                    &kern.residual_add_pipeline,
                    cur,
                    attn_resid_src,
                    &mid,
                    &resid_n,
                    k * hidden,
                );
                // --- FFN block ---
                encode_rms_norm_batch(kern, e, &mid, &ffn_norm_bufs[l], &norm_buf, &rms_scalar, k);
                if use_mm {
                    mm_stage(e, &norm_buf, &mm_y_hidden, 0, k * hidden);
                    mm_gemm(e, &mm_y_hidden, &w[4], &gate_buf, &gateup_gemv, ffn_dim, k);
                    mm_gemm(e, &mm_y_hidden, &w[5], &up_buf, &gateup_gemv, ffn_dim, k);
                } else {
                    encode_resident_matmul_f32(
                        e,
                        kern,
                        &mut keep,
                        &norm_buf,
                        &w[4],
                        &gate_buf,
                        &gateup_gemv,
                        hidden,
                        ffn_dim,
                        k,
                    );
                    encode_resident_matmul_f32(
                        e,
                        kern,
                        &mut keep,
                        &norm_buf,
                        &w[5],
                        &up_buf,
                        &gateup_gemv,
                        hidden,
                        ffn_dim,
                        k,
                    );
                }
                // gemma3 GeGLU (gelu_tanh(gate) * up) vs the Llama-family SiLU — the SAME
                // elementwise kernels the decode encode dispatches, with a wider `n`.
                let act_pipeline = if layers[l].ffn_geglu {
                    &kern.gelu_mul_pipeline
                } else {
                    &kern.silu_mul_pipeline
                };
                encode_binary(
                    e,
                    act_pipeline,
                    &gate_buf,
                    &up_buf,
                    &act_buf,
                    &act_n,
                    k * ffn_dim,
                );
                if use_mm {
                    mm_stage(e, &act_buf, &mm_y_ffn, 8, k * ffn_dim);
                    mm_gemm(e, &mm_y_ffn, &w[6], &down_buf, &down_gemv, hidden, k);
                } else {
                    encode_resident_matmul_f32(
                        e, kern, &mut keep, &act_buf, &w[6], &down_buf, &down_gemv, ffn_dim,
                        hidden, k,
                    );
                }
                let ffn_resid_src = match &post_ffw_norm_bufs[l] {
                    Some(pn) => {
                        encode_rms_norm_batch(kern, e, &down_buf, pn, &post_buf, &rms_scalar, k);
                        &post_buf
                    }
                    None => &down_buf,
                };
                encode_binary(
                    e,
                    &kern.residual_add_pipeline,
                    &mid,
                    ffn_resid_src,
                    nxt,
                    &resid_n,
                    k * hidden,
                );
                from_a = !from_a;
            }
            e.end_encoding();
            let encode_us = encode_started.elapsed().as_micros();
            let commit_started = std::time::Instant::now();
            cb.commit();
            cb.wait_until_completed();
            if trace {
                // Attribution, not decoration: `gpu_busy` vs wall separates
                // "the kernels are slow" from "the CPU cannot feed the GPU". Tier A's
                // whole claim is about the former, so the phase record needs the split.
                let wall_us = commit_started.elapsed().as_micros();
                let (gpu_busy_us, kernel_window_us) = command_buffer_gpu_times_us(&cb.to_owned());
                eprintln!(
                    "[batch-prefill] base={base} rows={k} gemm={} attn={} \
                     encode={encode_us}us commit_wait={wall_us}us gpu_busy={gpu_busy_us}us \
                     kernel_window={kernel_window_us}us",
                    if use_mm { "mm" } else { "gemv" },
                    if use_attn_mm { "mm" } else { "row" }
                );
            }
            if read_hidden {
                let final_buf = if from_a { &act_a } else { &act_b };
                let mut out = vec![0.0f32; k * hidden];
                read_buffer_f32(final_buf, &mut out);
                hidden_out.extend_from_slice(&out);
            }
            // Every entry came from `pool_get` (the per-row attention scratch and the
            // K-quant activation staging); returning them lets the NEXT chunk reuse the
            // same allocations instead of re-creating thousands of small MTLBuffers.
            pool_recycle(kern, keep);
            base += k;
        }
        // G11: the caller's rebuild predicate is `filled() != position`. Leaving this
        // short re-seeds from a CPU KV cache the resident lane leaves hollow, which then
        // declines at `history_materialized` and drops the whole prompt onto a CPU path
        // that fails closed for windowed archs.
        self.filled = n_tokens;
        Some(hidden_out)
    }

    /// WIN2METAL Phase 3: speculative-verify forward over `k` rows at sequence positions
    /// `[base_position, base_position + k)`. BIT-IDENTICAL to `k` independent
    /// `forward_token` decodes at those positions: the input RMSNorm/projections/FFN run as
    /// the proven byte-exact batched kernels (`rms_norm_batch_f32`, the C0 batched-column
    /// GEMV `encode_q8_matmul_f32y_batched`, elementwise residual/silu), while per-head
    /// QK-norm, RoPE, K/V scatter, attention and argmax run the EXACT single-token kernels
    /// once per row at a row byte-offset (so cos/sin pairing, scatter slot, attention
    /// v2/split-K routing and argmax tie-break are reproduced verbatim). All `k` K/V are
    /// scattered into `[base..base+k)` before any attention; row `i` attends over
    /// `position_count = base+i+1`, so it sees only `[0, base+i]` (its own slot + the prior
    /// rows), exactly as a standalone decode would. Does NOT advance `filled` — the host
    /// accept loop sets `filled = base + accepted.len()` and the rejected tail slots are
    /// overwritten by the next single-token decode. Returns the `k` greedy argmax ids, or
    /// `None` (lossless fallback) on any unsupported config.
    #[allow(clippy::too_many_arguments)]
    pub fn verify_batch(
        &mut self,
        embeddings: &[f32],
        cos_all: &[f32],
        sin_all: &[f32],
        layers: &[ResidentLayerWeights],
        logits: &LogitsStage,
        base_position: usize,
        k: usize,
        scale: f32,
    ) -> Option<Vec<u32>> {
        // The batched paths encode the dense FFN only; a MoE layer must fail closed.
        if layers.iter().any(|l| l.moe.is_some()) {
            return None;
        }
        self.verify_batch_inner(
            embeddings,
            cos_all,
            sin_all,
            layers,
            logits,
            base_position,
            k,
            scale,
            false,
            None,
        )
        .map(|(preds, _)| preds)
    }

    /// `verify_batch` that also reads back the `k * vocab` pre-argmax logits (the byte-exact
    /// gate compares logits by exact `to_bits`, which a logits bug that doesn't flip the
    /// argmax would slip past). Test-only: the production lane never pays the logits readback.
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    fn verify_batch_logits(
        &mut self,
        embeddings: &[f32],
        cos_all: &[f32],
        sin_all: &[f32],
        layers: &[ResidentLayerWeights],
        logits: &LogitsStage,
        base_position: usize,
        k: usize,
        scale: f32,
    ) -> Option<(Vec<u32>, Vec<f32>)> {
        self.verify_batch_inner(
            embeddings,
            cos_all,
            sin_all,
            layers,
            logits,
            base_position,
            k,
            scale,
            true,
            None,
        )
    }

    /// Maximum verify window (mirrors the CUDA host's `MAX_VERIFY_K`).
    const MAX_VERIFY_K: usize = 8;

    #[allow(clippy::too_many_arguments)]
    fn verify_batch_inner(
        &mut self,
        embeddings: &[f32],
        cos_all: &[f32],
        sin_all: &[f32],
        layers: &[ResidentLayerWeights],
        logits: &LogitsStage,
        base_position: usize,
        k: usize,
        scale: f32,
        read_logits: bool,
        tree: Option<&TreeAttn>,
    ) -> Option<(Vec<u32>, Vec<f32>)> {
        // ---- Eligibility gate (return None -> caller falls back, lossless) --------------
        // The tree path widens the node cap to TREE_MAX_NODES (a tree of N nodes has at most
        // depth N-1); the linear path keeps the MAX_VERIFY_K window. `None`-tree callers see
        // the original bound, so the linear path is byte-unchanged.
        let k_cap = if tree.is_some() {
            crate::inference::spec_tree::TREE_MAX_NODES
        } else {
            Self::MAX_VERIFY_K
        };
        if !(1..=k_cap).contains(&k) {
            return None;
        }
        if (self.kv16 || self.kvq8) && tree.is_some() {
            return None; // tree kernels do not yet carry compressed-primary non-split twins
        }
        // The tree split-K attention (encode_attention_tree) is mirror-only — there is no f32
        // split-K *tree* kernel. The CAMELID_METAL_ATTN_SPLITK_KV16=0 opt-out forces forward_token
        // and the LINEAR verify (encode_attention) onto the f32 split-K reads, so a tree verify
        // reading the f16 mirrors instead would diverge from plain greedy (NOT lossless). Fail
        // closed to the lossless single-token/CPU fallback rather than emit a non-lossless tree
        // verify. The linear path honors the env in encode_attention, so it is unaffected and
        // stays byte-exact; only the tree lane needs this guard. (Mirror predicate matches the
        // `use_mirrors` test in encode_attention.)
        if tree.is_some()
            && std::env::var("CAMELID_METAL_ATTN_SPLITK_KV16")
                .is_ok_and(|v| v == "0" || v.eq_ignore_ascii_case("false"))
        {
            return None;
        }
        // The new batched GEMV mirrors exactly the f32y + wire + NSG=8 production GEMV; any
        // other GEMV path would not match it bit-for-bit.
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            return None;
        }
        if !self.head_dim.is_multiple_of(32) || self.head_dim > 128 {
            return None; // v2 / split-K attention precondition
        }
        // gemma3 sandwich norms are wired into the decode encodes only; the
        // batched verify layouts do not apply them (and hardcode
        // kv_base_offset=0), and the per-layer dual-theta schedule cannot be
        // expressed by the verify's single table set — fail closed rather than
        // verify with an incomplete forward. (gemma3 additionally never
        // reaches here: head_dim 256 > 128 — this is the belt-and-braces gate.)
        if self.schedule.is_some()
            || layers
                .iter()
                .any(|l| l.post_attn_norm.is_some() || l.post_ffw_norm.is_some() || l.ffn_geglu)
        {
            return None;
        }
        if base_position != self.filled() {
            return None;
        }
        if base_position + k > self.cap {
            return None;
        }
        if layers.len() != self.n_layers || embeddings.len() != k * self.hidden {
            return None;
        }
        if cos_all.len() != sin_all.len() || cos_all.is_empty() || !cos_all.len().is_multiple_of(k)
        {
            return None;
        }
        let half_rope = cos_all.len() / k;
        if half_rope * 2 > self.head_dim {
            return None;
        }
        let q_dim = self.n_heads * self.head_dim;
        let kv_dim = self.n_kv_heads * self.head_dim;
        for l in layers {
            if l.attn_norm.len() != self.hidden
                || l.ffn_norm.len() != self.hidden
                || !l.q_weight_blocks.matches_shape(self.hidden, q_dim)
                || !l.k_weight_blocks.matches_shape(self.hidden, kv_dim)
                || !l.v_weight_blocks.matches_shape(self.hidden, kv_dim)
                || !l.o_weight_blocks.matches_shape(q_dim, self.hidden)
                || !l
                    .gate_weight_blocks
                    .matches_shape(self.hidden, self.ffn_dim)
                || !l.up_weight_blocks.matches_shape(self.hidden, self.ffn_dim)
                || !l
                    .down_weight_blocks
                    .matches_shape(self.ffn_dim, self.hidden)
            {
                return None;
            }
        }
        let vocab = logits.vocab_size;
        if vocab == 0
            || logits.final_norm.len() != self.hidden
            || !logits
                .output_weight_blocks
                .matches_shape(self.hidden, vocab)
        {
            return None;
        }

        // A pre-committed pending graph (from forward_token's encode-ahead) sits gated on the
        // serial queue; release it so this command buffer is not ordered behind a graph that
        // never gets signaled (which would deadlock the wait below).
        if let Some(stale) = self.pending.take() {
            self.release_stale(stale);
        }
        self.pending_signaled = false;
        if !self.ensure_capacity(base_position + k) {
            return None;
        }

        let kern = metal_linear_kernel()?;
        let max_positions = self.max_positions;
        let n_heads = self.n_heads;
        let n_kv_heads = self.n_kv_heads;
        let head_dim = self.head_dim;
        let hidden = self.hidden;
        let ffn_dim = self.ffn_dim;
        let eps = self.eps;
        let pairing = u32::from(self.split_half_pairing);
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn_dim / 32;

        // ---- Resolve resident weights (wire format; gated on f32y+wire above) ------------
        let resident: Vec<[ResidentLinearWeight; 7]>;
        let attn_norm_bufs: Vec<Buffer>;
        let ffn_norm_bufs: Vec<Buffer>;
        let qk_norm_bufs: Vec<Option<(Buffer, Buffer)>>;
        let ow_buf: ResidentLinearWeight;
        let final_norm_buf: Buffer;
        {
            let mut cache = metal_linear_cache().lock().ok()?;
            let mut wb = |w: &ResidentWeightBytes| {
                resolve_resident_weight(&mut cache, &kern.device, w, true)
            };
            resident = layers
                .iter()
                .map(|l| {
                    Some([
                        wb(&l.q_weight_blocks)?,
                        wb(&l.k_weight_blocks)?,
                        wb(&l.v_weight_blocks)?,
                        wb(&l.o_weight_blocks)?,
                        wb(&l.gate_weight_blocks)?,
                        wb(&l.up_weight_blocks)?,
                        wb(&l.down_weight_blocks)?,
                    ])
                })
                .collect::<Option<Vec<_>>>()?;
            ow_buf = wb(&logits.output_weight_blocks)?;
            attn_norm_bufs = layers
                .iter()
                .map(|l| cache.weight_buffer(&kern.device, l.attn_norm))
                .collect();
            ffn_norm_bufs = layers
                .iter()
                .map(|l| cache.weight_buffer(&kern.device, l.ffn_norm))
                .collect();
            qk_norm_bufs = layers
                .iter()
                .map(|l| match (l.q_norm, l.k_norm) {
                    (Some(qn), Some(kn)) => Some((
                        cache.weight_buffer(&kern.device, qn),
                        cache.weight_buffer(&kern.device, kn),
                    )),
                    _ => None,
                })
                .collect();
            final_norm_buf = cache.weight_buffer(&kern.device, logits.final_norm);
        }

        // ---- Buffers (row-major [token][dim]; token = verify row) -----------------------
        let nb = |bytes: usize| {
            kern.device
                .new_buffer(bytes.max(4) as u64, MTLResourceOptions::StorageModeShared)
        };
        let act_a = nb(k * hidden * 4);
        let act_b = nb(k * hidden * 4);
        let mid = nb(k * hidden * 4);
        let norm_buf = nb(k * hidden * 4);
        let q_buf = nb(k * q_dim * 4);
        let k_buf = nb(k * kv_dim * 4);
        let v_buf = nb(k * kv_dim * 4);
        let ctx_buf = nb(k * q_dim * 4);
        let o_buf = nb(k * hidden * 4);
        let gate_buf = nb(k * ffn_dim * 4);
        let up_buf = nb(k * ffn_dim * 4);
        let silu_buf = nb(k * ffn_dim * 4);
        let down_buf = nb(k * hidden * 4);
        let fnorm_buf = nb(k * hidden * 4);
        let logits_buf = nb(k * vocab * 4);
        let pred_buf = nb(k * 4);
        let cos_buf = nb(cos_all.len() * 4);
        let sin_buf = nb(sin_all.len() * 4);
        // Attention scores scratch (only read by the non-v2 fallback kernel); size to the
        // deepest row's position_count = base+k.
        let scores_buf = nb(n_heads * (base_position + k) * 4);
        write_buffer_f32(&act_a, embeddings);
        write_buffer_f32(&cos_buf, cos_all);
        write_buffer_f32(&sin_buf, sin_all);

        // ---- Scalars --------------------------------------------------------------------
        let rms_scalar = nb(8); // width (hidden), eps — shared by attn/ffn/final norms
        let q_gemv = nb(12); // blocks_per_row, rows, [n_rows_in set by helper]
        let kv_gemv = nb(12);
        let o_gemv = nb(12);
        let gateup_gemv = nb(12);
        let down_gemv = nb(12);
        let out_gemv = nb(12);
        let rope_q_scalar = nb(16);
        let rope_k_scalar = nb(16);
        let silu_n = nb(4);
        let resid_n = nb(4);
        let kv16_write = nb(4);
        let argmax_count = nb(4);
        let perhead_qk_scalar = nb(12);
        unsafe {
            let p = rms_scalar.contents() as *mut u8;
            *(p as *mut u32) = hidden as u32;
            *(p.add(4) as *mut f32) = eps;
            let set_gemv = |buf: &Buffer, bpr: usize, rows: usize| {
                let q = buf.contents() as *mut u32;
                *q = bpr as u32;
                *q.add(1) = rows as u32;
            };
            set_gemv(&q_gemv, bpr_hidden, q_dim);
            set_gemv(&kv_gemv, bpr_hidden, kv_dim);
            set_gemv(&o_gemv, bpr_q, hidden);
            set_gemv(&gateup_gemv, bpr_hidden, ffn_dim);
            set_gemv(&down_gemv, bpr_ffn, hidden);
            set_gemv(&out_gemv, bpr_hidden, vocab);
            let set_rope = |buf: &Buffer, hc: usize| {
                let r = buf.contents() as *mut u32;
                *r = hc as u32;
                *r.add(1) = head_dim as u32;
                *r.add(2) = half_rope as u32;
                *r.add(3) = pairing;
            };
            set_rope(&rope_q_scalar, n_heads);
            set_rope(&rope_k_scalar, n_kv_heads);
            *(silu_n.contents() as *mut u32) = (k * ffn_dim) as u32;
            *(resid_n.contents() as *mut u32) = (k * hidden) as u32;
            *(kv16_write.contents() as *mut u32) = u32::from(!self.kv16 && !self.kvq8);
            *(argmax_count.contents() as *mut u32) = vocab as u32;
            let p = perhead_qk_scalar.contents() as *mut u8;
            *(p as *mut u32) = head_dim as u32;
            *(p.add(4) as *mut f32) = eps;
            *(p.add(8) as *mut u32) = 1; // use_weight
        }
        // Per-row scatter scalars [head_dim, max_positions, base+i, kv_dim] and per-row
        // attention scalars (32 bytes) — write_position / position_count vary per row, so
        // each row gets its own storage (the command buffer reads them at execution time).
        let scatter_scalars = nb(16 * k);
        let mut attn_scalars: Vec<Buffer> = Vec::with_capacity(k);
        for i in 0..k {
            unsafe {
                let s = (scatter_scalars.contents() as *mut u8).add(i * 16) as *mut u32;
                *s = head_dim as u32;
                *s.add(1) = max_positions as u32;
                *s.add(2) = (base_position + i) as u32;
                *s.add(3) = if self.kvq8 {
                    (n_kv_heads * (head_dim / 32)) as u32
                } else {
                    kv_dim as u32
                };
            }
            // position_count: linear row i covers prefix+self = base+i+1; a tree node covers
            // prefix + its ancestor drafts (incl. self) = base + tail_count.
            let pc_i = match tree {
                Some(t) => t.base + t.tail_slots[i].len(),
                None => base_position + i + 1,
            };
            let a = nb(32);
            unsafe {
                let p = a.contents() as *mut u8;
                *(p as *mut u32) = n_heads as u32;
                *(p.add(4) as *mut u32) = head_dim as u32;
                *(p.add(8) as *mut u32) = pc_i as u32; // position_count
                *(p.add(12) as *mut u32) = (n_heads / n_kv_heads) as u32;
                *(p.add(16) as *mut f32) = scale;
                let kv_position_stride = if self.kvq8 {
                    (head_dim / 32) * 34
                } else {
                    head_dim
                };
                *(p.add(20) as *mut u32) = kv_position_stride as u32;
                *(p.add(24) as *mut u32) = (max_positions * kv_position_stride) as u32;
                *(p.add(28) as *mut u32) = 0u32; // kv base offset
            }
            attn_scalars.push(a);
        }

        // ---- Per-node tree-attention buffers (tree path only) ---------------------------
        // `base` (the contiguous prefix length) is shared; each node gets its own
        // `tail_slots` buffer (its ancestor draft cache slots, increasing). The linear path
        // leaves these empty and dispatches the unchanged `encode_attention`.
        let (tree_base_buf, tree_tail_bufs): (Option<Buffer>, Vec<Buffer>) = if let Some(t) = tree {
            let bb = nb(4);
            unsafe {
                *(bb.contents() as *mut u32) = t.base as u32;
            }
            let bufs: Vec<Buffer> = (0..k)
                .map(|i| {
                    let slots = &t.tail_slots[i];
                    let buf = nb(slots.len().max(1) * 4);
                    unsafe {
                        let p = buf.contents() as *mut u32;
                        for (j, &s) in slots.iter().enumerate() {
                            *p.add(j) = s;
                        }
                    }
                    buf
                })
                .collect();
            (Some(bb), bufs)
        } else {
            (None, Vec::new())
        };

        // ---- Encode the whole verify window into one serial compute encoder -------------
        let mut keep: Vec<Buffer> = Vec::new();
        let cb = kern.queue.new_command_buffer();
        let e = cb.new_compute_command_encoder();
        let mut from_a = true;
        for l in 0..layers.len() {
            let (cur, nxt) = if from_a {
                (&act_a, &act_b)
            } else {
                (&act_b, &act_a)
            };
            let w = &resident[l];
            // --- Attention block ---
            // 1. input RMSNorm (batched, byte-exact vs single rms_norm_f32 per row)
            encode_rms_norm_batch(kern, e, cur, &attn_norm_bufs[l], &norm_buf, &rms_scalar, k);
            // 2. Q/K/V projections (batched-column GEMV; column t == single-token row t)
            encode_resident_matmul_f32(
                e, kern, &mut keep, &norm_buf, &w[0], &q_buf, &q_gemv, hidden, q_dim, k,
            );
            encode_resident_matmul_f32(
                e, kern, &mut keep, &norm_buf, &w[1], &k_buf, &kv_gemv, hidden, kv_dim, k,
            );
            encode_resident_matmul_f32(
                e, kern, &mut keep, &norm_buf, &w[2], &v_buf, &kv_gemv, hidden, kv_dim, k,
            );
            // 3. per-head Q/K-norm (Qwen3) — per row, in place
            if let Some((qn_buf, kn_buf)) = &qk_norm_bufs[l] {
                for i in 0..k {
                    encode_rms_norm_per_head(
                        e,
                        kern,
                        &q_buf,
                        qn_buf,
                        &q_buf,
                        &perhead_qk_scalar,
                        n_heads,
                        (i * q_dim * 4) as u64,
                    );
                    encode_rms_norm_per_head(
                        e,
                        kern,
                        &k_buf,
                        kn_buf,
                        &k_buf,
                        &perhead_qk_scalar,
                        n_kv_heads,
                        (i * kv_dim * 4) as u64,
                    );
                }
            }
            // 4. RoPE — per row (position base+i; cos/sin position-major, stride half_rope)
            for i in 0..k {
                encode_rope(
                    e,
                    kern,
                    &q_buf,
                    &cos_buf,
                    &sin_buf,
                    &rope_q_scalar,
                    n_heads,
                    half_rope,
                    (i * q_dim * 4) as u64,
                    (i * half_rope * 4) as u64,
                );
                encode_rope(
                    e,
                    kern,
                    &k_buf,
                    &cos_buf,
                    &sin_buf,
                    &rope_k_scalar,
                    n_kv_heads,
                    half_rope,
                    (i * kv_dim * 4) as u64,
                    (i * half_rope * 4) as u64,
                );
            }
            // 5. K/V scatter — per row into slot base+i, dual-writing the f16 mirrors the
            //    split-K decode attention reads (ALL k before any attention reads).
            for i in 0..k {
                let scatter_pipeline = if self.kvq8 {
                    &kern.kv_scatter_kvq8_pipeline
                } else if self.kv16 {
                    &kern.kv_scatter_kv16_pipeline
                } else {
                    &kern.kv_scatter_pipeline
                };
                e.set_compute_pipeline_state(scatter_pipeline);
                e.set_buffer(0, Some(&k_buf), (i * kv_dim * 4) as u64);
                e.set_buffer(1, Some(&v_buf), (i * kv_dim * 4) as u64);
                e.set_buffer(2, Some(&self.cache_k[l]), 0);
                e.set_buffer(3, Some(&self.cache_v[l]), 0);
                e.set_buffer(4, Some(&scatter_scalars), (i * 16) as u64);
                e.set_buffer(5, Some(&scatter_scalars), (i * 16 + 4) as u64);
                e.set_buffer(6, Some(&scatter_scalars), (i * 16 + 8) as u64);
                e.set_buffer(7, Some(&scatter_scalars), (i * 16 + 12) as u64);
                if !self.kv16 && !self.kvq8 {
                    e.set_buffer(8, Some(&self.cache_k16[l]), 0);
                    e.set_buffer(9, Some(&self.cache_v16[l]), 0);
                    e.set_buffer(10, Some(&kv16_write), 0);
                }
                let scatter_units = if self.kvq8 {
                    n_kv_heads * (head_dim / 32)
                } else {
                    kv_dim
                };
                dispatch_1d(e, scatter_pipeline, scatter_units);
            }
            // 6. attention — per row. position_count auto-routes v2 vs split-K exactly like
            //    forward_token at that pc; reads the f16 mirrors. The None (linear) path
            //    dispatches the unchanged `encode_attention` (pc = base+i+1); the tree path
            //    dispatches the slot-indirected `encode_attention_tree` (pc = base+tail_count)
            //    with this node's ancestor draft slots.
            for (i, attn_scalar) in attn_scalars.iter().enumerate() {
                match tree {
                    None => encode_attention(
                        e,
                        kern,
                        &mut keep,
                        &q_buf,
                        &self.cache_k[l],
                        &self.cache_v[l],
                        if self.kv16 || self.kvq8 {
                            None
                        } else {
                            Some((&self.cache_k16[l], &self.cache_v16[l]))
                        },
                        &scores_buf,
                        &ctx_buf,
                        attn_scalar,
                        n_heads,
                        n_kv_heads,
                        head_dim,
                        base_position + i + 1,
                        (i * q_dim * 4) as u64,
                        (i * q_dim * 4) as u64,
                    ),
                    Some(t) => encode_attention_tree(
                        e,
                        kern,
                        &mut keep,
                        &q_buf,
                        &self.cache_k[l],
                        &self.cache_v[l],
                        Some((&self.cache_k16[l], &self.cache_v16[l])),
                        &scores_buf,
                        &ctx_buf,
                        attn_scalar,
                        n_heads,
                        n_kv_heads,
                        head_dim,
                        t.base + t.tail_slots[i].len(),
                        (i * q_dim * 4) as u64,
                        (i * q_dim * 4) as u64,
                        tree_base_buf.as_ref().expect("tree base buffer present"),
                        &tree_tail_bufs[i],
                    ),
                }
            }
            // 7. O projection (batched), 8. attention residual (batched)
            encode_resident_matmul_f32(
                e, kern, &mut keep, &ctx_buf, &w[3], &o_buf, &o_gemv, q_dim, hidden, k,
            );
            encode_binary(
                e,
                &kern.residual_add_pipeline,
                cur,
                &o_buf,
                &mid,
                &resid_n,
                k * hidden,
            );
            // --- FFN block (all batched / elementwise) ---
            encode_rms_norm_batch(kern, e, &mid, &ffn_norm_bufs[l], &norm_buf, &rms_scalar, k);
            encode_resident_matmul_f32(
                e,
                kern,
                &mut keep,
                &norm_buf,
                &w[4],
                &gate_buf,
                &gateup_gemv,
                hidden,
                ffn_dim,
                k,
            );
            encode_resident_matmul_f32(
                e,
                kern,
                &mut keep,
                &norm_buf,
                &w[5],
                &up_buf,
                &gateup_gemv,
                hidden,
                ffn_dim,
                k,
            );
            encode_binary(
                e,
                &kern.silu_mul_pipeline,
                &gate_buf,
                &up_buf,
                &silu_buf,
                &silu_n,
                k * ffn_dim,
            );
            encode_resident_matmul_f32(
                e, kern, &mut keep, &silu_buf, &w[6], &down_buf, &down_gemv, ffn_dim, hidden, k,
            );
            encode_binary(
                e,
                &kern.residual_add_pipeline,
                &mid,
                &down_buf,
                nxt,
                &resid_n,
                k * hidden,
            );
            from_a = !from_a;
        }
        let final_buf = if from_a { &act_a } else { &act_b };
        // ---- Final stage: norm -> output GEMV -> per-row argmax -------------------------
        encode_rms_norm_batch(
            kern,
            e,
            final_buf,
            &final_norm_buf,
            &fnorm_buf,
            &rms_scalar,
            k,
        );
        encode_resident_matmul_f32(
            e,
            kern,
            &mut keep,
            &fnorm_buf,
            &ow_buf,
            &logits_buf,
            &out_gemv,
            hidden,
            vocab,
            k,
        );
        for i in 0..k {
            e.set_compute_pipeline_state(&kern.argmax_f32_greedy_pipeline);
            e.set_buffer(0, Some(&logits_buf), (i * vocab * 4) as u64);
            e.set_buffer(1, Some(&pred_buf), (i * 4) as u64);
            e.set_buffer(2, Some(&argmax_count), 0);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 1024,
                    height: 1,
                    depth: 1,
                },
            );
        }
        e.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        // Note: `filled` is intentionally NOT advanced — the host accept loop sets it.
        let preds: Vec<u32> = (0..k)
            .map(|i| unsafe { *(pred_buf.contents() as *const u32).add(i) })
            .collect();
        let logits_out = if read_logits {
            let mut out = vec![0.0f32; k * vocab];
            read_buffer_f32(&logits_buf, &mut out);
            out
        } else {
            Vec::new()
        };
        Some((preds, logits_out))
    }

    /// WIN2METAL Phase 4 — TREE speculative verify. Batched forward over the `n` BFS-ordered
    /// nodes of a draft tree: each node attends `prefix [0, base_position)` ∪ its ancestor
    /// draft slots (the rest of the pass — RoPE / norms / GEMV / K/V scatter / argmax — is
    /// reused unchanged from the linear `verify_batch`). Returns one greedy argmax per node
    /// (`predicted[i]` = the target's next-token after node `i`), or `None` on any
    /// unsupported config (caller falls back, lossless).
    ///
    /// A LINEAR tree drives the slot indirection to the identity, so this is byte-identical
    /// to `verify_batch` (proven by `metal_tree_verify_bit_identical`).
    ///
    /// - `embeddings`: `n*hidden`, BFS node order (already looked up).
    /// - `cos_all`/`sin_all`: per-NODE RoPE tables at position `base_position + depth[i]`.
    /// - `node_kvslot[i]` must equal `base_position + i` (the scatter target, BFS order).
    /// - `(ancestor_bits, words)` is `TokenTree::ancestor_bitset()`.
    #[allow(clippy::too_many_arguments)]
    pub fn verify_batch_tree(
        &mut self,
        embeddings: &[f32],
        cos_all: &[f32],
        sin_all: &[f32],
        layers: &[ResidentLayerWeights],
        logits: &LogitsStage,
        node_kvslot: &[i32],
        ancestor_bits: &[u32],
        words: usize,
        base_position: usize,
        n: usize,
        scale: f32,
    ) -> Option<Vec<u32>> {
        let tree = self.build_tree_attn(node_kvslot, ancestor_bits, words, base_position, n)?;
        self.verify_batch_inner(
            embeddings,
            cos_all,
            sin_all,
            layers,
            logits,
            base_position,
            n,
            scale,
            false,
            Some(&tree),
        )
        .map(|(preds, _)| preds)
    }

    /// `verify_batch_tree` that also reads back the `n * vocab` pre-argmax logits (the gate
    /// compares logits by exact `to_bits`). Test-only.
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    fn verify_batch_tree_logits(
        &mut self,
        embeddings: &[f32],
        cos_all: &[f32],
        sin_all: &[f32],
        layers: &[ResidentLayerWeights],
        logits: &LogitsStage,
        node_kvslot: &[i32],
        ancestor_bits: &[u32],
        words: usize,
        base_position: usize,
        n: usize,
        scale: f32,
    ) -> Option<(Vec<u32>, Vec<f32>)> {
        let tree = self.build_tree_attn(node_kvslot, ancestor_bits, words, base_position, n)?;
        self.verify_batch_inner(
            embeddings,
            cos_all,
            sin_all,
            layers,
            logits,
            base_position,
            n,
            scale,
            true,
            Some(&tree),
        )
    }

    /// Build the per-node `TreeAttn` descriptor from the ancestor bitset. For node `i`, scan
    /// bits `0..n`; a set bit `j` (an ancestor-or-self) contributes cache slot
    /// `base_position + j`, collected in increasing `j` so the kernel's split-K boundaries
    /// match the linear path. Validates the shared invariants; returns `None` on any mismatch.
    fn build_tree_attn(
        &self,
        node_kvslot: &[i32],
        ancestor_bits: &[u32],
        words: usize,
        base_position: usize,
        n: usize,
    ) -> Option<TreeAttn> {
        if n == 0 || words != n.div_ceil(32) || ancestor_bits.len() != n * words {
            return None;
        }
        if node_kvslot.len() != n {
            return None;
        }
        // Scatter target is reused unchanged: node i -> slot base+i (BFS order).
        for (i, &slot) in node_kvslot.iter().enumerate() {
            if slot != (base_position + i) as i32 {
                return None;
            }
        }
        let mut tail_slots: Vec<Vec<u32>> = Vec::with_capacity(n);
        for i in 0..n {
            let mut slots: Vec<u32> = Vec::new();
            for j in 0..n {
                let word = ancestor_bits[i * words + j / 32];
                if (word >> (j % 32)) & 1 == 1 {
                    slots.push((base_position + j) as u32);
                }
            }
            // A node must at least attend itself (bit i set); a malformed bitset is unsupported.
            if slots.is_empty() {
                return None;
            }
            tail_slots.push(slots);
        }
        Some(TreeAttn {
            base: base_position,
            tail_slots,
        })
    }

    /// WIN2METAL Phase 4 — compact the accepted tree path's K/V into the contiguous slots
    /// `[base, base + path.len())`, so subsequent linear decode/attention reads it as an
    /// ordinary history. `path` is `TokenTree::path_to(leaf)` (root-first BFS node indices,
    /// `path[r] >= r`). For each rank `r` with `path[r] != r`, copies the `head_dim` row of
    /// slot `base + path[r]` into slot `base + r` for EVERY layer and kv_head, in BOTH the
    /// f32 cache and the f16 mirrors (subsequent decode reads both). Exploits unified memory:
    /// a direct `contents()` memcpy, no device round-trip. A linear path `[0..L-1]` is a
    /// no-op (the byte-identity anchor — a linear tree leaves the cache exactly as a linear
    /// decode would).
    pub fn compact_tree_kv_path(&mut self, path: &[usize], base: usize) -> Result<(), String> {
        let head_dim = self.head_dim;
        let max_positions = self.max_positions;
        let n_kv = self.n_kv_heads;
        let row = head_dim; // elements per (kv_head, slot) row
        for (r, &src_node) in path.iter().enumerate() {
            if src_node == r {
                continue; // already in place (incl. every rank of a linear path)
            }
            // CUDA invariant: path[r] >= r, so the source slot is never an earlier write's
            // destination — the in-place gather is order-independent.
            let dst_slot = base + r;
            let src_slot = base + src_node;
            if dst_slot >= max_positions || src_slot >= max_positions {
                return Err(format!(
                    "compact_tree_kv_path: slot out of range (src {src_slot}, dst {dst_slot}, \
                     max_positions {max_positions})"
                ));
            }
            for l in 0..self.n_layers {
                if self.kvq8 {
                    let row_bytes = (head_dim / 32) * 34;
                    unsafe {
                        let kp = self.cache_k[l].contents() as *mut u8;
                        let vp = self.cache_v[l].contents() as *mut u8;
                        for h in 0..n_kv {
                            let src_off = (h * max_positions + src_slot) * row_bytes;
                            let dst_off = (h * max_positions + dst_slot) * row_bytes;
                            std::ptr::copy_nonoverlapping(
                                kp.add(src_off),
                                kp.add(dst_off),
                                row_bytes,
                            );
                            std::ptr::copy_nonoverlapping(
                                vp.add(src_off),
                                vp.add(dst_off),
                                row_bytes,
                            );
                        }
                    }
                } else if self.kv16 {
                    unsafe {
                        let kp = self.cache_k[l].contents() as *mut u16;
                        let vp = self.cache_v[l].contents() as *mut u16;
                        for h in 0..n_kv {
                            let src_off = (h * max_positions + src_slot) * head_dim;
                            let dst_off = (h * max_positions + dst_slot) * head_dim;
                            std::ptr::copy_nonoverlapping(kp.add(src_off), kp.add(dst_off), row);
                            std::ptr::copy_nonoverlapping(vp.add(src_off), vp.add(dst_off), row);
                        }
                    }
                } else {
                    unsafe {
                        let kp = self.cache_k[l].contents() as *mut f32;
                        let vp = self.cache_v[l].contents() as *mut f32;
                        for h in 0..n_kv {
                            let src_off = (h * max_positions + src_slot) * head_dim;
                            let dst_off = (h * max_positions + dst_slot) * head_dim;
                            std::ptr::copy_nonoverlapping(kp.add(src_off), kp.add(dst_off), row);
                            std::ptr::copy_nonoverlapping(vp.add(src_off), vp.add(dst_off), row);
                        }
                    }
                }
                // f16 mirrors (empty in kv16-primary mode, where the primary caches are half).
                if !self.cache_k16.is_empty() {
                    unsafe {
                        let kp = self.cache_k16[l].contents() as *mut u16;
                        let vp = self.cache_v16[l].contents() as *mut u16;
                        for h in 0..n_kv {
                            let src_off = (h * max_positions + src_slot) * head_dim;
                            let dst_off = (h * max_positions + dst_slot) * head_dim;
                            std::ptr::copy_nonoverlapping(kp.add(src_off), kp.add(dst_off), row);
                            std::ptr::copy_nonoverlapping(vp.add(src_off), vp.add(dst_off), row);
                        }
                    }
                }
            }
        }
        Ok(())
    }

    /// Release a stale pre-committed token graph: it sits on the serial queue gated behind
    /// its event, so signal it and let it run once against the old buffers (its outputs go
    /// to scratch that the next real token overwrites). Skipping this would deadlock the
    /// queue. Happens at most once per KV growth or sequence restart.
    fn release_stale(&mut self, stale: PreparedToken) {
        // A fast-path pending graph may already be signaled (pre-released); the shared
        // event is monotonic, so only raise it when it is actually still gated.
        if self.gate_event.signaled_value() < stale.event_value {
            self.gate_event.set_signaled_value(stale.event_value);
        }
        stale.cb.wait_until_completed();
    }

    /// Seed `seed_positions` history slots of layer `layer` from contiguous
    /// `[kv_head][seed_positions][head_dim]` (already-roped) K and (raw) V — e.g. the prompt's
    /// K/V copied out of a CPU KV cache after a batched prefill, so resident decode can take
    /// over with the history already on the GPU. Returns false on dimension mismatch.
    pub fn seed_layer(
        &mut self,
        layer: usize,
        keys: &[f32],
        values: &[f32],
        seed_positions: usize,
    ) -> bool {
        if layer >= self.n_layers
            || seed_positions > self.max_positions
            || keys.len() != self.n_kv_heads * seed_positions * self.head_dim
            || values.len() != keys.len()
        {
            return false;
        }
        Self::seed_into(
            &self.cache_k[layer],
            keys,
            self.n_kv_heads,
            self.max_positions,
            self.head_dim,
            seed_positions,
            if self.kvq8 {
                ResidentKvFormat::Q8
            } else if self.kv16 {
                ResidentKvFormat::F16
            } else {
                ResidentKvFormat::F32
            },
        );
        Self::seed_into(
            &self.cache_v[layer],
            values,
            self.n_kv_heads,
            self.max_positions,
            self.head_dim,
            seed_positions,
            if self.kvq8 {
                ResidentKvFormat::Q8
            } else if self.kv16 {
                ResidentKvFormat::F16
            } else {
                ResidentKvFormat::F32
            },
        );
        if !self.kv16 && !self.kvq8 {
            Self::seed_into(
                &self.cache_k16[layer],
                keys,
                self.n_kv_heads,
                self.max_positions,
                self.head_dim,
                seed_positions,
                ResidentKvFormat::F16,
            );
            Self::seed_into(
                &self.cache_v16[layer],
                values,
                self.n_kv_heads,
                self.max_positions,
                self.head_dim,
                seed_positions,
                ResidentKvFormat::F16,
            );
        }
        true
    }

    /// Read layer `layer`'s first `positions` cached K and V back out as contiguous
    /// `[kv_head][positions][head_dim]` f32 — the exact inverse of [`seed_layer`](Self::seed_layer),
    /// and the Metal twin of the CUDA engine's `read_kv_layer`.
    ///
    /// This exists so a CPU fallback mid-sequence can recover the history the resident engine
    /// produced. Without it the CPU KV cache is simply empty for every GPU-produced position,
    /// and both the fallback step and any later GPU reseed silently run over a zeroed prompt.
    /// Metal buffers are shared storage, so this is a strided memcpy over unified memory — no
    /// device transfer, and it touches no kernel.
    ///
    /// Returns `None` on a dimension mismatch. Caller must ensure prior GPU work has completed.
    pub fn read_kv_layer(&self, layer: usize, positions: usize) -> Option<(Vec<f32>, Vec<f32>)> {
        if layer >= self.n_layers || positions > self.max_positions {
            return None;
        }
        Some((
            Self::read_from(
                &self.cache_k[layer],
                self.n_kv_heads,
                self.max_positions,
                self.head_dim,
                positions,
                if self.kvq8 {
                    ResidentKvFormat::Q8
                } else if self.kv16 {
                    ResidentKvFormat::F16
                } else {
                    ResidentKvFormat::F32
                },
            ),
            Self::read_from(
                &self.cache_v[layer],
                self.n_kv_heads,
                self.max_positions,
                self.head_dim,
                positions,
                if self.kvq8 {
                    ResidentKvFormat::Q8
                } else if self.kv16 {
                    ResidentKvFormat::F16
                } else {
                    ResidentKvFormat::F32
                },
            ),
        ))
    }

    /// Gather a `[kv_head][max_positions][head_dim]` cache buffer's first `positions` slots
    /// into contiguous `[kv_head][positions][head_dim]` f32. Inverse of [`Self::seed_into`].
    fn read_from(
        buf: &Buffer,
        n_kv_heads: usize,
        max_positions: usize,
        head_dim: usize,
        positions: usize,
        format: ResidentKvFormat,
    ) -> Vec<f32> {
        let run = positions * head_dim;
        let mut out = vec![0.0f32; n_kv_heads * run];
        // SAFETY: shared-storage buffer of n_kv_heads*max_positions*head_dim elements (f32 or
        // f16); each head's `run` values are read from a disjoint slot well within that
        // capacity (`positions <= max_positions` checked by the caller).
        unsafe {
            if format == ResidentKvFormat::Q8 {
                let src = buf.contents() as *const u8;
                let blocks = head_dim / 32;
                let row_bytes = blocks * 34;
                for h in 0..n_kv_heads {
                    for p in 0..positions {
                        let row = src.add((h * max_positions + p) * row_bytes);
                        let dst = (h * positions + p) * head_dim;
                        for b in 0..blocks {
                            let block = row.add(b * 34);
                            let d = f16_bits_to_f32(u16::from_le_bytes([*block, *block.add(1)]));
                            let qs = block.add(2) as *const i8;
                            for i in 0..32 {
                                out[dst + b * 32 + i] = d * *qs.add(i) as f32;
                            }
                        }
                    }
                }
            } else if format == ResidentKvFormat::F16 {
                let src = buf.contents() as *const u16;
                for h in 0..n_kv_heads {
                    let s = h * max_positions * head_dim;
                    let d = h * run;
                    for i in 0..run {
                        out[d + i] = f16_bits_to_f32(*src.add(s + i));
                    }
                }
            } else {
                let src = buf.contents() as *const f32;
                for h in 0..n_kv_heads {
                    let s = h * max_positions * head_dim;
                    let d = h * run;
                    std::ptr::copy_nonoverlapping(src.add(s), out[d..d + run].as_mut_ptr(), run);
                }
            }
        }
        out
    }

    /// Scatter contiguous `[kv_head][seed_positions][head_dim]` source data into a persistent
    /// `[kv_head][max_positions][head_dim]` cache buffer (the per-head position stride differs).
    fn seed_into(
        buf: &Buffer,
        src: &[f32],
        n_kv_heads: usize,
        max_positions: usize,
        head_dim: usize,
        seed_positions: usize,
        format: ResidentKvFormat,
    ) {
        let run = seed_positions * head_dim;
        // SAFETY: shared-storage buffer of n_kv_heads*max_positions*head_dim elements (f32 or
        // f16); each head's `run` values land at a disjoint slot well within that capacity.
        unsafe {
            if format == ResidentKvFormat::Q8 {
                let dst = buf.contents() as *mut u8;
                let blocks = head_dim / 32;
                let row_bytes = blocks * 34;
                for h in 0..n_kv_heads {
                    for p in 0..seed_positions {
                        let src_row = (h * seed_positions + p) * head_dim;
                        let dst_row = dst.add((h * max_positions + p) * row_bytes);
                        for b in 0..blocks {
                            let input = &src[src_row + b * 32..src_row + (b + 1) * 32];
                            let max_abs = input.iter().fold(0.0f32, |m, v| m.max(v.abs()));
                            let unrounded = max_abs / 127.0;
                            let stored = f32_to_f16_bits(unrounded);
                            let block = dst_row.add(b * 34);
                            std::ptr::copy_nonoverlapping(stored.to_le_bytes().as_ptr(), block, 2);
                            let inv = if unrounded == 0.0 {
                                0.0
                            } else {
                                1.0 / unrounded
                            };
                            for (i, &v) in input.iter().enumerate() {
                                let q = (v * inv).round().clamp(-127.0, 127.0) as i8;
                                *block.add(2 + i) = q as u8;
                            }
                        }
                    }
                }
            } else if format == ResidentKvFormat::F16 {
                let dst = buf.contents() as *mut u16;
                for h in 0..n_kv_heads {
                    let s = h * seed_positions * head_dim;
                    let d = h * max_positions * head_dim;
                    for i in 0..run {
                        *dst.add(d + i) = f32_to_f16_bits(src[s + i]);
                    }
                }
            } else {
                let dst = buf.contents() as *mut f32;
                for h in 0..n_kv_heads {
                    let s = h * seed_positions * head_dim;
                    let d = h * max_positions * head_dim;
                    std::ptr::copy_nonoverlapping(src[s..s + run].as_ptr(), dst.add(d), run);
                }
            }
        }
    }

    /// Read back layer `layer`'s first `position_count` cached K positions as a contiguous
    /// `[kv_head][position_count][head_dim]` buffer (test-only; used to build a reference cache
    /// for the persistent-vs-full-upload parity check).
    #[cfg(test)]
    fn cache_k_contiguous(&self, layer: usize, position_count: usize) -> Vec<f32> {
        self.read_cache(&self.cache_k[layer], position_count)
    }

    #[cfg(test)]
    fn cache_v_contiguous(&self, layer: usize, position_count: usize) -> Vec<f32> {
        self.read_cache(&self.cache_v[layer], position_count)
    }

    #[cfg(test)]
    fn read_cache(&self, buf: &Buffer, position_count: usize) -> Vec<f32> {
        Self::read_from(
            buf,
            self.n_kv_heads,
            self.max_positions,
            self.head_dim,
            position_count,
            if self.kvq8 {
                ResidentKvFormat::Q8
            } else if self.kv16 {
                ResidentKvFormat::F16
            } else {
                ResidentKvFormat::F32
            },
        )
    }

    /// **KV-equivalence capture hook (campaign gates G1 / G6).**
    ///
    /// Snapshot every layer's first `positions` cached K and V rows into the
    /// canonical `[kv_head][position][head_dim]` layout of
    /// [`crate::kv_equivalence::KvSnapshot`], with the per-head `max_positions`
    /// stride removed — so a session sized for 2 600 positions and one sized for
    /// 600 compare cleanly at the 600 they share.
    ///
    /// This is the direct invariant a batched prefill is held to: `n` batched rows
    /// must leave the cache in the same state as `n` token-by-token forwards. Tier A
    /// asserts bit equality on the result
    /// ([`crate::kv_equivalence::KvEquivalence::assert_bit_identical`]); Tier B
    /// asserts a published bound plus the per-position outlier test
    /// ([`crate::kv_equivalence::KvEquivalence::meets_bound`]).
    ///
    /// Test-only: it maps the shared-storage cache buffers on the CPU and widens
    /// f16/Q8 KV to f32, which no production path wants to pay for.
    #[cfg(test)]
    pub(crate) fn kv_snapshot(&self, positions: usize) -> crate::kv_equivalence::KvSnapshot {
        assert!(
            positions <= self.max_positions,
            "kv_snapshot: {positions} positions requested, session holds {}",
            self.max_positions
        );
        let geometry = crate::kv_equivalence::KvGeometry {
            n_layers: self.n_layers,
            n_kv_heads: self.n_kv_heads,
            head_dim: self.head_dim,
            positions,
        };
        let layers: Vec<(Vec<f32>, Vec<f32>)> = (0..self.n_layers)
            .map(|l| {
                (
                    self.cache_k_contiguous(l, positions),
                    self.cache_v_contiguous(l, positions),
                )
            })
            .collect();
        crate::kv_equivalence::KvSnapshot::from_layers(geometry, layers)
            .expect("kv_snapshot builds from this session's own geometry")
    }
}

#[cfg(target_os = "macos")]
impl Drop for ResidentDecodeState {
    fn drop(&mut self) {
        // A pre-committed pending graph left gated on the queue would block every future
        // commit on the shared serial queue; release it before the session goes away.
        if let Some(stale) = self.pending.take() {
            self.release_stale(stale);
        }
        if let Some(r) = self.retiring.take() {
            r.cb.wait_until_completed();
        }
    }
}

/// Gate for the gemma4 GPU-resident decode path (off by default until the full
/// graph is assembled and end-to-end parity is proven).
#[cfg(target_os = "macos")]
pub fn gemma4_gpu_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("CAMELID_GEMMA4_GPU")
            .is_ok_and(|v| v == "1" || v.eq_ignore_ascii_case("true"))
    })
}

/// GPU-resident decode session state for gemma4 — allocation scaffolding. Holds the
/// per-layer KV cache (each sized to that layer's per-type head_dim, and allocated
/// ONLY for layers that own their K/V; the trailing cross-shared layers read an
/// earlier same-type layer's cache, so their slot is `None`), the ping-pong hidden
/// buffers, and the gate/done events. The per-token forward graph is layered on in a
/// later port step; until then most fields are intentionally unread.
#[cfg(target_os = "macos")]
#[allow(dead_code)] // fields consumed by the forward graph (later port step)
pub struct Gemma4ResidentState {
    plan: Vec<crate::model::Gemma4LayerPlan>,
    n_kv_heads: usize,
    hidden: usize,
    eps: f32,
    /// Positions the KV cache is currently allocated for; grown toward `cap` later.
    max_positions: usize,
    /// Hard ceiling on `max_positions` (the model context length).
    cap: usize,
    /// KV positions currently materialized (seeded history + appended tokens).
    filled: usize,
    /// Per layer: `Some` for owning layers, `None` for the shared (read-source) layers.
    cache_k: Vec<Option<Buffer>>,
    cache_v: Vec<Option<Buffer>>,
    buf_a: Buffer,
    buf_b: Buffer,
    mid: Buffer,
    gate_event: metal::SharedEvent,
    done_event: metal::SharedEvent,
    event_counter: u64,
}

#[cfg(target_os = "macos")]
impl Gemma4ResidentState {
    /// Allocate the resident KV cache + scratch for a gemma4 decode session.
    /// `max_positions` is the initial KV capacity; `cap` is the hard ceiling
    /// (context length). Returns None if Metal is unavailable or shapes are invalid.
    pub fn new(
        plan: Vec<crate::model::Gemma4LayerPlan>,
        n_kv_heads: usize,
        hidden: usize,
        eps: f32,
        max_positions: usize,
        cap: usize,
    ) -> Option<Self> {
        if plan.is_empty()
            || n_kv_heads == 0
            || hidden == 0
            || max_positions == 0
            || cap < max_positions
        {
            return None;
        }
        let k = metal_linear_kernel()?;
        let fbuf = |n: usize| {
            k.device
                .new_buffer((n * 4) as u64, MTLResourceOptions::StorageModeShared)
        };
        // Owning layers get a cache sized to their per-type head_dim; shared layers
        // hold None and read their `kv_source_layer`'s cache at attention time.
        let kv_buf = |p: &crate::model::Gemma4LayerPlan| {
            p.owns_kv
                .then(|| fbuf(n_kv_heads * max_positions * p.head_dim))
        };
        let cache_k: Vec<Option<Buffer>> = plan.iter().map(kv_buf).collect();
        let cache_v: Vec<Option<Buffer>> = plan.iter().map(kv_buf).collect();
        Some(Self {
            plan,
            n_kv_heads,
            hidden,
            eps,
            max_positions,
            cap,
            filled: 0,
            cache_k,
            cache_v,
            buf_a: fbuf(hidden),
            buf_b: fbuf(hidden),
            mid: fbuf(hidden),
            gate_event: k.device.new_shared_event(),
            done_event: k.device.new_shared_event(),
            event_counter: 0,
        })
    }

    /// Byte length of layer `l`'s K-cache buffer, or None for a shared layer.
    #[cfg(test)]
    fn cache_k_len(&self, l: usize) -> Option<u64> {
        self.cache_k[l].as_ref().map(|b| b.length())
    }
}

