    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gelu_mul_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        let n = 257usize; // non-multiple of the execution width
                          // Include large-magnitude gate values (±300): the x^3 term drives tanh's
                          // argument to ~1e6, where an unclamped MSL tanh overflows to NaN. The kernel
                          // clamps the tanh arg; this must still match the saturating CPU gelu.
        let gate: Vec<f32> = (0..n)
            .map(|i| ((i as f32 % 13.0) - 6.0) * if i % 7 == 0 { 50.0 } else { 0.4 })
            .collect();
        let up: Vec<f32> = (0..n).map(|i| ((i as f32 % 5.0) - 2.0) * 0.5).collect();
        let mut expected = vec![0.0f32; n];
        crate::inference::gemma4::geglu_into(&gate, &up, &mut expected);
        let got = try_gelu_mul_f32(&gate, &up).expect("metal gelu_mul");
        for (a, b) in got.iter().zip(&expected) {
            assert!(a.is_finite(), "gpu gelu produced non-finite {a}");
            assert!((a - b).abs() < 1.0e-2, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_soft_cap_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        let cap = 30.0f32;
        let n = 263usize;
        // Include |logit| up to ~2000 (v/cap ~ 66): exp(2*v/cap) overflows f32, so an
        // unclamped tanh would NaN. The kernel clamps; result must still saturate to ±cap.
        let input: Vec<f32> = (0..n).map(|i| ((i as f32 % 91.0) - 45.0) * 45.0).collect();
        let mut expected = input.clone();
        crate::inference::gemma4::soft_cap_in_place(&mut expected, cap);
        let got = try_soft_cap_f32(&input, cap).expect("metal soft_cap");
        for (a, b) in got.iter().zip(&expected) {
            assert!(a.is_finite(), "gpu soft_cap produced non-finite {a}");
            assert!((a - b).abs() < 1.0e-2, "{a} != {b}");
        }
        // Disabled cap is a passthrough.
        let passthrough = try_soft_cap_f32(&input, 0.0).expect("metal soft_cap passthrough");
        assert_eq!(passthrough, input);
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_rms_norm_per_head_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        let eps = 1.0e-6f32;
        // Reference: standard RMSNorm applied independently per head_dim chunk.
        fn cpu_per_head(
            input: &[f32],
            weight: Option<&[f32]>,
            head_count: usize,
            head_dim: usize,
            eps: f32,
        ) -> Vec<f32> {
            let mut out = vec![0.0f32; input.len()];
            for h in 0..head_count {
                let base = h * head_dim;
                let mss: f32 = input[base..base + head_dim]
                    .iter()
                    .map(|v| v * v)
                    .sum::<f32>()
                    / head_dim as f32;
                let inv = (mss + eps).powf(-0.5);
                for d in 0..head_dim {
                    let mut v = input[base + d] * inv;
                    if let Some(w) = weight {
                        v *= w[d];
                    }
                    out[base + d] = v;
                }
            }
            out
        }
        // Exercise both gemma layer-type shapes: sliding (8x256) and global (8x512).
        for (head_count, head_dim) in [(8usize, 256usize), (8, 512)] {
            let n = head_count * head_dim;
            let input: Vec<f32> = (0..n).map(|i| ((i as f32 % 17.0) - 8.0) * 0.3).collect();
            let weight: Vec<f32> = (0..head_dim)
                .map(|d| 0.5 + (d as f32 % 7.0) * 0.1)
                .collect();
            // Weighted (QK-norm).
            let want_w = cpu_per_head(&input, Some(&weight), head_count, head_dim, eps);
            let got_w = try_rms_norm_per_head_f32(&input, Some(&weight), head_count, head_dim, eps)
                .expect("metal per-head rms_norm (weighted)");
            for (a, b) in got_w.iter().zip(&want_w) {
                assert!(
                    (a - b).abs() < 1.0e-3,
                    "weighted {a} != {b} ({head_count}x{head_dim})"
                );
            }
            // Weightless (V-norm).
            let want_n = cpu_per_head(&input, None, head_count, head_dim, eps);
            let got_n = try_rms_norm_per_head_f32(&input, None, head_count, head_dim, eps)
                .expect("metal per-head rms_norm (weightless)");
            for (a, b) in got_n.iter().zip(&want_n) {
                assert!(
                    (a - b).abs() < 1.0e-3,
                    "weightless {a} != {b} ({head_count}x{head_dim})"
                );
            }
        }
    }

    // Gemma's sliding-window attention needs no dedicated kernel: attending to the
    // window [lo..=pos] is the existing decode kernel with kv_base_offset shifted by
    // lo*position_stride and position_count = window length. This locks that property
    // in so a future attention-kernel refactor can't silently break gemma windowing.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_sliding_window_attention_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        // CPU reference: per head, softmax over the contiguous window [lo..lo+win)
        // of a [n_kv_heads][total][head_dim] cache, then the prob-weighted V sum.
        #[allow(clippy::too_many_arguments)]
        fn cpu_windowed(
            query: &[f32],
            keys: &[f32],
            values: &[f32],
            n_heads: usize,
            n_kv_heads: usize,
            head_dim: usize,
            total: usize,
            lo: usize,
            win: usize,
            scale: f32,
        ) -> Vec<f32> {
            let group = n_heads / n_kv_heads;
            let kv_head_stride = total * head_dim;
            let mut out = vec![0.0f32; n_heads * head_dim];
            for h in 0..n_heads {
                let kvh = h / group;
                let q = &query[h * head_dim..(h + 1) * head_dim];
                let mut scores = vec![0.0f32; win];
                let mut m = f32::NEG_INFINITY;
                for (i, s) in scores.iter_mut().enumerate() {
                    let p = lo + i;
                    let k = &keys[kvh * kv_head_stride + p * head_dim..][..head_dim];
                    *s = scale * q.iter().zip(k).map(|(a, b)| a * b).sum::<f32>();
                    m = m.max(*s);
                }
                let mut den = 0.0f32;
                for s in &mut scores {
                    *s = (*s - m).exp();
                    den += *s;
                }
                let o = &mut out[h * head_dim..(h + 1) * head_dim];
                for (i, &sc) in scores.iter().enumerate() {
                    let p = lo + i;
                    let v = &values[kvh * kv_head_stride + p * head_dim..][..head_dim];
                    let w = sc / den;
                    for d in 0..head_dim {
                        o[d] += w * v[d];
                    }
                }
            }
            out
        }

        let n_heads = 8usize;
        let n_kv_heads = 2usize;
        let total = 10usize; // positions 0..9 in the cache
                             // (head_dim, lo, win): a true sliding window and a full range (global, lo=0).
        for (head_dim, lo, win) in [(256usize, 3usize, 7usize), (512, 0, total)] {
            let kv_head_stride = total * head_dim;
            let query: Vec<f32> = (0..n_heads * head_dim)
                .map(|i| ((i as f32 % 23.0) - 11.0) * 0.05)
                .collect();
            let keys: Vec<f32> = (0..n_kv_heads * kv_head_stride)
                .map(|i| ((i as f32 % 31.0) - 15.0) * 0.03)
                .collect();
            let values: Vec<f32> = (0..n_kv_heads * kv_head_stride)
                .map(|i| ((i as f32 % 19.0) - 9.0) * 0.04)
                .collect();
            let scale = 1.0 / (head_dim as f32).sqrt();
            let want = cpu_windowed(
                &query, &keys, &values, n_heads, n_kv_heads, head_dim, total, lo, win, scale,
            );
            // Window = shift base by lo*position_stride, count = win.
            let got = try_attention_decode_strided_f32(
                &query,
                &keys,
                &values,
                n_heads,
                n_kv_heads,
                head_dim,
                win, // position_count = window length
                scale,
                head_dim,       // position_stride
                kv_head_stride, // kv_head_stride
                lo * head_dim,  // kv_base_offset = lo * position_stride
            )
            .expect("metal windowed attention");
            for (a, b) in got.iter().zip(&want) {
                assert!(
                    (a - b).abs() < 1.0e-3,
                    "windowed {a} != {b} (hd={head_dim} lo={lo})"
                );
            }
        }
    }

    // Gemma4ResidentState allocates a per-layer KV cache sized to each layer's
    // per-type head_dim, and only for layers that own their K/V — the trailing
    // cross-shared layers hold None and read an earlier layer's cache.
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma4_resident_state_allocates_per_layer_kv() {
        if !detect_metal_device().available {
            return;
        }
        use crate::model::Gemma4LayerPlan;
        let mk = |sliding, head_dim, owns_kv, src| Gemma4LayerPlan {
            sliding,
            head_dim,
            q_dim: 2 * head_dim,
            kv_heads: 1,
            kv_dim: head_dim,
            theta: 1.0,
            window: if sliding { Some(16) } else { None },
            owns_kv,
            kv_source_layer: src,
        };
        // 2 owning (sliding hd=4, global hd=8), then 2 shared reading them.
        let plan = vec![
            mk(true, 4, true, 0),
            mk(false, 8, true, 1),
            mk(true, 4, false, 0),
            mk(false, 8, false, 1),
        ];
        let n_kv_heads = 1usize;
        let hidden = 16usize;
        let max_positions = 32usize;
        let st = Gemma4ResidentState::new(plan, n_kv_heads, hidden, 1.0e-6, max_positions, 64)
            .expect("resident state");
        let bytes = |head_dim: usize| (n_kv_heads * max_positions * head_dim * 4) as u64;
        assert_eq!(st.cache_k_len(0), Some(bytes(4))); // owning sliding
        assert_eq!(st.cache_k_len(1), Some(bytes(8))); // owning global
        assert_eq!(st.cache_k_len(2), None); // shared sliding
        assert_eq!(st.cache_k_len(3), None); // shared global
                                             // Bad shapes are rejected.
        assert!(Gemma4ResidentState::new(vec![], 1, 16, 1.0e-6, 8, 16).is_none());
    }

    // A DENSE (no-PLE) resident model must apply layer_output_scale standalone at
    // the end of each layer (the reference multiplies it unconditionally; E-series
    // applies it inside the PLE encode). The layer here is also V-LESS, so this
    // covers the full 12B-class global-layer path through forward_token: V from
    // the raw K projection + standalone output scale + head.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_dense_layer_scale_and_vless_forward_token() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 64usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 32usize;
        let ffn_dim = 96usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let vocab = 96usize;
        let max_positions = 8usize;
        let eps = 1.0e-6f32;
        let softcap = 30.0f32;
        let attn_scale = 1.0f32;
        let layer_scale = 0.37f32;

        let mw = |rows: usize, in_dim: usize, seed: usize| -> Vec<u8> {
            let mut wire = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                for blk in quantize_q8_0_blocks(&row).iter() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for &q in blk.quants.iter() {
                        wire.push(q as u8);
                    }
                }
            }
            wire
        };
        let build_layer = || {
            let an: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
            let pa: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
            let fnw: Vec<f32> = (0..hidden)
                .map(|i| 0.85 + (i as f32 % 4.0) * 0.04)
                .collect();
            let pf: Vec<f32> = (0..hidden)
                .map(|i| 0.95 + (i as f32 % 6.0) * 0.02)
                .collect();
            let qn: Vec<f32> = (0..head_dim)
                .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
                .collect();
            let kn: Vec<f32> = (0..head_dim)
                .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
                .collect();
            Gemma4ResidentLayer::from_wire(
                GemmaWireFmt::Q8_0,
                an,
                qn,
                kn,
                pa,
                fnw,
                pf,
                &mw(q_dim, hidden, 1),
                &mw(kv_dim, hidden, 5),
                None, // V-less
                &mw(hidden, q_dim, 13),
                &mw(ffn_dim, hidden, 17),
                &mw(ffn_dim, hidden, 21),
                &mw(hidden, ffn_dim, 25),
                n_heads,
                n_kv_heads,
                head_dim,
                ffn_dim,
                eps,
            )
            .expect("layer")
        };
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();
        let h0: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let output_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.88 + (i as f32 % 5.0) * 0.03)
            .collect();
        let embd_wire = mw(vocab, hidden, 99);
        let cache_len = n_kv_heads * max_positions * head_dim;
        let zeros = vec![0.0f32; cache_len];

        // Expected: validated layer wrapper, CPU scale, validated head wrapper.
        let h1 = try_gemma4_layer(
            &build_layer(),
            &h0,
            &cos_t,
            &sin_t,
            &zeros,
            &zeros,
            max_positions,
            0,
            1,
            0,
            attn_scale,
            true,
        )
        .expect("layer fwd");
        let h1s: Vec<f32> = h1.iter().map(|v| v * layer_scale).collect();
        let want =
            try_gemma4_head(&h1s, &output_norm, &embd_wire, vocab, softcap, eps).expect("head");

        // Got: the resident model with layer_scales = [0.37] and no PLE.
        let model = Gemma4ResidentModel::new(
            vec![build_layer()],
            vec![None],
            vec![layer_scale],
            vec![true],
            vec![0],
            &embd_wire,
            output_norm.clone(),
            hidden,
            vocab,
            softcap,
            eps,
            max_positions,
            attn_scale,
        )
        .expect("model");
        let inputs = vec![Gemma4TokenLayerInput {
            cos_t: cos_t.clone(),
            sin_t: sin_t.clone(),
            pli: Vec::new(),
            window_start: 0,
        }];
        let got = model.forward_token(&h0, &inputs, &[], 0).expect("forward");
        let argmax =
            |v: &[f32]| -> usize { (0..v.len()).max_by(|&a, &b| v[a].total_cmp(&v[b])).unwrap() };
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 2.0e-2, "{a} != {b}");
        }
        assert_eq!(argmax(&got), argmax(&want));
    }

    // The gemma4 GPU GEMV workhorse (f32 activation × 34-byte wire Q8) must match a
    // CPU f32×dequant reference — this is the op the resident decode runs 8x/layer.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_q8_matmul_f32y_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        // Cover both the single-simdgroup case (<=8 blocks) AND realistic gemma sizes
        // (80 = hidden/32, 320 = ffn_dim/32) that exercise the 4-way k-split reduction.
        for blocks_per_row in [5usize, 80, 320] {
            let in_dim = blocks_per_row * 32;
            let rows = 7usize;
            let y: Vec<f32> = (0..in_dim)
                .map(|i| ((i as f32 % 11.0) - 5.0) * 0.1)
                .collect();
            let mut wire = Vec::with_capacity(rows * blocks_per_row * 34);
            let mut want = vec![0.0f32; rows];
            for (r, w) in want.iter_mut().enumerate() {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| (((r * in_dim + i) as f32 % 23.0) - 11.0) * 0.05)
                    .collect();
                let mut acc = 0.0f32;
                for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for (j, &q) in blk.quants.iter().enumerate() {
                        wire.push(q as u8);
                        acc += blk.scale * q as f32 * y[b * 32 + j];
                    }
                }
                *w = acc;
            }
            let got = try_gemma4_q8_matmul_f32y(&y, &wire, rows, blocks_per_row)
                .expect("gemma4 q8 matmul");
            for (a, b) in got.iter().zip(&want) {
                assert!((a - b).abs() < 2.0e-2, "bpr={blocks_per_row} {a} != {b}");
            }
        }
        // Shape guards.
        let blocks_per_row = 5usize;
        let in_dim = blocks_per_row * 32;
        let y: Vec<f32> = (0..in_dim)
            .map(|i| ((i as f32 % 11.0) - 5.0) * 0.1)
            .collect();
        let wire = vec![0u8; 7 * blocks_per_row * 34];
        let rows = 7usize;
        assert!(try_gemma4_q8_matmul_f32y(&y, &wire, 0, blocks_per_row).is_none());
        assert!(
            try_gemma4_q8_matmul_f32y(&y, &wire[..wire.len() - 1], rows, blocks_per_row).is_none()
        );
    }

    // The QAT-row GPU GEMV workhorse (f32 activation × 18-byte wire Q4_0, nibbles
    // unpacked inline) must match the CPU f32×dequant reference — the foundation
    // for running the Q4_0 attention/dense/expert matmuls on the GPU.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_q4_0_matmul_f32y_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::q4_0_wire_block_dequant;
        for blocks_per_row in [5usize, 80, 320] {
            let in_dim = blocks_per_row * 32;
            let rows = 7usize;
            let y: Vec<f32> = (0..in_dim)
                .map(|i| ((i as f32 % 11.0) - 5.0) * 0.1)
                .collect();
            let mut wire = Vec::with_capacity(rows * blocks_per_row * 18);
            let mut want = vec![0.0f32; rows];
            for (r, w) in want.iter_mut().enumerate() {
                let mut acc = 0.0f32;
                for b in 0..blocks_per_row {
                    let scale = (((r + b) as f32 % 7.0) + 1.0) * 0.02;
                    let mut blk = [0u8; 18];
                    blk[0..2].copy_from_slice(&f32_to_f16_bits(scale).to_le_bytes());
                    for (j, slot) in blk[2..].iter_mut().enumerate() {
                        *slot = ((r * 31 + b * 17 + j * 3) % 256) as u8;
                    }
                    let deq = q4_0_wire_block_dequant(&blk);
                    for (i, &d) in deq.iter().enumerate() {
                        acc += d * y[b * 32 + i];
                    }
                    wire.extend_from_slice(&blk);
                }
                *w = acc;
            }
            let got = try_gemma4_q4_0_matmul_f32y(&y, &wire, rows, blocks_per_row)
                .expect("gemma4 q4_0 matmul");
            for (a, b) in got.iter().zip(&want) {
                assert!((a - b).abs() < 2.0e-2, "bpr={blocks_per_row} {a} != {b}");
            }
        }
        // Shape guards.
        let blocks_per_row = 5usize;
        let in_dim = blocks_per_row * 32;
        let y: Vec<f32> = (0..in_dim)
            .map(|i| ((i as f32 % 11.0) - 5.0) * 0.1)
            .collect();
        let wire = vec![0u8; 7 * blocks_per_row * 18];
        let rows = 7usize;
        assert!(try_gemma4_q4_0_matmul_f32y(&y, &wire, 0, blocks_per_row).is_none());
        assert!(
            try_gemma4_q4_0_matmul_f32y(&y, &wire[..wire.len() - 1], rows, blocks_per_row)
                .is_none()
        );
    }

    // Ghost-MoE does not use the resident f32-activation Q4 path above: its
    // established comparator quantizes activations to Q8_0 first. The ordered
    // Metal kernel must reproduce that row dot exactly for multiple prompt
    // rows while sharing one expert-weight upload.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_q4_0_q8_batch_is_bit_exact() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::{q4_0_wire_row_dot, quantize_q8_0_blocks};

        for blocks_per_row in [5usize, 80] {
            let rows = 11usize;
            let inputs: Vec<Vec<crate::tensor::Q8_0Block>> = (0..3)
                .map(|token| {
                    let input: Vec<f32> = (0..blocks_per_row * 32)
                        .map(|i| {
                            ((((i * 17 + token * 13) % 97) as f32) - 48.0)
                                * (0.003 + token as f32 * 0.001)
                        })
                        .collect();
                    quantize_q8_0_blocks(&input)
                })
                .collect();
            let input_refs: Vec<&[crate::tensor::Q8_0Block]> =
                inputs.iter().map(Vec::as_slice).collect();
            let mut wire = Vec::with_capacity(rows * blocks_per_row * 18);
            for row in 0..rows {
                for block in 0..blocks_per_row {
                    let scale = 0.0025 * (1 + (row * 7 + block * 3) % 31) as f32;
                    wire.extend_from_slice(&f32_to_f16_bits(scale).to_le_bytes());
                    for j in 0..16 {
                        wire.push(((row * 43 + block * 19 + j * 11) % 256) as u8);
                    }
                }
            }

            let got = try_gemma4_q4_0_matmul_q8_batch(&input_refs, &wire, rows)
                .expect("ordered Ghost Q4_0 Metal matmul");
            for (token, input) in inputs.iter().enumerate() {
                for row in 0..rows {
                    let row_bytes = blocks_per_row * 18;
                    let expected =
                        q4_0_wire_row_dot(&wire[row * row_bytes..(row + 1) * row_bytes], input);
                    assert_eq!(
                        got[token][row].to_bits(),
                        expected.to_bits(),
                        "token={token} row={row} bpr={blocks_per_row}"
                    );
                }
            }
        }
    }

    // The fused-fast sibling splits complete blocks across a 32-lane SIMD
    // group, then lets lane zero replay every f32 term in increasing block
    // order. Exercise both sides of the lane-stride boundary plus the three
    // Q4 contractions used by the strict Gemma 4 26B common/expert graph.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_q4_0_q8_simd_is_bit_exact_at_edges_and_26b_shapes() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::{q4_0_wire_row_dot, quantize_q8_0_blocks};

        let kernel = metal_linear_kernel().expect("strict Metal kernel library");
        assert!(
            admitted_32_lane_pipeline(kernel.q4_0_q8_ordered_simd_pipeline.as_ref()).is_some(),
            "ordered Q4 SIMD pipeline must satisfy its 32-lane admission contract"
        );

        // (blocks/input width, output rows, tokens, shape label)
        for &(blocks_per_row, rows, tokens, label) in &[
            (1usize, 7usize, 2usize, "edge-1"),
            (31, 7, 2, "edge-31"),
            (32, 7, 2, "edge-32"),
            (33, 7, 2, "edge-33"),
            (88, 7, 2, "edge-88"),
            (128, 7, 2, "edge-128"),
            (256, 7, 2, "global-attention-8192"),
            (88, 1_408, 1, "2816-to-1408"),
            (88, 704, 1, "2816-to-704"),
            (22, 2_816, 1, "704-to-2816"),
        ] {
            let inputs: Vec<Vec<crate::tensor::Q8_0Block>> = (0..tokens)
                .map(|token| {
                    let input: Vec<f32> = (0..blocks_per_row * 32)
                        .map(|i| {
                            ((((i * 17 + token * 13 + blocks_per_row) % 257) as f32) - 128.0)
                                * (0.001_7 + token as f32 * 0.000_3)
                        })
                        .collect();
                    quantize_q8_0_blocks(&input)
                })
                .collect();
            let input_refs: Vec<&[crate::tensor::Q8_0Block]> =
                inputs.iter().map(Vec::as_slice).collect();
            let mut wire = Vec::with_capacity(rows * blocks_per_row * 18);
            for row in 0..rows {
                for block in 0..blocks_per_row {
                    let scale = 0.000_35 * (1 + (row * 7 + block * 3) % 61) as f32;
                    wire.extend_from_slice(&f32_to_f16_bits(scale).to_le_bytes());
                    for j in 0..16 {
                        wire.push(((row * 43 + block * 19 + j * 11 + 5) % 256) as u8);
                    }
                }
            }

            let got = try_gemma4_q4_0_matmul_q8_batch_impl(&input_refs, &wire, rows, true)
                .unwrap_or_else(|| panic!("ordered SIMD Q4 Metal matmul: {label}"));
            let row_bytes = blocks_per_row * 18;
            for (token, input) in inputs.iter().enumerate() {
                for row in 0..rows {
                    let expected =
                        q4_0_wire_row_dot(&wire[row * row_bytes..(row + 1) * row_bytes], input);
                    assert_eq!(
                        got[token][row].to_bits(),
                        expected.to_bits(),
                        "shape={label} token={token} row={row} bpr={blocks_per_row}"
                    );
                }
            }
        }

        // A dynamic scratch request that exceeds the device limit must never
        // reach Metal. Forced SIMD refuses it, while the established ordered
        // scalar lane remains a bit-exact fallback for the same valid row.
        let oversized_blocks = (kernel.device.max_threadgroup_memory_length() as usize / 4) + 1;
        let oversized_f32: Vec<f32> = (0..oversized_blocks * 32)
            .map(|i| (((i * 17 % 257) as f32) - 128.0) * 0.001_7)
            .collect();
        let oversized_input = quantize_q8_0_blocks(&oversized_f32);
        let oversized_refs = [oversized_input.as_slice()];
        let mut oversized_wire = Vec::with_capacity(oversized_blocks * 18);
        for block in 0..oversized_blocks {
            let scale = 0.000_35 * (1 + block % 61) as f32;
            oversized_wire.extend_from_slice(&f32_to_f16_bits(scale).to_le_bytes());
            for j in 0..16 {
                oversized_wire.push(((block * 19 + j * 11 + 5) % 256) as u8);
            }
        }
        assert!(
            try_gemma4_q4_0_matmul_q8_batch_impl(&oversized_refs, &oversized_wire, 1, true,)
                .is_none(),
            "forced SIMD must reject an over-limit threadgroup allocation"
        );
        let fallback = try_gemma4_q4_0_matmul_q8_batch(&oversized_refs, &oversized_wire, 1)
            .expect("ordered scalar fallback for over-limit SIMD scratch");
        let expected = q4_0_wire_row_dot(&oversized_wire, &oversized_input);
        assert_eq!(fallback[0][0].to_bits(), expected.to_bits());
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_q4_expert_slots_are_aligned_and_disjoint() {
        if !detect_metal_device().available {
            return;
        }
        assert!(Gemma4Q4ExpertSlots::new(0).is_none());
        let mut slots = Gemma4Q4ExpertSlots::new(2).expect("two persistent expert slots");
        assert_eq!(slots.slot_count(), 2);
        assert_eq!(slots.slot_record_bytes(), GEMMA4_Q4_EXPERT_RECORD_BYTES);
        assert!(slots
            .slot_stride_bytes()
            .is_multiple_of(GEMMA4_Q4_EXPERT_SLOT_ALIGNMENT));
        let stride = slots.slot_stride_bytes();
        let record = slots.slot_record_bytes();
        let slab = slots.slab_bytes_mut();
        assert_eq!(slab.len(), 2 * stride);
        assert!((slab.as_ptr() as usize).is_multiple_of(GEMMA4_Q4_EXPERT_SLOT_ALIGNMENT));
        slab[record - 1] = 0x51;
        slab[stride] = 0xa7;
        assert_eq!(slab[record - 1], 0x51);
        assert_eq!(slab[stride], 0xa7);
        assert_eq!(slots.slot_bytes_mut(0).unwrap().len(), record);
        assert_eq!(slots.slot_bytes_mut(1).unwrap()[0], 0xa7);
        assert!(slots.slot_bytes_mut(2).is_none());
    }

    // Full fixed-geometry expert gate. The parity lane must reproduce every
    // output bit from the established CPU Q4_0/Q8_0 comparator, including the
    // route-rank fold. The three-dispatch lane is intentionally measured rather
    // than called exact: Metal tanh can differ from Rust tanhf by a few ULP.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_q4_expert_pipeline_parity_and_fused_drift() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::{gemma4::gelu_tanh, q4_0_wire_row_dot, quantize_q8_0_blocks};

        const WIRE: usize = 18;
        const GU_ROWS: usize = 2 * GEMMA4_Q4_EXPERT_FF;
        const GU_BLOCKS: usize = GEMMA4_Q4_EXPERT_HIDDEN / 32;
        const GU_ROW_BYTES: usize = GU_BLOCKS * WIRE;
        const GU_BYTES: usize = GU_ROWS * GU_ROW_BYTES;
        const DOWN_BLOCKS: usize = GEMMA4_Q4_EXPERT_FF / 32;
        const DOWN_ROW_BYTES: usize = DOWN_BLOCKS * WIRE;
        assert_eq!(
            GU_BYTES + GEMMA4_Q4_EXPERT_HIDDEN * DOWN_ROW_BYTES,
            GEMMA4_Q4_EXPERT_RECORD_BYTES
        );

        let mut record = vec![0u8; GEMMA4_Q4_EXPERT_RECORD_BYTES];
        let fill_matrix = |wire: &mut [u8], rows: usize, blocks: usize, seed: usize| {
            for row in 0..rows {
                for block in 0..blocks {
                    let base = (row * blocks + block) * WIRE;
                    let scale = 0.000_35 * (1 + (row * 7 + block * 3 + seed) % 11) as f32;
                    wire[base..base + 2].copy_from_slice(&f32_to_f16_bits(scale).to_le_bytes());
                    for j in 0..16 {
                        wire[base + 2 + j] = ((row * 43 + block * 19 + j * 11 + seed) % 256) as u8;
                    }
                }
            }
        };
        fill_matrix(&mut record[..GU_BYTES], GU_ROWS, GU_BLOCKS, 5);
        fill_matrix(
            &mut record[GU_BYTES..],
            GEMMA4_Q4_EXPERT_HIDDEN,
            DOWN_BLOCKS,
            29,
        );

        let input_f32: Vec<f32> = (0..GEMMA4_Q4_EXPERT_HIDDEN)
            .map(|i| ((((i * 17 + 13) % 257) as f32) - 128.0) * 0.001_7)
            .collect();
        let input = quantize_q8_0_blocks(&input_f32);
        assert_eq!(input.len(), GEMMA4_Q4_EXPERT_INPUT_BLOCKS);

        let mut activated = Vec::with_capacity(GEMMA4_Q4_EXPERT_FF);
        for row in 0..GEMMA4_Q4_EXPERT_FF {
            let gate_start = row * GU_ROW_BYTES;
            let up_start = (row + GEMMA4_Q4_EXPERT_FF) * GU_ROW_BYTES;
            let gate = q4_0_wire_row_dot(&record[gate_start..gate_start + GU_ROW_BYTES], &input);
            let up = q4_0_wire_row_dot(&record[up_start..up_start + GU_ROW_BYTES], &input);
            activated.push(gelu_tanh(gate) * up);
        }
        let activated_q = quantize_q8_0_blocks(&activated);
        let down: Vec<f32> = (0..GEMMA4_Q4_EXPERT_HIDDEN)
            .map(|row| {
                let start = GU_BYTES + row * DOWN_ROW_BYTES;
                q4_0_wire_row_dot(&record[start..start + DOWN_ROW_BYTES], &activated_q)
            })
            .collect();
        let route_scales = [0.31f32, 0.17, 0.13, 0.11, 0.09, 0.07, 0.05, 0.03];
        let expected: Vec<f32> = down
            .iter()
            .map(|&y| {
                let mut total = 0.0f32;
                for &scale in &route_scales {
                    total += y * scale;
                }
                total
            })
            .collect();

        let mut slots = Gemma4Q4ExpertSlots::new(1).expect("persistent expert slot");
        slots.slot_bytes_mut(0).unwrap().copy_from_slice(&record);
        let routes = route_scales.map(|scale| Gemma4Q4ExpertRoute { slot: 0, scale });
        let mut engine = Gemma4Q4ExpertMetal::new().expect("persistent Q4 expert engine");
        let mut parity = vec![0.0f32; GEMMA4_Q4_EXPERT_HIDDEN];
        let parity_diag = engine
            .run_q8_into_parity(&input, &slots, &routes, &mut parity)
            .expect("Q4 expert parity lane");
        assert_eq!(parity_diag.command_buffers, 2);
        assert_eq!(parity_diag.dispatches, 2);
        assert!(parity_diag.cpu_geglu_boundary);
        for (row, (&got, &want)) in parity.iter().zip(&expected).enumerate() {
            assert_eq!(
                got.to_bits(),
                want.to_bits(),
                "ordered persistent expert mismatch at output row {row}: {got} != {want}"
            );
        }

        let kernel = metal_linear_kernel().expect("strict Metal kernel library");
        assert!(
            gemma4_q4_simd_fast_available(kernel),
            "fixed-geometry expert SIMD pipelines must satisfy admission"
        );
        let mut scalar_fused = vec![0.0f32; GEMMA4_Q4_EXPERT_HIDDEN];
        let scalar_fused_diag = engine
            .run_q8_into_fused(&input, &slots, &routes, &mut scalar_fused, false)
            .expect("Q4 expert scalar fused lane");
        let mut fused = vec![0.0f32; GEMMA4_Q4_EXPERT_HIDDEN];
        let fused_diag = engine
            .run_q8_into(&input, &slots, &routes, &mut fused)
            .expect("Q4 expert SIMD fused lane");
        assert_eq!(fused_diag.command_buffers, 1);
        assert_eq!(fused_diag.dispatches, 3);
        assert!(!fused_diag.cpu_geglu_boundary);
        for (row, (&simd, &scalar)) in fused.iter().zip(&scalar_fused).enumerate() {
            assert_eq!(
                simd.to_bits(),
                scalar.to_bits(),
                "SIMD/scalar fused expert mismatch at output row {row}: {simd} != {scalar}"
            );
        }
        let mut differing_bits = 0usize;
        let mut max_abs = 0.0f32;
        for (&got, &want) in fused.iter().zip(&expected) {
            differing_bits += usize::from(got.to_bits() != want.to_bits());
            max_abs = max_abs.max((got - want).abs());
        }
        eprintln!(
            "[gemma4-q4-expert-test] parity_gpu={}us scalar_fused_gpu={}us simd_fused_gpu={}us simd_fused={:.2}GiB/s differing_bits={differing_bits}/{} max_abs={max_abs:e}",
            parity_diag.gpu_us,
            scalar_fused_diag.gpu_us,
            fused_diag.gpu_us,
            fused_diag.effective_gib_per_s(),
            GEMMA4_Q4_EXPERT_HIDDEN,
        );
        assert!(
            max_abs <= 0.05,
            "fused Metal GeGLU drift exceeded validation bound: {max_abs}"
        );

        let invalid_routes = route_scales.map(|scale| Gemma4Q4ExpertRoute { slot: 1, scale });
        assert!(engine
            .run_q8_into(&input, &slots, &invalid_routes, &mut fused)
            .is_none());
    }

    // GABBRO M3 parity gate: the Metal NVFP4 GEMV must match the CPU oracle
    // `nvfp4_wire_block_dequant` × f32 activation (self-parity, §3 leg 3). Reduction
    // order differs from the CPU dot, so the bar is a tolerance (like the q4_0 gate),
    // not bit-exact; decode bit-exactness itself is proven by the M1 golden vectors.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_nvfp4_matmul_f32y_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::nvfp4_wire_block_dequant;
        for blocks_per_row in [3usize, 40, 160] {
            // blocks_per_row counts 64-value NVFP4 superblocks.
            let in_dim = blocks_per_row * 64;
            let rows = 7usize;
            let y: Vec<f32> = (0..in_dim)
                .map(|i| ((i as f32 % 11.0) - 5.0) * 0.1)
                .collect();
            let mut wire = Vec::with_capacity(rows * blocks_per_row * 36);
            let mut want = vec![0.0f32; rows];
            for (r, w) in want.iter_mut().enumerate() {
                let mut acc = 0.0f32;
                for b in 0..blocks_per_row {
                    let mut blk = [0u8; 36];
                    // 4 UE4M3 sub-block scales in [8, 72) — non-zero, and never the
                    // 0x7F/0xFF NaN sentinels.
                    for (s, slot) in blk[0..4].iter_mut().enumerate() {
                        *slot = (((r * 5 + b * 3 + s) % 64) + 8) as u8;
                    }
                    // 32 packed E2M1 nibble bytes.
                    for (j, slot) in blk[4..].iter_mut().enumerate() {
                        *slot = ((r * 31 + b * 17 + j * 3) % 256) as u8;
                    }
                    let deq = nvfp4_wire_block_dequant(&blk);
                    for (i, &d) in deq.iter().enumerate() {
                        acc += d * y[b * 64 + i];
                    }
                    wire.extend_from_slice(&blk);
                }
                *w = acc;
            }
            let got = try_gemma4_nvfp4_matmul_f32y(&y, &wire, rows, blocks_per_row)
                .expect("gemma4 nvfp4 matmul");
            for (a, b) in got.iter().zip(&want) {
                assert!((a - b).abs() < 2.0e-2, "bpr={blocks_per_row} {a} != {b}");
            }
        }
        // Shape guards.
        let blocks_per_row = 3usize;
        let in_dim = blocks_per_row * 64;
        let y: Vec<f32> = (0..in_dim)
            .map(|i| ((i as f32 % 11.0) - 5.0) * 0.1)
            .collect();
        let wire = vec![0u8; 7 * blocks_per_row * 36];
        let rows = 7usize;
        assert!(try_gemma4_nvfp4_matmul_f32y(&y, &wire, 0, blocks_per_row).is_none());
        assert!(
            try_gemma4_nvfp4_matmul_f32y(&y, &wire[..wire.len() - 1], rows, blocks_per_row)
                .is_none()
        );
    }

    // The gemma4 FFN sub-block run as one GPU command buffer (rms_norm -> gate/up
    // GEMV -> GeGLU -> down GEMV -> post_ffw_norm -> residual) must match the same
    // chain on CPU. Proves dependent dispatches compose correctly in one serial
    // encoder with no readback between ops.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ffn_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 128usize; // bpr_hidden = 4
        let ffn_dim = 256usize; // bpr_ffn = 8
        let eps = 1.0e-6f32;
        // Build a weight as (wire bytes, dequantized f32 rows) so the CPU reference
        // dots the SAME values the GPU's f32×dequant GEMV reads.
        let make_weight = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.04)
                    .collect();
                let mut drow = vec![0.0f32; in_dim];
                for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for (j, &q) in blk.quants.iter().enumerate() {
                        wire.push(q as u8);
                        drow[b * 32 + j] = blk.scale * q as f32;
                    }
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (gate_wire, gate_deq) = make_weight(ffn_dim, hidden, 1);
        let (up_wire, up_deq) = make_weight(ffn_dim, hidden, 7);
        let (down_wire, down_deq) = make_weight(hidden, ffn_dim, 3);
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let ffn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();

        let rms = |x: &[f32], w: &[f32]| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            x.iter().zip(w).map(|(v, wv)| v * inv * wv).collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let normf = rms(&h_in, &ffn_norm);
        let gate = matmul(&gate_deq, &normf);
        let up = matmul(&up_deq, &normf);
        let act: Vec<f32> = gate
            .iter()
            .zip(&up)
            .map(|(g, u)| crate::inference::gemma4::gelu_tanh(*g) * u)
            .collect();
        let down = matmul(&down_deq, &act);
        let dn = rms(&down, &post_norm);
        let want: Vec<f32> = h_in.iter().zip(&dn).map(|(a, b)| a + b).collect();

        let got = try_gemma4_ffn(
            GemmaWireFmt::Q8_0,
            &h_in,
            &ffn_norm,
            &post_norm,
            eps,
            &gate_wire,
            &up_wire,
            &down_wire,
            ffn_dim,
        )
        .expect("gemma4 ffn");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 1.0e-2, "{a} != {b}");
        }
    }

    // GPU QAT integration parity gate: the WHOLE gemma4 FFN sub-block (rms_norm ->
    // gate/up GEMV -> GeGLU -> down GEMV -> post_ffw_norm -> residual) run on the
    // GPU with Q4_0 weights must match the same chain on CPU. This proves the Q4_0
    // wire GEMV composes correctly inside the real gemma4 graph — the rung above
    // the standalone kernel test, and the integration gate for moving the QAT
    // rows' dominant cost (the FFN) onto the GPU.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ffn_q4_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::{gemma4::gelu_tanh, q4_0_wire_block_dequant};
        let hidden = 128usize; // bpr_hidden = 4
        let ffn_dim = 256usize; // bpr_ffn = 8
        let eps = 1.0e-6f32;
        // Build each weight as (Q4_0 wire bytes, dequantized f32 rows) so the CPU
        // reference dots the SAME values the GPU's f32×dequant Q4_0 GEMV reads.
        let make_weight = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let mut drow = vec![0.0f32; in_dim];
                for b in 0..(in_dim / 32) {
                    let scale = (((r + b + seed) % 7) as f32 + 1.0) * 0.015;
                    let mut blk = [0u8; 18];
                    blk[0..2].copy_from_slice(&f32_to_f16_bits(scale).to_le_bytes());
                    for (j, slot) in blk[2..].iter_mut().enumerate() {
                        *slot = ((r * 13 + b * 7 + j * 5 + seed) % 256) as u8;
                    }
                    let d = q4_0_wire_block_dequant(&blk);
                    for (i, &v) in d.iter().enumerate() {
                        drow[b * 32 + i] = v;
                    }
                    wire.extend_from_slice(&blk);
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (gate_wire, gate_deq) = make_weight(ffn_dim, hidden, 1);
        let (up_wire, up_deq) = make_weight(ffn_dim, hidden, 7);
        let (down_wire, down_deq) = make_weight(hidden, ffn_dim, 3);
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let ffn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let rms = |x: &[f32], w: &[f32]| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            x.iter().zip(w).map(|(v, wv)| v * inv * wv).collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let normf = rms(&h_in, &ffn_norm);
        let gate = matmul(&gate_deq, &normf);
        let up = matmul(&up_deq, &normf);
        let act: Vec<f32> = gate
            .iter()
            .zip(&up)
            .map(|(g, u)| gelu_tanh(*g) * u)
            .collect();
        let down = matmul(&down_deq, &act);
        let dn = rms(&down, &post_norm);
        let want: Vec<f32> = h_in.iter().zip(&dn).map(|(a, b)| a + b).collect();

        let got = try_gemma4_ffn(
            GemmaWireFmt::Q4_0,
            &h_in,
            &ffn_norm,
            &post_norm,
            eps,
            &gate_wire,
            &up_wire,
            &down_wire,
            ffn_dim,
        )
        .expect("gemma4 q4 ffn");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 1.0e-2, "{a} != {b}");
        }
    }

    // The gemma4 attention sub-block run as one GPU command buffer (rms_norm -> qkv
    // GEMV -> per-head QK/V norm -> RoPE -> KV scatter -> windowed decode attention ->
    // o GEMV -> post_attn_norm -> residual) must match the same chain on CPU. Uses
    // head_dim 256 (gemma's dim, forces the basic decode kernel) and a prefilled cache.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_attention_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let group = n_heads / n_kv_heads;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let write_position = 3usize;
        let filled = 4usize;
        let window_start = 0usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        let make_weight = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                let mut drow = vec![0.0f32; in_dim];
                for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for (j, &q) in blk.quants.iter().enumerate() {
                        wire.push(q as u8);
                        drow[b * 32 + j] = blk.scale * q as f32;
                    }
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (q_wire, q_deq) = make_weight(q_dim, hidden, 1);
        let (k_wire, k_deq) = make_weight(kv_dim, hidden, 5);
        let (v_wire, v_deq) = make_weight(kv_dim, hidden, 9);
        let (o_wire, o_deq) = make_weight(hidden, q_dim, 13);
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let q_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
            .collect();
        let k_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();
        let cache_len = n_kv_heads * max_positions * head_dim;
        let cache_k_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.05)
            .collect();
        let cache_v_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 23) as f32 - 11.0) * 0.04)
            .collect();

        // ---- CPU reference ----
        let rms = |x: &[f32], w: Option<&[f32]>| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            (0..x.len())
                .map(|i| x[i] * inv * w.map_or(1.0, |w| w[i]))
                .collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let per_head = |x: &[f32], heads: usize, w: Option<&[f32]>| -> Vec<f32> {
            let mut out = vec![0.0f32; x.len()];
            for h in 0..heads {
                let n = rms(&x[h * head_dim..(h + 1) * head_dim], w);
                out[h * head_dim..(h + 1) * head_dim].copy_from_slice(&n);
            }
            out
        };
        let rope = |x: &mut [f32], heads: usize| {
            for h in 0..heads {
                let base = h * head_dim;
                for i in 0..half {
                    let (x0, x1) = (x[base + i], x[base + half + i]);
                    x[base + i] = x0 * cos_t[i] - x1 * sin_t[i];
                    x[base + half + i] = x0 * sin_t[i] + x1 * cos_t[i];
                }
            }
        };
        let normf = rms(&h_in, Some(&attn_norm));
        let mut q = per_head(&matmul(&q_deq, &normf), n_heads, Some(&q_norm));
        let mut kk = per_head(&matmul(&k_deq, &normf), n_kv_heads, Some(&k_norm));
        let vv = per_head(&matmul(&v_deq, &normf), n_kv_heads, None);
        rope(&mut q, n_heads);
        rope(&mut kk, n_kv_heads);
        // Effective cache: prefilled positions, current token's k/v at write_position.
        let kv_at = |init: &[f32], cur: &[f32], kvh: usize, p: usize| -> Vec<f32> {
            if p == write_position {
                cur[kvh * head_dim..(kvh + 1) * head_dim].to_vec()
            } else {
                let base = kvh * max_positions * head_dim + p * head_dim;
                init[base..base + head_dim].to_vec()
            }
        };
        let mut ctx = vec![0.0f32; q_dim];
        for h in 0..n_heads {
            let kvh = h / group;
            let qh = &q[h * head_dim..(h + 1) * head_dim];
            let mut scores = Vec::new();
            for p in window_start..filled {
                let kp = kv_at(&cache_k_init, &kk, kvh, p);
                scores.push(scale * qh.iter().zip(&kp).map(|(a, b)| a * b).sum::<f32>());
            }
            let m = scores.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
            let mut den = 0.0f32;
            for s in &mut scores {
                *s = (*s - m).exp();
                den += *s;
            }
            for (idx, p) in (window_start..filled).enumerate() {
                let vp = kv_at(&cache_v_init, &vv, kvh, p);
                let w = scores[idx] / den;
                for d in 0..head_dim {
                    ctx[h * head_dim + d] += w * vp[d];
                }
            }
        }
        let o = matmul(&o_deq, &ctx);
        let on = rms(&o, Some(&post_norm));
        let want: Vec<f32> = h_in.iter().zip(&on).map(|(a, b)| a + b).collect();

        let got = try_gemma4_attention(
            GemmaWireFmt::Q8_0,
            &h_in,
            &attn_norm,
            &q_norm,
            &k_norm,
            &post_norm,
            eps,
            &q_wire,
            &k_wire,
            Some(&v_wire),
            &o_wire,
            &cos_t,
            &sin_t,
            &cache_k_init,
            &cache_v_init,
            max_positions,
            write_position,
            n_heads,
            n_kv_heads,
            head_dim,
            filled,
            window_start,
            scale,
            true, // owning layer
        )
        .expect("gemma4 attention");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 2.0e-2, "{a} != {b}");
        }
    }

    // QAT rung: the SAME gemma4 attention chain, but the q/k/v/o projections are
    // Q4_0 wire weights (18-byte blocks) dispatched through the GPU Q4_0 GEMV. Proves
    // GemmaWireFmt::Q4_0 routes attention end-to-end and matches the CPU f32×dequant
    // reference over the identical dequantized weights. Same geometry as the Q8 test.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_attention_q4_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::q4_0_wire_block_dequant;
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let group = n_heads / n_kv_heads;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let write_position = 3usize;
        let filled = 4usize;
        let window_start = 0usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        // Q4_0 wire weight + its dequantized rows (the CPU reference dots the SAME
        // values the GPU's f32×dequant Q4_0 GEMV reads).
        let make_weight = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let mut drow = vec![0.0f32; in_dim];
                for b in 0..(in_dim / 32) {
                    let scale = (((r + b + seed) % 7) as f32 + 1.0) * 0.015;
                    let mut blk = [0u8; 18];
                    blk[0..2].copy_from_slice(&f32_to_f16_bits(scale).to_le_bytes());
                    for (j, slot) in blk[2..].iter_mut().enumerate() {
                        *slot = ((r * 13 + b * 7 + j * 5 + seed) % 256) as u8;
                    }
                    let d = q4_0_wire_block_dequant(&blk);
                    for (i, &v) in d.iter().enumerate() {
                        drow[b * 32 + i] = v;
                    }
                    wire.extend_from_slice(&blk);
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (q_wire, q_deq) = make_weight(q_dim, hidden, 1);
        let (k_wire, k_deq) = make_weight(kv_dim, hidden, 5);
        let (v_wire, v_deq) = make_weight(kv_dim, hidden, 9);
        let (o_wire, o_deq) = make_weight(hidden, q_dim, 13);
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let q_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
            .collect();
        let k_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();
        let cache_len = n_kv_heads * max_positions * head_dim;
        let cache_k_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.05)
            .collect();
        let cache_v_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 23) as f32 - 11.0) * 0.04)
            .collect();

        // ---- CPU reference ----
        let rms = |x: &[f32], w: Option<&[f32]>| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            (0..x.len())
                .map(|i| x[i] * inv * w.map_or(1.0, |w| w[i]))
                .collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let per_head = |x: &[f32], heads: usize, w: Option<&[f32]>| -> Vec<f32> {
            let mut out = vec![0.0f32; x.len()];
            for h in 0..heads {
                let n = rms(&x[h * head_dim..(h + 1) * head_dim], w);
                out[h * head_dim..(h + 1) * head_dim].copy_from_slice(&n);
            }
            out
        };
        let rope = |x: &mut [f32], heads: usize| {
            for h in 0..heads {
                let base = h * head_dim;
                for i in 0..half {
                    let (x0, x1) = (x[base + i], x[base + half + i]);
                    x[base + i] = x0 * cos_t[i] - x1 * sin_t[i];
                    x[base + half + i] = x0 * sin_t[i] + x1 * cos_t[i];
                }
            }
        };
        let normf = rms(&h_in, Some(&attn_norm));
        let mut q = per_head(&matmul(&q_deq, &normf), n_heads, Some(&q_norm));
        let mut kk = per_head(&matmul(&k_deq, &normf), n_kv_heads, Some(&k_norm));
        let vv = per_head(&matmul(&v_deq, &normf), n_kv_heads, None);
        rope(&mut q, n_heads);
        rope(&mut kk, n_kv_heads);
        let kv_at = |init: &[f32], cur: &[f32], kvh: usize, p: usize| -> Vec<f32> {
            if p == write_position {
                cur[kvh * head_dim..(kvh + 1) * head_dim].to_vec()
            } else {
                let base = kvh * max_positions * head_dim + p * head_dim;
                init[base..base + head_dim].to_vec()
            }
        };
        let mut ctx = vec![0.0f32; q_dim];
        for h in 0..n_heads {
            let kvh = h / group;
            let qh = &q[h * head_dim..(h + 1) * head_dim];
            let mut scores = Vec::new();
            for p in window_start..filled {
                let kp = kv_at(&cache_k_init, &kk, kvh, p);
                scores.push(scale * qh.iter().zip(&kp).map(|(a, b)| a * b).sum::<f32>());
            }
            let m = scores.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
            let mut den = 0.0f32;
            for s in &mut scores {
                *s = (*s - m).exp();
                den += *s;
            }
            for (idx, p) in (window_start..filled).enumerate() {
                let vp = kv_at(&cache_v_init, &vv, kvh, p);
                let w = scores[idx] / den;
                for d in 0..head_dim {
                    ctx[h * head_dim + d] += w * vp[d];
                }
            }
        }
        let o = matmul(&o_deq, &ctx);
        let on = rms(&o, Some(&post_norm));
        let want: Vec<f32> = h_in.iter().zip(&on).map(|(a, b)| a + b).collect();

        let got = try_gemma4_attention(
            GemmaWireFmt::Q4_0,
            &h_in,
            &attn_norm,
            &q_norm,
            &k_norm,
            &post_norm,
            eps,
            &q_wire,
            &k_wire,
            Some(&v_wire),
            &o_wire,
            &cos_t,
            &sin_t,
            &cache_k_init,
            &cache_v_init,
            max_positions,
            write_position,
            n_heads,
            n_kv_heads,
            head_dim,
            filled,
            window_start,
            scale,
            true, // owning layer
        )
        .expect("gemma4 q4 attention");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 2.0e-2, "{a} != {b}");
        }
    }

    // V-less attention (12B-class full-attention layers carry no attn_v): the GPU
    // graph must use the RAW K projection (pre-norm, pre-rope) as the V source —
    // reference: `if v_proj is not present, use Kcur as Vcur`. Geometry mirrors a
    // real 12B global layer: kv_heads = 1, head_dim = 512.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_vless_attention_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 256usize;
        let n_heads = 4usize;
        let n_kv_heads = 1usize;
        let head_dim = 512usize;
        let group = n_heads / n_kv_heads;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let write_position = 3usize;
        let filled = 4usize;
        let window_start = 0usize;
        let eps = 1.0e-6f32;
        let scale = 1.0f32; // gemma folds the attention scale into the normed query

        let make_weight = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                let mut drow = vec![0.0f32; in_dim];
                for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for (j, &q) in blk.quants.iter().enumerate() {
                        wire.push(q as u8);
                        drow[b * 32 + j] = blk.scale * q as f32;
                    }
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (q_wire, q_deq) = make_weight(q_dim, hidden, 3);
        let (k_wire, k_deq) = make_weight(kv_dim, hidden, 7);
        let (o_wire, o_deq) = make_weight(hidden, q_dim, 11);
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let q_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
            .collect();
        let k_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();
        let cache_len = n_kv_heads * max_positions * head_dim;
        let cache_k_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.05)
            .collect();
        let cache_v_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 23) as f32 - 11.0) * 0.04)
            .collect();

        // ---- CPU reference (V = weightless-normed RAW K projection) ----
        let rms = |x: &[f32], w: Option<&[f32]>| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            (0..x.len())
                .map(|i| x[i] * inv * w.map_or(1.0, |w| w[i]))
                .collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let per_head = |x: &[f32], heads: usize, w: Option<&[f32]>| -> Vec<f32> {
            let mut out = vec![0.0f32; x.len()];
            for h in 0..heads {
                let n = rms(&x[h * head_dim..(h + 1) * head_dim], w);
                out[h * head_dim..(h + 1) * head_dim].copy_from_slice(&n);
            }
            out
        };
        let rope = |x: &mut [f32], heads: usize| {
            for h in 0..heads {
                let base = h * head_dim;
                for i in 0..half {
                    let (x0, x1) = (x[base + i], x[base + half + i]);
                    x[base + i] = x0 * cos_t[i] - x1 * sin_t[i];
                    x[base + half + i] = x0 * sin_t[i] + x1 * cos_t[i];
                }
            }
        };
        let normf = rms(&h_in, Some(&attn_norm));
        let k_raw = matmul(&k_deq, &normf);
        let mut q = per_head(&matmul(&q_deq, &normf), n_heads, Some(&q_norm));
        let mut kk = per_head(&k_raw, n_kv_heads, Some(&k_norm));
        // V from the RAW K projection, weightless norm, never roped.
        let vv = per_head(&k_raw, n_kv_heads, None);
        rope(&mut q, n_heads);
        rope(&mut kk, n_kv_heads);
        let kv_at = |init: &[f32], cur: &[f32], kvh: usize, p: usize| -> Vec<f32> {
            if p == write_position {
                cur[kvh * head_dim..(kvh + 1) * head_dim].to_vec()
            } else {
                let base = kvh * max_positions * head_dim + p * head_dim;
                init[base..base + head_dim].to_vec()
            }
        };
        let mut ctx = vec![0.0f32; q_dim];
        for h in 0..n_heads {
            let kvh = h / group;
            let qh = &q[h * head_dim..(h + 1) * head_dim];
            let mut scores = Vec::new();
            for p in window_start..filled {
                let kp = kv_at(&cache_k_init, &kk, kvh, p);
                scores.push(scale * qh.iter().zip(&kp).map(|(a, b)| a * b).sum::<f32>());
            }
            let m = scores.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
            let mut den = 0.0f32;
            for s in &mut scores {
                *s = (*s - m).exp();
                den += *s;
            }
            for (idx, p) in (window_start..filled).enumerate() {
                let vp = kv_at(&cache_v_init, &vv, kvh, p);
                let w = scores[idx] / den;
                for d in 0..head_dim {
                    ctx[h * head_dim + d] += w * vp[d];
                }
            }
        }
        let o = matmul(&o_deq, &ctx);
        let on = rms(&o, Some(&post_norm));
        let want: Vec<f32> = h_in.iter().zip(&on).map(|(a, b)| a + b).collect();

        let got = try_gemma4_attention(
            GemmaWireFmt::Q8_0,
            &h_in,
            &attn_norm,
            &q_norm,
            &k_norm,
            &post_norm,
            eps,
            &q_wire,
            &k_wire,
            None, // V-less: no attn_v weight
            &o_wire,
            &cos_t,
            &sin_t,
            &cache_k_init,
            &cache_v_init,
            max_positions,
            write_position,
            n_heads,
            n_kv_heads,
            head_dim,
            filled,
            window_start,
            scale,
            true, // owning layer
        )
        .expect("gemma4 v-less attention");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 2.0e-2, "{a} != {b}");
        }
    }

    // A cross-shared gemma4 layer (owns_kv = false) must skip K/V projection + scatter
    // and run q-only attention against the source layer's cache (here a fully-prefilled
    // cache covering all `filled` positions). Validates the owns_kv=false branch.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_attention_shared_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let group = n_heads / n_kv_heads;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let write_position = 3usize;
        let filled = 4usize;
        let window_start = 0usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        let make_weight = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                let mut drow = vec![0.0f32; in_dim];
                for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for (j, &q) in blk.quants.iter().enumerate() {
                        wire.push(q as u8);
                        drow[b * 32 + j] = blk.scale * q as f32;
                    }
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (q_wire, q_deq) = make_weight(q_dim, hidden, 1);
        // K/V weights are required by the wrapper's shape checks but unused when shared.
        let (k_wire, _) = make_weight(kv_dim, hidden, 5);
        let (v_wire, _) = make_weight(kv_dim, hidden, 9);
        let (o_wire, o_deq) = make_weight(hidden, q_dim, 13);
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let q_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
            .collect();
        let k_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();
        let cache_len = n_kv_heads * max_positions * head_dim;
        // Fully prefilled: the source layer already wrote every position incl. write_position.
        let cache_k_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.05)
            .collect();
        let cache_v_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 23) as f32 - 11.0) * 0.04)
            .collect();

        // CPU reference: q only, attention over the source cache directly.
        let rms = |x: &[f32], w: Option<&[f32]>| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            (0..x.len())
                .map(|i| x[i] * inv * w.map_or(1.0, |w| w[i]))
                .collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let normf = rms(&h_in, Some(&attn_norm));
        let mut q = vec![0.0f32; q_dim];
        for h in 0..n_heads {
            let qh = rms(
                &matmul(&q_deq, &normf)[h * head_dim..(h + 1) * head_dim],
                Some(&q_norm),
            );
            q[h * head_dim..(h + 1) * head_dim].copy_from_slice(&qh);
        }
        for h in 0..n_heads {
            let base = h * head_dim;
            for i in 0..half {
                let (x0, x1) = (q[base + i], q[base + half + i]);
                q[base + i] = x0 * cos_t[i] - x1 * sin_t[i];
                q[base + half + i] = x0 * sin_t[i] + x1 * cos_t[i];
            }
        }
        let cache_at = |c: &[f32], kvh: usize, p: usize| -> Vec<f32> {
            let base = kvh * max_positions * head_dim + p * head_dim;
            c[base..base + head_dim].to_vec()
        };
        let mut ctx = vec![0.0f32; q_dim];
        for h in 0..n_heads {
            let kvh = h / group;
            let qh = &q[h * head_dim..(h + 1) * head_dim];
            let mut scores = Vec::new();
            for p in window_start..filled {
                let kp = cache_at(&cache_k_init, kvh, p);
                scores.push(scale * qh.iter().zip(&kp).map(|(a, b)| a * b).sum::<f32>());
            }
            let m = scores.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
            let mut den = 0.0f32;
            for s in &mut scores {
                *s = (*s - m).exp();
                den += *s;
            }
            for (idx, p) in (window_start..filled).enumerate() {
                let vp = cache_at(&cache_v_init, kvh, p);
                let w = scores[idx] / den;
                for d in 0..head_dim {
                    ctx[h * head_dim + d] += w * vp[d];
                }
            }
        }
        let on = rms(&matmul(&o_deq, &ctx), Some(&post_norm));
        let want: Vec<f32> = h_in.iter().zip(&on).map(|(a, b)| a + b).collect();

        let got = try_gemma4_attention(
            GemmaWireFmt::Q8_0,
            &h_in,
            &attn_norm,
            &q_norm,
            &k_norm,
            &post_norm,
            eps,
            &q_wire,
            &k_wire,
            Some(&v_wire),
            &o_wire,
            &cos_t,
            &sin_t,
            &cache_k_init,
            &cache_v_init,
            max_positions,
            write_position,
            n_heads,
            n_kv_heads,
            head_dim,
            filled,
            window_start,
            scale,
            false, // shared layer: read the source cache, no K/V projection
        )
        .expect("gemma4 shared attention");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 2.0e-2, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    struct GhostCommonFixture {
        layer: Gemma4ResidentLayer,
        post_norm_1: Vec<f32>,
        attn_norm: Vec<f32>,
        q_norm: Vec<f32>,
        k_norm: Vec<f32>,
        post_attn_norm: Vec<f32>,
        ffn_norm: Vec<f32>,
        q_wire: Vec<u8>,
        k_wire: Vec<u8>,
        v_wire: Vec<u8>,
        o_wire: Vec<u8>,
        gate_wire: Vec<u8>,
        up_wire: Vec<u8>,
        down_wire: Vec<u8>,
    }

    #[cfg(target_os = "macos")]
    fn ghost_common_q4_wire(rows: usize, input: usize, seed: usize) -> Vec<u8> {
        let blocks = input / 32;
        let mut wire = vec![0u8; rows * blocks * 18];
        for row in 0..rows {
            for block in 0..blocks {
                let base = (row * blocks + block) * 18;
                let scale = 0.000_7 * (1 + (row * 5 + block * 3 + seed) % 17) as f32;
                wire[base..base + 2].copy_from_slice(&f32_to_f16_bits(scale).to_le_bytes());
                for nibble in 0..16 {
                    wire[base + 2 + nibble] =
                        ((row * 43 + block * 29 + nibble * 11 + seed * 7) & 0xff) as u8;
                }
            }
        }
        wire
    }

    #[cfg(target_os = "macos")]
    fn ghost_common_fixture(seed: usize) -> GhostCommonFixture {
        ghost_common_fixture_with_kv_heads(seed, 1)
    }

    #[cfg(target_os = "macos")]
    fn ghost_common_fixture_with_kv_heads(seed: usize, kv_heads: usize) -> GhostCommonFixture {
        const HIDDEN: usize = 128;
        const HEADS: usize = 2;
        const HEAD_DIM: usize = 256;
        const FFN: usize = 128;
        assert!(kv_heads > 0 && HEADS.is_multiple_of(kv_heads));
        let q_dim = HEADS * HEAD_DIM;
        let kv_dim = kv_heads * HEAD_DIM;
        let eps = 1.0e-6;
        let attn_norm: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.73 + ((i * 7 + seed) % 19) as f32 * 0.013)
            .collect();
        let q_norm: Vec<f32> = (0..HEAD_DIM)
            .map(|i| 0.69 + ((i * 5 + seed) % 23) as f32 * 0.009)
            .collect();
        let k_norm: Vec<f32> = (0..HEAD_DIM)
            .map(|i| 0.67 + ((i * 3 + seed) % 17) as f32 * 0.011)
            .collect();
        let post_attn_norm: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.79 + ((i * 11 + seed) % 13) as f32 * 0.017)
            .collect();
        let ffn_norm: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.76 + ((i * 13 + seed) % 11) as f32 * 0.019)
            .collect();
        let post_ffw_norm: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.82 + ((i * 17 + seed) % 7) as f32 * 0.021)
            .collect();
        let post_norm_1: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.71 + ((i * 19 + seed) % 29) as f32 * 0.008)
            .collect();
        let q_wire = ghost_common_q4_wire(q_dim, HIDDEN, seed + 1);
        let k_wire = ghost_common_q4_wire(kv_dim, HIDDEN, seed + 2);
        let v_wire = ghost_common_q4_wire(kv_dim, HIDDEN, seed + 3);
        let o_wire = ghost_common_q4_wire(HIDDEN, q_dim, seed + 4);
        let gate_wire = ghost_common_q4_wire(FFN, HIDDEN, seed + 5);
        let up_wire = ghost_common_q4_wire(FFN, HIDDEN, seed + 6);
        let down_wire = ghost_common_q4_wire(HIDDEN, FFN, seed + 7);
        let layer = Gemma4ResidentLayer::from_wire(
            GemmaWireFmt::Q4_0,
            attn_norm.clone(),
            q_norm.clone(),
            k_norm.clone(),
            post_attn_norm.clone(),
            ffn_norm.clone(),
            post_ffw_norm,
            &q_wire,
            &k_wire,
            Some(&v_wire),
            &o_wire,
            &gate_wire,
            &up_wire,
            &down_wire,
            HEADS,
            kv_heads,
            HEAD_DIM,
            FFN,
            eps,
        )
        .expect("synthetic Ghost common Q4 layer");
        GhostCommonFixture {
            layer,
            post_norm_1,
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            q_wire,
            k_wire,
            v_wire,
            o_wire,
            gate_wire,
            up_wire,
            down_wire,
        }
    }

    #[cfg(target_os = "macos")]
    fn ghost_common_cpu_q4_matvec(
        wire: &[u8],
        rows: usize,
        input: &[crate::tensor::Q8_0Block],
    ) -> Vec<f32> {
        let row_bytes = input.len() * 18;
        assert_eq!(wire.len(), rows * row_bytes);
        (0..rows)
            .map(|row| {
                crate::inference::q4_0_wire_row_dot(
                    &wire[row * row_bytes..(row + 1) * row_bytes],
                    input,
                )
            })
            .collect()
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ghost_common_26b_geometry_contract_is_exact() {
        assert_eq!(GEMMA4_GHOST_26B_GLOBAL_LAYERS, [5, 11, 17, 23, 29]);
        let schedule: Vec<bool> = (0..GEMMA4_GHOST_26B_LAYERS)
            .map(|layer| !GEMMA4_GHOST_26B_GLOBAL_LAYERS.contains(&layer))
            .collect();
        assert_eq!(schedule.iter().filter(|&&local| local).count(), 25);
        assert_eq!(schedule.iter().filter(|&&local| !local).count(), 5);
        let local_bytes_per_position = 25
            * 2
            * GEMMA4_GHOST_26B_LOCAL_KV_HEADS
            * GEMMA4_GHOST_26B_LOCAL_HEAD_DIM
            * std::mem::size_of::<f32>();
        let global_bytes_per_position = 5
            * 2
            * GEMMA4_GHOST_26B_GLOBAL_KV_HEADS
            * GEMMA4_GHOST_26B_GLOBAL_HEAD_DIM
            * std::mem::size_of::<f32>();
        assert_eq!(
            local_bytes_per_position + global_bytes_per_position,
            450_560
        );
        assert_eq!(450_560usize * 4096, 1_845_493_760);
        assert_eq!(GEMMA4_GHOST_26B_HIDDEN, 2_816);
        assert_eq!(GEMMA4_GHOST_26B_SHARED_FF, 2_112);
        assert_eq!(GEMMA4_GHOST_26B_SLIDING_WINDOW, 1_024);
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ghost_common_imports_position_major_kv_bit_exact_and_atomically() {
        if !detect_metal_device().available {
            return;
        }
        const KV_HEADS: usize = 2;
        const HEAD_DIM: usize = 256;
        const POSITIONS: usize = 3;
        const CAPACITY: usize = 4;
        let fixture = ghost_common_fixture_with_kv_heads(27, KV_HEADS);
        let mut common = Gemma4GhostCommonMetal::new_synthetic(
            vec![fixture.layer],
            vec![fixture.post_norm_1],
            CAPACITY,
            CAPACITY,
        )
        .expect("multi-head common-core fixture");
        let make_rows = |salt: usize| {
            (0..POSITIONS)
                .map(|position| {
                    (0..KV_HEADS * HEAD_DIM)
                        .map(|index| {
                            let head = index / HEAD_DIM;
                            let dim = index % HEAD_DIM;
                            (salt + position * 10_000 + head * 1_000 + dim) as f32 * 0.001
                        })
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>()
        };
        let keys = vec![make_rows(17)];
        let values = vec![make_rows(53)];
        common
            .import_position_major_kv(&keys, &values, POSITIONS)
            .expect("bit-preserving CPU KV import");
        assert_eq!(common.next_position, vec![POSITIONS]);
        assert_eq!(common.latest_attention_layer, None);

        let assert_layout = |buffer: &Buffer, rows: &[Vec<f32>]| unsafe {
            let actual = buffer.contents().cast::<f32>();
            for head in 0..KV_HEADS {
                for (position, row) in rows.iter().enumerate().take(POSITIONS) {
                    for dim in 0..HEAD_DIM {
                        let source = row[head * HEAD_DIM + dim];
                        let destination =
                            *actual.add((head * CAPACITY + position) * HEAD_DIM + dim);
                        assert_eq!(
                            destination.to_bits(),
                            source.to_bits(),
                            "head={head} position={position} dim={dim}"
                        );
                    }
                }
            }
        };
        assert_layout(&common.cache_k[0], &keys[0]);
        assert_layout(&common.cache_v[0], &values[0]);

        // A malformed later validation must not disturb either cache or the
        // sequential-position watermark established by the successful import.
        let snapshot = |buffer: &Buffer| unsafe {
            let source = buffer.contents().cast::<f32>();
            (0..KV_HEADS * CAPACITY * HEAD_DIM)
                .map(|index| (*source.add(index)).to_bits())
                .collect::<Vec<_>>()
        };
        let key_before = snapshot(&common.cache_k[0]);
        let value_before = snapshot(&common.cache_v[0]);
        let mut invalid_keys = keys.clone();
        invalid_keys[0][2][9] = f32::NAN;
        let error = common
            .import_position_major_kv(&invalid_keys, &values, POSITIONS)
            .expect_err("non-finite KV must refuse");
        assert!(error.to_string().contains("non-finite"));
        assert_eq!(snapshot(&common.cache_k[0]), key_before);
        assert_eq!(snapshot(&common.cache_v[0]), value_before);
        assert_eq!(common.next_position, vec![POSITIONS]);

        // The imported watermark is the next legal decode position. Reject a
        // rewind without mutation, then consume the imported history at exactly N.
        let hidden: Vec<f32> = (0..128).map(|index| index as f32 * 0.0007).collect();
        let cos = vec![1.0f32; HEAD_DIM / 2];
        let sin = vec![0.0f32; HEAD_DIM / 2];
        assert!(common.write_hidden(&hidden));
        assert!(common
            .enqueue_attention(0, &cos, &sin, POSITIONS - 1)
            .is_none());
        let diagnostics = common
            .enqueue_attention(0, &cos, &sin, POSITIONS)
            .and_then(Gemma4GhostCommonPending::wait)
            .expect("decode at the first post-import position");
        assert_eq!(diagnostics.position, POSITIONS);
        assert_eq!(common.next_position, vec![POSITIONS + 1]);
        assert!(common
            .read_attention_output()
            .iter()
            .all(|value| value.is_finite()));
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn ghost_common_owned_wire_pages_release_on_drop() {
        if !detect_metal_device().available {
            return;
        }
        use std::io::{Seek, SeekFrom, Write};
        let page = crate::wire_mmap::page_size();
        let mut file = tempfile::tempfile().expect("temporary wire file");
        file.write_all(&vec![0x5au8; page])
            .expect("write temporary wire bytes");
        file.seek(SeekFrom::Start(0)).expect("rewind wire file");
        let pages = crate::wire_mmap::WirePages::read_from_file(&file, 0, page)
            .expect("page-aligned wire allocation");
        let baseline = std::sync::Arc::strong_count(&pages);
        let layer = Gemma4ResidentLayer::from_wire_pages_owned(
            GemmaWireFmt::Q4_0,
            vec![1.0; 32],
            vec![1.0; 32],
            vec![1.0; 32],
            vec![1.0; 32],
            vec![1.0; 32],
            vec![1.0; 32],
            &pages,
            &pages,
            Some(&pages),
            &pages,
            &pages,
            &pages,
            &pages,
            1,
            1,
            32,
            32,
            1.0e-6,
        )
        .expect("reload-safe resident layer");
        assert_eq!(std::sync::Arc::strong_count(&pages), baseline + 7);
        drop(layer);
        assert_eq!(
            std::sync::Arc::strong_count(&pages),
            baseline,
            "dropping the Ghost layer must release every lifecycle-owned WirePages Arc"
        );
    }

    // Phase-1 attention parity: the reusable common core must follow the CPU wire
    // lane's RMS -> Q8 activation -> ordered Q4 projection order, persist its f32
    // KV slot, and stop exactly at the post-attention residual.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ghost_common_attention_matches_cpu_wire_oracle() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        const HIDDEN: usize = 128;
        const HEADS: usize = 2;
        const HEAD_DIM: usize = 256;
        const Q_DIM: usize = HEADS * HEAD_DIM;
        let fixture = ghost_common_fixture(31);
        let h: Vec<f32> = (0..HIDDEN)
            .map(|i| (((i * 37 + 17) % 211) as f32 - 105.0) * 0.0061)
            .collect();
        let cos_t = vec![1.0f32; HEAD_DIM / 2];
        let sin_t = vec![0.0f32; HEAD_DIM / 2];

        // At position zero every query head attends exactly one value row, so
        // context is the weightless-normalized V row repeated across GQA heads.
        // Q/K still execute and populate persistent K, but cannot obscure the O
        // projection and sandwich-norm parity this test is targeting.
        let normed = crate::gemma4_runtime::rms_norm(&h, Some(&fixture.attn_norm), 1.0e-6);
        let normed_q8 = quantize_q8_0_blocks(&normed);
        let value = ghost_common_cpu_q4_matvec(&fixture.v_wire, HEAD_DIM, &normed_q8);
        let value = crate::gemma4_runtime::rms_norm(&value, None, 1.0e-6);
        let mut context = Vec::with_capacity(Q_DIM);
        context.extend_from_slice(&value);
        context.extend_from_slice(&value);
        let context_q8 = quantize_q8_0_blocks(&context);
        let projection = ghost_common_cpu_q4_matvec(&fixture.o_wire, HIDDEN, &context_q8);
        let projection =
            crate::gemma4_runtime::rms_norm(&projection, Some(&fixture.post_attn_norm), 1.0e-6);
        let expected: Vec<f32> = h
            .iter()
            .zip(&projection)
            .map(|(residual, projected)| residual + projected)
            .collect();

        let mut common = Gemma4GhostCommonMetal::new_synthetic(
            vec![fixture.layer],
            vec![fixture.post_norm_1],
            2,
            2,
        )
        .expect("synthetic persistent Ghost common core");
        let geometry = common.geometry();
        assert_eq!(geometry.layers, 1);
        assert_eq!(geometry.local_layers, 1);
        assert_eq!(geometry.global_layers, 0);
        assert_eq!(geometry.kv_bytes, 2 * HEAD_DIM * 2 * 4);
        let (actual, diagnostics) = common
            .execute_attention(0, &h, &cos_t, &sin_t, 0)
            .expect("persistent ordered-Q4 attention");
        assert_eq!(diagnostics.stage, Gemma4GhostCommonStage::Attention);
        assert_eq!(diagnostics.command_buffers, 1);
        assert_eq!(diagnostics.dispatches, 17);
        assert_eq!(diagnostics.readback_bytes, (HIDDEN * 4) as u64);
        assert!(diagnostics.streamed_weight_bytes > 0);
        for (index, (&got, &want)) in actual.iter().zip(&expected).enumerate() {
            let tolerance = 3.0e-2 * want.abs().max(1.0);
            assert!(
                (got - want).abs() <= tolerance,
                "attention row {index}: metal={got} cpu={want} tolerance={tolerance}"
            );
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ghost_common_attention_reads_prior_kv_history() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        const HIDDEN: usize = 128;
        const HEADS: usize = 2;
        const HEAD_DIM: usize = 256;
        const Q_DIM: usize = HEADS * HEAD_DIM;
        let fixture = ghost_common_fixture(49);
        let h0: Vec<f32> = (0..HIDDEN)
            .map(|i| (((i * 29 + 13) % 181) as f32 - 90.0) * 0.0049)
            .collect();
        let h1: Vec<f32> = (0..HIDDEN)
            .map(|i| (((i * 43 + 19) % 227) as f32 - 113.0) * 0.0041)
            .collect();
        let cos_t = vec![1.0f32; HEAD_DIM / 2];
        let sin_t = vec![0.0f32; HEAD_DIM / 2];

        let qkv = |hidden: &[f32]| {
            let normalized =
                crate::gemma4_runtime::rms_norm(hidden, Some(&fixture.attn_norm), 1.0e-6);
            let input = quantize_q8_0_blocks(&normalized);
            let mut q = ghost_common_cpu_q4_matvec(&fixture.q_wire, Q_DIM, &input);
            for head in 0..HEADS {
                let base = head * HEAD_DIM;
                let normalized_head = crate::gemma4_runtime::rms_norm(
                    &q[base..base + HEAD_DIM],
                    Some(&fixture.q_norm),
                    1.0e-6,
                );
                q[base..base + HEAD_DIM].copy_from_slice(&normalized_head);
            }
            let k_raw = ghost_common_cpu_q4_matvec(&fixture.k_wire, HEAD_DIM, &input);
            let k = crate::gemma4_runtime::rms_norm(&k_raw, Some(&fixture.k_norm), 1.0e-6);
            let v_raw = ghost_common_cpu_q4_matvec(&fixture.v_wire, HEAD_DIM, &input);
            let v = crate::gemma4_runtime::rms_norm(&v_raw, None, 1.0e-6);
            (q, k, v)
        };
        let (_, k0, v0) = qkv(&h0);
        let (q1, k1, v1) = qkv(&h1);
        let mut context = vec![0.0f32; Q_DIM];
        for head in 0..HEADS {
            let qh = &q1[head * HEAD_DIM..(head + 1) * HEAD_DIM];
            let score0 = qh.iter().zip(&k0).map(|(a, b)| a * b).sum::<f32>();
            let score1 = qh.iter().zip(&k1).map(|(a, b)| a * b).sum::<f32>();
            let maximum = score0.max(score1);
            let weight0 = (score0 - maximum).exp();
            let weight1 = (score1 - maximum).exp();
            let denominator = weight0 + weight1;
            for d in 0..HEAD_DIM {
                context[head * HEAD_DIM + d] = (weight0 * v0[d] + weight1 * v1[d]) / denominator;
            }
        }
        let context_q8 = quantize_q8_0_blocks(&context);
        let projection = ghost_common_cpu_q4_matvec(&fixture.o_wire, HIDDEN, &context_q8);
        let projection =
            crate::gemma4_runtime::rms_norm(&projection, Some(&fixture.post_attn_norm), 1.0e-6);
        let expected: Vec<f32> = h1
            .iter()
            .zip(&projection)
            .map(|(residual, attention)| residual + attention)
            .collect();

        let mut common = Gemma4GhostCommonMetal::new_synthetic(
            vec![fixture.layer],
            vec![fixture.post_norm_1],
            3,
            3,
        )
        .expect("synthetic persistent Ghost common core");
        common
            .execute_attention(0, &h0, &cos_t, &sin_t, 0)
            .expect("position-zero KV write");
        let (actual, diagnostics) = common
            .execute_attention(0, &h1, &cos_t, &sin_t, 1)
            .expect("position-one history attention");
        assert_eq!(diagnostics.position, 1);
        for (index, (&got, &want)) in actual.iter().zip(&expected).enumerate() {
            let tolerance = 3.0e-2 * want.abs().max(1.0);
            assert!(
                (got - want).abs() <= tolerance,
                "history attention {index}: metal={got} cpu={want} tolerance={tolerance}"
            );
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ghost_common_attention_router_fusion_matches_standalone() {
        if !detect_metal_device().available {
            return;
        }
        const HIDDEN: usize = 128;
        const EXPERTS: usize = 128;
        const HEAD_DIM: usize = 256;
        let split_fixture = ghost_common_fixture(61);
        let fused_fixture = ghost_common_fixture(61);
        let hidden: Vec<f32> = (0..HIDDEN)
            .map(|i| (((i * 47 + 29) % 239) as f32 - 119.0) * 0.0047)
            .collect();
        let cos_t = vec![1.0f32; HEAD_DIM / 2];
        let sin_t = vec![0.0f32; HEAD_DIM / 2];
        let router: Vec<f32> = (0..EXPERTS * HIDDEN)
            .map(|i| (((i * 19 + 5) % 83) as f32 - 41.0) * 0.0007)
            .collect();
        let gate_input_scale: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.78 + (i % 17) as f32 * 0.006)
            .collect();
        let pre_norm_2: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.72 + (i % 11) as f32 * 0.009)
            .collect();
        let post_norm_2: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.75 + (i % 13) as f32 * 0.008)
            .collect();
        let config = || Gemma4GhostMoeLayerConfig {
            router: router.clone(),
            gate_input_scale: gate_input_scale.clone(),
            pre_norm_2: pre_norm_2.clone(),
            post_norm_2: post_norm_2.clone(),
            layer_output_scale: 1.0,
        };

        let mut split = Gemma4GhostCommonMetal::new_synthetic(
            vec![split_fixture.layer],
            vec![split_fixture.post_norm_1],
            2,
            2,
        )
        .expect("standalone common core");
        assert!(split.configure_moe(vec![config()]));
        assert!(split.write_hidden(&hidden));
        let attention_diagnostics = split
            .enqueue_attention(0, &cos_t, &sin_t, 0)
            .and_then(Gemma4GhostCommonPending::wait)
            .expect("standalone attention");
        let router_diagnostics = split
            .enqueue_router(0)
            .and_then(Gemma4GhostCommonPending::wait)
            .expect("standalone router");
        let expected_attention = split.read_attention_output();
        let expected_logits = split.read_router_logits().expect("standalone logits");

        let mut fused = Gemma4GhostCommonMetal::new_synthetic(
            vec![fused_fixture.layer],
            vec![fused_fixture.post_norm_1],
            2,
            2,
        )
        .expect("fused common core");
        assert!(fused.configure_moe(vec![config()]));
        assert!(fused.write_hidden(&hidden));
        let fused_diagnostics = fused
            .enqueue_attention_router(0, &cos_t, &sin_t, 0)
            .and_then(Gemma4GhostCommonPending::wait)
            .expect("fused attention/router");
        let actual_attention = fused.read_attention_output();
        let actual_logits = fused.read_router_logits().expect("fused logits");

        assert_eq!(
            fused_diagnostics.stage,
            Gemma4GhostCommonStage::AttentionRouter
        );
        assert_eq!(fused_diagnostics.command_buffers, 1);
        assert_eq!(
            fused_diagnostics.dispatches,
            attention_diagnostics.dispatches + router_diagnostics.dispatches
        );
        assert_eq!(
            fused_diagnostics.streamed_weight_bytes,
            attention_diagnostics.streamed_weight_bytes + router_diagnostics.streamed_weight_bytes
        );
        assert_eq!(fused_diagnostics.readback_bytes, (EXPERTS * 4) as u64);
        assert_eq!(fused_diagnostics.position, 0);
        assert!(actual_attention
            .iter()
            .zip(&expected_attention)
            .all(|(actual, expected)| actual.to_bits() == expected.to_bits()));
        assert!(actual_logits
            .iter()
            .zip(&expected_logits)
            .all(|(actual, expected)| actual.to_bits() == expected.to_bits()));
    }

